INSERT INTO `knowledge` (`kid`, `knowledgeTitle`, `knowledgePhoto`, `knowledgeDescript`, `knowledgeColor`, `CurrentDate`) VALUES
(1, '“မြေပဲရွက်ထွင်း၊ ရွက်လိပ် ရွက်ကပ်ပိုး” ကိုဂရုပြုကာကွယ်ပါ ..', 'IMG-65d22e22687d17.25116407.jpg', '“မြေပဲရွက်ထွင်း၊ ရွက်လိပ် ရွက်ကပ်ပိုး” ကိုဂရုပြုကာကွယ်ပါ ...<br><br>   🥜🐛🐛🥜🌱🥜🐛🐛🥜🌱🥜🐛🐛🥜🌱<br><br>   ✅မြေပဲ ရွက်ထွင်း၊ ရွက်လိပ်ရွက်ကပ်ပိုးသည်မြေပဲနှင့်ဖွားဘက်တော်ပိုးဖြစ်သည်။ မြေပဲပင် ပေါက်လာရင် ထိုပိုးကျစမြဲဖြစ်သည်။ ထိုပိုးသည်ဘဝအဆင့်လေးခုရှိသည်။အကောင်ကြီးဘဝ (ဖလံ) ၊ ဥဘဝ၊ လောက်ကောင်ဘဝ၊ရုပ်ဖုံးဘဝဖြစ်သည်။ အပင်ကို လောက်ကောင်ငယ်ဘဝတွင် ရွက်ထွင်းပိုး အဖြစ်နှင့်လောက်ကောင်ကြီးဘဝတွင်ရွက်လိပ်ရွက်ကပ်ပိုးအဖြစ် ဖျက်စီးခြင်းဖြစ်သည်။<br><br>   ✅ဖလံအမများသည်မိတ်လိုက်ပြီးလျှင်မြေပဲရွက်ပေါ်တွင်ဥများကိုအုချသည်။ ဥများသည်အလွန် သေးငယ်ပြီး အဖြူရောင်ရှိသည်။ ထိုဥကလေးတွေမှလောက်ကောင်သေးသေးလေးတွေပေါက်လာပြီး ထိုလောက်ကောင်ကလေးများသည်အရွက်အတွင်းသားကိုထွင်းဝင်သွားပြီး အတွင်းမှာအစိမ်းရောင် အသားကိုခြစ်ပြီးစားသောက်နေပါသည်။ အရွက်အတွင်းသားကိုခြစ်ပြီးစားသောက်သည့်အတွက် အရွက်မှာ တစ်သျှူးများမရှိတော့ဘဲလိုဏ်ခေါင်း များသဖွယ်ဖြစ်နေတာတွေ့ရသည်။<br><br>   ✅ထွင်းပြီးခြစ်စားခံရသည့်အရွက်များသည်တဖြည်းဖြည်းခြောက်သွားသည်။ လောက်ကောင်ကလေးများ သည် အရွက်အတွင်းစားသောက်ပြီး တစ်ပတ်ခန့်ကြာလျှင်အပြင်ကိုထွက်လာကြသည်။ အရွက်ငယ် နှစ်ရွက်ကိုသူ့ပါးစပ်ကထုတ်သည့်ချဉ်မျှင်နှင့်ရစ်ပတ်ထွေးပြီးရွက်လိပ်ဖြစ်သွားစေသည်။ လောက်ကောင်လေးတွေသည်ထိုအရွက်လိပ်အတွင်းမှာနေပြီးတစ်သျှူးတွေကိုခြစ်ပြီးစားသောက်နေ၍ နောက်ဆုံးတွင်အရွက်များခြောက်ပြီးသေသွားသည်။အရွက်အတွင်းမှာလိပ်ပြီးနေရင်း ရုပ်ဖုံးဘဝကို ပြောင်းသွားပြီး ခိုအောင်း၍ငြိမ်နေသည်။ ပြီးရင် ထိုရုပ်ဖုံးထဲကနေဖလံပျံထွက်လာခြင်းဖြစ်သည်။<br><br>   ✅ထိုပိုးကိုကာကွယ်နှိမ်နင်းရန် လောက်ကောင်ငယ်ဘဝ (မြေပဲရွက်ထွင်းပိုး)ကို “ဘီတာ စီ၊ မင်းရဲ” ဆေးတစ်မျိုးမျိုးပက်ဖျန်းပေးခြင်း၊ လောက်ကောင်ကြီးဘဝ (ရွက်လိပ် ရွက်ကပ်ပိုး)တွင် မြေပဲပန်းမပွင့်မီ ကျရောက်ပါက “အီမာလန်ဒါ၊ မိုးပျံ” ဆေးတစ်မျိုးမျိုးကိုအသုံးပြုရမည်ဖြစ်ပြီး၊ မြေပဲပန်းပွင့်နေလျှင် “သူရိယ၊ လိုင်းအောက်၊ အက်စ်ဖိတ်” ဆေးများဖြင့်နိုင်နင်းစွာ ကာကွယ်နိုင်ပါသည်။<br><br>   ✅လောက်ကောင်လေးမြေပဲရွက်နှင့်လိပ်ပြီးအရွက်ထဲမဝင်ခင်ဖျန်းနိုင်ရင်ပိုထိရောက်စေပါသည်။ မြေပဲပင်နှင့် မြေပဲရွက်ထွင်း၊ ရွက်လိပ်ရွက်ကပ်ပိုးသည်ဖွားဘက်တော်ဖြစ်သည်မို့ ကြိုတင်ဂရုပြု ကာကွယ်နိုင်ကြပါရန် အကြံပြုအပ်ပါသည်။<br><br>      Sources : အောင်ဆန်း(စိုက်ပျိုးရေး)', '#ADDFFF', '18-02-2024'),
(2, 'ဂရုပြု ကာကွယ်ရန် ဖျက်ပိုး “စိန်ကွက်ဖလံ”', 'IMG-65d22ef73903b0.34678768.jpg', 'ဂရုပြု ကာကွယ်ရန် ဖျက်ပိုး “စိန်ကွက်ဖလံ”<br><br>\r\n\r\n 🐛🐛🥦🥦🐛🐛🥦🥦🐛🐛🥦🥦<br>\r\n\r\n 🔹သီးနှံများစိုက်ပျိုးကြရာတွင် ဟင်းသီးဟင်းရွက်စိုက်ပျိုးရောင်းဝယ်မှုများကို တစ်နှစ်ပတ်လုံး ဆောင်ရွက်နေကြပြီး အများဆုံးစိုက်ပျိုးသောဟင်းသီးဟင်းရွက်မှာ မျိုးရင်း (Cruciferae) ဝင် အပင်များဖြစ်ကြသော မုန်ညင်း၊ မုန်လာ၊ ပန်းဂေါ်ဖီ၊ ဂေါ်ဖီထုပ်၊ ပန်းဂေါ်ဖီစိမ်း၊ နိုကိုဥ၊ ခါကျက်ဥ (မုန်လာဥနီ)၊ မုန်လာဥဖြူ တို့ဖြစ်ကြသည်။ သို့ဖြစ်ရာ မုန်ညင်း၊ မုန်လာစိုက်ပျိုးမှုနှင့်မိတ်ဖက်ဖြစ်နေသော ဖျက်ပိုး “စိန်ကွက်ဖလံ”အကြောင်း ဗဟုသုတအဖြစ် သိရှိနိုင်ပါရန် ရေးသားတင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n 🔹ဤဖျက်ပိုးသည် ရာသီဥတုပူပြင်းလျှင်ကျရောက်မှုများသည့် ဖျက်ပိုးအမျိုးအစားဖြစ်သည်။ ပိုးသတ်ဆေး ကိုခံနိုင်ရည်ရှိလာသောဖျက်ပိုးလည်းဖြစ်၍ ထိထိရောက်ရောက် ပိုးသတ်ဆေးသုံးမှရသည်။ မစို့မပို့၊ မထိမရောက်၊ နည်းစနစ်မမှန်ဘဲပိုးသတ်ဆေးသုံးလာကြလျှင် ဆေးအာနိသင်ကိုပို၍ ပို၍ခံနိုင်သော မျိုးဆက်သစ်ဖျက်ပိုးများ များပြားလာမည်ဖြစ်သည်။ <br><br>\r\n\r\n🔹“စိန်ကွက်ဖလံ”သည် အရွက်များကိုခြစ်စားသောဖျက်ပိုးဖြစ်၍ အစိမ်းရောင်အရွက်ပေါ်တွင် အဖြူကွက်များတွေ့ရလျှင် စိန်ကွက်ဖလံကျနိုင်ပြီဖြစ်သည်။ ဥ ဘဝမှာပင် ဥ ပြန်အုနိုင်သည်။ အကောင်ကြီးဖြစ်သည်အထိရက် (၃၀)ခန့်သာရှိ၍ သီးနှံပင်၏သက်တမ်းအတွင်း စိုက်ခင်းတွင်နှစ်ကြိမ်၊ သုံးကြိမ်ကြုံရနိုင်သည်။ ဥ ဘဝတစ်ပတ်၊ ဖျက်စီးသည့် လောက်ကောင်ဘဝ နှစ်ပတ်-သုံးပတ်၊ ရုပ်ဖုံးဘဝ(၁၀)ရက်သာကြာသည်။ ဥများသည်သေးငယ်၍ အဖြူရောင်ဖြစ်ပြီး အရွက်၏ အောက်မျက်နှာပြင်တွင်လူမမြင်ရအောင်အုချသည်။ <br><br>\r\n\r\n🔹ဥမှပေါက်သည့်လောက်ကောင်များသည်အရွက်အောက်မှအရွက်ပေါ်ထိ ထိုးဖောက်၍သွားကြပြီး အရွက်တွင်အပေါက်များဖြစ်ကျန်ခဲ့သည်။ အပင်တစ်ဝိုက်တွင်ပိုးကောင်ပါးစပ်ကထုတ်သည့်ချည်မျှင်များ နှင့်ပိုးချေးများတွေ့ရသည်။ ရုပ်ဖုံးမှာလည်းချည်မျှင်များထွေးလုံးရစ်ပတ်ထားသည်။ အတောင်ပံပါသော အကောင်ကြီးသည် မီးခိုးရောင်ရှိပြီးအတောင်ကိုစု၍နားနေချိန်တွင် ရှေ့အတောင်အောက်နား၌ စိန်ကွက် သွေးထားသည့်ပုံစံရှိနေ၍ ”စိန်ကွက်ဖလံ”ဟုခေါ်ကြသည်။ တစ်နှစ်လျှင်သားဆက်(၁၅)ဆက်ထိ ပွားများ နိုင်သည်။ <br><br>\r\n\r\nကာကွယ်နှိမ်နင်းရန်မှာ ... <br><br>\r\n\r\n🔹ပိုး၏ခန္ဓာကိုယ်သည်ပျော့ပျောင်းသဖြင့် မီးခိုးမှိုင်းတိုက်၊ မီးခိုးအူပေးမှုပြုလုပ်ပါ။ <br>\r\n\r\n🔹စိုက်ခင်းအတွင်း ပေါင်းမြက်၊ အမှိုက်ရှင်းပါ။ <br>\r\n\r\n🔹N: P: K မြေဩဇာသုံးမျိုးကို အချိုးအစားညီမျှအောင် သုံးပေးပါ။ နိုက်ထရိုဂျင်အချိုးအစားမပိုပါစေနှင့်။ ပိုတက်စီယမ်ဓာတ်ကို မဖြစ်မနေကျွေးပါ။ <br>\r\n\r\n🔹ညထွက်ဖလံမျိုးဖြစ်၍မီးရောင်ထောင်ချောက်ထွန်း၍ နှိမ်နင်းပါ။<br> \r\n\r\n🔹ပိုးကျရောက်မှုတွေ့သည်နှင့် ဓာတုပိုးသတ်ဆေး (ဘီတာ စီ၊ အီမာလန်ဒါ၊ မိုးပျံ၊ နိုက်ဝမ်း၊ လိုင်းအောက်၊ ရော့ကက်) ဆေးများမှတစ်မျိုးမျိုးသုံး၍ နှိမ်နင်းပေးပါ။<br> \r\n\r\n🔹ဂေါ်ဖီထုပ်တွင်အရွက်အထပ်ထပ်ဖုံးထားသလို၊ ပန်းဂေါ်ဖီတွင်အပွင့်များစုပြုံနေ၍ ပိုးကျရောက်မှု ပိုများသည်။ဂေါ်ဖီထုပ်၊ပန်းဂေါ်ဖီစိုက်ခင်းများတွင်ပိုးသတ်ဆေးအများဆုံးသုံးကြ၊ ဖျန်းကြရသည်။ ပိုးသတ်ဆေးဓာတ်ကြွင်းမကျန်ရန်ခူးဆွတ်ခါနီး ဓာတုပိုးသတ်ဆေးမဖျန်းသင့်ပါ။ တစ်ပင်တွင် ပိုးနှစ်ကောင်တွေ့လျှင် ထိသေစားသေ နှင့် ပင်လုံးပြန့်အာနိသင်ရှိ ဓာတုပိုးသတ်ဆေးတစ်မျိုးမျိုး အသုံးပြုပေးရပါမည်။ <br>\r\n\r\n🔹ဆေးဖျန်းလျှင်အရွက်၏အောက်ခြေ၊ပိုးဥ၊ပိုးကောင်ရှိသောနေရာကိုဖျန်းကြရမည်။ ပျိုးခင်းနှင့် စိုက်ပျိုးပြီးခါစအစောပိုင်းကာလများတွင်ဓာတုဆေးများသုံးလျှင်ဓာတ်ကြွင်းပါဝင်မှုနည်းနိုင်သည်။ ထို့ကြောင့် ဖျက်ပိုး “စိန်ကွက်ဖလံ”ကို ဆိုးရွားစွာကျရောက်ဖျက်စီးမှု မတိုင်မီကပင် ကြိုတင်သတိပြုကာကွယ်နှိမ်နင်းသင့်ပါကြောင်း တိုက်တွန်းအကြံပြုအပ်ပါသည်။ <br><br>\r\n\r\n\r\n\r\nSources : စိုက်ပျိုးရေးရာအကြံပြုချက်များ \r\n', '#57FEFF', '18-02-2024'),
(3, '“ငရုတ် နှင့် ရွက်သေးထိုးပြဿနာ”', 'IMG-65d22ff51ecbd1.01119081.jpg', '🌿🌶️🌿🌶️🌿🌶️🌿🌶️🌿🌶️🌿 <br><br>\r\n\r\n✔️ ငရုတ်စိုက်တောင်သူတိုင်း ငရုတ်ရွက်သေးထိုးသည့် ပြဿနာကိုကြုံဖူးကြပေမည်။ အဓိကအားဖြင့် သီးနှံပင်တွင် လှေးအပါအဝင် စုပ်စားပိုးများကျရောက်ခြင်း၊ အာဟာရဓာတ်ချို့တဲ့ခြင်း နှင့် စုပ်စားပိုးများသယ်ဆောင်လာသည့် ဗိုင်းရပ်စ်ကျရောက်ခြင်းတို့ကြောင့် \"ငရုတ်ရွက်သေးထိုး” ဖြစ်ပေါ်ရခြင်းဖြစ်သည်။ \"ငရုတ်ရွက်သေးထိုး”ဝင်ရောက်ပါက ငရုတ် အရည်အသွေးနှင့် အထွက်နှုန်းကိုထိခိုက်နိုင်ပြီး အထွက်သိသာစွာကျဆင်းနိုင်သည့်အတွက် ငရုတ်စိုက်တောင်သူများ အထူးဂရုပြု ကြိုတင်ကာကွယ်သင့်ပါသည်။ <br><br>\r\n\r\n✔️ စုပ်စားပိုးများသည် အလွန်သေးငယ်ပြီး ငရုတ်အညွန့်အတွင်းဝင်ရောက်ကာ သစ်ရည်ကိုစုပ်စား၍ ဖျက်ဆီးသည်။ ထိုသို့စားသောက်ပြီး (၄-၅)ရက်ခန့်ရှိသောအခါ အညွန့်များသည် ကြီးမားပြန့်ကားလာခြင်းမရှိတော့ပဲ စုပ်စားပိုးများ စုပ်ယူစားသောက်သည့်ဒဏ်ရာများကြောင့် တွန့်ကုတ်ကာ အရွက်များပုံသဏ္ဍာန်မမှန်ဖြစ်နေသည်ကို တွေ့ရပါသည်။ စုပ်စားပိုးများ စုပ်ယူစားသောက်ခံရသည့် အညွန့်မှန်သမျှ ဤသို့ ပုံသဏ္ဍာန်မမှန်ဖြစ်နေသည်ကိုတွေ့ရပါမည်။ <br><br>\r\n\r\n✔️ ထိုသို့ စုပ်စားပိုးများထဲတွင် လှေးပိုးသည် လေစီးကြောင်းအတိုင်းလိုက်ပါပြန့်နှံ့၍ နည်းလမ်းအမျိုးမျိုးဖြင့် မျိုးပွားကာ ပြန့်ပွားတတ်သဖြင့် လှေးပိုးကြောင့်ဖြစ်ပွားသော ရွက်သေးထိုးလက္ခဏာဖြစ်ပွားသည့် အပင်များကို လေစီးကြောင်းအလိုက်ဖြစ်ပွားနေသည်ကို တွေ့ရှိရပါမည်။ တစ်နေရာတည်းတွင် အကွက်လိုက်တွေ့ရလေ့မရှိပါ။ <br><br>\r\n\r\n ✔️ ထို့အပြင် စုပ်စားပိုးများသယ်ဆောင်လာသော “ဗိုင်းရပ်စ်ရောဂါများ” ကျရောက်ခြင်းကြောင့် ငရုတ်အရွက်များ တွန့်ကုတ်၍ ပုံသဏ္ဍာန်မမှန်ဖြစ်လာပြီး ငရုတ်ရွက်သေးထိုးလက္ခဏာ ဖြစ်ပေါ်သည်လည်းရှိပါသည်။ ဗိုင်းရပ်စ်ရောဂါအမျိုးမျိုးမှာ ပျ၊ ဖြုတ်၊ ယင်ဖြူ၊ မွှားပင့်ကူ နှင့် လှေးပိုး စသည့် စုပ်စားပိုးများမှ သယ်ဆောင်လာကာ ကူးစက်ပြန့်ပွားခြင်းဖြစ်သဖြင့် သီးနှံပင်စိုက်ပျိုးပြီး (၁၅)ရက်သားခန့်မှစ၍ လက်ဦးမှုရယူကာ စုပ်စားပိုးများကျရောက်မှုကို ထိထိရောက်ရောက် ကြိုတင်ကာကွယ်ရပါမည်။ <br><br>\r\n\r\n✔️ ၎င်းကိုကာကွယ်နိုင်ရန် စိုက်ခင်းကို ရေမများ/ရေမငတ်အောင် ဂရုစိုက်ပါ။ ရေသွင်းချိန် (သို့မဟုတ်) မြေအစိုဓာတ် ကောင်းကောင်းရှိချိန်မှာ ငရုတ်အပင်ခြေရင်းကို ဝိစာရ၏ “ဒီပါ ၄၆ဂျီ (သို့မဟုတ်) ဖစ်ပရို ၃ ဂျီအာ” ဆေးခဲများကိုကြဲပက်ပေးပါ။ ဆေးဖျန်းရန်အတွက် ငရုတ်အပင်ငယ်များပြောင်းရွှေ့စိုက်ပြီး (၁၅)ရက်ခန့်တွင် ဝိစာရ၏ စုပ်စားပိုးကာကွယ်နှိမ်နင်းဆေးများဖြစ်သော “နိုးဝမ်း၊ ကေလာ၊ ကလဲဗား” ဆေးများကိုရွေးချယ်၍ (၇-၁၀)ရက်ခြားတစ်ကြိမ်ခန့် အလှည့်ကျပက်ဖျန်း၍ ကြိုတင်ကာကွယ် ပေးရပါမည်။ လှေးပိုးကျရောက်ပါက “ပရိုဆင့်” ဆေးကို ပက်ဖျန်းနိုင်ပါသည်။ <br><br>\r\n\r\n✔️ ထို့မျှမကပဲ ငရုတ်ရွက်သေးထိုးပြဿနာသည် “ဇင့် နှင့် ကယ်လ်စီယမ်၊ ဆာလ်ဖာ၊ မန်းဂနိစ်၊ ကောပါး၊ ဘိုရွန်” စသည့်အာဟာရဓာတ်များ ချို့တဲ့ခြင်းကြောင့်လည်း ဖြစ်ပေါ်တတ်ပေရာ အပင်အတွက်အဓိက လိုအပ်သော NPK အာဟာရဓာတ်များအပြင် ဖော်ပြပါသက်စောင့်အာဟာရ ဓာတ်များ ပြည့်စုံမျှတအောင် ထည့်သွင်းပေးရန်လည်း လိုအပ်ပါသည်။ ထို့ကြောင့် အာဟာရဓာတ်များ အချိုးအစားညီမျှစွာဖြင့် ထုတ်လုပ်ထားသော ဝိစာရ၏ရွက်ဖျန်းအားဆေးများဖြစ်သည့် “ရိုက်စ်အပ်၊ ကယ်လ်စီပလပ်စ်၊ ဝီဂရိုး၊ မေခလာ” စသည် ရွက်ဖျန်းအားဆေးတို့မှ တစ်မျိုးမျိုးနှင့် “ဘိုစတာဟော်မုန်း နှင့် ဝိစာရကွန်ဘီ” အားဆေးတို့ကို ရောစပ်၍ ငရုတ်သီးနှံသက်တမ်းတစ်လျှောက် လိုအပ်သလိုပက်ဖျန်းအသုံးပြုပေးရပါမည်။ <br><br>\r\n\r\n✔️ အကယ်၍ ရောဂါကျရောက်ပြီး အရွက်များတွန့်ကုတ်၍ ပုံသဏ္ဍာန်မမှန်ဖြစ်သည့် အခြေအနေကို ရောက်ရှိလာပါက ၎င်းတွန့်ကုတ်နေသောအပင်များကို အချိန်မဆိုင်းပဲ ချက်ချင်းနုတ်ယူဖျက်ဆီးပစ်ရ ပါမည်။ ထို့အပြင်ကျန်အပင်များသို့ ရောဂါသယ်ဆောင်ပိုးများမကျရောက်စေရန် အထက်ဖော်ပြပါ ပိုးသတ်ဆေးများဖြင့် အချိန်မှီပက်ဖျန်းကာကွယ်ပေးရပါမည်။ <br><br>\r\n\r\n✔️ သို့ဖြစ်ရာ “ငရုတ် နှင့် ရွက်သေးထိုးပြဿနာ”ဖြစ်ပွားရသည့်အကြောင်းများ နှင့် ကြိုတင်ကာကွယ်ရန် ဆောင်ရွက်ကြရမည့်နည်းလမ်းများကို ရေးသားဖော်ပြပေးပြီးဖြစ်၍ ဦးကြီးတို့ငရုတ်စိုက်ခင်းများအတွင်း ရွက်သေးထိုးပြဿနာများ ကင်းဝေးနိုင်ကြပါစေရန် ဆန္ဒပြုလိုက်ရပါသည်။ \r\n', '#FF6763', '18-02-2024'),
(4, 'မိုးစပါးသီးနှံတွင် ပေါင်းမြက်အချိန်မှီ ကာကွယ်နှိမ်နင်းရန်', 'IMG-65d2310182ddc6.30881222.jpg', '🌾🌱🌾🌱🌾🌱🌾🌱🌾🌱🌾<br><br> \r\n\r\n✅ မိုးရာသီကာလ သီးနှံများစိုက်ပျိုးရေးမှာ အလေးထားဆောင်ရွက်ရမှာတွေက များပါတယ်။ အဲဒီအထဲမှာ မိုးစပါးနဲ့ မိုးယာသီးနှံများမှာ ပေါင်းမြက်အချိန်မှီ ကာကွယ်နှိမ်နင်းဖို့နဲ့ တစ်ဧက အပင်ရေပြည့်ဝစေဖို့ ဆောင်ရွက်ရမယ့်အချက်ကလေးများ မမေ့ကြဖို့ပြောပြချင်ပါတယ်။ <br><br>\r\n\r\n✅ ပေါင်းမြက်ဟာ သီးနှံများကို ဘယ်လောက်အထိ ဆုံးရှုံးမှုဖြစ်စေနိုင်တယ်၊ ဘာ့ကြောင့် ဂရုစိုက်သင့်သလဲဟု ဆိုရာတွင် ပေါင်းမြက်ကြောင့် ဖွံ့ဖြိုးပြီး စက်မှုနိုင်ငံတွေမှာ ဆုံးရှုံးမှု ၅ ရာခိုင်နှုန်းရှိပြီး အလယ်အဆင့်ဖွံ့ဖြိုးပြီးနိုင်ငံများမှာ ဆုံးရှုံးမှု ၁၀ ရာခိုင်နှုန်းရှိပါတယ်။ ဖွံ့ဖြိုးစနိုင်ငံများမှာတော့ ဆုံးရှုံးမှု ၂၅ ရာခိုင်နှုန်းအထိ မြင့်မားလာတယ်လို့ ဆိုပါတယ်။ ပေါင်းမြက်ကိုထိထိရောက်ရောက် ကာကွယ်နှိမ်နင်းမှု မပြုလုပ်နိုင်ဘူးဆိုရင် စပါးသီးနှံမှာ(၂၆ - ၄၀) ရာခိုင်နှုန်း၊ မြေပဲမှာ ၂၄.၄ ရာခိုင်နှုန်း၊ နှမ်းမှာ ၂၁ ရာခိုင်နှုန်း၊ ပဲတီစိမ်းမှာ ၁၆ ရာခိုင်နှုန်း၊ အစေ့ထုတ်ပြောင်းမှာ ၈ ရာခိုင်နှုန်း၊ ပဲပုပ်မှာ ၁၅ ရာခိုင်နှုန်း အထွက်နှုန်းထိခိုက်ကြောင်း သုတေသနတွေ့ရှိချက်များက ထောက်ပြထားပါတယ်။ <br><br>\r\n\r\n✅ ကမ္ဘာမှာ လက်ရှိ ပေါင်းမြက်ကာကွယ်နှိမ်နင်းမှုဟာ ထိရောက်မှုမရှိသေးတာ တွေ့ရပါတယ်။ မြန်မာနိုင်ငံမှာတော့ လယ်သမားဦးရေ ၆၀၀၀ မှာ ၃၂ ရာခိုင်နှုန်းသာ ပေါင်းမြက်ကိုဂရုတစိုက် ရှင်းလင်းတယ်လို့ ဆိုပါတယ်။ ပေါင်းမြက်ကြောင့် သီးနှံဆုံးရှုံးမှုဟာ ပိုးမွှားနဲ့ ရောဂါနှစ်ခုပေါင်း ဆုံးရှုံးမှုနဲ့ ညီမျှတယ်လို့ ဆိုပါတယ်။ <br><br>\r\n\r\n✅ ဒီနှစ် မိုးစပါးမှာ မိုးမကျမီ အခြောက်ကြဲခင်းစနစ်နဲ့ တိုက်ရိုက်မျိုးစေ့ချစနစ် များလာတာတွေ့ရပါတယ်။ မိုးဦးရေရလာလို့ အခြောက်ကြဲခင်းများ၊ တိုက်ရိုက်မျိုးစေ့ချစိုက်ခင်းများ စပါးပင်များပေါက်လာပြီး စိမ်းစိမ်းစိုစိုဖြစ်လာတာ တွေ့ရပါတယ်။ စပါးနဲ့အတူ ယှဉ်ပြိုင်တက်လာတာကတော့ ပေါင်းမြက်ပါပဲ။ တိုက်ရိုက်မျိုးစေ့ချ စိုက်ခင်းတွေမှာလည်း အလားတူပါပဲ။ ပေါင်းမြက်ကို အချိန်မှီ မကာကွယ် မနှိမ်နင်းနိုင်လို့ ပေါင်းမြက်က လွှမ်းမိုးသွားရင် စပါးအထွက် တစ်ဧက(၃၅-၄၅) တင်း နှုန်းခန့်သာ အများဆုံးထွက်မှာ သေချာပါတယ်။ <br><br>\r\n\r\n✅ စပါးအခြောက်ကြဲခင်းနဲ့ တိုက်ရိုက်မျိုးစေ့ချစိုက်ခင်းတွေမှာ အပင်ပေါက်ပြီးရက် (၄၀) ကျော်အထိ ပေါင်းမြက်ကြီးစိုးနေပါက အနှံစွေ့ပြီး တစ်နှံပါအစေ့နည်းသွားစေပါတယ်။ စပါးပင် အသက်ရက် (၂၀-၄၀) အတွင်း မဖြစ်မနေ ပေါင်းမြက်နှိမ်နင်းကာကွယ်ဖို့ အရေးကြီးပါတယ်။ ကုန်းမြင့်တောင်ယာ စပါးခင်းများမှာ ပေါင်းကြောင့် စပါးအထွက်ဟာ တစ်ဧက ၁၅ တင်းမှ တင်း ၂၀ အထိ ကျဆင်းသွား စေနိုင်ပါတယ်။ လက်ပေါင်း သို့မဟုတ် ရွေးချယ်ပေါင်းသတ်ဆေး အသုံးပြုသင့်ပါတယ်။<br><br>\r\n\r\n✅ အာဖရိကနဲ့ အိန္ဒိယနိုင်ငံတွေမှာ အပင်ငယ်စဉ် သုံးပတ်မှ ခြောက်ပတ်သားမှာ ပေါင်းမြက်နှိမ်နင်းပေးခြင်း ဖြင့် အထွက်နှုန်းမြင့်မားတာကိုတွေ့ရပါတယ်။ ဆူဒန်နိုင်ငံမှာ အပင်ငယ်စဉ် ပေါင်းမြက် ၁၀ ရာခိုင်နှုန်း ဖုံးလွှမ်းခံရပါက အထွက်ကျစေနိုင်ကြောင်းနဲ့ ပေါင်းမြက် ၅၀ ရာခိုင်နှုန်းအထိ ဖုံးလွှမ်းခံရပါက အထွက်နှုန်း ၇၀ ရာခိုင်နှုန်းအထိ ကျဆင်းစေတယ်လို့ ဆိုပါတယ်။ တန်ဇန်းနီးယားနိုင်ငံမှာ မြေသြဇာ မသုံးဘဲ အပင်ငယ်စဉ်ပေါင်းမြက်ကို အချိန်မှန်မှန် နိုင်နင်းအောင်သုတ်သင်ရှင်းလင်းပေးခြင်းဖြင့် အထွက် ၅၀ရာခိုင်နှုန်းအထိ ပိုမိုတယ်လို့ ဆိုပါတယ်။<br><br> \r\n\r\n✅ ထို့ကြောင့် တောင်သူလယ်သမားကြီးတွေက မိုးစပါးအခြောက်ကြဲခင်း၊ တိုက်ရိုက်အစေ့ချစိုက်ခင်းနဲ့ ပြောင်းရွှေ့စိုက်စပါးခင်းတွေမှာ ပေါင်းမြက်ဂရုတစိုက် ကာကွယ်နှိမ်နင်းခြင်းလုပ်ငန်းကို မမေ့မလျော့ ဆောင်ရွက်ကြစေဖို့တိုက်တွန်းလိုက်ရပါတယ်။ <br><br>\r\n\r\nSources : အောင်ဆန်း(စိုက်ပျိုးရေး) <br><br>\r\n\r\nမြန်မာတောင်သူကြီးများဂျာနယ်\r\n', '#ffffc2', '18-02-2024'),
(5, 'တောင်သူဦးကြီးများအတွက် “ဇွန်လ” သိမှတ်စရာများ', 'IMG-65d231d0cedfa7.47736207.jpg', '🌾🌱🌾🌱🌾🌱🌾🌱🌾🌱🌾<br><br>\r\n\r\n➡️ မိုးဦးကျပြီဟုဆိုရမည်။ ယခုလက နယုန်လဖြစ်သည်။ ရှေးက နယုန်မိုးသေးမြက်သားမွေးလို့ ဆိုစကားရှိသည်။ မိုးလှိုင်ဦးမည်မဟုတ်သည်ကို ညွှန်းဆိုခြင်းဖြစ်သည်။ ဇွန်လတစ်လလုံးမှာမှ မိုးနည်းပါးသည့်ဒေသများဖြစ်သော မြန်မာနိုင်ငံအလယ်ပိုင်းဒေသတွေမှာ မှတ်တမ်းတွေအရ လေးလက်မအောက်သာ မိုးရွာတတ်သည်။ နေရာလိုက်၍ မိုးအနည်းအများတော့ ကွာခြားနိုင်သည်။ မိုးဦးသီးနှံများကို မြေချစိုက်ပျိုးနိုင်မည့်ကာလဖြစ်သည်။ မိုးဦးယာသီးနှံများကို လျင်လျင်မြန်မြန် ပြီးစီးအောင်စိုက်ပျိုးရန်လိုပါသည်။<br><br>\r\n\r\nမိုးဦးယာသီးနှံများ<br>\r\n--------------<br>\r\nယာသီးနှံဆိုတာ အပင်ခြေရေဝပ်ဒဏ်မခံနိုင်သည့်သီးနှံများကို ရည်ညွှန်းခြင်းဖြစ်သည်။ စပါးလို လယ်ကွက်ထဲ ရေသိုလှောင်စိုက်ပျိုး၍ မရပေ။ ကန်သင်း မရှိသောယာမြေ၊ ကုန်းမြေလို မြေမျိုးမှာ စိုက်ပျိုးသည့်သီးနှံများကို ဆိုလိုခြင်းဖြစ်သည်။ နှမ်း၊ ပြောင်း၊ မြေပဲ၊ ပဲမျိုးစုံ၊ ဝါ၊ ငရုတ် စသည့် သီးနှံများ၏အမည်ကို ခြုံငုံ၍ ယာသီးနှံများဟု သုံးနှုန်းခေါ်ဝေါ်ခြင်းဖြစ်ပါသည်။ <br><br>\r\n\r\nဂရုပြုစိုက်ပျိုးသင့်သည်များ <br>\r\n----------------------<br>\r\nမိုးဦးကာလ အဆိုပါယာသီးနှံများ စိုက်ပျိုးရာတွင် ဂရုပြုသင့်သည်များကို အသိပေးလိုသည်။<br><br>\r\n\r\n၁။ အပင်ပေါက် ၈၀ ရာခိုင်နှုန်းအထက်ရှိသည့်မျိုးသန့်ကို အသုံးပြုစိုက်ပျိုးပါ။<br><br>\r\n\r\n၂။ ခြောက်သွေ့မှုဒဏ် (Water Stress) ခံနိုင်ပြီး အပင်ပေါက် သန်စွမ်းကောင်းမွန်သည့် good seedling vigour မျိုးကို အသုံးပြုပါ။ <br><br>\r\n\r\n၃။ ရေမြေဒေသကိုက်ညီဖြစ်ထွန်းပြီး ဈေးကွက်ရှိသည့်မျိုးကို အသုံးပြုစိုက်ပျိုးပါ။<br><br>\r\n\r\n၄။ အပင်ပေါက်ကောင်းနိုင်သည့်မြေအစိုဓာတ်ရရှိမှသာ စိုက်ပျိုးပါ။ <br><br>\r\n\r\nမိုးဆက်လက်ရွာသွန်းခြင်းမပြုလျှင် ပေါက်လာသောအပင်များသည်သေကုန်နိုင်သဖြင့် အထူးဂရုပြုစေလိုသည်။ အပင်ပေါက် ကောင်းမကောင်းနှင့် ပေါက်လာပါကလည်း အပင်များ၏ ကြံ့ခိုင်သန်စွမ်းမှုသည် မျိုးစေ့အပေါ်တွင်မူတည်သည်။ ယာသီးနှံများစိုက်ပျိုးအောင်မြင်ရန် ဒေသအချို့တွင် မိုးရွာသွန်းမှုသည် လိုအပ်သည့် ပုံမှန်မိုးရေချိန်ထက် လျော့နည်းနိုင်ပေရာ မိုးခေါင်ခံမျိုးဖြစ်ရန် လိုအပ်ပါသည်။ <br><br>\r\n\r\nမျိုးသန့်များစိုက်ပျိုးခြင်း <br>\r\n-------------------- <br>\r\nစိုက်နေကျမျိုးသည် မျိုးသစ်မျိုးဆန်းများထက် ဒေသရေမြေဖြစ်ထွန်းတာ သေချာသည်။ သို့သော် ဈေးကွက်မှာ မျိုးသန့်မျိုးစစ်ကိုမှ ကြိုက်သည်။ အထွက်ကောင်းရေးကအရေးတော့ကြီးသည်။ ဒေသဖြစ်ထွန်းပြီး ဈေးကွက်ရှိတာကို ဦးစားပေးရန်လိုသည်။ ဒေသတွင်း မဖြစ်ထွန်း၊ ဈေးကွက်မရှိလျှင် အထွက်ကောင်းသော်လည်း အကျိုးအမြတ်က နည်းနိုင်ပါသည်။<br><br>\r\n\r\nနှမ်းသီးနှံ <br>\r\n-------- <br>\r\nနှမ်းသီးနှံကို ဥပမာပြလိုသည်။ နှမ်းစေ့အရောင် အဖြူ၊ အနီ၊ အနက်မတူပါ။ ဈေးကွက်အကြိုက်မှာ တစ်နှစ်နှင့်တစ်နှစ်လည်းမတူပါ။ နှမ်းစေ့အရောင်ပေါ်မူတည်ပြီး ဈေးကောင်းရသည်။ စိုက်ပျိုးသည့်အခါ အနီမျိုးဈေးကောင်းရသည့်နှစ်တွင် အနီမျိုးကို ဦးစားပေးစိုက်ပျိုးသည်။ အနက်ကဈေးကောင်းလျှင် အနက်မျိုး၊ အဖြူကဈေးကောင်းရလျှင် အဖြူမျိုးကို ပို၍စိုက်လိုကြသည့်ဆန္ဒရှိကြောင်း သိရသည်။ မည်သည့်နှမ်းမျိုးကိုပဲစိုက်စိုက် မျိုးသန့်သည့် နှမ်းနီစစ်စစ်၊ နှမ်းနက်စစ်စစ်၊ နှမ်းဖြူစစ်စစ်ကို စိုက်ပျိုးရန်လိုကြောင်း အသိပေးလိုပါသည်။ <br><br>\r\n\r\nမြေပဲသီးနှံ <br>\r\n-------- <br>\r\nမိုးခေါင်သော်လည်း စိုက်ပျိုးသည့် သီးနှံအောင်မြင်ရန်လိုသည်။ မိုးမြေပဲနှင့် ပတ်သက်၍ မျိုးရွေးချယ်ရေး အကြံပေးလိုသည်။ ရာသီဥတုဖောက်ပြန်နေသော ယနေ့အခြေအနေတွင် ရေငတ်ခံနိုင်သည့်မျိုး ဖြစ်သင့်သည်။ ဆင်းပဒေသာ-၆ နှင့် မကွေး-၁၁မြေပဲမျိုးတို့သည် စံထားရသော ရေငတ်ခံမြေပဲမျိုးများ ဖြစ်ကြောင်း သိရသည်။ ဒေသအတွေ့အကြုံအရ ရေငတ်ခံသည့်မျိုးကို စိုက်ပျိုးကြစေလိုပါသည်။မြေပဲတွင် ဖိုးလမင်းပိုးကောင်ကျရောက်ဖျက်ဆီးတတ်သည်။ ယခင်နှစ်ကကျရောက်ဖူးသော စိုက်ခင်းများတွင် ပို၍သတိထားရမည်။ မြေပဲမျိုးစေ့ကို သင့်တော်ရာပိုးသတ်ဆေးရည်တွင် ရောမွှေခြင်း၊ စိုက်မြောင်းထဲသို့ သင့်တော်ရာပိုးသတ်ဆေးထည့်ပေးခြင်းတို့ ပြုလုပ်ရန်လိုအပ်ပါသည်။ မြေပဲသီးနှံ စိုက်ပျိုးရာတွင် မျိုးစေ့ကို ပဲမြစ်ဖုမြေသြဇာနှင့်လူးနယ်စိုက်ပျိုးစေလိုသည်။ မြေပဲပင်အတွက် နိုက်ထရိုဂျင် အာဟာရဓာတ်ရရှိစေရန်ဖြစ်သည်။ ဈေးနှုန်းမြင့်မားသောယူရီးယားဓာတ်မြေသြဇာကို ဝယ်ယူသုံးစွဲရန်မလိုသဖြင့် အရင်းအနှီးလျော့နည်းစေသည်။ ကုန်ကျစရိတ်နည်းနည်းဖြင့်မြေပဲပင် အတွက် အကျိုးရလဒ်ကောင်းကို ရရှိစေပါသည်။<br><br> \r\n\r\nပဲစင်းငုံသီးနှံ <br>\r\n---------- <br>\r\nပဲစင်းငုံကတော့ သီးနှံသဘာဝကိုယ်က မိုးခေါင်သီးနှံဖြစ်သည်။ အသက်ကြီးသည်။ အပင်ငယ်စဉ် ကြီးထွားမှုနှေးသည်။ အစောပိုင်းကာလ အချိန်နှင့်နေရာကို အကျိုးရှိအောင် အသုံးချသောအားဖြင့် အခြားသီးနှံတစ်မျိုးမျိုးနှင့် သီးညှပ်စိုက်သင့်ပါသည်။ ပဲစင်းငုံနှင့် နှမ်းလျင် (သို့မဟုတ်) ပဲစင်းငုံနှင့် ပဲတီစိမ်း (သို့မဟုတ်) သင့်တော်ရာ သီးနှံတစ်မျိုးမျိုးနှင့်သီးညှပ်ပုံစံချမှတ်စိုက်ပျိုးစေလိုပါသည်။<br><br> \r\n\r\nပဲပုပ်သီးနှံ <br>\r\n-------- <br>\r\nရှမ်းပြည်နယ်ကဲ့သို့ ကုန်းမြင့်ဒေသများတွင် စပါးကို ဝမ်းစာရရန် စိုက်ပျိုးသည်။ ပဲပုပ်သီးနှံကလည်း ဒေသအကြိုက်ဖြစ်သည်။ ယေဘုယျအားဖြင့် ကုန်းမြင့်ဒေသများမှာ မြေဆီလွှာညံ့ဖျင်းကြသည်။ သီးနှံအထွက်မြင့်မားရန်လိုသည်။ ရေရှည်လည်းမြေဆီလွှာဖွံ့ဖြိုးရန်လိုသည်။ ပဲပုပ်က ပြန်လည် ဖြည့်ဆည်းပေးနိုင်သည်။ ယာစပါးနှင့်ပဲပုပ်ကို သီးညှပ်စိုက်ပျိုးရန် ပြောလိုသည်။ တစ်သီးစိုက်သည်ထက် နှစ်သီးက ဝင်ငွေပိုမည်။ ဒေသစားသုံးမှုအတွက် ဝမ်းစာစပါးရော၊ ပဲပုပ်ပါဖူလုံစေမည်။တောင်သူတွေ ကျင့်သုံးမှုတော့နည်းသေးသည်။ နည်းလမ်ကောင်းဖြစ်သဖြင့်ကုန်းမြင့်ယာစပါးနှင့် ပဲပုပ်ကို သီးညှပ်စိုက်ရန် ပြောခြင်းဖြစ်သည်။ ယာစပါးကယူသည့် မြေဆီသြဇာကို ပဲပုပ်က ဖြည့်ဆည်းပေးခြင်းဖြင့် ရေရှည်မြေဆီလွှာထိန်းသိမ်းဖွံ့ဖြိုးစေသည့်နည်းလမ်းဟု ဆိုနိုင်ပါသည်။ <br><br>\r\n\r\nမိုးဦးသီးနှံ အလျင်အမြန်စိုက်ပျိုးရန် <br>\r\n------------------------------ <br>\r\nမိုးဦးသီးနှံများစိုက်ပျိုးရာတွင် သီးနှံအလိုက် လိုအပ်သည့် မြေအစိုဓာတ်ရအောင်မိုးရွာသွန်းသည်နှင့် မြန်မြန်ဆန်ဆန်ထွန်ရေးပြုပြင်စိုက်ပျိုးစေလိုသည်။ “ယာမှာအသုတ် လယ်မှာအပုပ်” ဟု ရှေးက အဆိုရှိသည်။ လယ်ဆိုတာ လယ်စပါးကိုရည်ညွှန်းသည်။ တမန်းညက်ရုံမက “ပုပ်” ဆိုတာ မြေပေါ်ရှိ ယခင်သီးနှံရိုးပြတ်၊ အပင်အကြွင်းအကျန်နှင့် ပေါင်းမြက်တွေ မြေမှာဆွေးမြည့်အောင် အချိန်ယူ ထွန်ယက်ရန်ပြောခြင်းဖြစ်သည်။ ယာကတော့ ယာသီးနှံတွေကိုညွှန်းတာဖြစ်သည်။ အထူးသဖြင့် မိုးဦးကျသီးနှံတွေကို ပြောခြင်းဖြစ်သည်။ ယခုပိုပြီး သတိထားလိုက်နာသင့်ပါသည်။ သီးနှံစိုက်ပျိုးခြင်းသည် ရာသီနှင့်ကိုက်ညီအောင်စိုက်ပျိုးမှသာ သီးနှံအထွက်သေချာသည်။ ရာသီဥတုကြောင့် စိုက်ချိန်နောက်ကျနိုင်သလို ထွန်တာယက်တာအချိန်ယူလွန်းနေသဖြင့် ကိုယ့်ကြောင့် လည်း နောက်ကျနိုင်သည်။ ထို့ကြောင့် ခပ်သုတ်သုတ်မြန်မြန်စိုက်ရန် ယာမှာအသုတ် ဟု အမှာစကားထားခဲ့ခြင်းဖြစ်နိုင်ပါသည်။ မိုးဦးသီးနှံများကို မိုးရွာသည်နှင့် အမြန်ထွန်ယက်စိုက်ပျိုးစေလိုပါသည်။ <br><br>\r\n\r\nစိုက်ပြီးမိုးဦးသီးနှံ အောင်မြင်ရန် <br>\r\n---------------------------- <br>\r\nမေလအတွင်း မိုးရွာသွန်းသောဒေသများတွင် မိုးဦးနှမ်းလျင်အပါအဝင် သီးနှံအချို့ကို စိုက်ပျိုးနိုင်ခဲ့သော ဒေသများ ရှိပေမည်။ အပင်သားခွဲနောက်မကျရန် သတိပေးလိုသည်။ ပေါင်းမြက်ကို ငယ်စဉ်ကပင် နိုင်နင်းအောင် နှိမ်နင်းရန်လိုသည်။ နေရာလိုက်၍ မိုးကြီးရွာသွန်းမှုကြောင့် သီးနှံမပျက်စီးရန် လိုသည်။ အပင်ခြေရေမဝပ်ရေး၊ ရေထုတ်မြောင်းများ ကောင်းစွာပြုလုပ်ထားသင့်သည်။ လိုအပ်သည့် မြေသြဇာကျွေးခြင်း အပါအဝင် ပြုစုဂရုစိုက်မှုလုပ်ငန်းများကို အထူးအလေးထားဆောင်ရွက်ကြရန် ဖြစ်ပါသည်။ <br><br>\r\n\r\nမိုးစပါး ပျိုးထောင်ရန် <br>\r\n------------------<br> \r\nဆည်ရေသောက်ဒေသ မိုးစပါးအတွက် ဦးစွာပြောလိုသည်။ ၁။ ဇွန်လလယ်တွင် ပျိုးထောင်ပါ။ ၂။ အပင်ပေါက် ၈၀ ရာခိုင်နှုန်းအထက်ရှိသည့်မျိုးသန့်ကို အသုံးပြုစိုက်ပျိုးပါ။ ၃။ ရေမြေဒေသကိုက်ညီဖြစ်ထွန်းပြီး ဈေးကွက်ရှိသည့် အထွက်ကောင်းစပါးမျိုး(High Yieding Variety) ကို အသုံးပြုရန် ဖြစ်ပါသည်။ <br><br>\r\n\r\n➡️ မိုးများသည့်ဒေသ အထူးသဖြင့် မြန်မာနိုင်ငံအောက်ပိုင်းဒေသများနှင့် ကချင်ပြည်နယ် စသည့် မိုးစပါးကို ဇွန်လအတွင်း မိုးရေချိန်ရှစ်လက်မနှင့်အထက်ရရှိရန် မျှော်မှန်းနိုင်သည့် အချို့ဒေသများတွင်လည်း စပါးသီးနှံကို အချိန်မှန်တွင် စိုက်ပျိုးသင့်သည်။ ဆည်ရေသောက်ဒေသများကဲ့သို့ပင် ဇွန်လလယ်ထက် နောက်မကျစေဘဲ ပျိုးထောင်ရန်၊ အပင်ပေါက် ၈၀ ရာခိုင်နှုန်းအထက်ရှိသည့် မျိုးသန့်ကို အသုံးပြုရန်နှင့် ရေမြေဒေသကိုက်ညီဖြစ်ထွန်းဈေးကွက်ရှိသည့် အထွက်ကောင်းမျိုး (HYV) သို့မဟုတ် ဒေသစပါးမျိုး (Local Variety) တို့ကိုအသုံးပြုရန်သင့်ပါကြောင်း တိုက်တွန်း အသိပေးလိုက်ရပါသည်။ <br><br>\r\n\r\nSources : မောင်ဖူးဝေ(တောင်တွင်းကြီး) <br><br>\r\n\r\nမြန်မာတောင်သူကြီးများဂျာနယ်\r\n', '#addfff', '18-02-2024'),
(6, 'သိရှိမှတ်သားထားရမည့် “ပိုးစေးနှဲ” ဖျက်ပိုးအကြောင်း', 'IMG-65d2324bc55750.15064821.jpeg', '🐛🐛🐛🐛🐛🐛🐛🐛🐛🐛<br><br>\r\n\r\nမြန်မာအမည် - ပိုးစေးနှဲ<br><br>\r\n\r\nအင်္ဂလိပ်အမည် - Mealybug<br><br>\r\n\r\nသိပ္ပံအမည် - Pseudococcidae (Various species)<br><br>\r\n\r\n⏩ ပိုးစေးနှဲ များကို ပူနွေး၍ စွတ်စိုထိုင်းမှိုင်းသော ရာသီဥတုရှိသည့် နေရာဒေသများတွင်တွေ့ရများပြီး စုပ်ယူနိုင်သော ပါးစပ်အစိတ်အပိုင်း(Mouth part) ပါရှိသည့် စုပ်စားပိုး( Sucking pests ) တစ်မျိုးဖြစ်သည်။ ပိုးစေးနှဲများသည် အပင်၏ သစ်ရည်တို့ကိုစုပ်ယူစားသုံးလေ့ရှိသည်။ အခြားသော ဒေသများထက် နွေးသမပိုင်းနှင့် အပူပိုင်းဒေသတို့တွင် ပိုးစေးနှဲ မျိုးစိတ်အရေအတွက် ပိုများသည်ကို တွေ့ရှိရသည်။ ပိုးစေးနှဲ၏ ခန္ဓာကိုယ်သည် ပျော့ပြောင်း၍ အဖြူရောင် ဝါဂွမ်းစနှင့် ဆင်သည်။ ၎င်းတို့၏ခန္ဓာကိုယ်အား ဝါဂွမ်းနှင့်ဆင်သော အဖြူရောင် ဖယောင်းလွှာ( Waxy layer )ကိုဖုံးကာထားသဖြင့် အရွယ်ရောက်သည့်တိုင် သတိမထားမိကြပါ။<br><br> \r\n\r\n⏩ ယေဘုယျအားဖြင့် ၎င်းတို့တွင် ဥအဆင့်၊ ပိုးမမည်အဆင့်၊ အရွယ်ရောက်အကောင်ကြီးအဆင့် ဟူ၍ ဘဝစက်ဝန်း (၃)ဆင့် ရှိသည်ဟု အကြမ်းဖျင်း သတ်မှတ်နိုင်သည်။ ပိုးစေးနဲ အထီး/အမ နှစ်မျိုးစလုံး ပိုးမမည် (Nymphs) အဆင့်တွင် ခြေထောက်များပေါက်လာပြီး ရွေ့လျားနိုင်သည်။ အထီးများသည် သက်တမ်းတိုပြီး ပိုးရုပ်ဖုံးအဆင့်နှင့် အရွယ်ရောက်ကောင် ဘဝအဆင့်တွင် အစာမစားတော့ပဲ အမများ၏ အနီးနားတွင်သာ သီးခြားနေထိုင်တက်ကြသည်။ အတောင်ရှိသော အရွယ်ရောက်အကောင်သည် နကျယ်( Wasp )နှင့် ဆင်သည်။<br><br>\r\n\r\n⏩ ပိုးစေးနဲများကို ပူနွေး၍ စွတ်စိုထိုင်းမှိုင်းသောရာသီဥတုရှိသည့် နေရာဒေသများတွင်တွေ့ရများပြီး အပင်၏သစ်ရည်တို့ကို စုပ်ယူစားသုံးလေ့ရှိသည်။ စိုက်ပျိုးသီးနှံပင်တွေအတွက် စိုးရိမ်ရတဲ့ ဖျက်ပိုးတစ်မျိုးဖြစ်ပြီး ပင်စည်၊ အရွက်နှင့် အသီးများတွင် တွေ့ရလေ့ရှိသည်။ လက်ခံပင်တွင် တွယ်ကပ်၍ ၎င်းတို့ထုတ်သောဖယောင်းလွှာအား အကာအကွယ်ပြုလုပ်ကာ ပင်ရည်ကိုစုပ်ယူသည်။ <br><br>\r\n\r\n⏩ ပိုးစေးနှဲများမှာ အကောင်သေးငယ်သော်လည်း အများအပြားကျရောက်ခံရသော အပင်သည် ပုံပျက်သွားပြီး ကြီးထွားမှု နှေးကွေးသွားသည်။ ကျရောက်သောနေရာတွင် ဒဏ်ရာတွေ ဖြစ်ကျန်ခဲ့နိုင် သည်။ ပိုးစေးနှဲတို့ စွန့်ထုတ်သော အချိုရည်(Honeydew) ကြောင့် စုပ်ယူခံရသောအပင်တွင် စေးကပ်နေသည်။ ယင်းအချိုရည် (Honeydew)သည် အချိုဓာတ်မြင့်မားသဖြင့် အပင်၌ ကြပ်ခိုးမှို (Sooty mold) ဟု ခေါ်သော Black powdery fungus ရောဂါကိုဖြစ်စေပြီး အပင်နှင့် အသီး အရည်အသွေးကို ကျစေသည်။ ရှောက်သံပုရာပင်များ နှင့် သရက်ပင်၊ မာလကာပင်များတွင် ကျရောက်သော ပိုးစေးနှဲ မျိုးစိတ်များသည် ဆိုးရွားသောဖျက်ပိုးများ ဖြစ်သည်။<br><br>\r\n\r\n⏩ ကြံ၊ စပျစ်၊ နာနတ်၊ ပီလောပီနံ၊ ကော်ဖီပင်၊ ပိုးစာပင်၊ သင်္ဘောပင်၊ နေကြာ၊ ရှားစောင်းပင်များ၊ သစ်ခွ၊ ဇီဇဝါပန်းပင် နှင့် Fernsပင်များတွင် ကျရောက်လေ့ရှိသည်။ ပိုးစေးနှဲ ကျရောက်နေသော လက်ခံပင်များတွင် ပုရွက်ဆိတ်များကို တွေ့ရှိရပြီး ပိုးစေးနှဲတို့နှင့် သဟဇီဝဖြစ်စွာ တူယှဉ်တွဲ နေထိုင်ကြသည်။ ထို့ကြောင့် စိုက်ပျိုးသီးနှံပင်များတွင် ပုရွက်ဆိတ်များတွေ့ရှိရသည်နှင့် ပိုးစေးနဲ ရှိနေကြောင်းသိရှိနိုင်သည်။ သို့သော် အခြားသော စုပ်စားပိုးမျိုးနွယ်များလည်း ဖြစ်နိုင်သောကြောင့်သေသေချာချာ ကြည့်ရှု့စစ်ဆေးသင့်သည်။<br><br>\r\n\r\n⏩ ပိုးစေးနှဲသည် ဥ၊ သားလောင်း၊ အရွယ်ရောက်ကောင်ဆိုသည့် ဘဝစက်ဝန်းကို ပိုင်ဆိုင်ထားပြီး ဘဝစက်ဝန်းတစ်ပတ်ပြည့်ရန် (၆-၈)ပတ်ခန့် ကြာနိုင်သည်။ ရာသီဥတု ပူနွေးသောအချိန် (သို့) အိမ်တွင်းစိုက်အပင်များတွင် ကြီးထွားမှုအဆင့်တိုင်းကို တစ်နှစ်ပတ်လုံးတွေ့နိုင်ပြီး မျိုးစိပ်နှင့် ပတ်ဝန်းကျင်အခြေအနေပေါ်မူတည်၍ တစ်နှစ်တွင် မျိုးဆက် (၆-၈)ဆက် ရှိနိုင်သည်။ <br><br>\r\n\r\nဖျက်ဆီးပုံ လက္ခဏာများ .....<br><br>\r\n\r\nပိုးစေးနှဲ ဖျက်ဆီးပုံမှာ အသီးနှစ်လုံး ထိစက်နေသောနေရာ၊ အပင်၏ ကန်တော့နေရာ၊ ကိုင်းဆက်နေရာ၊ မြေကြီးနှင့်နီးစပ်နေသောပင်စည်၊ အရွက်နှင့်ထိစပ်နေသောပင်စည်များတွင် အစုလိုက် အပြုံလိုက် စားသောက်ဖျက်ဆီးနေသည်ကို တွေ့ရတတ်သည်။ အချို့သောပိုးစေးနှဲများသည် အမြစ်ပေါ်တွင် စားသောက်ဖျက်ဆီးသည်။ ပိုးစေးနှဲသည် အပင်၏ ရေကြောမှတစ်ဆင့် ပင်စည်များကို စုပ်ယူပြီး အပင်ကို ခံနိုင်ရည်နည်းစေသည်။ အရွက် (သို့) ပင်စည်ပေါ်တွင် ပမာဏများစွာ ကျရောက်ပါက အပင်ကြီးထွားမှု ရပ်တန့်ပြီး အရွက်များ ကြွေကျနိုင်သည်။ သို့သော် ခံနိုင်ရည်ရှိသော အပင်များသည် ပမာဏာအနည်းငယ်ကျရောက်မှုကို ခံနိုင်ရည်ရှိပြီး သိသာထင်ရှားသော လက္ခဏာများမပြပါ။<br><br> \r\n\r\nပိုးစေးနှဲ ကာကွယ်နှိမ်နင်းရန်နည်းလမ်းများ …..<br><br>\r\n\r\n- ခံနိုင်ရည်ရှိသော၊ ကျန်းမာသန်စွမ်းသော မျိုးကောင်းမျိုးသန့်များကို စိုက်ပျိုးပါ။ <br><br>\r\n\r\n- မိတ်ဆွေပိုးများ ပွားများအောင် လုပ်ဆောင်ပါ။<br><br>\r\n\r\n- ရေများ အလွန်အကျွံပေးခြင်း၊ အာဟာရအလွန်အကျွံကျွေးခြင်းများရှောင်ပါ။<br><br>\r\n\r\n- ဓာတုဆေးအသုံးပြုမည်ဆိုပါက “အီမာလန်ဒါ၊ လန်ဒါ ၅၊ ဘီတာစီ” ပိုးသတ်ဆေး တစ်မျိုးမျိုးကို “ဟီးရိုး” တွယ်ကပ်ဆေးနှင့် ရောစပ်ပက်ဖျန်းပေးရပါမည်။ \r\n', '#57feff', '18-02-2024'),
(7, '“စပါး အထွက်တိုး စိုက်ပျိုးနည်း”', 'IMG-65d232e23746e4.27389043.jpg', '🌾🌾🌾🌾🌾🌾🌾🌾🌾🌾<br><br>\r\n\r\n✅ စပါးသီးနှံကို မြန်မာနိုင်ငံအနှံ့အပြားတွင် ကျယ်ကျယ်ပြန့်ပြန့်စိုက်ပျိုးကြပါသည်။ ရေရရှိမှုအပေါ် မူတည်၍ စိုက်ပျိုးချိန် နှင့် စိုက်ပျိုးရာဒေသများကွဲပြားကြသော်လည်း စိုက်ပျိုးထုတ်လုပ်မှု အများဆုံး သီးနှံဖြစ်သည်။တစ်နည်းအားဖြင့် မိရိုးဖလာ မျိုးရိုးစဉ်ဆက်စိုက်ပျိုးကြသည်လည်းဖြစ်သည်။ သို့ဖြစ်ရာ စပါးသီးနှံကို စနစ်တကျစိုက်ပျိုး၍ အထွက်နှုန်းကောင်းရရှိနိုင်စေရန် “စပါး အထွက်တိုး စိုက်ပျိုးနည်း” စနစ်များကို ရေးသားတင်ပြလိုက်ပါသည်။<br><br>\r\n\r\nစပါးမျိုးရွေးချယ်ခြင်း<br>\r\n-----------------<br>\r\nရေမြေဒေသနှင့် ကိုက်ညီသည့် အထွက်ကောင်းမျိုးသန့်စပါးကို ရွေးချယ်စိုက်ပျိုးပါ။ (၃)နှစ်တစ်ကြိမ် မျိုးသန့်များနှင့် လဲလှယ်စိုက်ပျိုးပါ။<br><br>\r\n\r\nမြေပြုပြင်ခြင်း<br>\r\n-----------<br>\r\nနွေထယ်ရေးခံခြင်းကို ဆောင်ရွက်ပါ။ ကန်သင်းများကို ကြိုတင်ပြင်ဆင်၍ ကန်သင်းလုံအောင် ဆောင်ရွက်ပေးသင့်ပါသည်။ ထယ်ရေးနက်နက်နှင့် ထွန်ရေးညက်ရန် အရေးကြီးဆုံးဖြစ်သည်။ စိုက်ခင်းမြေမြက်နှာပြင် ညီညာစေရန်လည်းလိုအပ်ပါသည်။ သို့မှသာ ရေထိန်းသိမ်းနိုင်မှု ကောင်းမွန်နိုင်ပါမည်။<br><br>\r\n\r\nပျိုးထောင်ခြင်း<br>\r\n-----------<br>\r\nစပါးစိုက်ခင်း (၁၀) ဧကစာအတွက် ပျိုးခင်းတစ်ဧကတွင် ပျိုးထောင်ပါ။ ပျိုးခင်းတစ်ဧကတွင် မျိုးစေ့ (၁၅) တင်း ထက်ပို၍ ပျိုးမထောင်သင့်ပါ။ ၎င်းထက်ပိုပါက ပျိုးသေးပျိုးညှင်းများဖြစ်ပြီး ပိုးနှင့်ရောဂါများ ကျရောက်လွယ်ပါသည်။ ပျိုးခင်းများတွင် ပိုးနှင့်ရောဂါများ စတင်ကျရောက်သည်နှင့် အချိန်မှီ ဆေးဖျန်းရန် အရေးကြီးပါသည်။ <br><br>\r\n\r\nစိုက်ပျိုးနည်းစနစ်<br>\r\n--------------<br>\r\nမျိုး၊ စိုက်ပျိုးသည့်စနစ် (ကြဲခင်း၊ ပျိုးစိုက်) စိုက်ပျိုးသည့် ဒေသပေါ်မူတည်၍ စိုက်ချိန်ကွာခြားမှု ရှိပါသည်။ စပါးပျိုးသက် (၂၀-၂၅) ရက်သားတွင် ရွှေ့ပြောင်းစိုက်ပါ။ ကြဲပက်စိုက်ပျိုးပါက လက်ဆညီညီနှင့် ကန်သင်း ကမ်းတိုက်အောင် ကြဲပက်ပါ။ ပျိုးစိုက်ပါက ပျိုးပင်လက်ဆ (၂ - ၃) ပင်နှင့် ကောက်ပင် တိမ်တိမ်သာ (၁ - ၁.၅) လက်မ စိုက်ရန် အရေးကြီးပါသည်။ ကြဲခင်းဖြစ်စေ၊ စိုက်ခင်းဖြစ်စေ စိုက်ပြီး (၂) ပတ်အကြာတွင် ကောက်ပင်ဖာခြင်းလုပ်ငန်းကိုဆောင်ရွက်ပါ။ <br><br>\r\n\r\nကောက်ကွက် အရေအတွက် <br>\r\n------------------------<br> \r\nစပါး အထွက်ကောင်းရန် တစ်ဧက ကောက်ကွက်ဝင်ဆန့်မှုသည် အလွန်အရေးကြီးပါသည်။ စိုက်ပျိုးသည့်စပါးမျိုးအလိုက် အောက်ပါအတိုင်း ကောက်ကွက်ပြည့်မီအောင် စိုက်ပျိုးရပါမည်။ သက်လျင်မျိုးများ = တစ်ဧကအတွက် (၁) သိန်း (၅) သောင်း မှ (၁) သိန်း (၇) သောင်း နှင့် သက်လတ်မျိုးများ = တစ်ဧကအတွက် (၁) သိန်း (၃) သောင်း မှ (၁) သိန်း (၅) သောင်း ပြည့်မီရပါမည်။<br><br> \r\n\r\nရေထိန်းသိမ်းမှု အခြေအနေ <br>\r\n----------------------- <br>\r\nအပင်ပွားချိန်တွင် ရေကို (၂)လက်မခန့် ထားပါ။ မှို့ကပ်ချိန်မှ ဖုံးတုန်းလုံးတုန်း အချိန်ထိ ရေကို (၄ - ၆) လက်မခန့် ထားပါ။ စပါးပန်းပွင့်ပြီး (၂)ပတ်အကြာတွင် ရေကိုပြောင်အောင်ထုတ်ပေးရပါမည်။ <br><br>\r\n\r\nသဘာဝမြေသြဇာနှင့် ဓာတ်မြေသြဇာ သုံးစွဲခြင်း <br>\r\n---------------------------------------- <br>\r\nပျိုးခင်းတွင် နွားချေးဆွေး၊ စက်ဖွဲပြာများ ထည့်၍ မြေပြင်ပါ။ စိုက်ခင်းတွင် နွားချေးဆွေး၊ အမှိုက်ဆွေးကို တစ်ဧကလျှင် လှည်း ၅ စီးမှ ၁၀ စီး တိုက်ချပေးပါ။ ရေမစိုသော စက်ဖွဲပြာချပေးနိုင်ပါက ပို၍ ကောင်းမွန်ပါသည်။ <br><br>\r\n\r\nစပါးသီးနှံတွင် ဝိစာရဓာတ်မြေဩဇာများ အသုံးပြုရန်မှာ<br> \r\n------------------------------<br>\r\nစပါးစိုက်ခင်း တစ်ဧကအတွက်<br><br> \r\n\r\n( ၁ ) မြေခံတွင် ဝိစာရ ၁၅ ပတ်လည် - အိတ်တစ်ဝက် နှင့် မော်နီတာဂျစ်ပ်ဆမ် - နှစ်အိတ် (သို့မဟုတ်) 16:16:8+12S (အထွက်တိုးကွန်ပေါင်း) - အိတ်တစ်ဝက်နှင့် မော်နီတာဂျစ်ပ်ဆမ် - နှစ်အိတ်နှုန်း ရောစပ်၍ ထည့်သွင်းအသုံးပြုပါ။ <br><br>\r\n\r\n( ၂ ) စပါးပင် (၂၅-၃၅)ရက်သက်တမ်းအတွင်း ပင်ပွားလှိုင်လှိုင်ထွက်ချိန်တွင် မိုးပုလဲ - (သုံးပုံတစ်ပုံ)အိတ် (သို့မဟုတ်) 17:8:8+15S (ရွှေတိုးကွန်ပေါင်း)- အိတ်တစ်ဝက်နှုန်း ထည့်သွင်းပေးပါ။ <br><br>\r\n\r\n( ၃ ) စပါးမှို့ကပ်ချိန်တွင် ၁၆ပတ်လည် (ဇီလီယန်) - အိတ်သုံးပုံတစ်ပုံနှုန်း ထည့်သွင်းအသုံးပြုပါ။<br><br>\r\n\r\n( ၄ ) စပါးပင် အလံရွက်စထွက်ချိန် (သို့မဟုတ်) ဖုံးတုန်းလုံးတုန်းအချိန်တွင် အောင်နှံဝေ အိတ်တစ်စိတ် နှင့် ဘက်စ်ကေ အိတ်တစ်စိတ်နှုန်း ရောစပ်၍ထည့်သွင်း အသုံးပြုပေးရန်ဖြစ်ပါသည်။ <br><br>\r\n\r\nပိုးမွှား၊ ရောဂါ ကာကွယ်နှိမ်နင်းခြင်း <br>\r\n------------------------------- <br>\r\nပိုးမွှားနှင့် ရောဂါများမှာ ပျိုးခင်းမှစ၍ကျနိုင်သောကြောင့် ပျိုးခင်းအချိန်မှစိုက်ခင်းအထိ မျက်ခြည်မပြတ် စောင့်ကြည့်ရပါမည်။ စပါးရွက်လိပ်အိမ်ပိုး၊ စပါးဆစ်ပိုး၊ ဖြုတ်ပိုးအမျိုးမျိုး၊ သရစ်လှေးပိုး၊ စပါးနှံစုပ်ပိုး များကျရောက်မှုများပြားတတ်ပြီး ဝိစာရ၏ “မင်းရဲ၊ ကေလာ၊ သူရိယ၊ ဘီတာစီ၊ နိုးဝမ်း၊ ပရိုဆင့်” ဆေးများကို ဆေးညွှန်းပါ အတိုင်းရွေးချယ်သုံးစွဲပေးရပါမည်။ မြေတွင်းအောင်းပိုးများနှင့် နီမတုတ် ကျရောက်ပါက “ဒီပါ၊ ဖစ်ပရို” ဆေးများကို ကြဲပက်သုံးစွဲနိုင်ပါသည်။ \r\nစပါးတွင် ကျရောက်မှုများသော ရောဂါများဖြစ်သည့် စပါးဂုတ်ကျိုးရောဂါ အတွက် “နိုက်စ်၊ ကာဗာ၊ ပိုင်ရီဆိုက်” စပါးရွက်ညိုပြောက်ရောဂါအတွက် “ဇိုလာ၊ ဘင်ဇိုကာ” စပါးဘက်တီးရီးယားရွက်ခြောက် ရောဂါအတွက် “ကျူပရိုမက်စ်၊ ကာစင်၊ ဘာလီဆိုဒ်” စသည့်ဆေးများကို ဆေးညွှန်းအတိုင်း သုံးစွဲ၍ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။ <br><br>\r\n\r\nပေါင်းမြက်ကာကွယ်ခြင်း<br> \r\n--------------------- <br>\r\nစပါးခင်းအတွင်း ပေါင်းမြက်များပေါက်ရောက်မှုက စပါးအထွက်ကို ၂၈ - ၆၀ ရာခိုင်နှုန်းအထိ ထိခိုက်နိုင်ပါသည်။ ထို့ကြောင့်ပေါင်းပေါက်ရောက်မှု နည်းနိုင်သမျှနည်းအောင် မြေကို ကောင်းစွာပြုပြင်ပါ။ အမှိုက်သရိုက်များကို တတ်နိုင်သမျှဖယ်ရှားပါ။ စိုက်ပြီး (၃၀-၃၅)ရက်အတွင်း ပေါင်းမြက်ကင်းစင်အောင် ဆောင်ရွက်ပါ။ ပေါင်းသတ်ဆေး အသုံးပြုရန် ဝိစာရ၏ စပါးရွေးချယ် ပေါင်းသတ်ဆေးများဖြစ်သော “ကွင်ဖျူရန်၊ အောရိုက်၊ ဟာဘီ၊ ပေါင်းကင်း၊ ဒီမင်း၊ ဂျက်၊ ခရေဇီ” စသည်တို့ကို စပါးပင်အသက်ရက်နှင့် ပေါက်ရောက်သည့်ပေါင်းအုပ်စုများအလိုက် ရွေးချယ် အသုံးပြုနိုင်ပါသည်။ <br><br>\r\n\r\nထိုသို့ပေါင်းသတ်ဆေးများပက်ဖျန်းရာတွင် ပေါင်းသတ်ဆေးမဖျန်းမီ စိုက်ခင်းအတွင်း ရေထုတ်ခြင်း၊ ဆေးဖျန်းပြီးနောက် (၂-၃) ရက်ကြာမှ ရေပြန်သွင်းခြင်းကို သေချာစွာပြုလုပ်ပါ။ ပေါင်းသတ်ဆေးများ ဖျော်စပ်ရာတွင် သန့်ရှင်းကြည်လင်၍ ရွံ့၊ နွံ၊ နုံး အနယ်အနှစ်များ ကင်းစင်သောရေကို အသုံးပြုပါ။ ပေါင်းသတ်ဆေးဖျန်းပြီး (၇-၁၀) ရက်အတွင်း ဓာတ်မြေသြဇာကျွေးခြင်း၊ အပင်အားဆေးဖျန်းခြင်းများကို ရှောင်ပါ။ ဆေးအာနိသင် ထိရောက်စေရန်နှင့် ကြာရှည်ခံစေရန်ဆေးဖျန်းသည့်အခါတိုင်း တွယ်ကပ်ပြန့်နှံ့ဆေး “ဟီးရိုး (သို့မဟုတ်) နတ်ဆေး တစ်မျိုးမျိုးနှင့် ရောစပ်အသုံးပြုပေးရပါမည်။ <br><br>\r\n\r\nရိတ်သိမ်းခြင်း<br> \r\n----------<br>\r\n စပါးကို မောင်းညိုချိန်(သို့မဟုတ်) ပန်းပွင့်ပြီး ရက် (၃၀) (သို့မဟုတ်) စပါးစေ့ (၇၅ မှ ၈၀) ရာခိုင်နှုန်း ရင့်မှည့်ချိန်တွင်ရိတ်သိမ်းပါ။ ရိတ်သိမ်းချိန်နောက်ကျပါက စပါးစေ့ (၅၀ - ၆၀) ရာခိုင်နှုန်းအထိ လေလွင့်ဆုံးရှုံးနိုင်ပါသည်။ မောင်းညိုချိန်တွင်ရိတ်မှသာ အလေအလွင့်နည်းပြီး ဆန်အရည်အသွေး ကောင်းမည်ဖြစ်ပါသည်။ <br><br>\r\n\r\n\r\nSources : စိုက်ပျိုးရေးဦးစီးဌာန\r\n', '#FF6763', '18-02-2024'),
(9, 'မိုးကြိုနှမ်းလျင် စိုက်ပျိုး‌ခြင်းဆိုင်ရာ သိမှတ်စရာများ', 'IMG-65d234356543c4.98906764.jpg', '🌿🌱🌿🌱🌿🌱🌿🌱🌿🌱🌿 <br><br>\r\n\r\n⏩ နှမ်းလျင်သီးနှံကို ‌လောင်းကစားသီးနှံဟု ရှေးယခင်ကခေါ်ဝေါ်ကြသည်။ စတင် စိုက်ပျိုးသည်မှ ရိတ်သိမ်းသည်အထိ မိုးကြီးခြင်း၊ မိုးခေါင်ခြင်းစသည့် ရာသီဥတုကြောင့် ပျက်စီးဆုံးရှုံးနိုင်လို့ ဖြစ်ပါမည်။ မိုးနှမ်းလျင်သီးနှံကို ရည်ညွှန်းပြောဆိုတာ ဖြစ်နိုင်သည်။ မိုးကြိုနှမ်းလျင်မှာမူ ထိုသို့ မဟုတ်နိုင်ပါ။ စနစ်တကျစိုက်ပျိုးလုပ်ကိုင်လျှင် မျှော်မှန်းအထွက်ကို ရရှိနိုင်သည်သာ ဖြစ်ပါသည်။ မိုးကြိုနှမ်းလျင်ကို အေးမြသည့် ဆောင်းရာသီအကုန် ညအပူချိန်မြင့်တက်လာသည့် ဖေဖေါ်ဝါရီနှင့် မတ်လတို့တွင် စိုက်ပျိုးသည်။ သွင်းရေရရှိသည့် မန္တလေးတိုင်းဒေသကြီး၊ မကွေးတိုင်းဒေသကြီး၊ စစ်ကိုင်းတိုင်းဒေသကြီးနှင့် အချို့ဒေသများတွင် စိုက်ပျိုးကြပါသည်။ <br><br>\r\n\r\n⏩ မိုးရာသီမဟုတ်သဖြင့် မိုးရေကိုအားကိုးလို့မရပါ။ သွင်းရေတစ်မျိုးမျိုးကိုသာ အားကိုးစိုက်ပျိုးခြင်း ဖြစ်သည်။ မိုးနှမ်းစိုက်ပျိုးရာတွင် ကုန်ကျစရိတ်များစွာကုန်ကျခြင်းမရှိသော်လည်း မိုးကြိုနှမ်း စိုက်ပျိုးရာတွင်မူ သွင်းရေအမျိုးအစားနှင့် ရရှိနိုင်သည့်နည်းလမ်းအပေါ်မူတည်ပြီး ကုန်ကျစရိတ် ပိုမိုနိုင်ပါသည်။ သို့ဖြစ်၍ စိုက်ပျိုးကုန်ကျစရိတ်အပေါ်အကျိုးအမြတ်ရှိရေးအတွက် လိုက်နာဆောင်ရွက် သင့်သည့်လုပ်ငန်းများကို အပြည့်အဝလုပ်ကိုင်ဖို့လိုသည်။ <br><br>\r\n\r\n⏩ လုပ်ငန်းများအနက် ဂရုစိုက်ဆောင်ရွက်သင့်သော လုပ်ငန်းသုံးရပ်ကို ဖေါ်ပြလိုက်ပါသည်။ ထိုလုပ်ငန်းများမှာ <br><br>\r\n\r\n(၁) မြေပြုပြင်ခြင်း <br><br>\r\n\r\n(၂) အပင်သားခွဲခြင်းနှင့် <br><br>\r\n\r\n(၃) ရေပေးသွင်းခြင်း လုပ်ငန်းတို့ ဖြစ်ပါသည်။ <br><br>\r\n\r\nမြေပြုပြင်ခြင်း<br>\r\n-----------<br>\r\n\r\nလုပ်ကိုင်နေကျမို့ ခက်ခဲသောလုပ်ငန်းတော့ မဟုတ်နိုင်ပါ။ သို့သော် အလေးထားရန် နှိုးဆော်ခြင်းသာ ဖြစ်သည်။ လယ်မြေမှာစိုက်သောမိုးကြိုနှမ်းဖြစ်၍ ထွန်ရေးမကောင်းလို့မဖြစ်ပါ။ ထို့ထက်ပိုမို အရေးကြီးသည်က ရေသွင်းစိုက်ပျိုးမှာဖြစ်သဖြင့် မြေမျက်နှာပြင် မညီညာလို့ မဖြစ်ပါ။ စပါးရိတ်သိမ်းအပြီး ရိုးပြတ်လယ်ကွင်းအတွင်း ရေသွင်းကာ ထယ်ရေးစတင်ဖို့ ဆောင်ရွက်ရသည်။ ဆက်တိုက်ဆောင်ရွက်လို့မရ။ နေလှမ်းရသည်။ ထွန်ရေးဝင်ရန် အနေတော်မတော် ကြည့်ရသည်။ စိုက်ပျိုးမြေအမျိုးအစား၊ နေ့အပူချိန်၊ လေတိုက်နှုန်းနှင့် လယ်သမား၏အတွေ့ အကြုံတွေက အရေးပါသည်။ အချိန်ကိုက်ဆောင်ရွက်ရန်လိုသည်။ မြေတွင်းအစိုဓာတ်ထိန်းနိုင်ရေး၊ နှမ်းအပင်ပေါက် ကောင်းရေး၊ ချိန်ဆဆောင်ရွက်ကြစေလိုပါသည်။ ရေသွင်းစိုက်ပျိုးမှာဖြစ်သဖြင့် ရေသွင်း မြောင်းများဖေါ်ရသည်၊ ရေထုတ်မြောင်းများ ဖေါ်ရသည်။ သွင်းလိုက်သည့်ရေ ပိုနေလို့မဖြစ်၊ နေရာကွက်ကြား ရေဝပ်နေလို့မဖြစ်၊ မြေပြုပြင်ချိန်တွင် စနစ်တကျ ရေသွင်းရေထုတ်မြောင်းတွေ တစ်ပြိုင်တည်း ဆောင်ရွက်ဖို့၊ ‌ဘောင်စနစ်ဖြင့် စိုက်မည်ဆိုပါကလည်း စိုက်ဘောင်တွေ သေချာပြင်ဖို့ ဖြစ်ပါသည်။ <br><br>\r\n\r\nအပင်သားခွဲခြင်း<br>\r\n------------<br>\r\n\r\nနှမ်းလျင်စိုက်ပျိုးရာတွင် တစ်ဧကလျင် မျိုးစေ့ (၁.၅ မှ ၂) ပြည်ခန့်ဖြင့် လုံလောက်သော်လည်း နှစ်ဆမက သုံးစွဲစိုက်ပျိုးလေ့ရှိသည်။ နှမ်းစေ့က သေးငယ်သဖြင့် အပင်ပေါက်သေချာစေရန် မျိုးစေ့များများသုံးသည့် အလေ့အထ ဖြစ်ပါမည်။ နှမ်းပင်လေးများ စုပုံကာ ထပ်ညပ်ပေါက်လာပါတော့သည်။ အတန်းလိုက်စိုက် သည် ဖြစ်စေ၊ ကြဲပက်စိုက်ပျိုးသည်ဖြစ်စေ တစ်ကျင်းတစ်ပင်ချန်ပြီး သားခွဲရန်လိုသည်။ နှမ်းခင်းအား မူမှန်အရွက် (၆) ရွက်ထွက်ချိန်ဖြစ်သည့် အပင်သက်တမ်း (၂)ပတ်သားတွင် သားခွဲခြင်းလုပ်ငန်းကို မဖြစ်မနေဆောင်ရွက်ရန် တိုက်တွန်းလိုပါသည်။ အတန်းလိုက်စိုက်ပါက အတန်းအတွင်း တစ်ပင်နှင့် တစ်ပင် ၄ လက်မအကွာထားဖို့ ဖြစ်သည်။ ကြဲပက်စိုက်ပါက ခန့်မှန်းခြေ ၄ လက်မခန့် အကွာရအောင် ထွန်ဖြင့် မှုန်းပေးရန် ဖြစ်ပါသည်။ အချုပ်အားဖြင့် တစ်ဧကတွင် အပင်ဦးရေတစ်သိန်းရှိဖို့ လိုသည်။ ဤသည်မှာ နှမ်းလျင်သီးနှံ အထွက်နှုန်းမြင့်မားဖို့ တစ်ဧကတွင်ရှိရမည့်မှန်ကန်သော အပင်ဦးရေ ဖြစ်ကြောင်း အသိပေးလိုပါသည်။ <br><br>\r\n\r\nရေပေးသွင်းခြင်း<br>\r\n------------<br>\r\n\r\nမိုးကြိုနှမ်းစိုက်ပျိုးရာတွင် မူလကပင် ရေသွင်းရေထုတ်ကောင်းမွန်သည့်မြေအမျိုးအစားတွင် စိုက်ပျိုးထားသည်ဖြစ်ရာ ရေပေးသွင်းမှုလုပ်ငန်းကို စနစ်တကျဆောင်ရွက်ရန်လိုသည်။ ‌လိုအပ်ပါက ရေပေးသွင်းနိုင်ခြင်း၊ ပိုလျှံပါက ရေထုတ်နိုင်ခြင်း ပြုလုပ်နိုင်ရပါမည်။ ထို့ပြင် အသုံးပြုမည့်ရေသည်လည်း သင့်တော်သည့်အရည်အသွေးရှိရန်လိုပါသည်။ နှမ်းလျင်စိုက်ပျိုးပြီး တစ်ပတ်သားကပင် အပင်ရှင်သန် ရေး အတွက် ရေပေးသွင်းရန် လိုမလို စစ်ဆေးပြီး လိုအပ်ပါက ရေပေးသွင်းရန် ဖြစ်သည်။ ထို့ကြောင့် နှမ်းပင်ကြီးထွားဖွံ့ဖြိုး ပွင့်သီးကာ အောင်မြင်စေရေးအတွက် ရေပေးသွင်းရန်လိုသည့်အချိန် သုံးချိန်ကို အသိပေးလိုသည်။ ထိုသုံးချိန်မှာ- (၁) ပန်းမပွင့်မီအချိန် (၂) ပန်းပွင့်ချိန်နှင့် (၃) နှမ်းအသီး ဖြစ်တည်ချိန်တို့ ဖြစ်ပါသည်။ ပန်းမပွင့်မီအချိန်သည် နှမ်းလျင်စိုက်ပျိုးပြီး (၂၂ မှ ၂၅) ရက်အကြာတွင် ဖြစ်သည်။ ရေတစ်ကြိမ် ပေးသွင်းသင့်ပါသည်။ ပန်းပွင့်ချိန်သည် နှမ်းလျင်စိုက်ပျိုးပြီး (၃၅ မှ ၄၅) ရက်အကြာတွင် ဖြစ်သည်။ ရေတစ်ကြိမ် ပေးသွင်းသင့်ပါသည်။ နှမ်းအသီးဖြစ်တည်ချိန်တွင်မူ ရေလိုအပ်မှုအခြေအနေကိုကြည့်ပြီး တစ်ကြိမ်(သို့မဟုတ်) နှစ်ကြိမ် ရေပေးသွင်းသင့်ပါသည်။ နှမ်းအသီးများရင့်မှည့်သည့်ကာလတွင်မူ နှမ်းခင်းမြေသည် အစိုဓာတ်အနည်းငယ်ရှိသော အခြေအနေ ဖြစ်နေသင့်ပါသည်။ နှမ်းလျင်စိုက်ပျိုးအပြီး (၆၅ - ၇၀)ရက် နောက်ပိုင်းတွင်မူ ရေပေးသွင်းမှုပြုလုပ်ရန် မလိုတော့ကြောင်း အသိပေးလိုပါသည်။ <br><br>\r\n\r\n⏩ ထိုသို့ မိုးကြိုနှမ်းလျင်သီးနှံ စိုက်ပျိုး‌ရေးဆိုင်ရာ လုပ်ငန်းများစွာအနက် မဖြစ်မနေသိရှိဆောင်ရွက်သင့်သည့် အရေးပါသည့်အချက်များကို သိရှိဆောင်ရွက်ခြင်းဖြင့် မိုးကြိုနှမ်းလျင်သီးနှံ စိုက်ပျိုးအောင်မြင်ကြစေလိုကြောင်း ရေးသားတင်ပြအပ်ပါသည်။ <br><br>\r\n\r\nSources : စိုက်ပျိုးရေးရာအကြံပြုချက်များ', '#57FEFF', '18-02-2024'),
(10, 'ပဲမျိုးစုံတွင်ကျရောက်တတ်သော ', 'IMG-65d2350a0928f2.08262620.jpg', '🌿🐛🌿🐛🌿🐛🌿🐛🌿🐛🌿<br><br>\r\n\r\nမြန်မာအမည် - ပွင့်ထွေးရွက်ထွေး (ပဲတောင့်ထိုးပိုး)<br><br>\r\n\r\nအင်္ဂလိပ်အမည် - legumes pod borer၊, Mung moth, Maruca pod borer<br><br>\r\n\r\nသိပ္ပံအမည် - Maruca testulalis<br><br>\r\n\r\n↗️ ကုလားပဲပင်မှလွဲ၍ ပဲတီစိမ်း၊ မတ်ပဲ၊ ပဲလွန်း၊ ပဲစင်းငုံ၊ ပဲပုပ် စသည့် ပဲမျိုးစုံသီးနှံပင်များတွင် ကျရောက်လေ့ရှိပါသည်။ အဖူးအပွင့်ဝင်ချိန်မှစ၍ သီးတောင့်ဝင်ချိန်အထိကျရောက်တတ်ပြီး ပွင့်ထွေးရွက်ထွေးပိုး၊ ပဲသီးထိုးပိုး၊ ပဲဖလံ စသဖြင့် အမျိုးမျိုးခေါ်ကြပါသည်။ ဖလံမများသည်အဖူး၊ အပွင့်များထဲမှာ အုဥပြီး၊ လောက်ကောင်လေးများသည် ပဲအသီးကင်း နှင့် အနီးနားရှိ အသီးရင်းထဲထိပါ ထိုးဝင်စားသောက်တတ်ပါသည်။ နီးစပ်ရာအရွက်၊ အပွင့်၊ အသီးတွေကိုချည်မျှင်နဲ့ထွေးထုပ်ထားတတ်၍ ပွင့်ထွေးရွက်ထွေးပိုး ဟု ခေါ်ကြခြင်းလည်းဖြစ်သည်။<br><br>\r\n\r\nဖျက်ဆီးပုံ လက္ခဏာများ<br>\r\n-------------------<br>\r\nအရွက်၊ အဖူး၊ အပွင့်တိုကို လောက်ကောင်၏ပါးစပ်မှ ထုတ်သောချည်မျှင်ဖြင့်လုံးထွေးလျှက် စားသောက်ဖျက်ဆီးသည်။ ပိုးပေါက်ဖြစ်နေသော အသီးတောင့်ကိုခွဲကြည့်ပါက ပဲစေ့ကို စားသောက်နေသော ပိုလောက်ကောင်ကို တွေ့ရှိရပါသည်။ ယင်းအပေါက်၏ဘေးပတ်လည်တွင် ပိုးလောက်ကောင်စွန့်ပစ်ထားသော ပိုးချေးများကိုတွေ့နိုင်ပါသည်။<br><br>\r\n\r\nဖျက်ပိုး၏ ဝိသေသလက္ခဏာ<br>\r\n-----------------------<br>\r\nလောက်ကောင် - ကိုယ်ခန္ဓာမှာ မီးခိုးဖြူရောင်ရှိပြီး အညိုရောင်ဦးခေါင်းပါရှိသည်။ ခန္ဓာကိုယ် အဆစ်အသီးသီး၏ ကျောဖက်တွင် အနက်ရောင်အစက်ပါရှိသော အစုံနှစ်စုံရှိသည်။<br><br>\r\n\r\nအရွယ်ရောက်ကောင် - ရှေ့တောင်ပံသည် အဖြူရောင်အမှတ်အသားများနှင့်အတူ ညိုနုရောင်ရှိသည်။ နောက်တောင်ပံသည် အရှည်လိုက်အစွန်းပိုင်းတွင် အညိုရောင်အမှတ်အသားများပါရှိပြီး အဖြူရောင်ရှိသည်။\r\n<br><br>\r\n\r\nကာကွယ်နှိမ်နင်းခြင်း<br>\r\n------------------<br>\r\n\r\n▪️ ပိုးချည်နှင့်လုံးထွေးနေသော အပင်အစိတ်အပိုင်းများနှင့် ပိုးကိုက်ရာအပေါက်တွေ့ရှိရသော အသီးတောင့်များကို ခူးယူဖျက်ဆီးပါ။<br><br>\r\n\r\n▪️ ဖလံအမများအုချချိန် (သိုမဟုတ်) လောက်ကောင်များ အပွင့်ထဲမရောက်မီ အဖူးဖူးချိန်တွင် ကြိုတင်ကာကွယ်မှုပြုလုပ်နိုင်ရမည်။<br><br>\r\n\r\n▪️ ပွင့်ထွေးရွက်ထွေးပိုးကျရောက်ခြင်းမှ ကာကွယ်နိုင်ရန် အညွန့်၊ အဖူးမဝင်ချိန်ကတည်းက ဝိစာရ ၏ “အီမာလန်ဒါ၊ နိုက်ဝမ်း၊ အက်စ်ဖိတ်၊ မိုးပျံ၊ လိုင်းအောက်၊ သူရိယ” ပိုးသတ်ဆေးများမှ တစ်မျိုးမျိုးကို ဆေးဗူး/ဆေးထုပ်ပါ အညွှန်းစာအတိုင်း ပက်ဖျန်းအသုံးပြုပေးပါ။ (သိုမဟုတ်) အပင်တစ်ပင်လျှင် ဖျက်ပိုးသုံးကောင်တွေ့ရှိရပါက စီးပွားရေးထိခိုက်နိုင်သောအဆင့်ဖြစ်သည်။ ထိုအချိန်တွင် ဖော်ပြပါဆေးများဖြင့် စတင်ပက်ဖျန်းနှိမ်နင်းပေးရပါမည်။<br><br>\r\n\r\n\r\nSources : ပဲမျိုးစုံတွင်ကျရောက်တတ်သောပိုးမွှားရောဂါများ (PP)', '#ff6763', '18-02-2024'),
(11, '\"စပါးမှိုသီးရောဂါ\" ကြိုတင်ဂရုပြု ကာကွယ်ပါ', 'IMG-65d2358c1b7b36.91664799.jpg', ' 🌾🌾🌾🌾🌾🌾🌾<br><br>\r\n\r\n ✨စပါး အနှံထွက်ချိန်ရောက်ပြီဆိုရင် စပါးမှိုသီးရောဂါဖြစ်လာတတ်ပါတယ်။ အပူချိန် (၂၅ - ၃၅) ဒီဂရီစင်တီဂရိတ် နှင့် လေထုထဲ စိုထိုင်းဆ ၉၀% ကျော်လျှင်အဖြစ်များပါတယ်။ စဖြစ်ခါစမှာဆိုရင် အဝါရောင် နနွင်းမှိုအလုံးတွေအဖြစ်တွေ့ရပြီး နောက်ပိုင်းအမည်းရောင်ပြောင်းသွားပါတယ်။ အဓိကကတော့ ပန်းပွင့်ချိန်မှာ မိုးရွာတာမျိုးဆိုအဖြစ်များပါတယ်။<br><br>\r\n\r\n ✨ဒီစပါးမှိုသီးရောဂါက လေအားဖြင့် ကူးစက်တတ်လို့ ပြန့်နှံ့လွယ်ပြီးပုလဲမြေသြဇာအကျွေးများတဲ့ အခင်းတွေမှာ ပိုမိုဆိုးရွားစွာကျရောက်တတ်ပါတယ်။ စပါးမှိုသီးရောဂါဖြစ်လျှင် စပါးအစေ့အဆံ အထွက်နှုန်းသိသိသာသာကျဆင်းပြီး အစေ့အဆံအလေးချိန်လျော့စေသည်။<br><br>\r\n\r\n \"စပါးမှိုသီးရောဂါ\"ကို ကာကွယ်ကုသရန် နည်းလမ်းများမှာ .....<br><br>\r\n\r\n ✨ရောဂါရအပင်များ၊ အနှံများနှင့် ရိတ်သိမ်းပြီးအပင်အကြွင်းအကျန်များကို ဖယ်ရှားပစ်ပါ။<br><br>\r\n\r\n ✨ရောဂါဒဏ်ခံနိုင်ရည်ရှိသော မျိုးကောင်းမျိုးသန့်ကိုသာ စိုက်ပျိုးပါ။<br><br>\r\n\r\n ✨နိုက်ထရိုဂျင်မြေသြဇာကို လိုတာထက်ပိုမကျွေးရပါ။<br><br>\r\n\r\n ✨ဆေးအသုံးပြုလိုပါက ဝိစာရ ၏ “ဘာလီဆိုဒ်၊နိုက်စ်၊ ဒိုင်ဇီ၊ ဟက်ဇာဂွန်” မှိုသတ်ဆေးတစ်မျိုးမျိုးဖြင့် ကာကွယ်ကုသနိုင်ပါတယ်။<br><br>\r\n\r\n ✨စပါးဖုံးလုံးချိန် အလံရွက်စထွက်ချိန်တွေကတော့ ကြိုတင်ကာကွယ်ဖို့ အရေးအကြီးဆုံး အချိန်တွေဖြစ်ပါတယ်။ ဦးကြီးတို့၏စပါးခင်းများ ဖျက်ပိုး နှင့် ရောဂါကင်းစင်ပြီး သီးနှံများ အရည်အသွေးကောင်း၍ အထွက်တိုးကြပါစေ။\r\n\r\n ', '#ffffc2', '18-02-2024'),
(12, '“ဂျုံပင် စိုက်ပျိုးနည်း”  ', 'IMG-65d235d852f0f2.73564677.jpg', '🎋🎋🎋🎋🎋🎋🎋🎋🎋🎋<br><br>\r\n\r\n▶️ ဂျုံသည် ကောက်ပဲသီးနှံပင်တစ်မျိုးဖြစ်ပါသည်။ ဂျုံတွင် အသားဓာတ်နှင့် ကာဗွန်ဟိုက်ဒရိတ်ဓာတ်များစွာ ပါဝင်နေပါသည်။ ဂျုံသီးနှံသည် ပြောင်းနှင့်စပါးပြီးလျှင် စိုက်ပျိုးထုတ်လုပ်မှု တတိယအများဆုံးသီးနှံဖြစ်ပါသည်။ ဂျုံသီးနှံကို ယခုအခါတွင် ကမ္ဘာတစ်ဝန်း၌ စိုက်ပျိုး ထုတ်လုပ်နေကြပါသည်။ ဂျုံကို မြန်မာနိင်ငံတွင် ကျယ်ကျယ်ပြန့်ပြန့် စိုက်ပျိုးခြင်းမရှိပါ။ စစ်ကိုင်း၊ မန္တလေးနှင့် ရှမ်းပြည်နယ်တို့တွင် အနည်းငယ်စိုက်ပျိုးကြပါသည်။ ပြည်တွင်းစားသုံးရန် အတွက်သာရရှိပါသည်။<br><br>\r\n\r\nမူရင်းဒေသ<br>\r\n--------<br>\r\n\r\nဂျုံ၏မူရင်းဒေသမှာ တူရကီနိုင်ငံ အရှေ့တောင်ဘက်ပိုင်းရှိ တောင်တန်းဒေသများဖြစ်သည် ဟု သိရှိရပါသည်။<br><br>\r\n\r\nမြေမျက်နှာသွင်ပြင်နှင့် ရာသီဥတု <br>\r\n-----------------------------<br>\r\n\r\nဂျုံပင်သည် ပင်လယ်ရေမျက်နှာပြင်အထက် ပေ ၁၀,၀၀၀ ရှိသော ဒေသများတွင် အများဆုံး စိုက်ပျိုးဖြစ်ထွန်းပါသည်။ နှစ်စဥ် မိုးရေချိန် ၁၀ လက်မ မှ ၄၀ လက်မ အတွင်းရှိပြီး မြေဆီသြဇာ ကြွယ်ဝသောဒေသများတွင် ကောင်းစွာဖြစ်ထွန်းပါသည်။ နွေရာသီတွင် စိုက်ပျိုးသော ဂျုံသီးနှံအတွက် အသင့်တော်ဆုံး အပူချိန်မှာ ၂၂ ဒီဂရီစင်တီဂရိတ် မှ ၃၄ ဒီဂရီစင်တီဂရိတ်အတွင်း ဖြစ်ပါသည်။ ဆောင်းရာသီတွင်စိုက်ပျိုးသော ဂျုံသီးနှံအတွက် အသင့်တော်ဆုံး အပူချိန်မှာ ၅ ဒီဂရီစင်တီဂရိတ် မှ ၂၅ ဒီဂရီစင်တီဂရိတ်အတွင်း ဖြစ်ပါသည်။ ဂျုံစိုက်ပျိုးရာတွင် အစေ့အဆန် ဖြည့်တင်းရန်အတွက် နေရောင်ခြည်အပြည့်အဝရရှိရန် လိုအပ်ပါသည်။<br><br>\r\n\r\nစိုက်ပျိုးသောနည်းစနစ်များ <br>\r\n----------------------<br>\r\n\r\nဂျုံစိုက်ပျိုးရာတွင် ကြဲပက်စိုက်ပျိုးခြင်း၊ ထယ်ထိုးပြီးချစိုက်ခြင်း၊ စိုက်ကြောင်းဆွဲ၍မျိုးစေ့ချစိုက်ခြင်းနှင့် ဆူးထိုးစိုက်ပျိုးခြင်း စသည့် စိုက်ပျိုးနည်းများဖြင့် စိုက်ပျိုးကြပါသည်။<br><br>\r\n\r\nမြေအမျိုးအစား <br>\r\n-----------<br>\r\n\r\nနုန်းမြေအမျိုးအစားသည် ဂျုံစိုက်ပျိုးရန်အတွက် အသင့်တော်ဆုံး ဖြစ်ပါသည်။ ဂျုံစိုက်ပျိုးရန်အတွက် အသင့်တော်ဆုံး မြေချဥ်ငံကိန်းမှာ ၆.၄ ဖြစ်ပါသည်။ အေးသောဒေသများတွင် ဂျုံစိုက်ပျိုးရန်အတွက် အသင့်တော်ဆုံး မြေချဥ်ငံကိန်းမှာ ၅.၅ မှ ၇.၅ အတွင်း ဖြစ်ပါသည်။<br><br>\r\n\r\nစိုက်ပျိုးခြင်းနှင့် အပင်ပြုစုခြင်း<br>\r\n--------------------------<br>\r\n\r\nဂျုံစိုက်ပျိုးရန်အတွက် အသင့်တော်ဆုံးကာလမှာ အောက်တိုဘာလနှောင်းပိုင်း နှင့် နိုဝင်ဘာလ အစောပိုင်းဖြစ်ပါသည်။ မိုးရေ၏အစိုဓာတ်ကို အမိအရစိုက်ပျိုးပါက အောက်တိုဘာ (၁၅ မှ ၃၀) အတွင်း စိုက်ပျိုးနိုင်ပါသည်။ ရေသွင်းစိုက်ပျိုးပါက နိုဝင်ဘာ (၁ မှ ၁၅) အတွင်း စိုက်ပျိုးနိုင်ပါသည်။ မြန်မာနိုင်ငံရှိ တောင်သူများမှာ နိုဝင်ဘာ (၁၅ မှ ၃၀) အတွင်း စိုက်ပျိုးကြပါသည်။ မိုးရေ၏အစိုဓာတ်ဖြင့် အမိအရ ဖမ်းကာ စိုက်လိုသောဒေသများတွင် မြေအနက် ၃.၄ လက်မမှ ၄ လက်မအတွင်း စိုက်ပျိုးနိုင်ပါသည်။ ရေသွင်းစိုက်ပျိုးလိုသောဒေသများတွင် မြေအနက် ၁.၃ လက်မ မှ ၂.၁ လက်မအတွင်း စိုက်ပျိုးနိုင် ပါသည်။ မိုးရေ၏အစိုဓာတ်ဖြင့် စိုက်ပျိုးပါကမျိုးစေ့နှုန်းထား ၁ဧကလျှင် ၁တင်းခွဲ အသုံးပြုကြပြီး ရေသွင်းစိုက်ပျိုးပါက ၁ ဧကလျှင်( ၂ )တင်း အထိ အသုံးပြုကြပါသည်။ စိုက်ပျိုးပြီး(၂၅) ရက်သားတွင် တစ်ကြိမ်၊ (၄၅)ရက်သားတွင် တစ်ကြိမ်၊ (၆၀)ရက်သားတွင်တစ်ကြိမ် ရေသွင်းပေးရမည်ဖြစ်ပါသည်။ စိုက်ပျိုးပြီး (၂၅) ရက်သားနှင့် (၄၅)ရက်သားတို့တွင် ပေါင်းမြက်ကင်းရှင်းစေရန်အတွက်ကြားပေါင်းလိုက်ရမည် ဖြစ်ပါသည်။<br><br>\r\n\r\nမြေသြဇာကျွေးခြင်း <br>\r\n---------------<br>\r\n\r\nဂျုံမစိုက်ပျိုးမီ ရက်သတ္တပတ် (၄)ပတ်မှ (၆)ပတ်ခန့်ကတည်းကကြိုတင်၍ သဘာဝမြေသြဇာများကို ထည့်သွင်းထားရမည်ဖြစ်ပါသည်။ ယူရီးယားမြေသြဇာကို (၁)ဧကလျှင် (၁)အိတ်နှုန်း အသုံးပြုရမည် ဖြစ်ပါသည်။ ယူရီးယားမြေသြဇာ၏ အိတ်ဝက် (သို့မဟုတ်) ၃ ပုံ ၂ ပုံအား စစိုက်ချိန်ကတည်းက ထည့်သွင်းနိုင်ပါသည်။ ကျန်တစ်ဝက် (သို့မဟုတ်) ၃ ပုံ ၁ ပုံအား ပထမဆုံးအကြိမ် ရေသွင်းချိန်၌ ထည့်သွင်းရမည် ဖြစ်ပါသည်။ တီစူပါနှင့် ပိုတက်မြေသြဇာများကို (၁)ဧကလျှင် အိတ်တစ်ဝက်နှုန်း အသုံးပြုပေးရမည်ဖြစ်ပြီး သီးနှံစစိုက်သည့်အချိန်ကတည်းက ထည့်သွင်းနိုင်ပါသည်။ <br><br>\r\n\r\nပိုးမွှား နှင့် ရောဂါ ကာကွယ်နှိမ်နင်းခြင်း<br>\r\n----------------------------------<br>\r\n\r\nဂျုံပင်တွင်ကျရောက်ဖျက်စီးလေ့ရှိသော ဖျက်ပိုးများမှာ ပျ၊ ငမြောင်တောင်၊ ခြ စသည်တို့ဖြစ်ပြီး ရောဂါများအနေဖြင့် သံချေးရောဂါနှင့် ကြပ်ခိုးမှိုရောဂါများ ကျရောက်လေ့ရှိပါသည်။ ဖော်ပြပါ ပိုး၊ ရောဂါများအတွက် ရောဂါဒဏ်ခံနိုင်ရည်ရှိသောမျိုးများဖြင့် အစားထိုးစိုက်ပျိုးခြင်း နှင့် ဓာတုဆေးဖြင့်ကာကွယ်နှိမ်နင်းရန် ပျပိုးအတွက် “ကေလာ၊ ဆိုင်လာ”၊ ငမြှောင်တောင်ပိုးအတွက် “နိုက်ဝမ်း၊ အီမာလန်ဒါ”၊ ခြ နှင့် မြေတွင်းအောင်းပိုးများကာကွယ်ရန် “ဒီပါ” ဆေးခဲများကို အသုံးပြုပေးရပါမည်။ မှိုရောဂါများကာကွယ်နှိမ်နင်းရန်အတွက် “ဟက်ဇာဂွန်၊ ဘင်ဇိုကာ” ဆေးများကို အသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\nရိတ်သိမ်းခြင်း <br>\r\n---------<br>\r\n\r\nဂျုံပင်၏ ရိုးတံနှင့် အနှံများ အဝါရောင်ပြောင်းချိန် (သို့မဟုတ်) စိုက်ပြီး ရက်(၉၀ မှ ၁၁၅) ရက်သားခန့် ရောက်လျှင် ရိတ်သိမ်းနိုင်ပြီဖြစ်ပါသည်။ တစ်နည်းအားဖြင့် အနှံအားလုံး (၈၀) ရာခိုင်နှုန်းရင့်မှည့်ချိန်တွင် ရိတ်သိမ်းနိုင်ပါသည်။', '#addfff', '18-02-2024'),
(13, '\"နှင်းဆီပင်တွင်ကျရောက်သော ရောဂါများနှင့် ကာကွယ်နှိမ်နင်းနည်းများ\"', 'IMG-65d23627b33c64.03820964.jpg', '🌹🌹🌹🌹🌹🌹🌹🌹🌹🌹<br><br>\r\n\r\n🔸နှင်းဆီပင်ကို မြန်မာနိုင်ငံသာမက နိုင်ငံတကာတွင်စိုက်ပျိုးကြပြီး နှင်းဆီပန်းကိုလည်း လူသားအားလုံး အမြတ်တနိုး တန်ဖိုးထားနှစ်ခြိုက်ကြသည်။ စီးပွားဖြစ်စိုက်ပျိုးထုတ်လုပ်မှုမှ အိမ်တွင်း ခြံဝန်းတွင်း တစ်ပိုင်တစ်နိုင် စိုက်ပျိုးမှုအထိရှိပြီး ဝင်ငွေရရှိရုံမျှမကပဲ စိုက်ပျိုးသူတို့၏စိတ်ကို ကြည်လင်လန်းဆန်းမှု ဖြစ်စေသည်။ ထိုသို့စိုက်ပျိုးမှုများပြားသော နှင်းဆီပင်တွင် ကျရောက်တတ်သော နှင်းဆီရောဂါများနှင့် ကာကွယ်နှိမ်နင်းရန်နည်းလမ်းများကို ဗဟုသုတရရှိနိုင်ပါရန်စုစည်းတင်ပြလိုက်ပါသည်။<br><br>\r\n\r\n(၁) နှင်းဆီရွက်ပြောက်ရောဂါ<br><br>\r\n\r\nအနက်ရောင်အကွက်အပြောက်များ ဖြစ်ပေါ်သောကြောင့် နှင်းဆီအနက်ပြောက်ရောဂါ ဟုလည်း ခေါ်ကြသည်။ စိုက်ပျိုးရာဒေသအနှံ့အပြားတွင် ဖြစ်ပေါ်လေ့ရှိပြီး အရေးအကြီးဆုံးနှင့် အဖြစ်အများဆုံးမှိုရောဂါ ရောဂါတစ်မျိုးဖြစ်သည်။ ရောဂါဖြစ်စေသောသက်ရှိမှာ Diplocarpon rosaea ဖြစ်သည်။ မြေစိုစွတ်သောရာသီတွင် အဖြစ်များပြီး မိုးများသောဒေသများနှင့် တောင်ပေါ်ဒေသများတွင် ရောဂါအထူးပြင်းထန်တတ်သည်။ အပူချိန်(၆၅)ဒီဂရီဖာရင်ဟိုက်တွင် မှိုစပိုးပေါက်ပွားမှုရှိပြီး အပူချိန်(၇၅) ဒီဂရီဖာရင်ဟိုက်တွင် ရောဂါလျင်မြန်စွာ ပြန့်ပွားစေနိုင်ပါသည်။ ၎င်းအခြေအနေတွင် အပင်ကြီးထွားမှုကို ရပ်တန့်စေပြီး ပန်းပွင့်မှုနှုန်းကျဆင်းစေပါသည်။ ရောဂါပြင်းထန်ပါက အရွက်အားလုံးဆုံးရှုံးပြီး အပင်သေစေနိုင်သည်။<br><br>\r\n\r\n ရောဂါလက္ခဏာ .....<br><br>\r\n\r\n နှင်းဆီအရွက်၏အထက်နှင့် အောက်မျက်နှာပြင်ပေါ်တွင် အနက်ရောင်စက်ဝိုင်းပုံ အစက်အပြောက် (၁ စင်တီမီတာအချင်းခန့်) များတွေ့ရမည်။ ရောဂါနုစဉ်တွင်အစက်အပြောက်အနားများသည် ပန်းဖွားကဲ့သို့ မညီမညာဖြစ်နေပြီး ရောဂါရင့်ချိန်တွင်အနားသတ်များတိကျထင်ရှားလာပါသည်။ ရောဂါရင့်လာပါက အရွက်မှာ အဝါရောင်ပြောင်းလာပြီး အရွက်မရင့်ပဲကြွေကျတတ်ပါသည်။ ရောဂါလက္ခဏာကို ပင်စည်၊ အညွှန့်နှင့် ပွင့်ညှာများပေါ်တွင်လည်း တွေ့ရတတ်သည်။ အပွင့်ကြွေခြင်း၊ အညွှန့်ခြောက်ခြင်း အပင်သေခြင်းထိဖြစ်နိုင်ပါသည်။<br><br>\r\n\r\n ကာကွယ်နှိမ်နင်းနည်းများ.....<br><br>\r\n\r\n▪️ ခံနိုင်ရည်ရှိသောမျိုးကိုရွေးပါ။<br><br>\r\n\r\n▪️ ရောဂါကျရောက်နေသော အရွက်များ၊ အကိုင်းများကို ဖယ်ထုတ်ရှင်းလင်းပါ။ မီးရှို့ပါ။ လေဝင်လေထွက်ကောင်းအောင်ပြုလုပ်ပါ။<br><br>\r\n\r\n▪️ အပင်ခြေတွင် ပိုတက်ရှ်ထည့်ပေးပြီး၊ ရေလောင်းခြင်းကို နံနက်ပိုင်းတွင် အပင်ခြေလောင်းခြင်း ပြုလုပ်ပါ။\r\n<br><br>\r\n\r\n▪️ ဓာတုဆေးဖြင့်နှိမ်နင်းရန် “ဒိုင်ကိုဇက်၊ တိုက်တန်၊ ဆာဗိတ်” မှိုသတ်ဆေးတစ်မျိုးမျိုးကို ဆေးညွှန်းအတိုင်း အသုံးပြုပက်ဖျန်းပေးပါ။<br><br>\r\n\r\n(၂) ဖားဥမှိုရောဂါ<br><br>\r\n\r\nအဖြူရောင်အမှုန့်များကပ်နေသော ပြင်းထန်သည့် မှိုရောဂါတစ်မျိုးဖြစ်သည်။ ရောဂါဖြစ်စေသောသက်ရှိမှာ Sphaerotheca pannosa var ဖြစ်သည်။ အပူချိန် (၇၀ - ၈၀) ဒီဂရီဖာရင်ဟိုက်ရှိပြီး ညအချိန်စိုထိုင်းဆမြင့်မားပြီး နေ့ပိုင်းတွင်စိုထိုင်းဆကျဆင်းတတ်သည့် ဒေသများတွင် အချိန်မရွေးဖြစ်ပွားနိုင်ပါသည်။ အထူးသဖြင့် အရိပ်ရသည့်ဒေသနှင့် အေးသော ကာလများမှာ အများဆုံးဖြစ်ပွားသည်။ အပင်တွင်ရောဂါကျရောက်ပါက ပန်းပွင့်မှုနှုန်းကျဆင်းပြီး ပန်းပွင့်ပါက အရည်အသွေးမမှီသောအပွင့်များဖြစ်စေနိုင်သည်။<br><br>\r\n\r\nရောဂါလက္ခဏာ.....<br><br>\r\n\r\n အရွက်များ၏မျက်နှာပြင်များနှင့် အညွှန့်များပေါ်တွင် ပေါင်ဒါမှုန့်ကဲ့သို့ အဖြူရောင်အမှုန့်များ တွေ့ရပေမည်။ ရောဂါပြင်းထန်လာသည်နှင့်အမျှ တစ်ရွက်လုံး အဖြူရောင်အမှုန့်များ ဖုံးလွှမ်းသွား ပါသည်။ ရောဂါကျသောအရွက်မှာပုံစံများပျက်နေပြီး အရွက်များကြွေကျလာပါသည်။ အပင်ထိပ်ပိုင်းတွင် ရောဂါပို၍ကျရောက်တတ်သည်။<br><br>\r\n\r\nကာကွယ်နှိမ်နင်းနည်းများ.....<br><br>\r\n\r\n▪️ ခံနိုင်ရည်ရှိသောမျိုးကိုရွေးပါ။<br><br>\r\n\r\n▪️ ရောဂါကျရောက်နေသော အရွက်များ၊ အကိုင်းများဖယ်ထုတ်ရှင်းလင်းပါ။<br><br>\r\n\r\n▪️ “ဟက်ဇာဂွန်၊ ဒိုင်ဇီ၊ ဇိုလာ၊ ကာဗာ” ဆေးများမှတစ်မျိုးမျိုးကို ဆေးညွှန်းပါအတိုင်းသုံးစွဲနိုင်ပါသည်။<br><br>\r\n\r\n(၃) ကိုင်းဖျားခြောက်ရောဂါ<br><br>\r\n\r\n ကိုင်းများဖြတ်တောက်ရာတွင်အသုံးပြုသောစိုက်ပျိုးရေးသုံးပစ္စည်း(ကိုင်းဖြတ်ကတ်ကြေး)များမှတစ်ဆင့် ရောဂါဝင်၍သော်လည်းကောင်း၊ ပိုးမွှားကျရောက်မှုမှတစ်ဆင့်သော်လည်းကောင်း၊ အပင်အာဟာရဓာတ် ချို့တဲ့လျှင်သော်လည်းကောင်း ရောဂါဖြစ်ပွားတတ်ပါသည်။<br><br>\r\n\r\nရောဂါလက္ခဏာ..... <br><br>\r\n\r\n အပင်အဖျားပိုင်းမှစတင်ကာ အရင်းဘက်သို့ တဖြည်းဖြည်းခြောက်လာပြီး အမြစ်ပါသေ၍ နောက်ဆုံးတွင် အပင်သေဆုံးစေနိုင်ပါသည်။ <br><br>\r\n\r\nကာကွယ်နှိမ်နင်းနည်းများ..... <br><br>\r\n\r\n▪️ မြေကို ကောင်းစွာပြုပြင်ပြီးမှ စိုက်ပါ။ <br><br>\r\n\r\n▪️ နွေရာသီတွင် စိုက်ပျိုးပါက အပင်ခြေကို ကောက်ရိုး၊ မြက်ခြောက်ဖုံးပေးပါ။ <br><br>\r\n\r\n▪️ ကိုင်းဖြတ်ကတ်ကြေးများ အသုံးမပြုမှီ ရေဆေးခြင်း၊ ပိုးသတ်ခြင်းများပြုလုပ်ပါ။ ကိုင်းဖြတ်ပြီးသောနေရာအား ထုံးတို့ပါ။ <br><br>\r\n\r\n▪️ ရောဂါကျရောက်ပါက ရောဂါရအပိုင်းမှ အကွာအဝေး ၅ စင်တီမီတာခန့်ထိ ဖြတ်ပြီး ကျူပရိုမက်စ် မှိုဆေးရည်သုတ်လိမ်းပေးပါ။ <br><br>\r\n\r\n(၄) သံချေးရောဂါ<br><br>\r\n\r\nလေမှတစ်ဆင့်ကူးဆက်သော မှိရောဂါတစ်မျိုးဖြစ်သည်။ Phragmidium မှိမျိုးစိတ်ကြောင့် ဖြစ်ပွားခြင်းဖြစ်သည်။ သံချေးရောဂါသည် အပင်၊ အမြစ် နှင့် ပွင့်ချပ်များမှလွဲ၍ ကျန်အပင် အစိတ်အပိုင်းများတွင် ဖြစ်ပွားနိုင်ပါသည်။ ရောဂါပြင်းထန်ပါက အရွက်များဝါပြီး ကြွေကျသွားသည်။ <br><br>\r\n\r\nရောဂါလက္ခဏာ..... <br><br>\r\n\r\nရောဂါကျရောက်ပါက ပင်စည်နှင့် အရွက်များပေါ်တွင် လိမ္မော်ရောင်အစက်အပြောက်များ တွေ့ရတတ်သည်။ ရောဂါဆိုးရွားလာပါက လိမ္မော်ရောင်အမှုန့်များကို ပင်ခြေနားတွင်ပါတွေ့ရမည်။ <br><br>\r\n\r\nကာကွယ်နှိမ်နင်းနည်းများ..... <br><br>\r\n\r\n▪️ လေဝင်လေထွက်ကောင်းအောင်ပြုလုပ်ပါ။ <br><br>\r\n\r\n▪️ အရွက်များ အမြဲစိုစွတ်နေခြင်းကို ရှောင်ရှားပါ။ <br><br>\r\n\r\n▪️ ရောဂါရအရွက်များကို ဖယ်ရှားပါ။ မီးရှိပါ။ <br><br>\r\n\r\n▪️ နှင်းဆီသံချေးရောဂါကို ကာကွယ်နှိမ်နင်းရန် “ဇိုလာ၊ ဒိုင်ဇီ၊ ဆာဗိတ်” ဆေးများမှ တစ်မျိုးမျိုးကို ပက်ဖျန်းအသုံးပြုပေးနိုင်ပါသည်။ <br><br>\r\n\r\n(၅) အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါ<br><br>\r\n\r\nဗိုင်းရပ်စ်ရောဂါဖြစ်သောကြောင့် ကုသဆေးမရှိပါ။ ဆောင်းရာသီတွင် အဖြစ်များတတ်သည်။ ရောဂါပိုးသယ်ဆောင်တတ်သော လှေး၊ ပျ၊ ယင်ဖြူများကျရောက်မှုမရှိအောင် ကြိုတင်၍ သတိထား ကာကွယ်ပါ။ \r\n<br><br>\r\n\r\nရောဂါလက္ခဏာ..... <br><br>\r\n\r\nအရွက်များပေါ်တွင် အဝါရောင်လှိင်းများ၊ အဝါစက်များတွေ့ရပါသည်။ နှင်းဆီအပင်သည် ပုနေပြီး အပင်အရပ်မရှည်လာတော့ပါ။ <br><br>\r\n\r\nကာကွယ်နှိမ်နင်းနည်းများ..... <br><br>\r\n\r\n▪️ ခံနိုင်ရည်ရှိသောမျိုးကို ရွေးချယ်ပါ။ <br><br>\r\n\r\n▪️ ရောဂါရအပင်များအား ရှင်းလင်းမီးရှိပါ။ <br><br>\r\n\r\n▪️ လှေး၊ ပျ၊ ယင်ဖြူနှင့် စုပ်စားပိုးများကို ကြိုတင်ကာကွယ်နိုင်ရန် “ကေလာ၊ နိုးဝမ်း” ဆေးများမှ တစ်မျိုးမျိုးဖြင့်ကြိုတင်ပက်ဖျန်းကာကွယ်ပေးရပါမည်။<br><br>\r\n\r\n(၆) နှင်းဆီမြစ်ဖုရောဂါ <br><br>\r\n\r\nAgrobacterium tumefaciens ဘက်တီးရီးယားကြောင့်ဖြစ်သော ရောဂါတစ်မျိုးဖြစ်သည်။ ၎င်းရောဂါဖြစ်စေသောသက်ရှိသည် မြေထဲတွင် (၁၅-၂၀) နှစ်အထိ အသက်ရှင်သန်နိုင်ပါသည်။ အမြစ်မှာ အဖုများဖြစ်သောကြောင့် ရေနဲ့အစာစုပ်ယူမှုကို နည်းပါးစေပြီး အပင်အာဟာရ ချိုတဲ့စေတတ်ပါတယ်။ ဤရောဂါဖြစ်ပွားဖူးသောနေရာတွင် နှင်းဆီကို အနည်းဆုံး ငါးနှစ်ခန့်ကြာမှ စိုက်ပျိုးသင့်သည်။ <br><br>\r\n\r\nရောဂါလက္ခဏာ..... <br><br>\r\n\r\nအပင်ပေါ် (သို) မြေဆီလွှာမျက်နှာပြင်အောက်တွင် အဖုများ၊ ရောင်ရမ်းခြင်းများဖြစ်ပေါ်တတ်ပါသည်။ ထိုအပြင် အပင်ပုခြင်းလည်း ဖြစ်ပွားတတ်သည်။ <br><br>\r\n\r\nကာကွယ်နှိမ်နင်းနည်းများ..... <br><br>\r\n\r\n▪️ ခံနိုင်ရည်ရှိသောမျိုးကိုရွေးချယ်ပါ။ <br><br>\r\n\r\n▪️ အပင်တွင် gall(အဖု)များတွေ့ပါက ၎င်းအပင်များကိုဖယ်ရှားပစ်ပါ။ <br><br>\r\n\r\n▪️ ကိုင်းဖြတ်ရာတွင်အသုံးပြုသော ကတ်ကြေးများအား ပိုးသန့်ပြီးမှ အသုံးပြုပါ။ <br><br>\r\n\r\nSources : ပန်းမန်ပင်များတွင်ဖြစ်ပွားသောရောဂါများ<br><br>', '#57feff', '18-02-2024');
INSERT INTO `knowledge` (`kid`, `knowledgeTitle`, `knowledgePhoto`, `knowledgeDescript`, `knowledgeColor`, `CurrentDate`) VALUES
(14, 'နွေစပါးအထွက်နှုန်းကောင်းရန် ဂရုပြုရမည့်အချက်များ', 'IMG-65d2374853a832.49907380.jpg', '🌾🌾🌾🌾🌾🌾🌾🌾🌾🌾<br><br>\r\n\r\n⏩မြန်မာနိုင်ငံတွင် နွေစပါးကို ၁၉၉၂ ခုနှစ်မှ စတင်စိုက်ပျိုးခဲ့ပြီး ၂၀၁၂ ခုနှစ်တွင် နွေစပါးစိုက်ဧက သုံးသန်းကျော်ထိ စိုက်ပျိုးလာနိုင်ခဲ့ပါသည်။ စတင်စိုက်ပျိုးခဲ့သည့်နှစ်များမှကြည့်လျှင် ယခုနှစ်ပိုင်းများတွင် စပါးအထွက်နှုန်း တန့်လာသည်ကိုတွေ့ရှိရသည်။ နွေစပါးသည် စိုက်ပျိုးနည်းစနစ်၊ မျိုးကောင်းမျိုးသန့်စိုက်ပျိုးခြင်း၊ စိုက်ချိန်မှန်အောင်စိုက်ပျိုးခြင်း စသည့်အခြေအနေကောင်းများတွင် နေရောင်ခြည်၊ ရေအလုံအလောက်ရရှိပါက တစ်ဧက တင်းတစ်ရာကျော်ထိ ထွက်ရှိနေသည်မှာ ငြင်းဖွယ်ရာမရှိပေ။<br><br>\r\n\r\n⏩ယခုအခါ နွေစပါးအထွက်နှုန်းများတန့်နေသည်။ အချို့နေရာများတွင် ကျဆင်းနေသည့် အခြေအနေများပင်ကြုံနေရသည်ကို တွေ့မြင်နေရပေသည်။ သို့ဖြစ်၍ သုံးသပ်လေ့လာကြည့်လျှင် စိုက်ပျိုးနည်းစနစ်၊ မျိုး၊ ရေမြေအခြေအနေများ ချို့ယွင်းချက်ရှိလာခြင်းကြောင့်ဖြစ်ရသည်ကို တွေ့မြင်နေရသည်။<br><br>\r\n\r\n⏩မိုးစပါးရိတ်သိမ်းပြီး နွေစပါးစိုက်ပျိုးရာတွင် ရိုးပြတ်မီးရှို့၊ ချက်ချင်းရေတင် မြေပြင်၍ မစိုက်ပျိုးသင့်ပေ။ မိုးစပါးရိတ်သိမ်းပြီး မြေအနေတော် ခြောက်သွားအောင် (ပတ်ကြားအက်ကာစ အခြေအနေထိ) တစ်ပတ်၊ နှစ်ပတ်ခန့် အခြောက်လှန်းထားရန် လိုအပ်ပါသည်။ ရိုးပြတ်ကို မီးမရှို့သင့်ပါ၊ ရိုးပြတ်မီးရှို့ပါက နိုက်ထရိုဂျင်ဓာတ်အားလုံး၊ ဖော့စဖရပ်ဓာတ် ၂၅ ရာခိုင်နှုန်း၊ ပိုတက်စီယမ်ဓာတ် ရာခိုင်နှုန်း ၂၀၊ ဆာလ်ဖာဓာတ် ငါးရာခိုင် နှုန်းမှ ရာခိုင်နှုန်း ၆၀ နှင့် သွပ်ဓာတ်၊ ဆီလီကာဓာတ်များလည်း ဆုံးရှုံးသွားစေပါသည်။<br><br>\r\n\r\n⏩မြေနှင့်ရိုးပြတ်ကို တစ်ပတ်၊ နှစ်ပတ်ခန့် နေပူလှန်းပြီးပါက ဓားစက်၊ သို့မဟုတ် ကွင်းစက်ဖြင့် အလျားလိုက်၊ အနံလိုက် နှစ်စပ်ခန့်မောင်းပေးပါက ရိုးပြတ်များကျိုးကြေပိပြားသွားပါသည်။ ၎င်းအခြေအနေရောက်မှသာ ၁၆ သွားထွန်စက်ကြီး နှစ်စပ်၊ သို့မဟုတ် ထယ်တစ်စပ်ထိုးပြီး ရေသွင်း၍ မြေကို တစ်ပတ်ခန့်နှပ်ထားရန်လိုပါသည်။ ထွန်၊ ထယ်မထွန်မီ နွားချေး၊ သဘာဝမြေ ဆွေး၊ စက်ဖွဲပြာ၊ ထုံး၊ ကျောက်မှုန့်မြေသြဇာများကို ကြိုတင်ထည့်ထားရန် ဖြစ်ပါသည်။<br><br>\r\n\r\n⏩ရေသွင်း၍ တစ်ပတ်ခန့်နှပ်ထားသဖြင့် ထွန်၊ ထယ်စာခဲများ နူးသွားစေပြီး တမန်းကောင်းရရှိစေရန် အထောက်အကူ ပြုပါသည်။ ၎င်းပြင် ပေါင်းစေ့များ၊ မြက်ခေါင်းများ၊ စပါးအလေအလွင့်ပင်များ ပေါက်ရောက်ဆွေးမြေ့ပြီး၊ ပေါင်းမြက်ကင်းစင်ခြင်း၊ မျိုးသန့်ထိမ်းသိမ်းခြင်းအတွက် အကျိုးပြုစေပါ သည်။<br><br>\r\n\r\n⏩မိုးစပါးအပြီး နွေစပါးစိုက်ပျိုးသော ဒေသများတွင် သီးနှံဆက်တိုက် စိုက်ပျိုးလာရသဖြင့် စပါးပင်က ထုတ်နုတ်စားသုံး၍ ကုန်းခန်းသွားသော အာဟာရဓာတ်များကို မြေတွင်းသို့လုံလောက်အောင် ပြန်လည်ဖြည့်ဆည်းမပေးကြသဖြင့် မြေပျက်သုဉ်းစေပြီး၊ မြေကန်းသွားရသည့် အဓိကပြဿနာများဖြင့် ကြုံတွေ့နေကြရသည်။ တစ်နေရာတည်းတွင် သီးနှံတစ်မျိုးတည်း ဆက်တိုက်စိုက်ပျိုးလာပါက စတုတ္ထနှစ်မှစ၍ စပါးအထွက်နှုန်းကျဆင်းလာကြောင်း ရေဆင်းစိုက်ပျိုးရေးသုတေသနဦးစီးဌာနမှ သုတေသနပြုချက်များအရ သိရပါသည်။ <br><br>\r\n\r\n⏩အထွက်နှုန်းကျဆင်းမှုသည် ယူရီးယား၊ တီစူပါ၊ ပိုတက်ရှ် ဓာတ်မြေသြဇာများကိုသာ အသုံးပြုပါက လျော့ကျမှုမြန်စေပြီး၊ နွားချေးတစ်ဧက ငါးတန်နှုန်း (သို့မဟုတ်) ဂျစ်ပဆန်မြေသြဇာတစ်ဧက ပေါင် ၁၀၀ နှုန်းတွဲဘက်အသုံးပြုပါက အထွက်နှုန်းသိသာစွာလျော့ကျမှုမရှိကြောင်း ရေဆင်းစိုက်ပျိုးရေးသုတေသန ဦးစီးဌာန၏ ရှစ်နှစ်တာစမ်းသပ်ချက်များအရ တွေ့ရှိထားပါသည်။ နွေစပါးစိုက်လယ်မြေများသို့ မြေဆွေး၊ နွားချေး၊ အပင်အကြွင်းအကျန်၊ ဖွဲ၊ ဆန်ကွဲ၊ ကောက်မှော်၊ နှမ်းမှော်၊ ပြောင်းရိုး၊ မြေဆွေး စသည်များ အလုံအလောက်ထည့်ပေးရမည်မှာ အလွန်သတိပြုရမည့်အချက်ဖြစ်ပါသည်။<br><br>\r\n\r\n⏩နွေစပါးစိုက်ပျိုးရာတွင် အထူးသတိပြုရမည့် အချက်တစ်ချက်မှာ မျိုး ကိစ္စဖြစ်ပါသည်။ ယခုမြင်တွေ့နေရသည်မှာ နွေစပါးစိုက်ခင်းများတွင် စပါးမျိုးများမသန့်တော့ဘဲ စပါးနှစ်ထပ်ဖြစ်နေခြင်း၊ အပင်များအနိမ့် အမြင့်မညီခြင်း၊ ပေါင်းမြက်ထူပြောခြင်းများပင် ဖြစ်ပါသည်။ မူလအထွက်နှုန်းနှင့် ဗီဇအရည်အသွေးများကို သွေဖီ၍ အရည်အချင်းများကျလာခြင်း၊ မူလအထွက်နှုန်းဗီဇကို ပြည့်မီအောင် မထွက်တော့ခြင်းများ ဖြစ်ပေါ်နေပါသည်။ <br><br>\r\n\r\n⏩ရေဆင်းစိုက်ပျိုးရေးသုတေသနဦးစီးဌာနမှ မွေးမြူထုတ်လုပ်ပေး၍၊ နယ်ခြံများတွင် မျိုးသန့်ပွားများထားသော မျိုးကောင်း မျိုးသန့် အဆင့် (၁)၊ မျိုးကောင်းမျိုးသန့်အဆင့်(၂) မျိုးများကို မဖြစ်မနေရယူ၍ သွေးသစ်လောင်း အစားထိုးပြောင်းလဲစိုက်ပျိုးရန်လိုအပ်ပါသည်။ တောင်သူလယ်သမားများ အနေဖြင့် မိမိရှိပြီးသားမျိုးကို တယူသန်စွဲ၍ မစိုက်ပျိုးသင့်ကြပေ။ စပါးမျိုးသန့်ကို အသုံးပြုပါက အခြေခံပန်းတိုင်အထွက်နှုန်းထက် (၂၀ - ၂၅)ရာခိုင်နှုန်းအထိ ပိုမိုထွက်ရှိနိုင်သည်ကို အလေးမူသင့်ကြပါသည်။<br><br>\r\n\r\n\r\n⏩နွေစပါးစိုက်ပျိုးရာတွင် သက်တမ်း ရက် (၉၀ မှ ၁၂၅) ရက်၀န်းကျင်ရှိ စပါးမျိုးများကို ဦးစားပေး စိုက်ပျိုးသင့်ပါသည်။ နွေစပါးတွင် မျိုးစေ့ခြောက်တင်းနှုန်း အသုံးပြုခြင်းဖြင့် ပေါင်းပင်ပေါက်ရောက်မှု ၅၄ ရာခိုင်နှုန်း သက်သာစေကြောင်း သုတေသနပြု စမ်းသပ်ချက်များမှတွေ့ရှိရပါသည်။ သက်တမ်း (၁၃၅) ရက် စပါးမျိုးများကို စိုက်ပျိုးမည်ဆိုပါက ရိတ်သိမ်းချိန်တွင် မိုးမမိစေရန် တွက်ချက်ချိန်ကိုက်၍ ပျိုးထောင်စိုက်ပျိုးနိုင်ပါသည်။ သက်ငယ်စပါးမျိုးများသည် သက်တမ်းတိုသဖြင့် အပင်ကြီးထွားမှုကာလတိုပြီး အပင်ပွားစည်းမှု ကာလလည်းမျှော်လင့်မထားဘဲ ပင်မခေါင်နှံများကိုသာ အမိအရယူရန်ဖြစ်သဖြင့် မျိုးစေ့နှုန်း ပိုမိုသုံးစွဲရန်ဖြစ်ပါသည်။<br><br>\r\n\r\n⏩မျိုးစေ့နှုန်း ပိုသုံးထားပါက ယူရီးယားဓာတ်မြေသြဇာ ပိုသုံးရမည်ဖြစ်ပါသည်။ ဧရာ၀တီတိုင်း ဒေးဒရဲ၊ ဖျာပုံ၊ ကျိုက်လတ်၊ မအူပင်၊ ညောင်တုန်း မြို့နယ်များတွင် တစ်ဧက မျိုးစပါး (၄-၅) တင်းအသုံးပြု၍ တစ်ဧက တင်းရာကျော် ထွက်နေသည်မှာ ကြာခဲ့ပါပြီ။ အာဟာရဓာတ်စုံပါဝင်သော ကွန်ပေါင်း မြေသြဇာများ အသုံးပြုပါက နိုက်ထရိုဂျင်သုံးစွဲမည့်ပမာဏသည် ၁၁၂ ပေါင်၀င် ယူရီးယား သုံးအိတ်နှင့် ညီမျှသော အာဟာရတန်ဖိုးရောက်ရှိအောင် အသုံးပြုရမည်ကို အထူးသတိပြုသင့်ကြပေသည်။<br><br>\r\n\r\n⏩တောင်သူကြီးများ၏ အဓိကအားနည်းသောအချက်မှာ ယူရီးယားဓာတ်မြေသြဇာအသုံးပြုရာတွင် ယူရီးယားတစ်အိတ်၊ နွားချေးမြေဆွေးသုံးအိတ်နှင့် ရောနှပ်၍ ကြဲပက်ရန် နည်းပညာအရ ဆိုထားသော်လည်း လိုက်နာကျင့်သုံးမှုမှာ အလွန်နည်းသည်ကို တွေ့မြင်နေကြရပါသည်။ ဤသို့အသုံးပြုရန် နည်းပညာဆိုထားချက်မှာ ယူရီးယားမြေသြဇာဆုံးရှုံးမှုလည်း လျော့နည်း၊ နွားချေးမြေဆွေးလည်း ထည့်ပြီးသားဖြစ်အောင် တစ်ချက်ခုတ် နှစ်ချက်ပြတ်ပေးထားသော နည်းပညာဖြစ်ပါသည်။<br><br>\r\n\r\n⏩နွေစပါးစိုက်ပျိုးချိန်တွင် သတိပြုရမည့်အချက်မှာ ကြဲခင်းကြဲပြီး ရေလွှတ်ပြီးစအချိန်တွင် စားသောက်ဖျက်ဆီးသော စနိုက်၊ ဂျိုး၊ ရေဘဲနှင့် ကြွက်တို့၏အန္တရာယ်ပင် ဖြစ်ပါသည်။ မျိုးစပါးကြဲပြီး ရေလွှတ်မည်ဆိုပါက အပင်စတင်ပြူထွက်သည်မှ အပင်ဖြစ်ထွန်းလာသည်အထိ ၎င်းအန္တရာယ်များမှ လွတ်ကင်းအောင် ဂရုပြုစောင့်ရှောက် ခြောက်လှန့်ပေးရန်လိုအပ်ပါသည်။ သို့မဟုတ်လျှင် ခင်းလုံးကျွတ်မျှ အန္တရာယ်ကြီးမားလှပါသည်။<br><br>\r\n\r\n⏩မြေချဉ်ငန်ဓာတ်ပြင်းသော မန္တလေးတိုင်းဒေသကြီး၊ စစ်ကိုင်းတိုင်းဒေသကြီး၊ မကွေးတိုင်းဒေသကြီးများရှိ လယ်မြေများသည် ဇင့်ဓာတ်ချို့တဲ့သဖြင့် ဇင့်ဓာတ်ပါဝင်သော မြေသြဇာကို တစ်ဧက သုံးပေါင်မှ ငါးပေါင်ထည့်ပေးပါက စပါးအထွက်နှုန်း ငါးရာခိုင်နှုန်းမှ ၂၅ ရာခိုင်နှုန်းထိ ပိုမိုလာနိုင်ပါသည်။ မြေချဉ်ငံဓာတ်နိမ့်သော ဧရာ၀တီတိုင်းဒေသကြီး၊ ပဲခူးတိုင်းဒေသကြီး၊ ရန်ကုန်တိုင်းဒေသကြီး၊ မွန်ပြည်နယ်၊ တနင်္သာရီတိုင်းဒေသကြီးတို့ရှိ စပါးစိုက်ခင်းများတွင် စပါးမစိုက်မီ နှစ်ပတ်အလိုတွင် မဖောက်ထုံးတစ်ဧက ပေါင် (၂၀၀) ထည့်ပေးပါက စပါးအထွက်နှုန်း ရှစ်ရာခိုင်နှုန်း ပိုမိုလာနိုင်ပါသည်။ <br><br>\r\n\r\n⏩နွေစပါးခင်းများတွင် ယူရီးယားမြေသြဇာကို အနည်းဆုံး ငါးကြိမ်ခွဲကျွေးပါက စပါးပိုမိုထွက်ရှိစေနိုင်ပါသည်။ ပိုတက်ရှ်မြေသြဇာကို စပါးခင်းတွင် မြေခံတစ်ကြိမ်တည်း ထည့်သွင်းခြင်းထက် သတ်မှတ်နှုန်းထားကို အညီအမျှသုံးပုံခွဲ၍ စိုက်ပျိုးချိန်၊ ပင်ပွားချိန်၊ မှိုကပ်ချိန် သုံးကြိမ် အလီလီ ခွဲထည့်ပေးပါက စပါးထွက်နှုန်း (၈ - ၁၀)ရာခိုင်နှုန်းထိ ပိုမိုထွက်ရှိနိုင်ပါသည်။ မြန်မာနိုင်ငံရှိ လယ်ယာမြေအတော်တော်များများတွင် ကန့်ဓာတ်ချို့တဲ့သဖြင့် ကန့်ဓာတ်ပါ၀င်သော ဂျစ်ပဆန် ကျောက်မှုန့်မြေသြဇာ တစ်ဧက ပေါင် (၁၀၀) နှုန်း ထည့်ပေးပါက စပါးအထွက် သိသိသာသာ တိုးလာစေနိုင်ပါသည်။ <br><br>\r\n\r\n⏩နွေစပါးသည် ခြောက်သွေ့သောရာသီတွင် ရေကိုနည်းစနစ်အမျိုးမျိုးဖြင့် ရေတင်စိုက်ပျိုးသည့် သီးနှံဖြစ်ပါသည်။ သို့အတွက် စပါးပင်သက်တမ်းတစ်လျှောက် သက်တမ်းအလိုက်ရှိနေရမည့် ရေပမာဏကို သိုလှောင်ထိန်းသိမ်းထားနိုင်ရေးသည် စပါးခင်းတွင် ရေမပြတ်စေရန် အထူးသတိပြု ထိန်းသိမ်းရန်လိုအပ်ပါသည်။ စပါးပင်ကြီးထွားမှုကာလတွင် ရေပြတ်ပါက ပင်ပွားနည်းပြီး စပါးပင် ကြီးထွားမှုလည်း ညံ့သွားစေပါသည်။ အနှံသန္ဓေကြီးထွားမှုကာလနှင့် ပန်းပွင့်နို့ရည်တည်သော ကာလများတွင် ရေပြတ်ပါက အဖျင်းများစေပါသည်။ အောင်စေ့ရာခိုင်နှုန်း ကျစေပါသည်။ အထူးသဖြင့် ဆန်သားဗိုက်ဖြူဖြစ်ပေါ်စေပြီး၊ ဆန်သားအက်စေပါသည်။ ဆန်ကြိတ်ပါက ဆန်အကျိုးအကြေများစေပြီး၊ ဆန်အရည်အသွေးကျစေနိုင်ပါသည်။<br><br>\r\n\r\n⏩သို့ဖြစ်ပါ၍ တောင်သူဦးကြီးတို့၏နွေစပါးခင်းများတွင် အထွက်နှုန်းတင်းရာကျော်ရှိနိုင်ရေးအတွက် အထက်ပါဂရုပြုဆောင်ရွက်ရမည့်အချက်များကို အလေးအနက်ထား ဆောင်ရွက်နိုင်ကြစေရန် အကြံပြုရေးသားလိုက်ရပါသည်။<br><br>\r\n\r\n\r\nSources : ဆရာဦးအောင်ဆန်း (စိုက်ပျိုးရေး)', '#ff6763', '18-02-2024'),
(15, 'သီးနှံအရည်အသွေး နှင့် အထွက်မကျစေဖို့ရာ “မွှားပင့်ကူနီ” ကို စနစ်တကျ ကာကွယ်ပါ .....', 'IMG-65d23795a0f0e3.07303356.jpeg', '🌿🕷🌿🕷🌿🕷🌿🕷🌿🕷🌿<br><br>\r\n\r\nမြန်မာအမည် - မွှားပင့်ကူနီ<br><br>\r\n\r\nအင်္ဂလိပ်အမည် - Red spider mite<br><br>\r\n\r\nသိပ္ပံအမည် - Tetranychus urticae <br><br>\r\n\r\n↗️ သီးနှံပင်များတွင် ဆိုးဝါးစွာကျရောက်လေ့ရှိသည့် ဖျက်ပိုးပေါင်းများစွာတွင် “မွှားပင့်ကူနီ” သည် အပါအဝင်ဖြစ်သည်။ မွှားပင့်ကူနီ ကျရောက်ပါက သီးနှံပင်များ၏ ပင်ရည်များကိုစုပ်ယူစားသောက်ပြီး အရွက်များတွန့်ခြင်း၊ အပင်ကြီးထွားမှုရပ်တန့်ခြင်း စသည်တို့ဖြစ်ပေါ်တတ်ပြီး သီးနှံပင်အရည်အသွေး ကျဆင်းကာ အထွက်နှုန်းကိုပါ လျော့ကျထိခိုက်စေနိုင်သည်။ <br><br>\r\n\r\n↗️ မွှားပင့်ကူနီသည် အရွယ်အစား (၁) မီလီမီတာထက်သေးငယ်ပြီး ခန္ဓာကိုယ်တစ်ဖက်စီမှာ အဝါရောင် (သို့) အဝါဖျော့ရောင် အစက်လေးများရှိသည့် ပင့်ကူငယ်လေးများဖြစ်သည်။ ၎င်းအကောင်ငယ်လေးများကို အပင်ရဲ့အရွက်အောက်မျက်နှာပြင်များတွင် အမြောက်အများတွေ့ရှိနိုင်ပါသည်။ ဆိုးရွားစွာကျရောက်ချိန်တွင် အပင်အရွက်များပေါ်တွင် ပင့်ကူမျှင်လေးများကိုပါ တွေ့ရှိနိုင်သည်။ နေ့တာတိုသည့်ဆောင်းရာသီတွင် ပိုးကောင်လေးများသည်အနီရောင်ရင့်ရင့်သို့ပြောင်းသွားပြီး ဆောင်းခိုရန်အတွက် သီးနှံပင်များကို စွန့်ခွာသွားတတ်ကြသည်။<br><br>\r\n\r\n↗️ မွှားပင့်ကူနီသည် ပူပြင်းခြောက်သွေ့သော ရာသီဥတုတွင် မျိုးပွားနှုန်း နှင့် အသက်ရှင်သန်နိုင်မှုနှုန်း များပြားသည်။ မွှားပင့်ကူနီများသည် ကြီးထွားမှုအဆင့် (၅) ဆင့်ရှိပြီး ဥအဆင့် မှ အကောင်ကြီး အဆင့်အထိ (၇ မှ ၁၄) ရက်အထိ ကြာမြင့်နိုင်ပါသည်။ အမတစ်ကောင်သည် သုံးပတ်အတွင်းမှာ ဥပေါင်း ၁၀၀ ကျော်ကို အုနိုင်ပါသည်။ ဥတွေကို အရွက်ရဲ့အောက်မျက်နှာပြင်မှာ အုကြပြီး မွှားပင့်ကူနီ (၁၀) ကောင်မှ တစ်လအတွင်း အကောင်ရေ ၁,၀၀၀ မှ နှစ်လအတွင်း အကောင်ရေ ၁၀၀,၀၀၀ ထိ မျိုးပွားနိုင်ကြပါသည်။ ပတ်ဝန်းကျင် အစိုဓာတ်မြင့်မားခြင်းက မွှားပင့်ကူနီများ ဥအုနှုန်းကို လျော့ကျစေပါသည်။ မွှားပင့်ကူနီသည် ခြေချောင်းများဖြင့် နေရာတိုင်းပြန့်နှံ့နိုင်သလို လေနှင့် အင်းဆက်ခန္ဓာကိုယ်များမှတစ်ဆင့် ကပ်တွယ်၍လည်း အဝေးသို့ပြန့်နှံ့နိုင်သည်။ <br><br>\r\n\r\n↗️ မွှားပင့်ကူ၏ ဖျက်ဆီးပုံလက္ခဏာမှာ အရွက်အောက်မျက်နှာပြင်မှနေ၍ အပင်ဆဲလ်များကို ထိုးဖောက်ခြစ်စားသဖြင့် အရွက်များအောက်သို့ တွန့်ကုပ်သွားသည်။ ၎င်းပိုးစကျသည့်အချိန်တွင် အရွက်အပေါ်မျက်နှာပြင်၌ အဖြူရောင်အစက်အပြောက်များကိုတွေ့ရပြီး အကောင်ရေများပြား လာသည်နှင့်အမျှ အဖြူရောင် အစက်အပြောက်များ ပိုမိုများပြားလာပြီး အရွက်အရောင်ပျောက်ကာ နောက်ဆုံးမှာ အပင်သေဆုံးသွားနိုင်ပါသည်။ သီးနှံပင်အရွက်အောက်မျက်နှာပြင်များတွင် မွှားပင့်ကူနီ အမြောက်အများရှိနိုင်သော်လည်း မှန်ဘီလူးဖြင့်ကြည့်မှသာ သေချာကွဲပြားစွာ မြင်တွေ့နိုင်ပါသည်။ အကောင်ရေများပြားလာမှသာ အကောင်အစုအဝေးများစွာနှင့် ပင့်ကူမျှင်များကို တွေ့မြင်နိုင်မှာ ဖြစ်သည်။<br><br>\r\n\r\n↗️ မွှားပင့်ကူနီများသည် အစာမစားပဲ ဆောင်းခိုနိုင်ပြီး နွေနှင့်မိုးရာသီများတွင် သီးနှံပင်များကိုပြန်လည်ဖျက်ဆီးတတ်ကြပါသည်။ အထူးသဖြင့် မတ်လ မှ အောက်တိုဘာလအတွင်း သီးနှံပင်များပေါ်တွင် ကျရောက် ဖျက်ဆီးနိုင်ပါသည်။ <br><br>\r\n\r\n↗️ “မွှားပင့်ကူနီ”ကျရောက်မှုကို ကာကွယ်နှိမ်နင်းရန်မှာ .....<br><br>\r\n\r\n☑️ မွှားပင့်ကူနီ ကျရောက်ထားသောအခင်း၏ လေအောက်ကျသောနေရာများတွင် သီးနှံခင်းအသစ် စိုက်ပျိုးခြင်းကိုရှောင်ကြဉ်ပါ။<br><br>\r\n\r\n☑️ ပိုးကျထားသော အပင်များကို နှုတ်၍ မီးရှို့ဖျက်ဆီးပြီး (၁-၂)ပတ် မြေလှပ်ထားပါ။ <br><br>\r\n\r\n☑️ စိုက်ခင်း နှင့် စိုက်ခင်းဘေးပတ်လည်တွင် ပေါင်း၊မြက်များ ပြောင်စင်အောင်ရှင်းလင်းထားရမည်။<br><br>\r\n\r\n☑️ ဓာတုပိုးသတ်ဆေးအသုံးပြုရန်မှာ ဝိစာရ၏ “အီမာလန်ဒါ၊ မိုက်အိုကေ၊ ရော့ကက်၊ ဆာဗိတ်” ဆေးများမှ တစ်မျိုးမျိုးကို ပက်ဖျန်းအသုံးပြုပေးနိုင်ပါသည်။<br><br>\r\n\r\n', '#ffffc2', '18-02-2024'),
(16, '“ရာသီဥတု ဖြစ်စဉ်ပြောင်းလဲမှု နှင့် စပါးဖျက်ပိုးများ”', 'IMG-65d239655d7288.78366405.jpg', '🌾🐛🌾🦗🌾🐛🌾🦗🌾🐛🌾<br><br>\r\n\r\n⏩သဘာဝပတ်ဝန်းကျင်ပျက်စီးမှုများကြောင့်ရာသီဥတုဖြစ်စဉ်ပြောင်းလဲမှုပြင်းထန်လာပြီး သီးနှံစိုက်ပျိုးရေးတွင်စိုက်ချိန်မိုးမရွာ၊ ရိတ်သိမ်းချိန်မိုးရွာမှုများကြုံတွေ့နေရသည်။ စိုက်ချိန်မိုးများ၊ ပွင့်သီးချိန်မိုးမရွာ၊ ရိတ်ချိန်သိမ်းချိန်မိုးမိဖြစ်နေကြရသည်။ ဤအထဲတွင်ဖျက်ပိုးနှင့်အပင်ရောဂါသည် ရာသီဥတုပြောင်းလဲဖောက်ပြန်မှုနှင့်အတူယှဉ်တွဲပြီးကပ်ညှိပါလာတတ်ပါသည်။<br><br>\r\n\r\n⏩နေရာဒေသအလိုက်မိုးရွာသွန်းမှုကွဲပြားခြားနားသည်နှင့်အမျှ တစ်နှစ်ပတ်လုံး လယ်ထဲယာထဲ၌ သီးနှံတစ်မျိုးမျိုးသည်ရှိနေသည်။ စဉ်ဆက်မပြတ်သီးနှံအမယ်စုံရှိသကဲ့သို့ဖျက်ပိုးမျိုးစုံကလည်း ရှိနေသည်။ဤတွင်သီးနှံမျိုးစုံကိုကျရောက်သည့်ဖျက်ပိုးအမျိုးအစားကပို၍များ၊ပို၍ပွားပြီးကျရောက်တော့သည်။ ထို့ကြောင့်ရာသီဥတုဖြစ်စဉ်ပြောင်းလဲမှုနှင့်အတူ စပါးတွင်ကျရောက်တတ်သောဖျက်ပိုးများ ကိုရေးသားတင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n⏩စိုထိုင်းဆများပြီးလေပြင်းတိုက်မှုများလျှင် “စပါးလောင်မီးပိုး” ဂရုပြုရမည်။ မိုးများပြီးရေကြီး နစ်မြုပ်လျှင်စပါးပိုးလောင်မီးသည်ရေစပ်၊ရေကျန်နေရာများ၌တင်ကျန်ခဲ့သည်။စပါးရွက်လိပ်အိမ်ပိုး သည်လည်းမိုးစပါးတွင်ကျရောက်မှုများ၍ ရေကြီး၊ရေလွှမ်း၊ ရေမြုပ်ဒေသတွင်များများကျတတ်သည်။ ပို၍ဂရုပြုရမည်မှာ ငမြှောင်တောင်ဖျက်ပိုးဖြစ်သည်။သီးနှံအစုံစား၍မျိုးပွားပျံ့နှံ့မှုများပြားသဖြင့်စိုက်ပျိုး ပြီးစပါးခင်းများဂရုထားရမည်။ ရေကြီးရေလွှမ်းဒေသရေပြန်ကျ၍စပါးစိုက်လျှင်အထူးသတိပြုကြပါ။<br><br>\r\n\r\n⏩“စပါးဆစ်ပိုး” သည်မြန်မာနိုင်ငံအလယ်ပိုင်းရွှေဘို၊ ခင်ဦး၊ ရေဦး တစ်ဝိုက်ရှိပေါ်ဆန်းစပါးခင်းများတွင် ကျရောက်တတ်သည်ဖြစ်၍ ကြိုတင်သတိပြုကာကွယ်နှိမ်နင်းကြသင့်သည်။ မိုးမရွာ၊ တိမ်ထူ၊ မိုးအုံ့မှု ကြာရှည်ဖြစ်ပေါ်သောဒေသတွင်စပါးခင်းများ၌ “ကြက်သွန်မြိတ်ပိုး” ကျနိုင်သည်။ ရာသီဥတုနှင့်ဆက်စပ် မှုအများဆုံးရှိသောဖျက်ပိုးမှာ “ဖြုတ်ပိုး” ဖြစ်သည်။ မိုးရွာသွန်းမှုများ၍စိုစွတ်မှုများလျှင်ဖျက်ဆီးမှု များသည်။ စပါးပင်၏ပင်ခြေရွက်ဖုံးများကြားတွင် နေထိုင်ဖျက်စီးသဖြင့်နှိမ်နင်းမှုကို သေချာပြုလုပ် ရသည်။ စပါးပင်အဆစ်များကြားတွင်နေထိုင်သော ဆစ်ပိုးကဲ့သို့နေထိုင်မှုအကာအကွယ်ယူထားသဖြင့် ပိုးနှင့်ဆေး တွေ့ရန်အခွင့်အလမ်းနည်းသည်။<br><br>\r\n\r\n⏩ကာကွယ်ခြင်းသည်ကုသခြင်းထက်ပို၍ကောင်းသည်ဆိုသကဲ့သို့ ကြိုတင်ကာကွယ်ခြင်းသည် ဖြစ်မှ နှိမ်နင်းခြင်းထက် ပိုထိရောက်သည်။ ထို့ကြောင့်ရာသီဥတုဖြစ်ပေါ်ပြောင်းလဲမှုကြောင့် စပါးတွင် ကျရောက်နိုင်သောဖျက်ပိုးများကိုကာကွယ်နှိမ်နင်းရာတွင် ပိုးကျရောက်မှုများလျော့နည်းသက်သာစေရန် ဖော်ပြပါစိုက်ပျိုးရေးနည်းလမ်းကောင်းများဖြင့်ဆောင်ရွက်သင့်ပါသည်။<br><br>\r\n\r\n☑️ စပါးစိုက်ခင်းနှင့် စိုက်ခင်းဝန်းကျင်ရှိ ပေါင်း၊မြက်များကို ရှင်းလင်းပါ။<br><br>\r\n\r\n☑️ သီးလှည့်စိုက်စနစ်ကို ဆောင်ရွက်ပါ။<br><br>\r\n\r\n☑️ အဓိကအာဟာရဓာတ်သုံးမျိုးအပါအဝင် ဓာတ်မြေဩဇာများကို အချိုးကျကျအသုံးပြုပါ။<br><br>\r\n\r\n☑️ ရေသွင်းရေထုတ် မှန်မှန်ပြုလုပ်ပါ။<br><br>\r\n\r\n☑️ ထယ်ရေးပြင်စဉ် ထယ်နက်နက်ထိုးပါ။<br><br>\r\n\r\n☑️ ရာသီဥတုပြောင်းလဲမှုဖြစ်စဉ်များရှိပါက ပိုးမွှားများကျရောက်နိုင်ပါ၍ စိုက်ခင်းအတွင်း ပိုးမွှားများ ကျရောက်နေမှုရှိ/မရှိ စဉ်ဆက်မပြတ်ကွင်းဆင်းကြည့်ရှုပေးပါ။<br><br>\r\n\r\n☑️ ပိုးကျရောက်မှုအတွက်ပိုးသတ်ဆေးအသုံးပြုတော့မည်ဆိုပါက ပိုးနှင့်ဆေးထိထိမိမိတွေ့စေရန် အသုံးပြုသည့်ဆေးအမျိုးအစားမှန်၍ ဆေးနှုန်းထားလည်းမှန်ကန်စေရန် သတိရှိရှိအသုံးပြုကြ စေလိုပါသည်။<br><br>\r\n\r\n\r\n\r\nSources : ကိုရဲ (စိုက်ပျိုးရေး)', '#addfff', '18-02-2024'),
(17, '\"စိုက်ပျိုးရေးဆေးများ ပက်ဖျန်းရာတွင် သိထားရမည့်အချက်များ\"', 'IMG-65d239db7a18d1.56172189.png', '🌿🌱🌿🌱🌿🌱🌿🌱🌿🌱🌿<br><br>\r\n\r\n☑️ သီးနှံများစိုက်ပျိုးထုတ်လုပ်နေကြသော တောင်သူဦးကြီးတို့သည် စိုက်ပျိုးရေးသုံးဆေးများကို သီးနှံပင်များအတွက် ပက်ဖျန်းအသုံးပြုနေကြသော်လည်း အချို့မှာနည်းစနစ်မမှန်ကန်ခြင်းများကြောင့် ထိရောက်သည့်အာနိသင်မရှိဘဲ လေလွင့်ဆုံးရှုံးမှုများကို ကြုံတွေ့နေရပါသည်။ မျှော်မှန်းသလောက် အကျိုးမရှိဘဲ မရယူလိုသည့်ဘေးထွက်ဆိုးကျိုးများကိုလည်း မလွှဲမရှောင်သာ လက္ခံရယူနေကြရပါသည်။ ထို့ကြောင့် ပိုးသတ်ဆေး၊ ပေါင်းသတ်ဆေး၊ မှိုသတ်ဆေး၊ ရွက်ဖျန်းအားဆေးများကို အမှန်ကန်ဆုံး နှင့် အကောင်းဆုံးပက်ဖျန်းပေးရမည့်အချိန်၊ တွဲစပ်မဖျန်းသင့်သည့်ဆေးများ စသည့် စိုက်ပျိုးရေး ဗဟုသုတများကို သတိပြုမှတ်သားနိုင်ပါရန် တင်ပြရေးသားလိုက်ရပါသည်။ <br><br>\r\n\r\n၁။ ပေါင်းသတ်ဆေးများပက်ဖျန်းခြင်း<br><br>\r\n\r\nပေါင်းသတ်ဆေးဖျန်းရမည့်အချိန်သည် ရာသီဥတု နှင့် အပူချိန်အပေါ်မူတည်ပါသည်။ ပူနွေးသည့် ရာသီတွင် နံနက်ခင်းနှင့်နေရိပ်သည့်အချိန်ဖျန်းပေးရပါမည်။ နေအရမ်းပူသည့်အချိန်ဖျန်းလိုက်လျှင် ဆေးအာနိသင်လျော့နည်းစေပါသည်။ အပူချိန်လည်းမြင့်သည့်အတွက် ဖျန်းလိုက်သည့်ဆေးများ အာနိသင်မပြနိုင်ခင်မှာပင် ခမ်းခြောက်ဆုံးရှုံးမှုများဖြစ်တတ်ပါသည်။ အေးသည့်ရာသီ ပေါင်းသတ်ဆေး ဖျန်းလျှင် အပူချိန်မြင့်လာချိန်၊ နှင်းတွေကျပြီးနှင်းကွဲသွားသည့်အချိန်တွင်ဖျန်းပေးရပါသည်။ မနက်ခင်းအစောပိုင်းဖျန်းလိုက်လျှင် မိမိဖျန်းလိုက်သော ဆေးများနှင်းများနဲ့အတူ ရောပြီးပါသွားသော ကြောင့် အာနိသင်မရှိနိုင်တော့ပါ။ မိုးရာသီပေါင်းသတ်ဆေးဖျန်းလျှင်ဆေးဖျန်းပြီး အချိန်(၄-၅)နာရီခန့် မိုးလွတ်နိုင်စေရန် ရာသီဥတုနှင့်ချိန်ဆ ပက်ဖျန်းပေးရပါမည်။ ထို့ပြင်ဆေးအာနိသင်ပိုမိုထိရောက် စေရန်ပေါင်းသတ်ဆေးဖျန်းသည့်အခါတိုင်း ပြန့်ဆေးကပ်ဆေးတစ်မျိုးမျိုးကို ရောစပ်အသုံးပြု ပေးသင့်ပါသည်။<br><br>\r\n\r\n၂။ ပိုးသတ်ဆေး၊ ရောဂါကာကွယ်ဆေးများ ပက်ဖျန်းခြင်း<br><br>\r\n\r\nကျရောက်သည့်ပိုး/ရောဂါနှင့် သင့်တော်ကိုက်ညီသော စစ်မှန်သည့်ဆေးကိုရွေးချယ် အသုံးပြုရပါမည်။ “မိမိအပင်ဘာဖြစ်နေသလဲ” ဆိုသည်ကို သိရန်အရေးကြီးပါသည်။ ပိုးကျသလား? ရောဂါဖြစ်သလား? စသည်ဖြင့် သိရပါမည်။ ပိုးကျလျှင် ကိုက်စားပိုး၊ ခြစ်စားပိုး၊ စုပ်စားပိုး၊ မြေအောင်းပိုး စသည်ဖြင့် သီးနှံဖျက်ပိုးများသဘာဝအမျိုးမျိုးရှိသလို ဆေးများမှာလဲ ပိုးအမျိုးအစားအလိုက် ပိုမိုထိရောက်သည့် အာနိသင်များရှိပါသည်။ ထို့ကြောင့်အနာနှင့် ဆေးတည့်အောင်ရွေးချယ်နိုင်မှသာ ထိရောက်အကျိုးရှိ ပါမည်။ မဆိုင်သည့်ဆေးဖျန်းနေ၍ အကျိုးရှိမည်မဟုတ်ပါ (ဥပမာ - သီးနှံပင်တွင် ကိုက်ဖြတ်စားသော ပိုးများကျနေသည်ကို စုပ်စားပိုးသတ်ဆေးနှင့် ပက်ဖျန်းပါက မထိရောက်နိုင်ပါ)။ ထို့အတူသီးနှံများကို စဉ်ဆက်မပြတ်စိုက်ပျိုးထုတ်လုပ်နေသူများအနေဖြင့် သီးနှံပင်များတွင်ကျရောက်လေ့ရှိသော အပင်ရောဂါများ၏ လက္ခဏာများကိုခွဲခြားသိရန်လိုအပ်သည်။ မိမိမကျွမ်းကျင်လျှင် ကျွမ်းကျင်သူထံ အကြံဉာဏ်ရယူရပါမည်။ ထို့အပြင် တရားဝင်မှတ်ပုံတင်ထားသည့် မြန်မာစာအညွှန်းပါသော ဆေးများကို ရွေးချယ်သုံးရပါမည်။<br><br>\r\n\r\nဆေးဖျန်းရာတွင်နံနက်စောစောနှင့်ညနေပိုင်းနေအေးချိန်တွင် ဆေးဖျန်းရပါမည်။ နေအလွန်ပူနေချိန် ဆေးမဖျန်းသင့်ပါ။ နေအလွန်ပူနေချိန်တွင်အရွက်လေပေါက်များပိတ်နေသဖြင့် ထိရောက်မှုနည်းသည့် အပြင် ဆေးဖျန်းသူမှာလည်းချွေးပေါက်များကျယ်နေပြီး သွေးကျဲနေသဖြင့် အန္တရာယ်အလွန်များပါသည်။ အကောင်းဆုံးမှာညနေပိုင်းဖျန်းရန်ဖြစ်ပါသည်။ မနက်ခင်းတွင်ညပိုင်းကအအေးဓါတ်ကြောင့် ဆဲလ်တင်း အားများနေပြီး ဆေးစုပ်ယူမှုနည်းပါသည်။ ညနေပိုင်းတွင်ဆေးစိမ့်ဝင်နိုင်မှုများသည့်အပြင် ဖျက်ပိုး အများစုသည်လည်း ညပိုင်းတွင်မြူးလေ့ရှိသောကြောင့်ဖြစ်ပါသည်။<br><br>\r\n\r\n၃။ ရွက်ဖျန်းအားဆေးများ ပက်ဖျန်းခြင်း<br><br>\r\n\r\nအားဆေးဖျန်းမည်ဆိုလျှင် မနက်ခင်းဖျန်းခြင်းသည် ပိုထိရောက်မှုရှိပါသည်။ အရွက်တစ်ရှူးလေးများ သည် မနက် (၃) နာရီ နှင့် (၈) နာရီကြားအချိန်၊ ညနေခင်းနေအေးတဲ့အချိန်များတွင်လေရှူပေါက်များ ပွင့်သည်။ ထိုအချိန်များမှာအားဆေးဖျန်းလျှင် စုပ်ယူမှုအားကောင်းပြီး မိမိဖျန်းလိုက်သည့်ဆေးက သီးနှံပင်အတွက် အကျိုးရှိစေမှာဖြစ်ပါသည်။<br><br>\r\n\r\n၄။ ရောစပ်၍မဖျန်းသင့်သည့်ဆေးများ<br><br>\r\n\r\nစိုက်ပျိုးရေးဆေးများပက်ဖျန်းရာတွင်သတိပြုရန်မှာ မိမိဖျန်းမည့်ဆေးများတွင် Sulphur(ဆာလ်ဖာ) နှင့် Copper(ကောပါး) ဓာတ်ပါလျှင် အခြားဆေးများနှင့်တွဲမသုံးသင့်ပါ။ အပင်လောင်ကျွမ်းတတ်ပါသည်။ လိုအပ်လျှင်ပိုးသတ်ဆေးကို အားဆေးနှင့်ရောဖျန်း၍ရပြီး ကျန်မှိုသတ်ဆေး၊ ပေါင်းသတ်ဆေး၊ ဘက်တီးရီးယားသတ်ဆေးများ ဖျန်းသည့်အခါ သီးသန့် ဖျန်းရပါမည်။ သို့သော် ပိုးအရမ်းဆိုးရွားနေပါက ပိုးသတ်ဆေးနှင့်အားဆေး တွဲမဖျန်းသင့်သည်ကို သတိပြုရပါမည်။<br><br>\r\n\r\n☑️တောင်သူဦးကြီးတို့၏သီးနှံစိုက်ခင်းများအတွင်း ဓာတုဆေးဝါးများကို လိုအပ်မှသာပက်ဖျန်းရန် နှင့် စိုက်ခင်းများတွင် ပိုးမွှား၊ ရောဂါများကင်းစင်၍ အထွက်နှုန်းကောင်းများ ပိုင်ဆိုင်နိုင်ကြပါစေ။<br><br>\r\n\r\n\r\n\r\nSources : Saya U Than Win Agri.', '#57feff', '18-02-2024'),
(18, '“လက်ဖက်ပင် စိုက်ပျိုးနည်း”', 'IMG-65d23a15c53394.56204163.jpg', '🌿🌱🌿🌱🌿🌱🌿🌱🌿🌱🌿<br><br>\r\n\r\n၁။ မူရင်းဒေသ<br><br>\r\n\r\nလက်ဖက်စိုက်ပျိုးရာ မူရင်းဒေသများမှာ မြန်မာပြည်မြောက်ပိုင်းဧရာဝတီဖြစ်ဖျားခံရာဒေသ၊ တရုတ် ပြည် နှင့် ဂျပန်ပြည်တို့ ဖြစ်သည်။<br><br>\r\n\r\n၂။ လက်ဖက်မျိုးများ<br><br>\r\n\r\nစိုက်ပျိုးဖြစ်ထွန်းသော နေရာဒေသအလိုက် သုံးမျိုးခွဲခြားထားပါသည်။<br><br>\r\n\r\n(က) တရုတ်လက်ဖက်<br><br>\r\n\r\n(ခ) အာသံလက်ဖက်<br><br>\r\n\r\n(ဂ) အင်ဒိုချိုင်းနားလက်ဖက်<br><br>\r\n\r\nတရုတ်လက်ဖက်မျိုးကို ရှမ်းပြည်နယ်တွင်စိုက်ပျိုးပြီး အပင်ပု၍အရွက်သေးကာချုံပုတ်သဏ္ဍန်ဖြစ်သည်။ အရွက်မှာ အစိမ်းရင့်ရောင်ဖြစ်ပြီး အထွက်နှုန်းနည်းသည်။ အာသံလက်ဖက်မျိုးသည် အပင်ငယ်သဏ္ဍန် ဖြစ်ပြီး အမြင့် (၃၀-၄၅)လက္မရှိကာ အရွက် အရွယ်အစား ကြီးမား၍ ရွက်ကြော ထင်ရှားစွာတွေ့ရသည်။ အင်ဒိုချိုင်းနား လက်ဖက်မျိုးသည် အာသံလက်ဖက်ထက်ထူပြီး အရွက်သည် အဝါ သို့မဟုတ် အစိမ်းပျော့ရောင်ရှိသည်။<br><br>\r\n\r\n၃။ စိုက်ပျိုးသည့်ဒေသများ<br><br>\r\n\r\nရှမ်းပြည်နယ်တွင် ကျောက်မဲ၊ နမ့်စန် ၊ ပင်လောင်း ၊ ပင်းတယ၊ မိုင်းကိုင် နှင့် မိုင်းရှူး မြို့နယ်များတွင် အများအပြားစိုက်ပျိုးပြီး ကချင်ပြည်နယ်၊ ကရင်ပြည်နယ် နှင့် ချင်းပြည်နယ်တို့တွင် အနည်းငယ်စီစိုက် ပျိုးကြောင်းတွေ့ရပါသည်။<br><br>\r\n\r\n၄။ ရေမြေ ရာသီဥတု<br><br>\r\n\r\nပင်လယ်ရေမျက်နှာပြင်မှ အမြင့်ပေ ၄,၀၀၀ မှ ၆,၀၀၀ ကျော် ရှိသည့်ဒေသများ၊ မိုးရေချိန် လက်မ ၆၅ မှ ၈၅ လက်မ အပူချိန် ပျှမ်းမျှ ၈၅ ဒီဂရီဖာရင်ဟိုက်၊ မြေသားထူ၍ မြေချဉ်ငန်ဓာတ် (၄.၅ မှ ၆) အထိရှိပြီး ရေမဝပ်သည့် တောင်ပေါ်မြေနီများကို နှစ်သက်သည်။<br><br>\r\n\r\n၅။ မြေပြုပြင်နည်း<br><br>\r\n\r\nလက်ဖက်စိုက်ပျိုးရန်အတွက် သစ်တောများကို ဒီဇင်ဘာလအတွင်း ခုတ်ထွင်ရှင်းလင်း၍ မတ်လတွင် မီး ရှို့ပါသည်။ ၎င်းနောက် တစ်တန်း နှင့် တစ်တန်း ငါးပေအကွာ ပန္နက်များရိုက်ပါ။ ကျင်းများကို ၁၂ လက်မ အကျယ်၊ ၁၈ လက်မအနက်တူးပါ။ ၎င်းကျင်းများကိုနွားချေး၊ မြေဆွေးတစ်ဝက် နှင့် အပေါ်ယံမြေဆွေး တစ်ဝက်ရောထားသောမြေဖြင့်လည်းဖြည့်ပါ။<br><br>\r\n\r\n၆။ ပျိုးထောင် မျိုးပွားခြင်း<br><br>\r\n\r\nလက်ဖက်ကို မျိုးစေ့မှဖြစ်စေ၊ ပင်ပိုင်းဆိုင်ရာ မျိုးပွားနည်းများနှင့်ဖြစ်စေ မျိုးပွားနိုင်ပါသည်။ မျိုးစေ့မှ ပျိုးထောင်နည်းတွင် ဆွတ်ခူးပြီးလက်ဖက်မျိုးစေ့များကို တစ်ပတ်အတွင်းပျိုးပါ။ မျိုးစေ့ကို ရက်ပေါင်းများစွာ သိုလှောင်ထားပါက အပင်ပေါက်ညံ့သွားတတ်ပါသည်။ လက်ဖက်ပျိုးဘောင် (သို့မဟုတ်) သေတ္တာများတွင် သန့်ရှင်းလတ်ဆတ်သည့် သဲမြေများထည့်ပေးရသည်။ လက်ဖက်စေ့များ ကို တစ်စေ့ နှင့် တစ်စေ့ တစ်လက်မအကွာ၊ တစ်တန်း နှင့် တစ်တန်း လေးလက်မ အကွာထား၍ မျိုးစေ့ ချပါ။ သဲမြေဖြင့် အစေ့မြှုပ်ရုံဖုံး၍ အပေါ်မှကောက်ရိုးများဖြင့် ဖုံးအုပ်ပေးထားပြီး ရေဝသည့်တိုင် လောင်းပါ။ ပျိုးဘောင်များကို အရိပ်ပြုလုပ်ပေးရန်လိုပါသည်။ ပျိုးပင်ကလေးများ ပေါက်လာသည့်အခါတွင် ပလပ်စတစ်ပျိုးအိတ်အတွင်းသို့ ရွေ့ပြောင်းစိုက်ပျိုးရသည်။ လက်ဖက်ပင်ပိုင်းဆိုင်ရာမျိုးပွားနည်းဖြင့် မျိုးပွားမည်ဆိုပါက အထွက်နှုန်းကောင်းသော လက်ဖက်ပင်ကို ရွေးကာ ခြောက်လကြိုတင်၍ ကိုင်းဖြတ်ပေးရမည်။ မျိုးယူမည့်ကိုင်းမှ လက်ဖက်ကို မခူးမိစေရန် အထူး အရေးကြီးပါသည်။ ကိုင်းဖြတ်ပြီးခြောက်လအကြာတွင် သန်မာသော မျိုးကိုင်းသစ်များထွက်လာပြီး ထိုမျိုးကိုင်းမှ နုလွန်းသောအပိုင်းကိုပယ်ကာ မကျိုးလွယ်သောကိုင်းကိုရွေးရမည်။ ကိုင်းဖြတ်ရာတွင် အဆစ်အောက်ကပ်လျက်စောင်းဖြတ်ပြီး အဆစ်အထက် လက်မဝက်ခန့်အမြင့်တွင် အတည့်ဖြတ်ပေး ရ၍ မြေဆွေးထည့်ထားသောအိတ်တွင် ပျိုးနိုင်သည်။ အပင်ငယ်(၁၀) လက်မခန့်ရှိလျှင် စိုက်ခင်းသို့ ရွှေ့ စိုက်နိုင်ပါသည်။<br><br>\r\n\r\n၇။ စိုက်ပျိုးခြင်း<br><br>\r\n\r\nပျိုးပင်သက်တမ်း တစ်နှစ်မှ နှစ်နှစ်သားအရွယ် မေ၊ ဇွန်လများတွင် ရွှေ့ပြောင်းစိုက်ပျိုးနိုင်သည်။ လက် ဖက်စိုက်ရန်မြေကို မြေဆီသြဇာတက်စေရန် ပဲမျိုးရင်းဝင်အပင်များစိုက်ထားသင့်သည်။ တောင်စောင်း များတွင်စိုက်မည်ဆိုပါက စိုက်တန်းများကို ၄ပေ × ၂ပေ ကွန်တို စိုက်တန်းဖော်၍ စိုက်ရန်ဖြစ်ပါသည်။ ကျင်းကို ၁.၅ပေ တူးကာ စိုက်ပျိုးနိုင်ပြီး ကျင်းအကျယ်ကို ထိပ် ကိုးလက်မ၊ အောက်ခြေ ခြောက်လက်မ အကျယ်ထား၍ စိုက်နိုင်ပါသည်။<br><br>\r\n\r\n၈။ မြေသြဇာကျွေးနည်း<br><br>\r\n\r\nလက်ဖက်ပင်ကို စိုက်ခင်းအတွင်းစိုက်ပြီးနောက် (၄၅) ရက်သားအတွင်း အမြစ်စွဲပြီးဖြစ်၍ မြေသြဇာ စတင်ကျွေးနိုင်ပါသည်။ နိုက်ထရိုဂျင်အဓိကလိုအပ်သည့်အတွက် ယေဘုယျအားဖြင့် တစ်ဧကလျှင် ယူရီး ယား ၁၁၂ပေါင် နှုန်း နှစ်စဉ်ထည့်ပေးသင့်ပါသည်။<br><br>\r\n\r\n၉။ အပင်ပြုစုစောင့်ရှောက်ခြင်း<br><br>\r\n\r\nကိုင်းဖြတ်ခြင်းကို မိုးဦး နှင့် မိုးလယ်တွင် ဆောင်ရွက်သင့်ပြီး ကိုင်းဖြတ်ရာတွင် အပင်အမြင့် နှစ်ပေခန့် တွင် သန်မာသော ဘေးကိုင်းနှစ်ကိုင်းကိုချန်ပြီး ကျန်ကိုင်းများကို ၄၅ ဒီဂရီစောင်း၍ ဖြတ်ပစ်ရမည်။ ကိုင်းဖြတ်ခြင်းကို ပေ ၄,၀၀၀အောက် မြေနိမ့်ဒေသများတွင် သုံးနှစ်တစ်ကြိမ် ဆောင်ရွက်သင့်သည်။ ကိုင်းဖြတ်ခြင်းဖြင့် အောက်ပါအကျိုးကျေးဇူးများရရှိစေပါသည်။<br><br>\r\n\r\n☑️ အပင်အိုများ နုပျိုလာခြင်း။<br><br>\r\n\r\n☑️ လက်ဖက်ပင်များ သန်စွမ်းပြီး ရွက်နုပိုထွက်စေခြင်း။<br><br>\r\n\r\n☑️ လက်ဖက်ခူးရန် လွယ်ကူသောအပင်အမြင့်ကို ထိန်းသိမ်းထားနိုင်ခြင်း။<br><br>\r\n\r\n☑️ လက်ဖက်အထွက်နှုန်းတိုးတက်စေခြင်း။ <br><br>\r\n\r\nလက်ဖက်သည် သုံးနှစ်သားအထိ ဆီးနှင်းဒဏ် ခံနိုင်ရည်မရှိ၍ ဆီးနှင်းဒဏ်မှ ကာကွယ်ရန် ဍရင်ကောက် ပင်၊ မြက်ခြောက်၊ ကောက်ရိုးခြောက်တို့ဖြင့် မိုးအုပ်ပေးလေ့ရှိပါသည်။<br><br>\r\n၁၀။ ရောဂါပိုးမွှားများ<br><br>\r\n\r\nရွက်စားပိုး နှင့် ပင့်ကူနီများ ကျတတ်ပါသည်။ ရောဂါများအကြီးအကျယ် ကျရောက်လေ့မရှိပါ။<br><br>\r\n\r\n၁၁။ အရွက်ခူးခြင်း နှင့် အထွက်<br><br>\r\n\r\nလက်ဖက်ရွက်ခူးခြင်းကို သုံးနှစ်သား အပင်များမှသာ ဆောင်ရွက်လေ့ရှိပါသည်။ ပြုစုစောင့်ရှောက်မှု နည်းသော လက်ဖက်ပင်များတွင် ၁၅ရက် တစ်ကြိမ်သာခူးနိုင်ပြီး လက်ဖက်ခူးသည့်အကြိမ် တစ်ကြိမ် နှင့် တစ်ကြိမ်ကြား ကာလတိုတောင်းပါက တစ်ဧကအထွက်မြင့်မားပါသည်။ အရွက်ခူးရာတွင် ဂရုပြုသင့်သောအချက်များ .....<br><br>\r\n\r\n☑️ မြေပြင်မှ နှစ်ပေခွဲအတွင်းရှိသော အရွက်များကိုမခူးရပါ။<br><br>\r\n\r\n☑️ အရွက်ခူးရမည့်ထိပ်ပိုင်းအတွက် မျက်နှာပြင်သည် ပြန့်ကားနေရမည်။<br><br>\r\n\r\n☑️ အရွက်ခူးယူသည့်အခါ အထက်သို့တက်လာသော အတက်သစ်ကို (၆ - ၈) လက်မအထိ ချိန်ပေးရမည်။\r\n<br><br>\r\n\r\n☑️ ဘေးအစို့နှင့် ကြားဖူးမှအရွက်ကြီးများထွက်လာစေရန် အရွက်သေးကို အမြဲတမ်းချန်ပေးရမည်။<br><br>\r\n\r\n☑️ အပင်အတွင်းပိုင်းရှိ အစို့သစ်နှင့် အရွက်ခူးယူသည့်မျက်နှာပြင်အောက်ရှိ ဘေးအကိုင်းမှ အစို့သစ်များကို မခူးသင့်ပါ။<br><br>\r\n\r\nလက်ဖက် စိုက်ပျိုးနည်းစနစ်၊ အပင်ပြုစုစောင့်ရှောက်နည်းစနစ် နှင့် လက်ဖက်ခူးသော စနစ်များ အလိုက် တစ်ဧကလျှင် လက်ဖက်ခြောက် ပိဿာ ၁၂၀ မှ ၂၄၀ အထိ ထွက်နိုင်ပါသည်။<br><br>\r\n\r\nSources : စိုက်ပျိုးရေးဦးစီးဌာန', '#ff6763', '18-02-2024'),
(19, 'အထူးဂရုပြု ကာကွယ်ပါ “ပဲတီစိမ်း၊ မတ်ပဲ အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါ”', 'IMG-65d23a5a6402f4.44299144.jpeg', '🌿🫘🌿🫘🌿🫘🌿🫘🌿🫘🌿<br><br>\r\n\r\n↗️ ယခုလတ်တလောတွင် ပဲတီစိမ်း၊ မတ်ပဲ နှင့် ပဲမျိုးစုံစိုက်ခင်းများတွင် အဝါရောင်မိုစေ့ဗိုင်းရပ်ရောဂါများ အများအပြားကျရောက်နေကြသည်ကိုတွေ့ရပါသည်။ ၎င်းရောဂါသည်ဗိုင်းရပ်စ်ရောဂါတစ်မျိုးဖြစ်ပြီး ကုသဆေးမရှိပါ။ မိုစေ့ဗိုင်းရပ်စ်ရောဂါကျရောက်ခဲ့ပါက လျှင်မြန်စွာကူးစက်ပြန့်နှံ့ပြီး တစ်ခင်းလုံးအနှံ့ရောဂါများ ဖြစ်ပွားကာ မိမိတို့ပြုစုစောင့်ရှောက်ခဲ့သမျှ လေလွင့်ဆုံးရှုံးပြီး အထွက်နှုန်းကျကာ ဝင်ငွေကျဆင်းစေနိုင်မည်ဖြစ်သည်။ ထို့ကြောင့် “အဝါရောင်မိုစေ့ဗိုင်းရပ်ရောဂါ” အကြောင်းသိရှိပြီး ရောဂါမကျရောက်အောင်ကြိုတင်ကာကွယ်နိုင်ရန် ရေးသားတင်ပြအပ်ပါသည်။<br><br>\r\n\r\nရောဂါလက္ခဏာ<br>\r\n-------------<br><br>\r\n\r\nရောဂါကျရောက်လျှင် ပဲပင်အရွက်များအောက်ကိုကွေးပြီး လိပ်သွားပါသည်။ အစောပိုင်းကာလများတွင် ပဲတီစိမ်း၊ မတ်ပဲအရွက်များပေါ်တွင် သေးငယ်ပြီး ပုံသဏ္ဍာန်မမှန်သော အဝါရောင်အစက်အပျောက်များ ဖြစ်ပေါ်နေပါသည်။ ထိုအစက်များသည် တဖြည်းဖြည်း ကြီးထွားလာကာ အရွက်တစ်ခုလုံးနီးပါး ပျံ့နှံ့သွားကာ စိမ်းဝါရောင်အကွက်များ ဖြစ်ပေါ်နေပါသည်။ နောက်ပိုင်းကာလများတွင် အရွက်တစ်ခုလုံး အဝါရောင်ပြောင်းသွားပါသည်။ ထို့နောက် ပုံသဏ္ဍာန်မမှန်သော အရွက်များ၊ အသီးများကိုလည်း တွေ့ရပါသည်။ ရောဂါကူး စက်ခံထားရသော အပင်များသည် သိသိသာသာ ပုနေပါသည်။ အဆစ်ကြားများလည်းတိုသွားပြီး ကိုင်းများလည်းပိုထွက်လာကာ ချုံပုပ်ပုံသဏ္ဍာန်များ ဖြစ်နေပါသည်။ ထို့အပြင် အသီးများရင့်မှည့်မှု နောက်ကျပြီး အထွက်နှုန်းများကိုလည်းသိသာစွာ လျော့ကျသွားပါသည်။ ရောဂါကျရောက်မှုဆိုးရွားပါက အခင်းသည် အပင်ကြီးထွားမှု နှေးခြင်း၊ အသီးတောင့်များမပြည့်မီခြင်း၊ အဖျင်းအမှော်များခြင်းနှင့် ရိတ်သိမ်းရန်မကျန်ရှိသည်အထိဖြစ်တတ်ပါသည်။<br><br>\r\n\r\nရောဂါဖြစ်စေသော အကြောင်းအရင်းများ<br>\r\n----------------------------------<br><br>\r\n\r\n“အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါ” ကိုဖြစ်စေသည့် အဓိကအကြောင်းအရင်းမှာ ပဲစိုက်ခင်းများသို့ ယင်ဖြူကျရောက်ခြင်းကြောင့်ဖြစ်သည်။ ယင်ဖြူသည် အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါကို သယ်ဆောင်သူဖြစ်သည်။ ပဲပင်၏ အစိတ်ပိုင်းတစ်ခုခုသို့ ယင်ဖြူထိုးစုပ်ချိန် ခြောက်စက္ကန့်ကြာလျှင် ၎င်းဗိုင်းရပ်စ်သည် အပင်ထဲသို့ရောက်ရှိနိုင်ပါသည်။ ထို့ကြောင့် တစ်ကြိမ်ထိုးစုပ်သည်နှင့် အပင်ထဲသို့ရောက်ရှိပြီး ဗိုင်းရပ်စ်အရေအတွက် သောင်း၊ သိန်းချီအောင် ပွားများနိုင်ပါသည်။ ရောဂါကျရောက်လျှင် အချိန်ပမာဏနည်းနည်းဖြင့် တစ်ခင်းလုံးဝါသည့်တိုင် ပျံ့နှံ့နိုင်သော ရောဂါမျိုးဖြစ်သည်။<br><br>\r\n\r\nကာကွယ်နှိမ်နင်းခြင်း<br>\r\n-----------------<br><br>\r\n\r\nပဲစိုက်ခင်းများသို့ ယင်ဖြူကျရောက်သည်ကို သိရှိပြီးမှ ပိုးသတ်ဆေးဖျန်းလျှင် ယင်ဖြူရန်မှ ကာကွယ်နိုင်မည်ဖြစ်သော်လည်း အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်အား ကာကွယ်တားဆီးနိုင်မည်မဟုတ်ပါ။ ရောဂါကျရောက်ပြီးလျှင် ထိရောက်စွာကာကွယ်နှိမ်နင်းရန် မလွယ်ကူသောကြောင့် ကြိုတင်ကာကွယ်သည့်နည်းလမ်းကို အသုံးပြုရန် လိုအပ်သည်။ ယင်ဖြူကျရောက်မှုကို တားဆီးပြီး ရောဂါကာကွယ်နိုင်ရန်အတွက် ကြိုတင်ကာကွယ်ရန် နည်းလမ်းများမှာ .....<br><br>\r\n\r\n(၁) ရောဂါဒဏ်ခံနိုင်ရည်ရှိသောမျိုးများ စိုက်ပျိုးခြင်း<br><br>\r\n\r\nအဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါအား ခံနိုင်ရည်ရှိသောပဲတီစိမ်းမျိုးများမှာ ရေဆင်း-၁၄၊ ရေဆင်း-၁၁၊ ရေဆင်း-၉၊ ရေဆင်း-၈ မျိုးများဖြစ်ပြီး၊ မတ်ပဲမျိုးသည် ရေဆင်း-၇ ဟု ထုတ်ပြန်ထားသော်လည်း တစ်နိုင်ငံလုံးအတိုင်းအတာအနေဖြင့် မျိုးစေ့မလုံလောက်ခြင်းနှင့် ၎င်းရေဆင်းမျိုးများသည် မိမိစိုက်ပျိုးမည့်နေရပ်ဒေသနှင့် ကိုက်ညီမှုမရှိခြင်း စသည့် အခက်အခဲများကြောင့် ဤနည်းလမ်းသည် အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါကိုကာကွယ်ရန် ရာနှုန်းပြည့် အောင်မြင်မှုမရှိနိုင်ပါ။<br><br>\r\n\r\n(၂) စိုက်ချိန်မှန်အောင်စိုက်ပျိုးခြင်း (သို့) စိုက်ချိန်စောစိုက်ခြင်း<br><br>\r\n\r\nဤနည်းလမ်းသည် မိုးစပါးအပြီး ဆောင်းသီးနှံ များများစိုက်ပျိုးရခြင်းဖြစ်သည့်အတွက် မိုးစပါးရိတ်သိမ်းချိန်များတွင် တစ်ချို့နေရာတွင် အခက်အခဲဖြစ်ပေါ်နိုင်သည်။ ထို့ကြောင့် မိုးနည်းသည့် မိုးစပါးရိတ်သိမ်းချိန် မှန်ကန်မှုမရှိသော နေရာများတွင် အဆင်ပြေနိုင်သော်လည်း ရိတ်သိမ်းမှု အခက်အခဲရှိသော နေရာများတွင် ထိရောက်စွာ ကာကွယ်နိုင်မှုမရှိပါ။<br><br>\r\n\r\n(၃) ဖျက်ပိုးများအန္တရာယ် ကြိုတင်ကာကွယ်ခြင်း<br><br>\r\n\r\nပဲတီစိမ်း၊ မတ်ပဲအဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါ မဖြစ်စေရန်အတွက် အဓိက ကာကွယ်ရန်မှာ ယင်ဖြူဖြစ်သည်။ ထို့ကြောင့်ပဲမျိုးစုံတွင်အပင်နှင့် အရွက်များသန်မာမှုရှိစေရန်နှင့် ယင်ဖြူအားကာကွယ်ရန် ရွက်ဖျန်းမြေဩဇာများနှင့် ပိုးသတ်ဆေးအား ပေါင်းစပ်အသုံးပြုခြင်းဖြင့် ကာကွယ်နိုင်ပါသည်။ တောင်သူဦးကြီးတို့အနေဖြင့် အပင်များသန်မာစေရန်ဝိစာရ၏ “စူပါ ပါဝါ၊ မေခလာ(၁)၊ ဓနတိုး” စသည့်ရွက်ဖျန်းမြေဩဇာများ နှင့် ပင်လုံးပြန့်အာနိသင်ရှိ “ကေလာ၊ နိုးဝမ်း” ပိုးသတ်ဆေး တစ်မျိုးမျိုးအား ပေါင်းစပ်ကာ အချိန်မှန်မှန်ကြိုတင်ပက်ဖျန်းအသုံးပြုရန်လိုအပ်ပါသည်။ ကြိုတင်ပေါင်းစပ်အသုံးပြုရာတွင် မတ်ပဲပင် (၁၅) ရက်သားမှစကာ (၁၀) ရက်တစ်ကြိမ် ပုံမှန်ပက်ဖျန်းပေးခြင်းအားဖြင့် ကာကွယ်နိုင်သည်။ ဆေးများပက်ဖျန်းသည့်အခါ ပဲပင်များ၏ အရွက်အပေါ်နှင့်အောက် အနှံ့ရောက်အောင်ပက်ဖျန်းပေးရမည်။ အများအားဖြင့် ယင်ဖြူသည် အရွက်၏အောက်မျက်နှာပြင်တွင် ခိုအောင်းကပ်တွယ်နိုင်သောကြောင့် ပဲပင်၏ အရွက် အောက်မျက်နှာပြင်အား ဆေးရည်ရောက်ရှိရန် အထူးလိုအပ်သည်။<br><br>\r\n\r\n↗️ ဖော်ပြပါကာကွယ်နှိမ်နင်းနည်းများအနက် တတိယမြောက်နည်းလမ်းသည် ပိုမိုထိရောက်မှုရှိပြီး ကျန်နှစ်ခုသည် ထိရောက်မှုမရှိဟု ဆိုလိုခြင်းမဟုတ်ပါ။ မိမိနေထိုင်ရာ အရပ်ဒေသအလိုက် အဆင်ပြေ၊ သင့်တော်မည့် နည်းလမ်းများအား ပေါင်းစပ်အသုံးပြုခြင်းဖြင့် ပဲတီစိမ်း၊ မတ်ပဲနှင့် ပဲမျိုးစုံတွင် ကျရောက်သော အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါအား ကြိုတင်ကာကွယ်နိုင်ပြီး ပဲမျိုးစုံအထွက်တိုး စေရန်ဆောင်ရွက်ကြရမည်ဖြစ်ပါသည်။\r\n<br><br>\r\n\r\n↗️ ဆက်လက်၍ အကြံပြုရေးသားလိုသည်မှာ .....<br><br>\r\n\r\n☑️ ထိုရောဂါသည် မျိုးစေ့ဆောင်ရောဂါမဟုတ်သော်လည်း မျိုးစေ့မှ ၃ မှ ၆ ရာခိုင်နှုန်း ကူးစက်နိုင်သည့်အတွက် ယခုကဲ့သို့ရောဂါကျအခင်းများမှထွက်ရှိလာသော ပဲစေ့များကို မျိုးအဖြစ်သိုလှောင်ခြင်း၊ နောက်သီးနှံတွင်မျိုးအဖြစ်ပြန်လည်စိုက်ပျိုးခြင်းမျိုးမပြုလုပ်ရန် အထူးဂရုပြုရပါမည်။<br><br>\r\n\r\n☑️ ရောဂါကျခဲ့သောစိုက်ခင်းများကို စနစ်တကျ ထယ်ထိုးမြေလှန်ပြီးမှ နောက်သီးနှံ စိုက်ပျိုးပေးရပါမည်။ <br><br>\r\n\r\n☑️ ထို့အပြင် ရောဂါကျစိုက်ခင်းများပတ်ဝန်းကျင်ရှိကန်သင်းမြေများပေါ်မှ ယင်ဖြူနှင့် ဖျက်ပိုးများခိုအောင်းနိုင်မည့် ပေါင်း၊မြက်များကို ပြောင်စင်အောင်ရှင်းလင်းပေးပါ။ <br><br>\r\n\r\n☑️ ပဲတီစိမ်း၊ မတ်ပဲ စိုက်ခင်းများထဲတွင် ထိုရောဂါ ကူးစက်ခံထားရသော အပင်များတွေ့ရှိပါက နောက်ထပ်အပင်များကို မကူးစက်စေရန် ချက်ချင်းနုတ်၍ မီးရှို့ပစ်ရပါမည်။<br><br>\r\n\r\n↗️ သို့ဖြစ်ရာ ပဲတီစိမ်း၊ မတ်ပဲ နှင့် ပဲမျိုးစုံတွင်ကျရောက်တတ်သော အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်ရောဂါ နှင့် ပတ်သက်သည်များကိုသိရှိမှတ်သားပြီး ဦးကြီးတို့၏ပဲမျိုးစုံစိုက်ခင်းများတွင် “အဝါရောင်မိုစေ့ဗိုင်းရပ်စ်” ရောဂါကင်းစင်ပြီး အထွက်နှုန်းကောင်းသည့်စိုက်ခင်းများဖြစ်စေဖို့ ဝိုင်းဝန်းကြိုးပမ်းဆောင်ရွက်ကြပါစို့။<br><br>\r\n\r\n', '#ffffc2', '18-02-2024'),
(20, '“ပြောင်းပင် နှင့် အာဟာရ”', 'IMG-65d23a94d5e648.80701031.jpg', '🌱🌽🌱🌽🌱🌽🌱🌽🌱🌽🌱<br><br>\r\n\r\n⏩ မြန်မာနိုင်ငံတွင် ပြောင်းသီးနှံကို ရှမ်းပြည်နယ် နှင့် မြန်မာနိုင်ငံ အလယ်ပိုင်းတို့တွင် စိုက်ပျိုးမှုများသည်ကို တွေ့ရှိရပါသည်။ ပြောင်းသီးနှံသည် ကောက်နှံပင်များတွင် ကာဘွန်လေးလုံး အလင်းမှီအစာစုဖွဲ့နည်း(C4 Photosynthesis) ဖြင့် အစာချက်လုပ်သည့်အပင်ဖြစ်ပြီး ပူပြင်းခြောက်သွေ့တဲ့ ဒေသမျိုးမှာ C4 အပင်တွေက ပိုမိုအောင်မြင်ဖြစ်ထွန်းကြပါသည်။ ယနေ့ကမ္ဘာ့လေထုတွင် ကာဗွန်ဒိုင်အောက်ဆိုဒ်(Carbon Dioxide) ပိုမိုများပြားလာပြီး ပိုလည်းပူနွေးလာပါသည်။ ပူနွေးခြောက်သွေ့ခြင်းက C4 အပင်တွေကို မျက်နှာသာပေးပါသည်။ ထို့ကြောင့် မြန်မာနိုင်ငံရှိပြောင်းစိုက်ဧကများတွင် ရာသီဥတုနှင့် စိုက်ပျိုးမြေသာ အခြေအနေပေးပါက စိုက်ပျိုးသူ၏ကျွမ်းကျင်မှုနှင့် စိုက်ပျိုးနည်းစနစ်များ၊ အပင်ပြုစု စောင့်ရှောက်ခြင်း တို့ကိုထိန်းချုပ်ပေးခြင်းဖြင့် အထွက်နှုန်းကောင်းရရန်ဆောင်ရွက်နိုင်ပါသည်။ <br><br>\r\n\r\n⏩ ပြောင်းသီးနှံသက်တမ်းတစ်လျှောက် လိုအပ်သောအာဟာရဓာတ်များကိုထည့်သွင်းပေးရန်အတွက် မှန်ကန်သောစီမံခန့်ခွဲမှုသည်လည်း ပြောင်းစိုက်ပျိုးခြင်းရဲ့ အရေးကြီးသည့်ကဏ္ဍတစ်ခုဖြစ်ပါ သည်။ ပြောင်းသီးနှံသည် အာဟာရလိုအပ်ချက်မြင့်မားသောသီးနှံဖြစ်သည့်အတွက် အာဟာရဓာတ်များကို လုံလောက်စွာ ထည့်မပေးနိုင်ပါက ၆၀ ရာခိုင်နှုန်းအထိ အထွက်နှုန်းကို ထိခိုက်စေပါသည်။ ပြောင်းပင်က နိုက်ထရိုဂျင်နှင့် ပိုတက်စီယမ်ပမာဏကို များစွာလိုအပ်ပြီး ဆာလ်ဖာ၊ ဖော့စဖိတ်၊ ကယ်လ်စီယမ် နှင့် မဂ္ဂနီစီယမ် စသည့် အာဟာရဓာတ်တွေကိုလည်း အထူးလိုအပ်သည့် သီးနှံဖြစ်ပါသည်။<br><br>\r\n\r\n⏩ နိုက်ထရိုဂျင် ၇၅ ရာခိုင်နှုန်းကို ပြောင်းဖူးပင်၏ အပင်ပိုင်းကြီးထွားမှုအဆင့် (ပြောင်းဖူးအနှံမထွက်မီအချိန်) တွင် လိုအပ်ပါသည်။ ထိုအချိန်မှာ နိုက်ထရိုဂျင်ဓာတ်ကို လုံလောက်စွာမရခဲ့ပါက ပင်စည် နှင့် အရွက်များကြီးထွားမှုကို ထိခိုက်နိုင်သည့်အပြင် ပြောင်းစေ့အဆန်ထွက်မှုကို ထိခိုက်နိုင်သည့်အတွက် အထွက်နှုန်းကိုပါလျော့ကျစေနိုင်ပါသည်။ နိုက်ထရိုဂျင်ရဲ့ကျန်တဲ့ပမာဏကတော့ ပန်းပွင့်တဲ့အချိန် နှင့် အစေ့အဆန်ဖြည့်တင်းတဲ့အချိန်တွင် လိုအပ်ပါသည်။ ပိုတက်စီယမ်ဓာတ် ၅၀ ရာခိုင်နှုန်းကို အပင်ပိုင်းကြီးထွားမှုအဆင့်တွင် လိုအပ်ပါသည်။ ပန်းစပွင့်သည့်အချိန်နှင့် နို့ရည်တည်သည့်အဆင့်တွင် ဖော့စဖိတ် ၄၅ ရာခိုင်နှုန်းကိုလိုအပ်ပြီး ၎င်းအချိန်မှာ ဖော့စဖိတ်ဓာတ်ရဲ့ လိုအပ်ချက်အမြင့်မားဆုံးအချိန်လည်း ဖြစ်ပါသည်။ ၎င်းအာဟာရဓာတ်များ၏ ကျန်သည့်ပမာဏကိုတော့ သန္ဓေဆောင်ချိန်၊ ပန်းပွင့်ချိန်၊ အစေ့အဆန်ဖြည့်တင်းချိန်၊ ရင့်မှည့်သည့်အချိန်တို့တွင် လိုအပ်ပါသည်။ <br><br>\r\n\r\n⏩ အာဟာရဓာတ်များကိုလိုအပ်ချိန်တွင် မဖြည့်တင်းပေးပါက အပင်ကြီးထွားမှုနှေးကွေးကာ စိမ်းလန်းသောပြောင်းပင်အရွက်များမှာ အရောင်ပြောင်းသွားပြီးအပင်၏အလင်းမှီအစာချက်လုပ်မှုကိုပါ ထိခိုက်နိုင်သည်။ ထို့ကြောင့် သီးနှံပင်၏ အာဟာရဓာတ်လိုအပ်သောအချိန်၌ ၎င်းအာဟာရဓာတ်ကို အချိန်မီဖြည့်တင်းပေးနိုင်ရန်မှာ အလွန်အရေးကြီးလှပြီး ယခုကဲ့သို့ကိုက်ညီအောင်ဖြည့်တင်းပေးနိုင်မှသာ ပြောင်းသီးနှံအတွက် အရည်အသွေး နှင့် အထွက်ကောင်းရရှိနိုင်မည်ဖြစ်သည်။<br><br>\r\n\r\n⏩ ပြောင်းစိုက်ပျိုးရာတွင် မြေပြုပြင်ချိန်တွင် နွားချေး၊ မြေဆွေး စသည်တို့ကို တစ်ဧကလျှင် ၃ တန်မှ ၅ တန်နှုန်း ထည့်သွင်းပေးရမည်။ မြေကြီး၏ရုပ်ဂုဏ်သတ္တိနှင့် ဓာတ်ဂုဏ်သတ္တိများတိုးပွားစေရန် ကောင်းစွာဆွေးမြေ့နေသော သဘာဝမြေသြဇာနှင့် သစ်ရွက်ဆွေးမြေသြဇာများကို မြေဆီလွှာအတွင်း နှစ်စဉ်ထည့်သွင်းပေးသင့်ပါသည်။ ဓာတ်မြေသြဇာများထည့်သွင်းရာတွင် မြေပြင်ချိန်တွင် တစ်ဧကလျှင် ယူရီးယား (၁၁၂) ပေါင်၊ တီစူပါ (၁၁၂) ပေါင်၊ ပိုတက်ရှ် (၅၆) ပေါင်နှုန်း ထည့်သွင်းပေးရမည်။ပြောင်းဖူးပင်သက်တမ်း (၂၀-၂၁) ရက်သား ကြားထွန်ဝင်သည့်အချိန်တွင် တစ်ဧကလျှင် ယူရီးယား ၅၆ ပေါင်၊ ပိုတက်ရှ် ၂၈ ပေါင်နှုန်း ထည့်သွင်းပေးရမည်။ ပြောင်းပင်၏သက်တမ်း (၃၅ - ၄၀) ရက်သား ဘောင်တင်သည့်အချိန်တွင် ယူရီးယား (၁၁၂) ပေါင်၊ ပိုတက်ရှ် ၂၈ ပေါင်နှုန်း ထည့်သွင်းပေး၍ ဘောင်တင်ပေးရပါမည်။<br><br>\r\n\r\n⏩ မြေသြဇာမကျွေးမီ အပင်ခြေရှိပေါင်းမြက်များကို ကင်းစင်အောင်ပြုလုပ်ပေးရန်လည်းအရေးကြီးပါသည်။ ပေါင်းမြက်များကင်းစင်မှသာလျှင် ထည့်ပေးသောအာဟာရဓာတ်များကို ပြောင်းပင်က အပြည့်အဝ ရရှိနိုင်မှာဖြစ်ပါသည်။ အပင်ပေါက်သည်မှ တစ်လသားအတွင်း ပေါင်းမြက်ကင်းစင်ရန်နှင့် ရေမဝပ်ရန် အထူးဂရုစိုက်ဆောင်ရွက်ရပါမည်။ ပြောင်းစိုက်ပျိုးပြီးသောမြေသည် အာဟာရဓာတ်ဆုံးရှုံးမှုများသည့် အတွက်ကြောင့် ပြောင်းသီးနှံဆက်တိုက်စိုက်ပျိုးခြင်းကို ရှောင်ရှားပြီး ပဲမျိုးစုံသီးနှံများဖြင့် သီးလှည့်စိုက်ပျိုး၍ ဆုံးရှုံးသွားသော အာဟာရဓာတ်များကို ပြန်လည်ဖြည့်တင်းပေးသင့်ပါကြောင်း အကြံပြုရေးသားလိုက်ရပါသည်။<br><br>\r\n\r\n\r\n\r\nကိုးကား : စိုက်ပျိုးရေးဦးစီးဌာန', '#addfff', '18-02-2024'),
(21, '\"ငရုတ်အပွင့်များအသီးမတင်ပဲ ဝါပြီးကြွေရသည့် အကြောင်းများ\"', 'IMG-65d23b33b99297.31338179.jpg', '🍃🌶🍃🌶🍃🌶🍃🌶🍃🌶🍃<br><br>\r\n\r\n✅ဦးကြီးတို့ငရုတ်စိုက်ခင်းများအတွင်း သီးနှံပင်များတွင်အသီးမတင်ပဲ အပွင့်များဝါပြီးကြွေကျနေသည်များ ကြုံတွေ့ရတတ်ပါသည်။ ထိုသို့ဖြစ်ပေါ်ရသည့်အကြောင်းရင်းများ နှင့် ကြိုတင်ကာကွယ်နိုင်ရန် နည်းလမ်းများကို ဗဟုသုတအဖြစ်သိရှိနိုင်ပါရန် တင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n(၁) ရာသီဥတု အခြေအနေကြောင့် အပူအအေးမမျှတခြင်း (ပူလွန်းခြင်း သို့မဟုတ် အေးလွန်းခြင်း)<br><br>\r\n\r\n(၂) ရေအလွန်အကျွံပေးမိ၍ အပင်ခြေရေဝပ်ခြင်း (သို့မဟုတ်) ရေငတ်ဒဏ်ခံရခြင်း။<br><br>\r\n\r\n(၃) အပင်ဦးရေများ၍ အပင်စိပ်လွန်းသဖြင့် လေဝင်လေထွက်အားနည်းခြင်း။<br><br>\r\n\r\n(၄) အသီးဖြစ်စေရန် အရေးကြီးသည့် ဝတ်မှုန်ကူးမှု မအောင်မြင်ခြင်း။<br><br>\r\n\r\n(၅) မြေသြဇာ အသုံးများခြင်း (ဓာတ်မြေဩဇာများအသုံးပြုရာတွင် သီးနှံပင်၏လိုအပ်ချက်အလိုက် အချိုးအစားမျှတစွာ ထည့်သွင်းပေးရပါမည်။)<br><br>\r\n\r\n(၆) အာဟာရချို့တဲ့ခြင်း (သို့မဟုတ်) လွန်ကဲစွာကျွေးခြင်း။ (လိုအပ်သောအနည်းလို အာဟာရဓာတ်များ အတွက် ရွက်ဖျန်းအားဆေးများကိုထောက်ခံနှုန်းထားများအတိုင်း အသုံးပြုပေးရပါမည်။)<br><br>\r\n\r\n(၇) ဖျက်ပိုးများဖျက်ဆီးခံရခြင်း(လှေးပိုးသည် ငရုတ်အပွင့်ကြွေရသည့် အကြောင်းအရင်းများထဲတွင် အဓိကပါဝင်သည်။ လှေးပိုးသည် ပန်းပွင့်အတွင်းရှိဝတ်ဆံများကို စားသောက်ဖျက်ဆီးကြသည်။ အဖူးအပွင့်များသည် ကြေးနီရောင်ပြောင်းလာပြီး ရိုးတံများကြွပ်ဆပ်ကာကြွေကျသွားရသည်။ လှေးပိုးကိုကာကွယ်နှိမ်နင်းရန် စိုက်ခင်းရေမပြတ်အောင် ဂရုစိုက်ပါ။ ရေသွင်းချိန်မှာဖြစ်စေ၊ မြေအစိုဓာတ်ကောင်းချိန်မှာဖြစ်စေ အပင်ခြေရင်းကို ဒီပါ (သို့) ဖစ်ပရို ဆေးခဲတစ်မျိုးမျိုးကြဲပက်ပေးပါ။ (သို့မဟုတ်) ပရိုဆင့် ပိုးသတ်ဆေးဖျန်းပေးရပါမည်။)<br><br>\r\n\r\n(၈) ငရုတ်တွင်အဖြစ်များသော ကိုင်းဖျားခြောက်ရောဂါကျရောက်ခြင်း(ကိုင်းဖျားခြောက်ရောဂါအတွက် “ဒိုင်ဇီ” မှိုသတ်ဆေးကို ကာကွယ်ဆေးအဖြစ် ငရုတ်အပွင့်မဝင်မီကပင်(၁၀)ရက်ခြားတစ်ကြိမ်ခန့် ကြိုတင်ပက်ဖျန်းပေးရပါမည်။)<br><br>\r\n\r\n✅ဦးကြီးတို့ငရုတ်စိုက်ခင်းများအတွင်း အထက်ပါအကြောင်းအချက်များမတွေ့ရှိရပဲ အပွင့်များကြွေပါက ဝိစာရ၏ အသီးတင်အားဆေးများဖြစ်သော “ကယ်လ်စီပလပ် နှင့် ဘိုစတာဟော်မုန်း” ရောစပ်ပက်ဖျန်းပေးပါရန် အကြံပြုရေးသားအပ်ပါသည်။<br><br>\r\n\r\n', '#57feff', '18-02-2024'),
(22, '“သရက်ပွင့်သီးမှုအတွက် ရိုးရှင်းတဲ့ဆောင်ရွက်နည်းများ”', 'IMG-65d23beda50477.70592356.jpg', '🥭🥭🥭🥭🥭🥭🥭🥭🥭🥭<br><br>\r\n\r\n🔼သရက်ပင်မှ အသီးသီးလာရန်အတွက် ပန်းပွင့်မှုဟာ အရေးကြီးတဲ့ ဇီဝကမ္မဖြစ်စဉ် ဖြစ်ပါတယ်။ သရက်ပန်းပွင့်လာစေရန်အတွက်ပန်းခိုင်၊ ပန်းပွင့်စတင်ဖြစ်လာမှုဟာ ပထမဆုံးဖြစ်စဉ် ဖြစ်ပါတယ်။ သရက်ပင်ရဲ့ ကြီးထွားမှုဖြစ်စဉ်ကိုကြည့်သော် အညွန့်စတင်ဖြစ်ပေါ်လာပြီးနောက် ထိပ်ဖူးမှ ပန်းခိုင်ဖူးခွဲခြားဖြစ်ပေါ်လာကာ ပန်းခိုင်ထွက်ပေါ်လာစေတာ ဖြစ်ပါတယ်။ သရက်တွင် ပန်းခိုင်ထွက်ကာ ပန်းပွင့်မှု မတူကွဲပြားခြားနားနေမှုဟာ စိုက်ပျိုးထားတဲ့ သရက်သီးမျိုး၊ သရက်ပင်ရဲ့ သက်တမ်း၊ ပတ်ဝန်းကျင်အခြေအနေများ၊ စိုက်ပျိုးထားရာဒေသများဖြစ်တဲ့ ခြောက်သွေ့တဲ့ သို့မဟုတ် စိုစွတ်တဲ့ အပူပိုင်းဒေသရဲ့အပင်ကြီးထွားဖြစ်ထွန်းနေမှု အခြေအနေများပေါ် မူတည်ကွဲပြားခြားနားတာကို တွေ့ရပါတယ်။<br><br>\r\n\r\n🔼သရက်ဟာအမြဲစိမ်း အပူပိုင်းအပင်မျိုးဖြစ်ကာ နှစ်ခြားသီးမှုခေါ်တဲ့ အသီးသီးပြီး နောက်နှစ်တွင် အသီးမသီးတော့ဘဲ လာမည့်နှစ်ရောက်မှသာ အသီးပြန်သီးလေ့ရှိတဲ့ “အလှည့်ကျအသီးသီးတဲ့ အလေ့အထရှိတဲ့” အပင်မျိုးဖြစ်ပါတယ်။ မြန်မာနိုင်ငံရဲ့ သရက်စိုက်ပျိုးထုတ်လုပ်နေကြတဲ့ဒေသများ အနက်၊ အပူပိုင်းဒေသများဟာ ရှမ်းပြည်နယ်ကဲ့သို့သော အပူလျော့ပိုင်းဒေသများထက် နှစ်စဉ် ပန်းပွင့်အသီးရရှိမှုတွင် မတည်ငြိမ်မှုများ၊ အခက်အခဲများ ကြုံတွေ့ရပါတယ်။<br><br>\r\n\r\n🔼ယခုအခါ မြန်မာနိုင်ငံအလယ်ပိုင်းနဲ့ တောင်ပိုင်းဒေသများတွင် သရက်ပွင့်သီးမှု နည်းပါးတာကို တွေ့ရပါတယ်။ ယခင်နှစ်က အသီးများခဲ့တဲ့ နှစ်စဉ်အသီးသီးလေ့ရှိကြတဲ့သရက်မျိုးများပင်လျှင် အသီးမသီးတဲ့အပင်များ သို့မဟုတ်အသီးနည်းသွားတဲ့ အပင်များကို တွေ့ရပါတယ်။ ဥပမာ မြကျောက်သရက်မျိုးဟာ နှစ်စဉ်ပွင့်သီးလေ့ရှိတဲ့ သရက်မျိုးထဲမှာ ပါဝင်ပါတယ်။ ယခုနှစ်တွင် ပန်းပွင့်မှုမရှိတဲ့အပင်များကို တွေ့လာရသကဲ့သို့ ပန်းပွင့်မှုနည်းတဲ့ အပင်များကိုလည်း တွေ့လာရပါတယ်။ အထူးသဖြင့် စီးပွားဖြစ်စိုက်ခင်းများနဲ့ စိုက်ပျိုးထားတဲ့ အပင်များထက် အိမ်ခြံဝင်းများမှာ စိုက်ပျိုးထားကြတဲ့ အပင်များမှာတွေ့ရပါတယ်။ ယခင်နှစ်က အသီးများခဲ့တဲ့ စိန်တလုံးကဲ့သို့ နှစ်ခြားသီးလေ့ရှိတဲ့ အပင်မျိုးများမှာ ယခုနှစ်တွင် လုံးဝမသီးကြတာကို တွေ့ရပါတယ်။<br><br>\r\n\r\n🔼စီးပွားဖြစ် စိုက်ခင်းများမှာမူ ပန်းပွင့်မှုနည်းတဲ့အပင်များနဲ့အတူ ပန်းမပွင့်တဲ့အပင်များ ရောနှောရှိနေတာကိုတွေ့ရပါတယ်။ အပူပိုင်းဒေသ၊ အိမ်ခြံဝင်းအတွင်းအပင် အနည်းငယ်ကိုသာ စိုက်ပျိုးကြရာတွင် သဘာဝအတိုင်းသာ စိုက်ပျိုးထားကြတာ များပါတယ်။ ရေလောင်းမှု၊ မြေသြဇာကျွေးမှု၊ ပိုးသတ်ဆေးများ၊ ပွင့်သီးစေတဲ့ ဆေးများကို အသုံးပြုလေ့ မရှိကြပါ။ သို့အတွက် အိမ်ခြံဝင်းများမှ ထွက်ရှိတဲ့ သရက်သီးအများစုဟာ အော်ဂဲနစ်သရက်သီးများအဖြစ်ပင် သတ်မှတ်နိုင်ပါတယ်။ သို့သော်ရာသီဥတုဖောက်ပြန်မှုများကြောင့် အအေးဓာတ်လုံလောက်စွာ မရရှိတဲ့အခါ သရက်ပင်များပန်းပွင့်မှုမရှိခြင်း (သို့မဟုတ်) နည်းခြင်းများ ဖြစ်စေတာဖြစ်ပါတယ်။<br><br>\r\n\r\n🔼စီးပွားဖြစ်စိုက်ခင်းများမှာမူ စိုက်ပျိုးပြုစုနည်းများဖြစ်တဲ့ ကိုင်းဖြတ်၊ ကိုင်းရှင်းခြင်း၊ မြေသြဇာ ကျွေးမွေးပေးခြင်း၊ ပိုးသတ်ဆေးများ၊ ပန်းပွင့်သီးဆေးများကို ပက်ဖျန်းပေးခြင်းများကို ဆောင်ရွက်ပေးကြတဲ့အတွက် အအေးဓာတ်လုံလောက်စွာမရသည့်တိုင် ပန်းပွင့်လာနိုင်ကြတာကို တွေ့ရပါတယ်။ သို့အတွက် အပူပိုင်းဒေသများမှာ အိမ်ခြံဝင်းများအတွင်း အပင်အနည်းငယ်ကိုသာ စိုက်ပျိုးနေကြသူများအနေနဲ့ အသီးခူးပြီးနောက် သဘာဝမြေသြဇာများ၊ ဓာတ်မြေသြဇာများကို ပုံမှန်ကျွေးပေးသင့်ပါတယ်။ မိုးနှောင်းရာသီ သရက်ပင်များ ပန်းဖူးစတင်မဖြစ်သေးမီတွင်လည်း နောက်ထပ်တစ်ကြိမ် မြေသြဇာကျွေးပေးသင့်ပါတယ်။<br><br>\r\n\r\n🔼အသီးခူးပြီးနောက် အပင်အလင်းဖွင့်ပေးခြင်းအဖြစ် ကိုင်းဖြတ်၊ ကိုင်းရှင်းခြင်း လုပ်ငန်းများကိုလည်း ဆောင်ရွက်ပေးရန် လိုအပ်ပါတယ်။ မိုးရာသီကုန်ပြီးနောက်သရက်ပင်များ ရေငတ်နေစေရန် အစိုဓာတ်ဖြတ်ပေးထားပြီး ရေသွင်းပေးခြင်းဖြင့်လည်း သရက်ပင်များပန်းပွင့်လာစေနိုင်ပါတယ်။ သို့သော် လက်တွေ့ဆောင်ရွက်ရန်မှာ အခက်အခဲများ ရှိနိုင်ပါတယ်။ သရက်ပန်းပွင့်မှုအတွက် အားပေးမှု၊ ဟန့်တားမှု များဖြစ်စေတဲ့ အခြေအနေများစွာရှိတဲ့အနက် အပင်အနည်းငယ်သာ စိုက်ပျိုးကြသူများအနေနဲ့ စိုက်ပျိုးပြုစုနည်းတချို့ကိုဆောင်ရွက်ပေးသင့်ပါတယ်။<br><br>\r\n\r\n🔼လွယ်ကူရိုးရှင်းတဲ့သရက်ပန်းပွင့်စေရန် ဆောင်ရွက်နိုင်တဲ့နည်းများကတော့ ပင်စည်ကို ဓားထစ်ပေးတဲ့ နည်း (သို့မဟုတ်) အခေါက်ရစ်ခွာပေးတဲ့နည်းပင် ဖြစ်ပါတယ်။ အခြေခံသဘောတရားမှာ အပင် အပေါ်ပိုင်းတွင် ကာဘိုဟိုက်ဒရိတ်များနေပြီးနိုက်ထရိုဂျင်ဓာတ်နည်းနေစေရန်အတွက် ကာဘို ဟိုက်ဒရိတ် နဲ့ နိုက်ထရိုဂျင်အချိုးကို ထိန်းညှိပေးတာဖြစ်ပါတယ်။<br><br>\r\n\r\n🔼မိုးနှောင်းရာသီရောက်သော် အရွက်ရင့်နေပြီးအပင်များကိုမြေမှ အမြင့်နှစ်ပေမှ သုံးပေနေရာတွင် ပင်စည်ပတ်လည်အပင်ရဲ့အခေါက်ကိုပြတ်နေစေရန် ဓားထစ်ပေးထားရမှာ ဖြစ်ပါတယ်။ အဓိကရည်ရွယ်ချက်မှာ အပင်ရဲ့အပေါ်ပိုင်းမှာရှိနေတဲ့အရွက်များမှ အလင်းမီအစာချက်လုပ် ရရှိထားတဲ့ အစာများကို အပင်ရဲ့အပေါ်ပိုင်းအကိုင်းအခက်များတွင်သာ စုနေစေရန်အတွက် အမြစ်ပိုင်းဆီသို့ ပေးပို့မှုလျော့နည်းစေရန် အစာကြောကိုဖြတ်ပေးတာဖြစ်ပါတယ်။ အပင်အပေါ်ပိုင်းများမှ ပေးပို့လိုက်တဲ့ အစာများဟာ ဓားထစ်ထားတဲ့နေရာ (သို့မဟုတ်) အခေါက်ရစ်ခွာထားတဲ့နေရာများရောက်သော် အစာများ မြေအောက်ရှိအမြစ်များဆီသို့ မရောက်နိုင်စေရန် ဟန့်တားပေးလိုက်တာဖြစ်ပါတယ်။<br><br>\r\n\r\n🔼ဒီနည်းစနစ်ဟာ ရှေးကာလများမှာကတည်းကပင်ကျင့်သုံးလာခဲ့ကြတာဖြစ်ပြီး တချို့မျိုးများမှာ ထိရောက်မှုရှိစေပါတယ်။ သို့သော် တချို့မျိုးများအတွက် ပန်းပွင့်လာစေရန်မှာမသေချာနိုင်ပါ။ ယခင်နှစ် အသီးသီးခဲ့တဲ့သရက်ပင်များကို ယခုနှစ်ပန်းပွင့်လာစေရန်အပင်အနည်းငယ်သာ စိုက်ပျိုးသူများအနေနဲ့ ကျင့်သုံးသင့်တဲ့ လွယ်ကူတဲ့နည်း ဖြစ်ပါတယ်။<br><br>\r\n\r\n🔼နောက်တစ်နည်းကတော့ ပင်စည်ပေါ်မှာ မပြုလုပ်လိုပါက အကိုင်းရင်းနေရာများတွင် အခေါက်ကို သွပ်နန်းကြိုးဖြင့် တင်းနေစေရန်ချည်နှောင်ပေးခြင်း (ကြိုးချည်ပေးခြင်း) နည်းဖြင့်လည်း အပင်ရဲ့ အပေါ်ပိုင်းများမှအစာများအောက်ပိုင်းသို့ ပေးပို့ရောက်ရှိမှုကိုဟန့်တားပေးနိုင်ပါတယ်။ <br><br>\r\n\r\n🔼ရှေးကာလ များမှာကတည်းကပင်ကျင့်သုံးလာခဲ့ကြတဲ့ နည်းတစ်ခုကတော့ အပင်အောက်မှ မီးခိုးမှိုင်း တိုက်ပေးခြင်းဖြစ်ပါတယ်။ တစ်ချက်ခုတ်နှစ်ချက်ပြတ်စေတဲ့နည်းလို့ ခေါ်နိုင်မယ်ထင်ပါတယ်။ မီးခိုးမှိုင်းတိုက်ပေးခြင်းဖြင့် အပင်မှာကျရောက်နေတဲ့ပိုးများကို မောင်းနှင်ပေးသကဲ့သို့ မီးခိုးမှိုင်းကြောင့် ပန်းခိုင်ဖူးထွက်လာစေနိုင်ပါတယ်။ မီးခိုးမှိုင်းမှာပါဝင်နေတဲ့ အီသလင်းဓာတ်များက သရက်ပင်ကိုင်းများရဲ့ ထိပ်ဖူးများမှအညွန့်၊ အရွက်များ ထွက်လာမယ့်အစားပန်းခိုင်ဖူးအဖြစ် ပြောင်းလဲထွက်လာစေရန် ကူညီအားပေးတယ်လို့ ယူဆကြပါတယ်။ အီသလင်းဓာတ်ငွေ့ဟာ အပင်များမှ ထုတ်လုပ်ထွက်ရှိတဲ့ သဘာဝအပင်ဟော်မုန်းတစ်မျိုး ဖြစ်ပါတယ်။ အပင်အမျိုးအစားပေါ်မူတည်ကာ အပင်ရဲ့ကြီးထွား ဖွံ့ဖြိုးမှုကို အမျိုးမျိုးတုံ့ပြန်ဖြစ်ပေါ်စေနိုင်ပါတယ်။<br><br>\r\n\r\n🔼မီးခိုးမှိုင်းတိုက်ပေးရာတွင် သရက်ပင်ရှိ အရွက်များ အရွယ်ရင့်နေစေရန် လိုအပ်မှာဖြစ်ပါတယ်။ အရွက်နုရှိနေတဲ့ အပင်များမှာမူ ထိရောက်မှုမရှိနိုင်ကြောင်း သုံးသပ်ထားကြပါတယ်။ သရက်ပန်းပွင့်လာ စေရန်အီသလင်းဟော်မုန်းရဲ့ အကူအညီနဲ့ ဆောင်ရွက်ပေးနိုင်ကြောင်းကိုစမ်းသပ်လေ့လာ တွေ့ရှိမှုများရှိနေပြီးဖြစ်ပါကြောင်းရေးသားတင်ပြလိုက်ရပါတယ်။<br><br>\r\n\r\nSources : ဒေါက်တာစိန်လှဗိုလ်<br><br>\r\n\r\nမြန်မာတောင်သူကြီးများ ဂျာနယ်', '#ff6763', '18-02-2024'),
(23, '“ပြောင်းအထွက် နှင့် ပေါင်းမြက်အန္တရာယ်”', 'IMG-65d23cddd293e9.91592153.jpg', '🌽🌱🌽🌱🌽🌱🌽🌱🌽🌱🌽<br><br>\r\n\r\n▶️မြန်မာနိုင်ငံတွင် ပြောင်းသီးနှံသည် ဆန်၊ စပါးပြီးလျှင် ဒုတိယအရေးပါသော သီးနှံများမှတစ်ခုဖြစ်သည်။ ပြောင်းသီးနှံကို မြန်မာနိုင်ငံတွင် စိုက်ဧကစုစုပေါင်း (၁)သန်း မှ (၁.၂)သန်းကျော်ခန့် စိုက်ပျိုးကြသည်။ စိုက်ဧကစုစုပေါင်း၏ ၅၅ရာခိုင်နှုန်းခန့်ကို ရှမ်းပြည်နယ်တွင်စိုက်ပျိုးကြပြီး အခြားအဓိကစိုက်ပျိုးသော ဒေသများမှာ မန္တလေးတိုင်း၊ ကချင်ပြည်နယ်၊ ဧရာဝတီတိုင်းဒေသကြီး၊ ပဲခူးတိုင်းဒေသကြီး နှင့် ကရင်ပြည်နယ်တို့ဖြစ်သည်။<br><br>\r\n\r\n▶️ပြောင်းစိုက်ဧရိယာစုစုပေါင်း၏ ၈၅ရာခိုင်နှုန်းဝန်းကျင်ကို မိုးသီးနှံအဖြစ် မေလ နှင့် ဇွန်လတွင် စိုက်ပျိုးကြပြီး အောက်တိုဘာ၊ နိုဝင်ဘာလများတွင် ရိတ်သိမ်းကြပါသည်။ စိုက်ဧရိယာ၏ ကျန် ၁၅ရာခိုင်နှုန်းကို နိုဝင်ဘာလ မှ ဒီဇင်ဘာလအတွင်း ဆောင်းယာသီးနှံအဖြစ်စိုက်ပျိုး၍ မတ်လ နှင့် ဧပြီလတွင် ရိတ်သိမ်းကြပါသည်။<br><br>\r\n\r\n▶️ထိုသို့ပြောင်းသီးနှံ စိုက်ပျိုးထုတ်လုပ်ကြရာတွင် ပေါင်းမြက် ကာကွယ်နှိမ်နင်းခြင်းကို မဖြစ်မနေ ဆောင်ရွက်ရပါမည်။ ပြောင်းဖူးပင်များ တစ်လသားမပြည့်မီ ပေါင်းမြက်ကို နိုင်နင်းစွာမနှိမ်နင်းပါက ထည့်သွင်းသောအာဟာရဓာတ်များဆုံးရှုံးပြီး အပင်များမကြီးထွားနိုင်တော့ဘဲ ဝါလာတတ်သည်။ ထို့အပြင် ပေါင်းပင်များတွင်အမှီပြု၍ ခိုအောင်းနေထိုင်သော ရွက်ဖြတ်ပိုးများလည်း ကျရောက်လာတတ်ပါသည်။ <br><br>\r\n\r\n▶️ပေါင်းပင်များ၏ဖျက်ဆီးမှုကြောင့် ပြောင်းဖူးအစေ့အထွက်ကို (၃၆ မှ ၆၀) ရာခိုင်နှုန်းထိ လျော့နည်း စေနိုင်သည်။ လျော့နည်းမှုရာခိုင်နှုန်းသည် ပြောင်းဖူးစိုက်ခင်းထဲ၌ပေါက်ရောက်သော ပေါင်းပင် အမျိုးအစားနှင့် အနည်းအများပေါ်တွင်မူတည်သည်။ ထို့အတူ မိုးရာသီ၊ ဆောင်းရာသီ နှင့် မိုးကြိုရာသီဟူ၍ စိုက်ပျိုးရာသီအလိုက်လည်း ကွာခြားနိုင်သည်။ ပေါင်းထူထပ်စွာပေါက်ပါက ပေါင်းပင်ကြောင့် အထွက်နှုန်း လျော့နည်းသည့်အပြင် ပေါင်းပင်ကတစ်ဆင့် ရောဂါပိုးမွှားများ ကူးစက်ပြန့်ပွားကာ ပြောင်းဖူးအထွက်ကို ထိခိုက်နိုင်ကြောင်းသုတေသနပြုချက်များမှတွေ့ရှိရသည်။ <br><br>\r\n\r\n▶️ပြောင်းစိုက်ခင်းများတွင် ပေါင်းမြက်မျိုးစုံပေါက်ရောက်နိုင်သည်။ မြက်မုန်ညင်း၊ ဝက်ကျွတ်၊ ဆူးလေး၊ ကြက်မောက်ရိုင်း၊ ဟင်းနုနယ်ဆူးပေါက်၊ ဆင်ငိုမြက်၊ ဘဲစာမြက်၊ မြက်ယား၊ မြေစာ၊ ဆေးပုလဲ၊ မှိုချဉ်၊ ဆင်ပေါင်း၊ စိန်နားပန်၊ ယုန်မတိုး၊ ကရင်မပန်းဖူး၊ ထိကရုန်းကြီး၊ ဗောက်ပင်၊ ကပ်စေးနှဲ၊ နေကြာကလေး၊ ပန်းတော်(ဘတော်)၊ ဒူးကျိုး စသည့် ပေါင်းမြက်တို့ကို ပြောင်းစိုက်ခင်းများတွင် တွေ့မြင်နိုင်ပါသည်။ မြက်မုန်ညင်း၊ မြက်ယား၊ မြေစာ၊ ဝက်ကျွတ်နှင့် ဆူးလေး စသည့်ပေါင်းပင်တို့သည် မြေမျက်နှာပြင်ပေါ် ၌ ကပ်၍ တစ်ပြင်တစ်စပ်တည်း ပေါက်ရောက်ပြီး ပြောင်းဖူးပင်ငယ်တို့၏ အစာအာဟာရနှင့် ရေတို့ကို ရယူစားသုံးကြသည်။ သို့ဖြစ်သောကြောင့် အပင်ကြီးထွားမှုကို အဟန့်အတားဖြစ်စေနိုင်ပါသည်။ ကြက်မောက် နှင့် ဟင်းနုနယ်ရိုင်း နှင့် အခြားရွက်ပြန့်ပေါင်းအုပ်စုဝင်များသည် ပြောင်းဖူးပင်နှင့်အတူ အပင် အရပ်မြင့်တက်ကြီးထွားကြကာ ပြောင်းဖူးပင်ကြီးထွားလာသည်အထိ သီးနှံပင်နှင့်အပြိုင် အစာအာဟာရ နှင့် ရေတို့ကို ရယူစားသုံးကြပါသည်။<br><br> \r\n\r\n▶️ပြောင်းစိုက်ပျိုးသည့်အရပ်ဒေသများအလိုက်ပေါက်ရောက်သည့်ပေါင်းမြက်များမှာ ပြောင်းသီးနှံ အဓိကစိုက်ပျိုးသည့် ရှမ်းပြည်နယ် တောင်တန်းဒေသများတွင် မြက်ယား၊ မြေစာ၊ ဆင်ငိုမြက်၊ ယုန်မတိုး၊ မှိုချဉ်၊ ဆေးပုလဲ၊ ကြက်မောက်ရိုင်း၊ နွယ်ပင် တို့ဖြစ်သည်။ မန္တလေးတိုင်းနှင့် ကျန်ဒေသများတွင် မြက်ယား၊ ဝမ်းဘဲစာ၊ မြေစာ၊ ပန်းတော်(ဘတော်)၊ ဒူးကျိုး စသည့်မြက်အုပ်စုများနှင့် ဆေးပုလဲ၊ ဝက်ကျွတ်၊ နေကြာကလေး၊ ဗောက်သီးပင်၊ မှိုချဉ်၊ ဆင်ပေါင်း စသည့် ရွက်ပြန့်ပေါင်းအုပ်စုများပေါက်ရောက်ကြသည်။<br><br>\r\n\r\n▶️ပြောင်းစိုက်ခင်းများအတွင်း ပေါင်းနှိမ်နင်းခြင်းလုပ်ငန်းဆောင်ရွက်ရာတွင် လက်တွေ့ဆောင်ရွက်ချက်များအရ ဓာတုပေါင်းသတ်ဆေးအသုံးပြုခြင်းသည်ပြောင်းဖူးသီးနှံ ပေါင်းမြက်ကာကွယ်နှိမ်နင်းရေး အတွက်အထိရောက်ဆုံးဖြစ်သည်။ သို့သော် ပေါင်းမြက်ကာကွယ်နှိမ်နင်းရန် ဓာတုပေါင်းသတ်ဆေး ပက်ဖျန်းခြင်းနှင့်အတူ လယ်ယာလုပ်ကိုင်နည်းစနစ်များကိုလည်း အတိုင်းအတာတစ်ခုအထိ ဆောင်ရွက်သင့်သည်။ နည်းလမ်းပေါင်းစုံ ပေါင်းစပ်သုံးစွဲလျှင်တော့ အကောင်းဆုံးဖြစ်ပါသည်။<br><br>\r\n\r\n▶️လယ်ယာလုပ်ကိုင်မှု နည်းစနစ်၏ ဆောင်ရွက်ရမည့်နည်းလမ်းများမှာ .....<br><br> \r\n\r\n☑️ စိုက်ပျိုးသည့်ဒေသအခြေအနေနှင့် သင့်တော်ကိုက်ညီသော ပြောင်းဖူးမျိုးကို အသုံးပြုစိုက်ပျိုးရန်။<br><br>\r\n\r\n☑️ ထယ်ရေး၊ ထွန်ရေး ကိုကောင်းစွာပြုပြင်ခြင်းဖြင့် ပေါင်းမြက်ကင်းစင်သောစိုက်ခင်းဖြစ်အောင် ဆောင်ရွက်ရန်။ <br><br>\r\n\r\n☑️ စိုက်ပျိုးရာသီအလိုက် စိုက်ချိန်မှန်ကန်စွာ စိုက်ပျိုးရန်။ <br><br>\r\n\r\n☑️ ထောက်ခံထားသည့် အပင်အတန်းအကွာအဝေးဖြင့် စိုက်နည်းစနစ်မှန်မှန် စိုက်ပျိုးရန်။ <br><br>\r\n\r\n☑️ သတ်မှတ်အပင်ရေ ပြည့်မီအောင်စိုက်ပျိုးရန်။ <br><br>\r\n\r\n☑️ ထို့အပြင် အတန်းလိုက်စိုက်ပျိုးခြင်းသည် အတန်းကြားအတွင်း ကြားထွန်တိုက်ခြင်း၊ ပေါက်ပေါင်းပေါက်ခြင်း၊ လက်ပေါင်းလိုက်ခြင်းတို့ကို လွယ်ကူစွာ ဆောင်ရွက်နိုင်ပါသည်။<br><br>\r\n\r\n▶️ယခုအခါ ပြောင်းခင်းအတွင်းပက်ဖျန်းရန် ပြောင်းရွေးချယ်ပေါင်းသတ်ဆေးအမျိုးမျိုးကို အလွယ်တကူဝယ်ယူရရှိနိုင်သည်။ ပြောင်းဖူးသီးနှံစိုက်ပျိုးခြင်းမပြုမီ (Preplant) အသုံးပြုနိုင်သည့် ပေါင်းသတ်ဆေး၊ ပြောင်းဖူးသီးနှံ စိုက်ပျိုးပြီးသော်လည်း ပေါင်းမြက်အပင်မပေါက်မီ (Preemergence) အသုံးပြုနိုင်သည့် ပေါင်းသတ်ဆေး၊ ပြောင်းဖူးသီးနှံစိုက်ပျိုးပြီး အပင်ပေါက်ချိန်တွင် ပေါင်းမြက်အပင် ပေါက်ပြီးခါစ (Postemergence) အသုံးပြုနိုင်သည့် ပေါင်းသတ်ဆေးဟူ၍ ခွဲခြားထားရာ မိမိတို့ပြောင်းခင်း အနေအထားများအလိုက် အသုံးပြုလိုသည့် ဓာတုပေါင်းသတ်ဆေးကို ရွေးချယ်အသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\n▶️ပြောင်းဖူးသီးနှံစိုက်ပျိုးသူများသည် မိမိတို့ပြောင်းဖူးသီးနှံစိုက်ခင်းများတွင် ပေါက်ရောက်လေ့ရှိသော ပေါင်းမြက်အမျိုးအစားများကို အပင်ပေါက်ခြင်း၊ ကြီးထွားခြင်း၊ ပန်းပွင့်ခြင်း၊ မျိုးစေ့ပျံ့နှံ့ခြင်း စသည့် ပေါင်းမြက်ဆိုင်ရာ ဗဟုသုတရှိဖို့လိုသည်။ ဓာတုပေါင်းသတ်ဆေးဆိုင်ရာ သုံးစွဲသင့်သည့်ဆေး၊ သုံးစွဲသင့် သည့်အချိန်၊ သုံးစွဲနည်း စသည်တို့ကိုလည်း သိထားရပါမည်။ ထို့အပြင် နှစ်စဉ်ပေါင်းမြက်ပေါက်ရောက်မှု အဆက်ပြတ်ရေးအတွက် သီးလှည့်စိုက်ပျိုးခြင်း (Crop Rotation) နည်းစနစ်ကိုလည်း နားလည်ထားဖို့ လိုပါသည်။<br><br>\r\n\r\n▶️သို့သော် အထူးတင်ပြလိုသည်မှာ ပြောင်းခင်းများအတွင် ရှင်သန်ပေါက်ရောက်တတ်ကြသော ပေါင်းမြက်များအားလုံး၏ ကြီးထွားရှင်သန်မှုအလေ့အထများ (Growth Habit) အရ ပြောင်းသီးနှံ စိုက်ပျိုးပြီး (၁၅ - ၂၅)ရက်အတွင်း (သို့မဟုတ်) ပေါင်းပင်များအရွက် (၃ - ၅) ရွက် ထွက်ချိန်တွင် ပေါင်းသတ်ဆေးပက်ဖျန်းနှိမ်နင်းခြင်းသည် အထိရောက်ဆုံး ပေါင်းနှိမ်နင်းချိန်ဖြစ်ကြောင်း သုတေသနပြုချက်များမှ တွေ့ရှိရပါသည်။<br><br>\r\n\r\n▶️ထို့ကြောင့် အထက်ပါအကြောင်းအချင်းရာများကိုသိရှိပြီး ပြောင်းခင်းများအတွင်း ထိရောက်သော ပေါင်းနှိမ်နင်းမှုဖြစ်စေရန် မှန်ကန်သော ပြောင်းသီးနှံသုံးပေါင်းသတ်ဆေးများကို ရွေးချယ်အသုံးပြု၍ အချိန်မှန်ပက်ဖျန်းပေးနိုင်ရေးအတွက် ဂရုပြုဆောင်ရွက်ပေးသင့်ပါသည်။ ထိုသို့ ဆေးမှန်၊ အချိန်မှန်၊ နည်းစနစ်မှန် သုံးစွဲခြင်းဖြင့် ပြောင်းခင်းများအတွင်း ပေါင်းမြက်များကင်စင်၍ ပြောင်းပင်များ လွတ်လပ်စွာ ရှင်သန်ကြီးထွားနိုင်ခြင်း၊ ပိုးမွှား ရောဂါ ကင်းစင်ခြင်းတို့နှင့်အတူ အရည်အသွေးကောင်း၊ အထွက်မြင့်မားသည့် ပြောင်းဖူးခင်းများကို ဦးကြီးတို့ရရှိနိုင်ကြမည် မလွဲပင်ဖြစ်ပါတော့သည်။<br><br>\r\n\r\n', '#ffffc2', '18-02-2024');
INSERT INTO `knowledge` (`kid`, `knowledgeTitle`, `knowledgePhoto`, `knowledgeDescript`, `knowledgeColor`, `CurrentDate`) VALUES
(24, '“ငရုတ် နှင့် သရစ်လှေးပိုး”', 'IMG-65d23dc41bb0e3.41582447.jpg', '🌶🫑🌶🫑🌶🫑🌶🫑🌶🫑🌶<br><br>\r\n\r\n❇️“သရစ်လှေးပိုး” သည် ငရုတ်ခင်းထဲတွင် ဆိုးဆိုးရွားရွားကျရောက် ဖျက်ဆီးတတ်ပြီး ၎င်းလှေးပိုး ကျရောက်ဖျက်စီးပါက အထွက်နှုန်းကိုသိသာစွာ ထိခိုက်ကျဆင်းစေနိုင်ပါသည်။ ထို့ကြောင့် ငရုတ်ခင်းအတွင်း လှေးပိုးကျရောက်ဖျက်ဆီးမှုလက္ခဏာများ နှင့် ကာကွယ်နှိမ်နင်းနိုင်ရန် နည်းလမ်းများကို တင်ပြပေးလိုက်ပါသည်။<br><br>\r\n\r\n  လှေးပိုး၏ ဖျက်ဆီးပုံလက္ခဏာ  <br>  \r\n--------------------------<br><br>\r\n\r\n▪️လှေးပိုးဖျက်ဆီးခံရသောအရွက်များသည် တွန့်လိမ်သွားပြီး အပေါ်သို့ကွေးသွားသည်။<br><br>\r\n\r\n▪️ပင်စည်ရိုးတံရှည်လာသည်။<br><br>\r\n\r\n▪️အဖူးများကြွတ်ဆတ်ပြီး ကြွေကျသွားတတ်သည်။<br><br>\r\n\r\n▪️ငရုတ်အပင်အစောပိုင်းအဆင့်တွင် ဖျက်ဆီးခံရခြင်းသည် အပင်ကိုပုစေကာ ပန်းပွင့်ခြင်းနှင့် အသီးတင်ခြင်းကို ထိခိုက်စေသည်။<br><br>\r\n\r\n▪️အပင်ငယ်စဉ်မှ ခူးဆွတ်ရိတ်သိမ်းချိန်အထိ သစ်ရည်ကိုစုပ်ယူဖျက်ဆီးသဖြင့် အရွက်များအပေါ်သို့ တွန့်ကုပ်၍ ရွက်သေးထိုးခြင်းလက္ခဏာမှာ အဓိကဖြစ်ပေါ်သည်။<br><br>\r\n\r\n▪️လှေးပိုးသည် အရွက်များကိုဖျက်ဆီးသဖြင့် အရွက်များငွေရောင်ဖြစ်နေပြီး အကွက်အပျောက်များ ဖြစ်နေမည်။ များပြားစွာကျပါက အပင်နုဖြစ်လျှင် ညှိုးခြောက်ကုန်သည်။ ရံဖန်ရံခါ တစ်ပင်လုံး သေနိုင်သည်။  <br><br> ‎\r\n\r\nလှေပိုး    ၏ဝိသေသလက္ခဏာ<br>\r\n-----------------------<br><br>\r\n\r\n▪️အကောင်ငယ်သည်သေးငယ်ပြီး ဖြောင့်တန်းကာ အလွယ်တကူ ကျိုးပဲ့လွယ်သော၀မ်းဗိုက်ပိုင်းပါရှိ၍ ကောက်ရိုးဝါရောင်ရှိသည်။<br><br>\r\n\r\n▪️အရွယ်ရောက်ကောင်တွင် အမြိတ်အနားပါသော တောင်ပံများရှိသည်။<br><br>\r\n\r\nကာကွယ်နှိမ်နင်းနည်း<br>\r\n-------------------<br><br>\r\n\r\n(၁) ပေါင်းမြက်များ ရှင်းလင်းပြီး ဟင်းသီးဟင်းရွက်ခင်းများတွင်ခြောက်သွေ့ချိန်၌ မီးရှို့၍ မီးခိုးမှိုင်းတိုက်ထားပါ။<br><br>\r\n\r\n(၂) နှံစားပြောင်းစိုက်ပြီးနောက် ငရုတ်မစိုက်ရန်၊ ငရုတ်နှင့်ကြက်သွန်ကို သီးနှောမစိုက်ပျိုးရန် အထူးဂရုပြုရပါမည်။<br><br>\r\n\r\n(၃) သရစ်လှေးပိုးသည် စိုက်ခင်းရေငတ်၊ ခြောက်သွေ့ပါက ပိုမိုဆိုးရွားစွာကျရောက်တတ်သဖြင့် ရေသွင်း/ရေထုတ်ကို ဂရုပြုပေးရပါမည်။<br><br>\r\n\r\n(၄) ငရုတ်ပန်းပွင့်ချိန်တွင် ရေငတ်/အစာငတ်ခြင်း၊ အပင်ခြေရေဝပ်/မြေအစိုဓာတ်များခြင်း တို့မဖြစ်အောင်လဲ ဂရုစိုက်ဆောင်ရွက်ပါ။<br><br>\r\n\r\n(၅) ငရုတ်ပင်တွင် သရစ်လှေးပိုးကျရောက်လျှင် စိုက်ခင်းရေမပြတ်အောင် ဂရုစိုက်ပါ။ ရေသွင်းချိန်မှာဖြစ်စေ မြေအစိုဓာတ်ကောင်းချိန်မှာဖြစ်စေ အပင်ခြေရင်းကို ဒီပါ (သို့) ဖစ်ပရို ရရာဆေးခဲတစ်မျိုးမျိုးကို ကြဲပက်ပေးပါ (သို့မဟုတ်) ပရိုဆင့် ပိုးသတ်ဆေးဖျန်းပေးပါ။<br><br>\r\n\r\n', '#57feff', '18-02-2024'),
(25, '“သခွားသီး စိုက်ပျိုးနည်း”', 'IMG-65d23e0fee8dd9.08905572.jpg', '🥒🥒🥒🥒🥒🥒🥒🥒🥒🥒<br><br>\r\n\r\nမြန်မာအမည် - သခွား<br>\r\n\r\nအင်္ဂလိပ်အမည် - CUCUMBER<br>\r\n\r\nရုက္ခဗေဒအမည် - Cucumis sativus<br>\r\n\r\nမျိုးရင်းအမည် - CUCURBITACEAE<br>\r\n\r\n၁။ မူရင်းဒေသ<br><br>\r\n\r\n အာရှတိုက်တောင်ပိုင်းတွင် စတင်ပေါက်ရောက်သည်ဟုယူဆပါသည်။<br><br>\r\n\r\n၂။ အမျိုးအစား<br><br>\r\n\r\n သခွားတွင် အစိမ်းစားနှင့် အမှည့်စားဟူ၍ နှစ်မျိုးရှိပြီး အစိမ်းစားမျိုးတွင် (က) ဆင်ချေးတုံး (ခ) သခွားကြား (ဂ) ဆတ်တွန့်သခွား (ဃ) သခွားချဉ် (င) ချဉ်ဖတ်သခွား တို့ဖြစ်သည်။<br><br>\r\n\r\n သခွားအုပ်စုကို (၃) စုခွဲထားသည်။<br><br>\r\n\r\n(၁) မိုးသခွား - အပူဒါဏ်ခံနိုင်သည်။ ကိုင်းထွက်ရန်လွယ်ကူသည်။ အသီးများသည် ကိုင်းများတွင်သီး သည်၊ ကိုင်းသေးသည်၊ အဆစ်ကြာရှည်သည် ၊ အရွက်ရှည်သည် ၊ အရွက်၏အလျားသည် အနံထက် ပိုရှည်သည်။ အမြစ်ဖွဲ့စည်းပုံသေးသောကြောင့် ရွှေ့ပြောင်းရန်ခက်ခဲသည်။ အသီးသေးသွယ်သည် အရွက်ချောသည်။<br><br>\r\n\r\n(၂) ဆောင်သခွား - အအေးဒါဏ်ခံနိုင်သည်။ ကိုင်းထွက်မှုနည်းသည်။ အသီးများသည် ပင်မပိုင်းမှထွက်သည် ။ ပင်မကိုင်းသည်တုတ်နိုင်သည် ။ ဆစ်ကြားတိုသည် ။ အရွက်များ သည်အနံထက်အလျားပိုရှည်သည်။ ပြောင်းရွှေ့လွယ်ကူသည်။ အသီးများသည် တိုတုတ်သည်။ အရွက်ကြမ်းသည်။<br><br>\r\n\r\n(၃) စပ်မျိုးများ - အမမျိုးလိုင်းကြားတွင် အဖိုမျိုးလိုင်း (၂) တန်း (၃) တန်း ခြား၍ စိုက်ပျိုးနိုင်၍ စပ်မျိုးများထုတ်လုပ်ခြင်းဖြစ်သည်။<br><br>\r\n\r\nအမှည့်စားမျိုးတွင် (က) ကျောက်သခွားလေး (ခ) ကျောက်သခွားကြီး တို့ဖြစ်သည်။<br><br>\r\n\r\n၃။ စိုက်ပျိုးသည့်ဒေသ<br><br>\r\n\r\n မလေးရှား ၊ အင်ဒိုနီးရှား ၊ အရှေ့နှင့်အနောက်အာဖရိက၊ ဖိလစ်ပိုင်းနှင့်အပူပိုင်းသမဒေသများ နှင့် မြန်မာပြည်တွင် နေရာအနှံအပြားစိုက်ပျိုးကြသည်။<br><br>\r\n\r\n၄။ ရေမြေရာသီဥတု<br><br>\r\n\r\n သခွားသည် သဲဆန်သောသဲမြေမှ စနယ်မြေစေးအထိ မြေအမျိုးမျိုးတွင် စိုက်ပျိုးဖြစ်ထွန်းသော်လည်း၊ နုံးမြေ ၊ သဲနုံးမြေ နှင့်နုံးစနယ်မြေများတွင် ပိုမိုဖြစ်ထွန်းပါသည်။ သခွားစိုက်သောမြေနေရာတွင် ရေမဝပ်စေဘဲ ရေစီးရေလာကောင်းသောနေရာများတွင် ပိုမိုဖြစ်ထွန်းပါသည်။ သခွားမျိုးများသည် မြေချဉ်ငံဓါတ် pH (၅.၅) မှ (၆.၅)အတွင်းပိုမိုဖြစ်ထွန်းပါသည်။ သခွားသည်ပူနွေးသောရာသီတွင် ပိုမိုဖြစ်ထွန်းပြီး ဆီးနှင်းဒါဏ်ကို ခံနိုင်ရည်မရှိပေ။ သခွားပင်များသည် (၁၁)°Cတွင် အပင်မပေါက်နိုင်ပေ။ သခွားပင်များသည် အပူချိန် (၁၈)°C မှ (၂၄)°C အတွင်းမှာသာ ပိုမိုဖြစ်ထွန်းပါသည်။ မိုးများပြီးစိုထိုင်းဆများသောနေရာများတွင် စိုက်ပျိုးပါကအပင်များရောဂါကျ လွယ်ပါသည်။ ထို့ကြောင့်နေရောင်ခြည် ကောင်းစွာရရှိပြီး စိုထိုင်းဆနည်းသောအရပ်များတွင် သခွားစိုက်ပျိုးရန်သင့်တော်ပါသည်။<br><br>\r\n\r\n၅။ မြေပြုပြင်ခြင်း<br><br>\r\n\r\n ထယ်တစ်စပ်ထိုးပေးပြီးနောက်ထွန်ဖြင့် (၆) စပ်မှ (၈) စပ်အထိ ထွန်မွှေပေးရန်လိုအပ်ပါသည်။ မိုးရွာလျှင် ရေမဝပ်စေရန် ရေနှုတ်မြောင်းများလည်း ဖောက်လုပ်ပေးရပါမည်။ ထယ်ရေးကြေညက်ပြီးနောက် စိုက်ဘောင်များ (သို့မဟုတ်) စိုက်ကျင်းများပြုလုပ်စိုက်ပျိုးနိုင်ပါသည်။<br><br>\r\n\r\n၆။ မြေဩဇာကျွေးနည်း<br><br>\r\n\r\n နွားချေးမြေဩဇာကို တစ်ဧကလျှင် လှည်း (၁၀)စီး မှ (၁၅)စီးအထိထည့်ပေးပါ။ နွားချေး မြေဩဇာကို စိုက်ဘောင်ပြုလုပ်ရာတွင် မြေကြီးနှင့်ရောစပ်သမအောင်မွှေပေးပါ။ သခွားစိုက်ပျိုးရန်အတွက် ယူရီးယားဓါတ်မြေဩဇာ (၁၁၂)ပေါင် မှ (၂၂၄)ပေါင် ၊တီစူပါ (၁၁၂)ပေါင်မှ (၂၂၄)ပေါင်ထိ ထည့်ပေးပါ။<br><br>\r\n\r\n၇။ စိုက်ပျိုးနည်း<br><br>\r\n\r\n သခွားစိုက်ပျိုးရန် အလျားပေ (၃၀) x အနံ (၃) ပေရှိ စိုက်ဘောင်များပြုလုပ်ပေးရမည်။ ဘောင်ပေါ်တွင် တစ်တန်းနှင့်တစ်တန်း (၁.၅)ပေနှင့် တစ်ပင် (၁.၅)ပေခွာပြီး သခွားစေ့များကို စိုက်ပျိုးရမည်။ စိုက်ကျင်း တစ်ကျင်းလျှင် သခွားစေ့ (၃-၄) စေ့ ထည့်ပေးပြီး အပင်များပေါက်လာ၍ အရွက် (၂ - ၃) ရွက် ထွက်လာပါက တစ်ကျင်းလျှင်တစ်ပင်သာချန်ပြီး မှုန်းပေးပါ။ အပင်ကလေးများတက်နိုင်ရန် (၅ - ၆) ပေ ရှိသောဝါးခြမ်းများထောင်ပေးရမည်။ သခွားကို မိုးဦးမေလ နှင့် ဇွန်လ၊ ဆောင်းတွင်း အောက်တိုဘာလ တွင် စိုက်ပျိုးနိုင်သည်။<br><br>\r\n\r\n၈။ တစ်ဧကမျိုးစေ့နှုန်း<br><br>\r\n\r\n တစ်ဧကလျှင် သခွားမျိုးစေ့ (၂၀၀)ဂရမ် မှ (၃၀၀) ဂရမ်အထိ ထည့်သွင်းစိုက်ပျိုးရန်ဖြစ်ပါသည်။ တစ်ဧကလျှင် အပင်ရေ (၁၉,၀၀၀) ထက်မနည်း ရှိရပါမည်။<br><br>\r\n\r\n၉။ ရေသွင်းနည်း<br><br>\r\n\r\n သခွားကိုမိုးတွင်းတွင် စိုက်ပါကရေသွင်းပေးရန်မလိုသော်လည်း ၊ ဆောင်းစိုက်များအတွက် စိုက်ချိန်တွင်တစ်ကြိမ် နှင့် အစိုဓါတ်အခြေအနေအရ ထပ်မံ၍ လိုအပ်ပါက ၊ ရေ (၂) ကြိမ်မှ (၄)ကြိမ် အထိပေးရန်လိုပါသည်။<br><br>\r\n\r\n၁၀။ အပင်ပြုစုနည်း<br><br>\r\n\r\n သခွားစိုက်ပြိး (၁၅) ရက်မှ (၂၀)ရက်အတွင်း ပေါင်းတစ်ကြိမ်လိုက်ပေးရပါမည်။ သခွားသက်တမ်း တစ်လျှောက်တွင် ပေါင်းအခြေအနေအရ (၂)ကြိမ်ခန့် ပေါင်းလိုက်ပေးရပါမည်။ အပင်ကလေးများ ခါးကြပ်နေပါက အပင်ခြေရင်းကို မြေဆွပေးပြီးနောက် ၊ မြေတောင်မြှောက်ပေးရပါမည်။<br><br>\r\n\r\n၁၁ ။ ပိုးမွှား၊ ရောဂါ ကာကွယ်နှိမ်နင်းခြင်း<br><br>\r\nဖျက်ပိုးများမှာ ရွက်ထွင်းပိုး၊ ဘူးဖရုံကျိုင်း၊ ပိုးနဂါး၊ ငမြှောင်တောင်၊ ထွာကောင်စိမ်းတို့ကျရောက်တတ်ပြီး ဝိစာရ၏ “အက်စ်ဖိတ်၊ ရော့ကက်၊ လန်ဒါ ၅၊ အီမာလန်ဒါ၊ နိုက်ဝမ်း၊ ဘီတာ စီ” ဆေးများမှ ကျရောက်သည့်ပိုးအလိုက် ဆေးညွှန်းပါအတိုင်း ရွေးချယ်သုံးစွဲပေးရပါမည်။ ပျ၊ ယင်ဖြူ နှင့် သရစ်လှေးပိုးတို့သည် ကျရောက်လာပါက ဗိုင်းရပ်စ်ရောဂါများကိုသယ်ဆောင်လာသည့်အတွက် “ကေလာ၊ ဆိုင်လာ၊ ပရိုဆင့်” ဆေးများဖြင့် ကြိုတင်ပက်ဖျန်းကာကွယ်ပေးရပါမည်။<br><br>\r\n\r\n ရောဂါကျရောက်မှုအနေဖြင့် ခါးရိရောဂါအတွက် “ဘာလီဆိုဒ်” ပင်ရင်းပုတ်ရောဂါအတွက် “ကာဗာ၊ ထီး” မှိုဆေးများကို ကြိုတင်ပက်ဖျန်းကာကွယ်ပေးနိုင်ပါသည်။ ပင်စည်အစေးထွက်ရောဂါ ကျရောက်ပါက “ဒိုင်ဇီ” ၊ ဒေါင်းနီးရွက်ခြောက်ရောဂါအတွက် “တိုက်တန်၊ ဆိုင်မောက်၊ စူပါမော့” ဆေးများမှ တစ်မျိုးမျိုး ကို ဆေးညွှန်းပါအတိုင်း အသုံးပြုပေးရပါမည်။ သခွားမှဲ့ပြောက်စွန်းရောဂါ ကျရောက်ပါက “ဟက်ဇာဂွန်၊ ဒိုင်ဇီ” ဆေးများဖြင့် ကာကွယ်နှိမ်နင်းပေးနိုင်ပါသည်။<br><br>\r\n\r\n၁၂။ အသီးဆွတ်ခူးနည်<br><br>\r\n\r\nသက်လတ် ၊ သက်ကြီး ၊ သက်လျင်မျိုးများတွင်(၄၅) ရက်မှစ၍ သခွားသီးများစတင်ခူးဆွတ်နိုင်ပါသည်။ ရင့်မှည့်သောသခွားသီးများကို ဆွတ်ခူးရန်အရေးကြီးပါသည်။ နုသောသခွားသီးများကို ဆွတ်ခူးပါက အစိုဓါတ်များ၏။ သခွားသီးမှည့်ပါက အသီးအောက်ခြေရှိအညှာအက်ကွဲလာပါသည်။ ၁၃။ အထွက်နှုန်း သခွားအထွက်နှုန်းသည် ရေမြေရာသီဥတု၊ အပင်ပြုစုမှုပေါ်မူတည်နေပါသည်။ သခွားတစ်ဧကလျှင် ကီလိုဂရမ် (၄၀,၀၀၀) မှ (၅၀,၀၀၀) အထိထွက်နိုင်ပါသည်။ <br><br>\r\n\r\n၁၃။ မျိုးထုတ်လုပ်နည်း <br><br>\r\n\r\n ရင့်မှည့်၍ရောဂါကင်းသောသခွားသီးကိုရွေးချယ်ပြီးလျှင် သခွားသီးကိုဓါးဖြင့်ခွဲ၍ အတွင်းမှအစေ့များကို ထုတ်ယူပြီး လေလုံသောဘူးတွင်ထည့်၍ တစ်ညထားရမည်ဖြစ်ပါသည်။ ဤကဲ့သို့ထားခြင်းဖြင့် အစေ့တွင်ကပ်နေသော အချွဲများအချဉ်ဓါတ်ပေါက်ပြီး ပျက်စီးသွားမည်ဖြစ်ပါသည်။ ၎င်းအစေ့များကို ရေဆေးပြီး နေ(၂) နေလှမ်း၍ လုံခြုံသောဘူးတွင် ထည့်ထားရန်လိုအပ်ပါသည်။ <br><br>\r\n\r\n၁၄။ သိုလှောင်နည်း <br><br>\r\n\r\n သခွားများကို (ဝ)°C မှ (၁)°C အခန်းတွင်စိုထိုင်းဆ (၉၀)% ပေးထားလျှင် တစ်ပတ်ခန့် သိုလှောင်နိုင် မည်ဖြစ်ပါသည်။ <br><br>\r\n\r\n၁၅။ သတိပြုရန်အချက်များ <br><br>\r\n\r\n (၁)သခွားပင်များတွင် ကျရောက်တတ်သောကျိုင်းကောင်များကို ထိရောက်စွာနှိမ်နှင်းရန်လိုပါသည်။<br><br>\r\n\r\n (၂)သခွားပင်များအား အင်ဒရင်းဆေးများမပက်ဖျန်းသင့်ပေ။ ပက်ဖျန်းပါက အရွက်များလောင်ကျွမ်း ပျက်စီးမည်ဖြစ်သည်။ <br><br>\r\n\r\n (၃) သခွားသီးများ ရင့်မှည့်မှခူးရန်လိုပါသည်။ နုစဉ်ခူးပါက အခါးဓါတ်များ၏။ <br><br>\r\n\r\nSources : ဟင်းသီးဟင်းရွက်စိုက်ပျိုးနည်း', '', '18-02-2024'),
(26, 'ပဲမျိုးစုံ နှင့် “ပျပိုး” အန္တရာယ် ကြိုတင်ကာကွယ်', 'IMG-65d23fa514cf49.54023688.png', '🌿🦗🌿🦗🌿🦗🌿🦗🌿🦗🌿<br><br>\r\n\r\n✅ယခုအချိန်ကာလသည်ပဲမျိုးစုံ စိုက်ပျိုးချိန်ဖြစ်သည်။ အထူးသဖြင့် ပဲတီစိမ်း နှင့် မတ်ပဲကို အဓိက စိုက်ပျိုးနေကြပြီး တချို့ စိုက်နေဆဲ၊ တချို့မှာ အပင်ပေါက်ခါစ၊ တချို့မှာ စိုက်ချိန်စော၍ အဖူးအပွင့် ဝင်နေကြပြီဖြစ်သည်။<br><br> \r\n\r\n✅ထိုသို့ပဲခင်းတွေစိမ်းလာသည်နှင့်အတူ ပဲပင်ကိုဖျက်သည့် ပိုးမွှားများလည်းပေါ်ပေါက်လာစမြဲပင် ဖြစ်သည်။ ၎င်းဖျက်ပိုးများအနက် ပဲအပင်ပေါက်သည်နှင့် ပဲပင်နှင့်အတူ ဖွားဘက်တော်သဖွယ် ပေါ်လာပြီး ဖျက်ဆီးသည့်ပိုးမှာ “ပျပိုး”ပင်ဖြစ်သည်။ “ပျပိုး” သည် ကန်သင်းပေါ်ရှိ ခြုံနွယ်ပိတ်ပေါင်း များတွင်ခိုအောင်းနေပြီး ပဲပင်ပေါက်လာသည်နှင့် ပဲပင်ပေါ်ရောက်လာတော့သည်။ “ပျပိုး” သည် ပဲမျိုးစုံတွင် ကျရောက်တတ်ပြီး တခြား မြက်၊ ခြုံပင်များတွင် ခိုအောင်းနေတတ်ပါသည်။ ရာသီဥတု ပူပြင်းလျှင် အကောင်ပေါက်ဖွားမှု ပိုမို၍ မြန်မြန်များများ ပွားနိုင်ပါသည်။ <br><br>\r\n\r\n✅ပဲအပင်ငယ် (၅ - ၇)ရက်သားရလျှင် အရွက်အောက်မျက်နှာပြင်မှာ စတင်ကျတာတွေ့ရပါသည်။ “ပျပိုး” အကောင်ငယ်များသည် ပဲရွက်၏အောက်မျက်နှာပြင် ရွက်ကြောကြားတွင် အစုလိုက်အပြုံလိုက် တွယ်ကပ်နေပြီး ပဲရွက်ရှိသစ်ရည်ကိုစုပ်စားပါသည်။ ထိုသို့စုပ်စားသည့်အတွက် ပဲရွက်တွေဟာ ရွက်နားကစပြီး တဖြည်းဖြည်းအောက်ကိုကုပ်ဝင်သွားပါသည်။ ထို့နောက်တစ်ရွက်လုံး ခြောက်သေသွား တတ်သည်။ ပဲပင်ငယ်လွန်းလျှင် ခံနိုင်ရည်မရှိသောကြောင့် နလံမထူနိုင်တော့ဘဲ အပင်သေသွားပါသည်။ တစ်ခါတစ်ရံ “ပျပိုး” သည် ရောဂါပိုးကိုသယ်ဆောင်လာတတ်သည့်အတွက် နောက်ဆက်တွဲရောဂါများ ဖြစ်စေသည့် အကျိုးဆက်လည်းဖြစ်သည်။<br><br> \r\n\r\n✅ပျကောင်အကြီးများ တချို့အတောင်ရှိကြသည်။ ထို့ကြောင့် တစ်ပင်မှတစ်ပင် တစ်ကွက်မှတစ်ကွက်သို့ ကူးစက်ပြန့်ပွားသွားစေပါသည်။ အတောင်မပါသည့်ပျပိုးများသည် အနီးပတ်ဝန်းကျင်ရှိ အထီးများနှင့် မိတ်လိုက်ပြီးမျိုးဆက်ပြန့်ပွားစေပါသည်။ တချို့ပျပိုးများမှာ အထီးနှင့်မိတ်လိုက်ခြင်းမရှိဘဲ လိင်မဲ့နည်းနှင့် တစ်နှစ်လုံးမျိုးဆက်ပွားနိုင်ပါသည်။ ထို့ကြောင့် \"ပျပိုး\" ကျရောက်လျှင် ဂရုမစိုက်မိပါက နိုင်အောင်နှိမ်နင်းဖို့ခက်ခဲပါသည်။ <br><br>\r\n\r\n✅ပျမတစ်ကောင်သည် မိတ်လိုက်မျိုးပွားလျှင် ဥပေါင်း(၃၀)ခန့် အုနိုင်သည်။ နှစ်ရက်မှသုံးရက်ကြာလျှင် ဥမှအကောင်ငယ်လေးတွေပေါက်သည်။ အကောင်ငယ်မှအကောင်ကြီးအထိ နှစ်ပတ်မှသုံးပတ်ကြာ နေနိုင်ပါသည်။ ပျပိုးသည်သက်တမ်းတိုပေမယ့် လိင်မဲ့နည်းနှင့် တစ်နှစ်ပတ်လုံးမျိုးဆက်ပြန့်ပွားနိုင်သည်။ လက်ခံပင် (သီးနှံပင်) မရှိချိန်တွင် တခြားမြက်၊ခြုံတွေမှာ ခိုအောင်းနေနိုင်သည်။ ထို့အပြင် ပြန့်ပွားမှု မြန်ဆန်သည့်အတွက် ဂရုပြုကာကွယ်နှိမ်နင်းရမည့် ပိုးတစ်မျိုးဖြစ်သည်။<br><br>\r\n\r\n✅ပျပိုးကို ကာကွယ်နှိမ်နင်းနိုင်ရန် .....<br><br>\r\n\r\n ▪️ စိုက်ခင်းပတ်ဝန်းကျင် နှင့် ကန်သင်းပေါ်ရှိ ခြုံနွယ် မြက်ပင်တွေကို ပြောင်စင်အောင် သုတ်သင်ရှင်းလင်း မီးရှို့ပစ်ပါ။<br><br>\r\n\r\n ▪️ ပတ်ဝန်းကျင်တွင် ပဲမျိုးရင်းဝင် အပင်အကြွင်းအကျန်များရှိပါက သုတ်သင်ရှင်းလင်းပါ။<br><br>\r\n\r\n ▪️ ပဲစိုက်ချိန်စောလွန်းပါက “ပျပိုး” ပိုမိုကျရောက်တတ်သည့်အတွက် စိုက်ချိန်မစော (စိုက်ပျိုးချိန်မှန်) စေရန်သတိပြုပါ။<br><br>\r\n\r\n ▪️ “ပျပိုး”ဒဏ်ခံနိုင်ရည်ရှိသော မျိုးများကိုရွေးချယ် စိုက်ပျိုးပါ။<br><br>\r\n\r\n ▪️ “ပျပိုး” ကျရောက်မှုကို ကြိုတင်ကာကွယ်နိုင်ရန် ဝိစာရ၏ “ကေလာ၊ ဆိုင်လာ၊ နိုးဝမ်း၊ အက်စ်ဖိတ်၊ သူရိယ” စသည့် ပင်လုံးပြန့်အာနိသင်ရှိ ပိုးသတ်ဆေးတစ်မျိုးမျိုးကို အပင်ငယ် (၇ - ၁၀)ရက်သားခန့်မှ စ၍ တစ်ပတ်တစ်ကြိမ်နှုန်းဖြင့် နှစ်ကြိမ် မှ သုံးကြိမ်ခန့် ပက်ဖျန်းပေးပါရန် ရေးသားတင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n✅စစ်မှန် ပြည့်ဝ ဝိစာရ✅<br><br>\r\n\r\nSources : စိုက်ပျိုးရေးရာအကြံပြုချက်များ', '', '18-02-2024'),
(27, '“ပဲရွက်ပြောက်ရောဂါ” ကြိုတင် ဂရုပြုကာကွယ်ပါ', 'IMG-65d2e3cdcc60a5.77265310.png', '🍃🍂🍃🍂🍃🍂🍃🍂🍃🍂🍃<br><br>\r\n\r\nမြန်မာအမည် - ပဲရွက်ပြောက်ရောဂါ<br><br>\r\n\r\nအင်္ဂလိပ်အမည် - Cercospora Leaf Spot<br><br>\r\n\r\nရောဂါဖြစ်စေသက်ရှိ - Cercospora canescens<br><br>\r\n\r\nရောဂါလက္ခဏာ<br>\r\n--------------<br><br>\r\n\r\nရောဂါကျအရွက်ရင့်ပေါ်တွင် အရွယ်အစားအမျိုးမျိုးရှိသည့် အညိုရောင်၊ သံချေးရောင်ကွက်ပြောက်များ ဖြစ်ပေါ်ပြီး ရောဂါကွက်များသည်အလယ်တွင်မီးခိုးရောင်ရှိပြီး နီညိုရောင် အနားရစ်ပါရှိသည်။ ရောဂါပြင်းထန်ပါကအစိမ်းရောင်တစ်ရှူးသားများခြောက်သွားပြီး အရွက်များအစိမ်းရောင် မရှိတော့ပါ။ အထူးသဖြင့်ပဲတီစိမ်းတွင် ပိုမိုဆိုးရွားစွာကျရောက်တတ်သည်။ ပန်းပွင့်ချိန်နှင့် အသီးကင်းဝင်ချိန်တွင် ရွက်ပြောက်ရောဂါပြင်းထန်စွာကျရောက်ပါက အပွင့်နှင့် သီးကင်းကြွေခြင်းများ ဖြစ်ပေါ်တတ်ပါသည်။<br><br>\r\n\r\nရောဂါကူးစက် ပြန့်နှံ့ပုံ<br>\r\n-------------------<br><br>\r\n\r\nCercospora ဟာ အပင်အကြွင်းအကျန်တွေပေါ်မှာ အသက်ရှင်နေထိုင်နိုင်ပြီး ရောဂါပျံ့ပွားဖို့ အဓိက ကတော့ မိုးရေ (Rain Splashes) ကြောင့်ပဲဖြစ်ပါတယ်။ ပဲမျိုးအများစုဟာ ဒီရောဂါကိုခံနိုင်ရည်မရှိတဲ့ အတွက်ကြောင့် ရောဂါကူးစက်ပျံ့ပွားဖို့ အရမ်းလွယ်ကူပါတယ်။ ပဲရွက်ပြောက်ရောဂါကျရောက်ရန် အကောင်းဆုံးပတ်ဝန်းကျင်အခြေအနေမှာ စိုထိုင်းဆ(၉၀-၁၀၀) ရာခိုင်နှုန်း နှင့် အပူချိန် (၂၀-၂၆) ဒီဂရီ စင်တီဂရိတ် ပူနွေးစွတ်စိုတဲ့ အခြေအနေဖြစ်ပါတယ်။ ဒီရောဂါကျရောက်ဖို့ အကြိုက်ဆုံးအပူချိန်က (၂၅ - ၃၀) ဒီဂရီစင်တီဂရိတ်ဖြစ်ပါတယ်။ အပူချိန်(၁၀)ဒီဂရီစင်တီဂရိတ်အောက်ကျရောက်သွားပါက ရောဂါဖြစ်စေသက်ရှိဟာ ဆက်လက်ပြီးမျိုးပွားနိုင်ခြင်းမရှိတော့ပါ။ ပဲရွက်ပြောက်ရောဂါကို ကောင်းမွန်စွာကာကွယ်နိုင်ခြင်းမရှိပါက အထွက်နှုန်း(၆၀)ရာခိုင်နှုန်းအထိ ဆုံးရှုံးနိုင်ပါသည်။<br><br>\r\n\r\nသို့ဖြစ်ပါ၍ ပဲရွက်ပြောက်ရောဂါကို ထိရောက်စွာ ကာကွယ်ကုသမှုပေးနိုင်သော ဝိစာရ၏ “ဘင်ဇိုကာ၊ ဟက်ဇာဂွန်၊ ဒိုင်ဇီ၊ ဇိုလာ၊ ကာဗာ” ဆေးများမှတစ်မျိုးမျိုး ကို ကြိုတင်ကာကွယ်ပက်ဖျန်းပေးနိုင်ပါရန် တင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n', '', '19-02-2024'),
(28, '\"မရမ်းပင် စိုက်ပျိုးနည်း\"', 'IMG-65d2e443994056.15008513.jpg', '🌳🌳🌳🌳🌳🌳🌳🌳🌳🌳<br><br>\r\n\r\nမြန်မာအမည် – မရမ်း<br><br>\r\n\r\nအင်္ဂလိပ်အမည် – MARIAN TREE<br><br>\r\n\r\nရုက္ခဗေဒအမည် – Bouea burmanica<br><br>\r\n\r\nမျိုးရင်းအမည် – ANACARDIACEAE<br><br>\r\n\r\nနိဒါန်း<br>\r\n----<br><br>\r\n\r\nမရမ်းပင်ဟာ သားစဉ်မြေးဆက် စိုက်ပျိုးထုတ်လုပ် စီးပွားဖြစ်ထွန်းစေတဲ့အပင်မျိုးတစ်ခုဖြစ်ပါတယ်။ အချို၊ အချဉ် အရသာနှစ်မျိုးရှိပြီး မရမ်းသီးအစိမ်းအတိုင်းကို မရမ်းသီးထောင်း၊ မရမ်းသီးကြော်အဖြစ် စားသောက်ကြသလို အခြောက်လှမ်းပြီး မရမ်းပြား၊ မရမ်းပေါင်း၊ မရမ်းယိုတွေအဖြစ်နဲ့လည်း စားသုံးကြပါတယ်။ မွန်လူမျိုးတွေဟင်းချက်သည့်အခါ မရမ်းပြားကို ထည့်ချက်လေ့ရှိတာကို တွေ့ရတတ်ပါတယ်။ မရမ်းသီးအမှည့်ကတော့ အရောင်တဝင်းဝင်းနှင့် ရာသီပေါ်ချိန်ဆို အရောင်းသွက်လှပါတယ်။ ထို့ကြောင့်လူတို့ခံတွင်းတွေ့ပြီး ကြိုက်နှစ်သက်မှုရှိလှတဲ့ မရမ်းသီး (မရမ်းပင်) စိုက်ပျိုးနည်းကို ဗဟုသုတအဖြစ် တင်ဆက်ပေးလိုက်ပါသည်။<br><br>\r\n\r\n၁။ မရမ်းမျိုးများ<br>\r\n-------------<br>\r\nမရမ်းသီးကို အရသာအလိုက် အချိုမျိုးနှင့် အချဉ်မျိုး ဟူ၍ နှစ်မျိုး ခွဲထားပါသည်။ <br><br>\r\n\r\n၂။ စိုက်ပျိုးသည့်ဒေသ <br>\r\n------------------- <br>\r\nမန္တလေးတိုင်း၊ ပဲခူးတိုင်း၊ ရန်ကုန်တိုင်း၊ ဧရာဝတီတိုင်း၊ မွန်ပြည်နယ်၊ ကရင်ပြည်နယ်၊ တနင်္သာရီတိုင်း တို့ တွင် စိုက်ပျိုးဖြစ်ထွန်းသည်။ <br><br>\r\n\r\n၃။ ရေမြေရာသီဥတု <br>\r\n----------------- <br>\r\nမြေစေးဆန်သော နုန်းမြေ၊ ပူအိုက်စွတ်စိုသောရာသီဥတုတို့ကို နှစ်သက်သည်။ သင့်တော်သော မိုးရေချိန် မှာ ၅၀ မှ ၁၅၀ လက်မ ဖြစ်သည်။ <br><br>\r\n\r\n၄။ ပျိုးထောင်နည်း <br>\r\n---------------- <br>\r\nမရမ်းသီး မျိုးကောင်းကိုရွေးကာ သီးမှည့်၏အခွံကိုသင်ပစ်ပြီး အသားမဖယ်ဘဲ ပြာလူးကာ အရိပ်အောက်တွင် သုံးရက်ခန့်ဖြန့်ပြီး ပျိုးထောင်ရပါသည်။ ပျိုးသက်တစ်နှစ်ကျော်မှ စိုက်လေ့ရှိသည်။ စိုက်ကျင်း နှစ်ပေပတ်လည် စိုက်တန်းအကွာအဝေး ၃၀ × ၃၀ ပေ၊ စိုက်စနစ် တစ်ဧကလျှင် သီးသန့် စိုက်ပါက ၄၈ ပင် နှုန်းထားလေ့ရှိသည်။ <br><br>\r\n\r\n၅။ မြေသြဇာကျွေးနည်း <br>\r\n-------------------- <br>\r\nကြီးထွားမှုနှေးသောအပင်မျိုးဖြစ်ကာ အပင်ငယ်တစ်ပင်လျှင် နွားချေးတစ်တင်းနှုန်း၊ အပင်ကြီးလျှင် သုံးတင်းနှုန်း ထည့်ပေးသင့်ပါသည်။ ဝင်ငွေနှင့် တွက်၍ စီးပွားရေးတွက်ခြေကိုက်မည်ဆိုပါက ယူရီးယား၊ တီစူပါ၊ ပိုတက်ရှ် ၁: ၂: ၁ နှုန်းရောကာ အပင်ငယ်လျှင် တစ်ပေါင်နှုန်း အပင်ကြီးလျှင် နှစ်ပေါင်နှုန်း ထည့်ပေးသင့်ပါသည်။ <br><br>\r\n\r\n၆။ အပင်ပြုစုနည်း <br>\r\n---------------<br>\r\nကိုင်းခြောက်ရှင်းပေးခြင်း ၊ သုံးနှစ်သားအပင်ထိ ရေသွင်းပေးခြင်း၊ လောင်းရိပ်များရှင်းပေးခြင်း တို့ကို ဆောင်ရွက်ပေးရပါမည်။ မတ်လနှင့် ဇွန်လတွင် အသီးရင့်မှည့်တတ်သဖြင့် ဈေးကောင်းရစေရန်နှင့် အသီးစောစောရစေရန် ရေနှင့် မြေသြဇာကျွေးခြင်းကို မိုးပြတ်သောရာသီမှစ၍ဆောင်ရွက်ပေးရပါမည်။ <br><br>\r\n\r\n၇။ အထွက်နှုန်း <br>\r\n------------<br>\r\nစိုက်ပျိုးပြီး ခုနစ်နှစ်ကြာလျှင်အသီးစတင်ဆွတ်ခူးနိုင်ပြီး ရရှိနိုင်သောသီးထွက်မှာ အောက်ပါအတိုင်း ဖြစ်ပါသည်။ <br><br>\r\n\r\n▪️ အပင်ငယ်တစ်ပင် မှ အလုံး ရေ ၅,၀၀၀ မှ ၇,၀၀၀ အထိ။ <br><br>\r\n\r\n▪️ အပင်ကြီးတစ်ပင်မှ အလုံး ရေ ၂၀,၀၀၀ မှ ၃၀,၀၀၀ အထိ ရနိုင်ပါသည်။ <br><br>\r\n\r\nSources : စိုက်ပျိုးရေးဦးစီးဌာန', '', '19-02-2024'),
(29, 'ဆီထွက်သီးနှံများ မျိုးကောင်းမျိုးသန့် ရွေးချယ်စိုက်ပျိုးပါ', 'IMG-65d2edbcd5c7c7.85886869.jpg', '🌱🥜🌻🌱🥜🌻🥜🌱🌻🥜🌱<br><br>\r\n\r\n✅တောင်သူဦးကြီးများအတွက် ဆီထွက်သီးနှံများစိုက်ပျိုးရာတွင် မျိုးကောင်းမျိုးသန့်များရွေးချယ် စိုက်ပျိုးကြရန် အလေးထားဆွေးနွေးပေးချင်ပါတယ်။<br><br>\r\n\r\n✅ဆီထွက်သီးနှံမျိုးပြဿနာက မသေးလှပါ။ အချို့ကဆီထွက်သီးနှံများစိုက်ပျိုးရန် ကိုယ့်မျိုးကိုယ် ဆက်ပြီးနှစ်စဉ်ထားကြသည်။ အချို့က စိုက်ခါနီးမှမျိုးရှာပြီးရသည့်မျိုးနှင့် စိုက်လိုက်ကြသည်။ မျိုးကောင်းမျိုးသန့်လည်းမဟုတ် အထွက်ကောင်းမျိုးများလည်းမဟုတ်လျှင် မြေပဲတွင်တစ်နှစ်ထက် တစ်နှစ် အထွက်ဆုတ်လာခြင်း၊ နှမ်းစိုက်လျှင်အပင်ပေါက်နှုန်း မကောင်းခြင်း၊ အသီးနည်းခြင်း၊ နေကြာစိုက်ပါက အပင်ပေါက်များမသန်စွမ်းခြင်း၊ အပွင့်များသေးခြင်း စသည်တို့ကြုံရမည်ဖြစ်သည်။ <br><br>\r\n\r\n✅ထို့ကြောင့် မြေပဲစိုက်လျှင် အပင်ပေါက်ရာခိုင်နှုန်း ၈၅ရာခိုင်နှုန်းမှ ၉၀ရာခိုင်နှုန်းရှိသည့်မျိုးကို ရွေးရပါမည်။ တစ်ပင်မှာအတောင့်ပေါင်း ၁၀၀ကျော်သီးနိုင်သည့် ဆင်းပဒေသာမျိုးများကိုရွေးချယ်ပါ။ တစ်ဧကရိတ်သိမ်းပင် ၁၀၀,၀၀၀ ရအောင်စိုက်ပါ။ တစ်ဧကရှိရမည့် အပင်ရေမပြည့်ပါက အပင် ၁၀,၀၀၀လျော့လျှင် မြေပဲအထွက် (၅ မှ ၁၀)တင်း လျော့နိုင်ပါသည်။<br><br>\r\n\r\n✅နှမ်းမျိုးကိုရွေးမည်ဆိုလျှင် အပင်ပေါက်ရာခိုင်နှုန်း ၈၅ရာခိုင်နှုန်းမှ ၉၀ရာခိုင်နှုန်းရှိသည့်မျိုးကိုရွေးပါ။ အထွက်သေချာသည့် ဆင်းရတနာမျိုးများကို စိုက်ပျိုးပါ။ တစ်ဧကရိတ်သိမ်းပင် ၁၃၀,၀၀၀ ရအောင်စိုက်ပျိုးပါ။ အကယ်၍ တစ်ဧကအတွက်အပင်ရေမပြည့်လျှင် အပင်၅,၀၀၀ အထိ လျော့နိုင်ပါသည်။<br><br>\r\n\r\n✅နေကြာမျိုးရွေးချယ်ရာတွင်တော့ ဆင်းရွှေကြာ(၁) ၊ (၂) စပ်မျိုးနေကြာကိုရွေးချယ်ပါ။ ၎င်းစပ်မျိုးများသည် ဆီထွက်နှုန်းလည်းများပါသည်။ တစ်ဧကရိတ်သိမ်းပင် ၂၉,၀၀၀ ရရှိအောင်စိုက်ပါ။ တစ်ဧကအပင်အရေအတွက်မပြည့်ပါက အပင်ရေ ၁၀ရာခိုင်နှုန်းလျော့လျှင် အထွက်လည်း ၁၀ရာခိုင်နှုန်း လျော့သွားနိုင်ပါသည်။ <br><br>\r\n\r\n✅ထို့ကြောင့် တောင်သူဦးကြီးများဆီထွက်သီးနှံစိုက်ပျိုးရာတွင် မျိုးရွေးချယ်စိုက်ပျိုးမှုကိုအထူးသတိပြုဆောင်ရွက်ကြပါရန် တိုက်တွန်းရေးသားလိုက်ရပါသည်။<br><br>\r\n\r\n\r\n\r\nSources : စိုက်ပျိုးရေးရာအကြံပြုချက်များ', '', '19-02-2024'),
(30, '“အစေ့ထုတ်ပြောင်း အထွက်ကောင်းရအောင် ပြုစုစောင့်ရှောက်ခြင်း”', 'IMG-65d2ee370af424.41383127.jpg', '🌽🌽🌽🌽🌽🌽🌽🌽🌽🌽<br><br>\r\n\r\n🔸အစေ့ထုတ်ပြောင်းကို တောင်ပေါ်ဒေသတွင် စိုက်ပျိုးမှုများပြားပြီး တစ်ဧကအထွက်နှုန်းကောင်းစေရန် ရေဆင်းစိုက်ပျိုးရေးသုတေသနဌာနက တောင်ပေါ်ဒေသအတွက် ထုတ်လုပ်ထားသော အထွက်ကောင်းမျိုးများဖြစ်သည့် ရေဆင်းစပ်မျိုး(၃)၊ ရေဆင်းစပ်မျိုး(၅)၊ စီပီ 888 စသည့်မျိုးများ စိုက်ပျိုးကြရပါမည်။<br><br>\r\n\r\n🔸အစေ့ထုတ်ပြောင်းစိုက်ပျိုးရာတွင် အထွက်နှုန်းကိုအဓိကစိုးမိုးနေသည့် တစ်ဧကဝင်ဆံ့ရမည့် အပင်ဦးရေကို မိုးရာသီတွင် အပင် ၂၃,၀၀၀ မှ ၂၅,၀၀၀ ပင်၊ ဆောင်းရာသီတွင် ၁၇,၀၀၀ မှ ၂၀,၀၀၀ ပင် အရေအတွက်ပြည့်အောင်ရရှိဖို့ ဂရုပြုရပါမည်။ တစ်ဧကရှိရမည့်အပင်ဦးရေမရရှိပါက အထွက်နှုန်းကို ၄၀ မှ ၆၀ ရာခိုင်နှုန်းအထိ ကျဆင်းစေနိုင်ပါသည်။<br><br>\r\n\r\n🔸အစေ့ထုတ်ပြောင်းသည် သဘာဝမြေဩဇာနှင့် ဓာတ်မြေဩဇာ အလွန်နှစ်ခြိုက်သည့်သီးနှံပင်ဖြစ်သည်။ မြေပြုပြင်ချိန်တွင် နွားချေး၊ မြေဆွေး တစ်ဧကလျှင် (၅-၁၀)တင်းနှုန်းထည့်ပေးပါ။ စိုက်ချိန်တွင် ယူရီးယား (၂၈)ပေါင် ထည့်ပေးရပါမည်။ တောင်ပေါ်ဒေသများတွင်မြေချဉ်တတ်သည့်အတွက် တစ်ဧကလျှင် မဖောက်ထုံး ပေါင်(၅၀၀)ခန့် ထည့်ပေးဖို့လိုပါသည်။ <br><br>\r\n\r\n🔸စိုက်ပျိုးပြီးအပင်(၁၅-၂၀)ရက်သား ရရှိသည့်အချိန်တွင် အပင်သားခွဲ၊ ပေါင်းရှင်းပြီးလျှင် ယူရီးယား (၂၈)ပေါင် ထည့်ပေးပြီး မြေဩဇာမြေကြီးထဲအမြစ်ဇုန်ရောက်အောင် မြေဆွပေးဖို့လိုပါသည်။ ပြောင်းပင်အသက် (၃၅-၄၀)ရက် ခန့်ရောက်လျှင် ယူရီးယားမြေဩဇာ (၂၈)ပေါင် တစ်ကြိမ်ထပ်ထည့်ပေးပြီး မြေဆွဘောင်တင်ပေးရပါမည်။ တီစူပါမြေဩဇာ တစ်ဧကအတွက် (၁၁၂)ပေါင်ကို မြေယာပြုပြင် စိုက်ပျိုးချိန်မှာတစ်ကြိမ်တည်းထည့်ပေးရန်လိုပါသည်။ ပိုတက်ရှ်ဓာတ်မြေဩဇာကို မြေယာပြုပြင် စိုက်ပျိုးချိန်တွင် (၂၈)ပေါင်၊ အပင်သက် (၁၅-၂၀)ခန့်ရှိချိန်တွင် (၂၈)ပေါင် နှင့် စိုက်ပျိုးပြီး (၃၅-၄၀) ရက်သား တွင် (၂၈)ပေါင် ထည့်ပေးရပါမည်။<br><br>\r\n\r\n🔸အစေ့ထုတ်ပြောင်းပင် အပင်ပေါက်စမှ သုံးပတ်သားအတွင်း ပြောင်းမြက်များကင်းစင်အောင် ဂရုတစိုက် ပေါင်းရှင်း ဆောင်ရွက်ပေးရန်လိုအပ်ပြီး ဝိစာရ၏ “ပေါင်းစင်၊ အေမီကွင်း” ရွေးချယ်ပေါင်းသတ်ဆေး များဖြင့် ပက်ဖျန်းကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n🔸ပိုးမွှားများအနေဖြင့် အပင်ငယ်စဉ်တွင် ရွက်ဖြတ်ပိုး၊ ရွက်စားပိုး၊ ပျပိုးများ ကျရောက်တတ်ပြီး ပန်းပွင့်ချိန်တွင် ပျပိုးကျရောက်တတ်ကာ ဝိစာရ၏ “အီမာလန်ဒါ၊ နိုက်ဝမ်း၊ ကေလာ၊ နိုးဝမ်း”ဆေးများကိုဆေးညွှန်းပါအတိုင်းသုံးစွဲပေးရန် နှင့် ပြောင်းဖူးအစေ့စတင်တည်ချိန်တွင် ပြောင်းဖူး အစေ့ထိုးပိုးကို “ဘီတာစီ၊ လိုင်းအောက်” ဆေးများအသုံးပြု၍ ကာကွယ်နှိမ်နင်းပေးရပါမည်။<br><br>\r\n\r\n🔸အစေ့ထုတ်ပြောင်းတွင်ကျရောက်တတ်သောရောဂါများမှာ ရွက်ဖုံးခြောက်ရောဂါ၊ ပင်စည်ပုပ်ရောဂါ၊ ရွက်ခြောက်ရောဂါများဖြစ်ပြီး ၎င်းရောဂါများအတွက် “ကျူပရိုမက်စ်၊ ကာစင်၊ ဘာလီဆိုဒ်၊ ကာဗာ” စသည့် ဘက်တီးရီးယားနှင့် မှိုရောဂါ ကာကွယ်နှိမ်နင်းဆေးများကို အသုံးပြုပေးရပါမည်။<br><br>\r\n\r\n🔸ဤသို့ဖြင့် အစေ့ထုတ်ပြောင်းစိုက်ပျိုးရာတွင် အထွက်ကောင်းရအောင် ပြုစုစောင့်ရှောက်ရမည့်နည်းစနစ် များကို ဂရုပြုဆောင်ရွက်ပေးခြင်းဖြင့် ပိုးမွှား ရောဂါ ကင်းစင်သည့် အထွက်ကောင်းစိုက်ခင်းများကို ပိုင်ဆိုင်နိုင်ကြစေရန် ဆန္ဒပြုရေးသားလိုက်ရပါသည်။<br><br>\r\n\r\n\r\n\r\nSources : စိုက်ပျိုးရေးရာအကြံပြုချက်များ', '', '19-02-2024'),
(31, '“ဘိုစားပဲ” စိုက်ပျိုးနည်း', 'IMG-65d2eecc833a79.81907072.jpg', '🍀🌱🍀🌱🍀🌱🍀🌱🍀🌱🍀<br><br>\r\n\r\nနိဒါန်း<br>\r\n-----<br>\r\n\r\nဘိုစားပဲကို ပင်ထောင်မျိုး နှင့် နွယ်တက်မျိုး ဟူ၍ ခွဲခြားထားသည်။ အစေ့သည် ကျောက်ကပ်ပုံ၊ အဖြူ၊ အနက်၊ နီညို၊ ခရမ်းစသည်ဖြင့် မျိုးကွဲပေါင်းများစွာရှိသည်။ အပူပိုင်းနှင့် အအေးပိုင်းဇုန်များတွင် ဖြစ်ထွန်းသည်။ ရေမြေ ရာသီဥတုမရွေးပေါက်ရောက်နိုင်သော်လည်း ပူအိုက်စွတ်စိုသော ဒေသ၌ မဖြစ်ထွန်းပေ။<br><br>\r\n\r\nမြေပြုပြင်ခြင်း<br>\r\n------------<br>\r\n\r\nသဲဆန်သောမြေမှ မြေစေးအထိ မြေအမျိုးမျိုးတွင် ပေါက်နိုင်သည်။ ရေမဝပ်သော သဲနုန်းမြေ၊ နုန်းမြေစေး၊ နုန်းမြေတို့တွင်ကောင်းစွာဖြစ်ထွန်းသည်။ မြေချဉ်ငံဓာတ် (၄ . ၂ – ၈ . ၇)အတွင်း ဖြစ်ထွန်းနိုင်သည်။ ထွန်ရေးကောင်းအောင် မြေကိုပြုပြင်ရန်မလိုချေ။ မျိုးစေ့နှုန်း --------- ပင်ထောင်မျိုးများကို တစ်ဧကအတွက် မျိုးစေ့(၁၀-၁၂)ပြီ လိုအပ်ပြီး တိုင်ထောင်မျိုးများအတွက် (၆-၈)ပြီ လိုအပ်သည်။<br><br>\r\n\r\nစိုက်ပျိုးခြင်း<br>\r\n----------<br>\r\n\r\nမျိုးစေ့ချရာ၌ အစိုဓာတ်များလွန်းက အစေ့ပုပ်တတ်သည်။ တိုင်ထောင်ပြီး စိုက်ပျိုးလျှင် တစ်ကျင်းတွင် (၂-၃)စေ့ ထည့်၍စိုက်ရသည်။ တစ်ဧကလျှင် နွားချေး ၁၀ တန်၊ ယူရီးယား ၁၈ ကီလို၊ တီစူပါ တစ်အိတ်၊ ပိုတက်ရှ် အိတ်ဝက်ထည့်ပေးရန်လိုသည်။ ကြားထွန်နှစ်ကြိမ် လိုက်ပေးလျှင်လုံလောက်သည်။ ပင်ထောင်မျိုးကို တစ်တန်းနှင့်တစ်တန်း နှစ်ပေခြား၍ တစ်ပင်နှင့်တစ်ပင် ၁၀ လက်မ ခွာစိုက်သည်။ ရာသီဥတုသင့်တင့်သောဒေသတွင် တစ်နှစ်ပတ်လုံးစိုက်ပျိုးနိုင်သည်။<br><br>\r\n\r\nအပင်ပြုစုခြင်း<br>\r\n------------<br>\r\n\r\nပေါင်းနှစ်ကြိမ် လိုက်ပေးလျှင် လုံလောက်သည်။ ခြောက်သွေ့သောရာသီဒဏ်ကို ခံနိုင်ရည်ရှိသော်လည်း ရက်ရှည်ခြောက်သွေ့က ရေသွင်းပေးရန်လိုအပ်သည်။ ပဲသံချေး၊ ပဲမှဲ့ပျောက်စွန်းရောဂါ၊ ဘက်တီးရီးယားရွက်ခြောက်၊ အရွက်နူရောဂါများ ကျရောက်တတ်သည်။ ခူမွှေးစုပ်၊ ပိုးကျိုင်းငယ်၊ ပဲစားကြမ်းပိုးနှင့် ပျပိုးများ ကျရောက်သည်။ ထိသေ၊ စားသေပိုးသတ်ဆေး၊ မှိုသတ်ဆေးများသုံး၍ ကာကွယ်နိုင်သည်။<br><br>\r\n\r\nခူးယူခြင်း<br>\r\n--------<br>\r\n\r\nအပင်ပေါက်ပြီး (၇၅) ရက်မှစ၍ အသီးများဆွတ်ခူးနိုင်သည်။ ပဲသီးများကိုအရွယ်မရောက်မီ အစေ့နုသေး သောအချိန်တွင်ဆွတ်ခူးသည်။ ပန်းပွင့်ပြီး (၂-၃)ပတ်အကြာတွင် စတင်ဆွတ်ခူးနိုင်သည်။ ပင်ထောင်မျိုး တစ်ဧကလျှင် (၈၀ဝ - ၉၀ဝ)ပိဿာ၊ တိုင်ထောင်မျိုးတစ်ဧကလျှင် ၂,ဝဝဝ ပိဿာကျော်အထိ ထွက်ရှိနိုင်ပါသည်။<br><br>\r\n\r\nမျိုးစေ့ထုတ်ယူခြင်း<br>\r\n----------------<br>\r\n\r\nမျိုးစေ့ထုတ်လုပ်ရန် အသီးများကို အပင်ပေါ်တွင်ခြောက်အောင်ထား၍ ဆွတ်ခူးရမည်။ အချို့က အပင် လိုက်နုတ်၍နေလှမ်းပြီး အတောင့်များကို မူလအတိုင်းသိမ်းဆည်းကြသည်။ ထို့နောက် စိုက်ချိန်ရောက်လျှင် အစေ့များချွေပြီး စိုက်ပျိုးကြသည်။ အများအားဖြင့် အစေ့ကို ကြိုတင်ချွေ၍ ဆက်လက်နေလှမ်းပြီးမှ သိမ်းဆည်းသည်။ ပဲစေ့သည် သိုလှောင်ရာ၌ ပိုးထိုးတတ်သောကြောင့် မျိုးအဖြစ်အသုံးပြုမည့်အစေ့များကို ထုံးနှင့်ရောမွှေ၍ သိမ်းဆည်းသင့်သည်။<br><br>\r\n\r\nSources : ဟင်းသီးဟင်းရွက်စိုက်ပျိုးခြင်းလမ်းညွှန်', '', '19-02-2024'),
(32, '\"ဈေးကွက်ရှိနေသောမတ်ပဲ နှင့် မျိုးစေ့ ရွေးချယ်စိုက်ပျိုးခြင်း\"', 'IMG-65d2ef7d973901.63694409.jpg', '🌱🫘🌱🫘🌱🫘🌱🫘🌱🫘🌱<br><br>\r\n\r\n⏩ပဲမျိုးစုံဈေးကွက်၌ မတ်ပဲဈေးကွက်သည်ခိုင်မာနေသည်။ ပဲအများဆုံးစားသုံးသည့် အိမ်နီးချင်းနိုင်ငံကလည်း ရာသီဥတုမမှန် မိုးရွာမှုနည်းသဖြင့် ပဲလိုအပ်ချက်ရှိနေသည်။ မတ်ပဲသည်နေ့တာတို အပင်အမျိုးအစားဖြစ်သဖြင့် နေ့တာတုံ့ပြန်မှုရှိသည်။ မိုးရာသီစိုက်ပျိုးမှုကို မိုးလယ်ကာလ၌မြန်မာနိုင်ငံအထက်ပိုင်း၌စိုက်ကြသည်။ သို့သော်မြန်မာနိုင်ငံတွင် မတ်ပဲဧကများများစိုက်ကြသည်မှာ မြန်မာနိုင်ငံအောက်ပိုင်းဒေသများဖြစ်သည့် ပဲခူးတိုင်း နှင့် ဧရာဝတီတိုင်း ဒေသကြီးဖြစ်သည်။<br><br>\r\n\r\n⏩စပါးအပြီးမတ်ပဲသီးထပ်စိုက်ကြသလို နိုဝင်ဘာလလယ်တွင် ဆောင်းစိုက်စိုက်ပျိုးကြသည်။ စပါးအပြီးစိုက်ကြသည်မှာ စပါးခင်းမှစပါးရိတ်ပြီး လက်ကျန်မြေအစိုဓာတ်ဖြင့်စိုက်နိုင်လေ ကောင်းလေဖြစ်သည်။ ထို့ကြောင့်စပါးမြန်မြန်ရိတ်ကြ ပဲမြန်မြန်စိုက်ကြနှင့် တက်သုတ်ရိုက်ကြရသည်။ ရေငတ်ဒဏ်ခံနိုင်သောသီးနှံဖြစ်သည်ဆိုသော်လည်း စိုက်ချိန်၊ ပန်းပွင့်ချိန်၊ အစေ့အဆံတည်ချိန်များတွင် မြေအစိုဓာတ်ကောင်းမှသာ အထွက်ကောင်းသည်။ <br><br>\r\n\r\n⏩သို့သော်ခက်နေသည်က “မျိုး”ဖြစ်သည်။ မျိုးသန့်မျိုးစေ့ဖြင့် စိုက်ပျိုးသူကနည်းပြီး စိုက်ခင်းထဲမှမျိုးကို မျိုးခံ၍မျိုးဆံစိုက်ပျိုးသူက အများစုဖြစ်သည်။ မတ်ပဲမှမဟုတ်ပါ။ သီးနှံတော်တော်များများကို စိုက်ခင်းထဲမှရိတ်သိမ်းချိန် တစ်ချို့ကို မျိုးချန်ပြီး ကျန်တာများရောင်းချလိုက်ကြသည်။ ဤနည်းဖြင့်နောက်တစ်နှစ်လည်းထိုနည်းလည်းကောင်း ရိတ်ချိန်နည်းနည်းချန်၍ ကျန်တာရောင်းပစ်ကြသည်။ ဤသို့ဖြင့်နှစ်ကြာသော် မျိုးစေ့ကိုစိုက်ပျိုးခြင်းမဟုတ်သဖြင့် သီးနှံအထွက်သည် ကျသထက်ကျလာသလို အရည်အသွေးကလည်း ညံ့သထက်ညံ့လာသည်။ ဤသို့ဖြင့် ဈေးကွက်ပျက်ကြရသည်။<br><br>\r\n\r\n⏩ထို့ကြောင့် မျိုးစေ့ကို မျိုးပွားနည်းများ၊ မျိုးစေ့ထုတ်လုပ်ငန်းများဖြင့် ဆင့်ပွားထုတ်လုပ်နိုင်ရန် နည်းပညာများရယူပြီး တောင်သူများကိုယ်တိုင်မျိုးစေ့ထုတ် စိုက်ပျိုးသင့်ပါသည်။ ပြည်ပဝယ်လက်များသည်ပင် အရည်အသွေးကောင်းသောနိုင်ငံများမှပြောင်းလဲဝယ်ယူလာကြပြီ ဖြစ်သည်။ မတ်ပဲတွင် ပုလဲနက်၊ ရေဆင်း(၁)၊ ရေဆင်း(၂)၊ ရေဆင်း(၃)၊ ရေဆင်း(၄)၊ ရေဆင်း(၅)၊ LBG(၁၇) မျိုး နှင့် ဒေသမျိုးများမှ မင်းလှထွန်းမျိုး၊ ဟင်္သာတလုံးကြီး၊ မိုးညိုလုံးကြီးမျိုးများ ကို မျိုးကောင်းထား၍ စိုက်ပျိုးနေကြရသည်။ <br><br>\r\n\r\n⏩ရေဆင်း(၂)သည် အသက်ရက် (၉၀ - ၁၀၀)နှင့် အစေ့အရွယ်ကြီးပြီး ဒေသမရွေးစိုက်နိုင်သည်။ ရေဆင်း(၃)သည် အစေ့သေးသော်လည်း အထွက်ကောင်းသည်။ ရေဆင်း(၄)သည် ရာသီမရွေးစိုက်နိုင်သည်။ ရေဆင်း(၅)သည်အစေ့ကြီး၍ အထွက်ကောင်းသည်။ မျိုးကောင်းလျှင် တစ်ဧက (၂၅ - ၃၀)တင်းကျော်ထွက်နိုင်သော်လည်း မျိုးစေ့ကိုမစိုက်ကြပဲ မျိုးညံ့မျိုးပျက်ပြီးဗီဇမမှန်၍ တစ်ဧက တင်း(၂၀) မှ (၁၅)တင်းသို့သာ ထွက်နိုင်တော့သည်။ <br><br>\r\n\r\n⏩ထို့ကြောင့်ပြည်ပဈေးကွက်ကောင်းရှိနေသော မတ်ပဲကို အရည်အသွေးကောင်းကောင်းပဲစေ့ရရန်မှာ မျိုးစေ့စိုက်ကြသင့်ပြီး မျိုးစေ့ထုတ်ခြံများမှလည်း မျိုးများများထုတ်လုပ်ပွားများ၍ဖြန့်ဖြူးသင့်ပေပြီ။ ပုဂ္ဂလိကများကလည်းပဲမျိုးစေ့ထုတ်လုပ်သည့်လုပ်ငန်းများလုပ်ကိုင်၍ မျိုးစေ့ရောင်းချပေးသင့်ပါသည်။ ဓာတ်မြေဩဇာများလည်း သုံးသင့်သလောက်ထည့်သွင်း အသုံးပြုပေးရပါမည်။ မျိုးကညံ့ သင့်တင့်သည့် မြေဩဇာကိုလည်း ထည့်မသုံးလျှင် ထွက်ရှိလာသောပဲသည် အရည်အသွေးညံ့ညံ့သာဖြစ်နေပါတော့မည်။<br><br>\r\n\r\nSources : စိုက်ပျိုးရေးရာအကြံပြုချက်များ', '', '19-02-2024'),
(33, '“ဘိုကိတ်ပဲ စိုက်ပျိုးနည်း”', 'IMG-65d2efc4a254b3.70466557.jpg', '🌿🫘🌿🫘🌿🫘🌿🫘🌿🫘🌿<br><br>\r\n\r\n🌿မူရင်းဒေသ🌿<br><br>\r\n\r\nဘိုကိတ်ပဲ၏ မူရင်းဇာတိမှာ အမေရိကန်ပြည်ထောင်စုဖြစ်ပါသည်။ ၎င်း ဘိုကိတ်ပဲမျိုးကို မြန်မာနိုင်ငံသို့ ယူဆောင်လာသူမှာ မစ္စတာဘရေတွန်ကေ့စ် (Mr Brayton Case) ဆိုသူပင်ဖြစ်ပါသည်။<br><br>\r\n\r\n🫘ဘိုကိတ်ပဲ အမည်ဖြစ်ပေါ်လာပုံ🫘<br><br>\r\n\r\nမစ္စတာကေ့စ်က အသားဖြူဖြူ၊ မျက်လုံးပြာပြာ၊ နှာခေါင်းက ချွန်ချွန်ရှည်ရှည်၊ အရပ်မြင့်မြင့် ဖြစ်ပါသည်။ အရင်အင်္ဂလိပ်ခေတ်က ထိုကဲ့သို့ရုပ်ရှည်ရှိတဲ့သူတွေကို \"ဘို\" ဟု ခေါ်ဝေါ်ကြပြီး သူ့အမည် Case (ကေ့စ်)ကိုလည်း မြန်မာတို့နားထဲတွင် \"ကိတ်\" လို့ပဲ ကြားပုံရပါသည်။ သူတင်သွင်းလာပီး စိုက်ပျိုးဖြန့်ဖြူးခဲ့တဲ့ ပဲကို \"ဘိုကိတ်ပဲ\" လို့ ခေါ်ရာကအစ ယနေ့တိုင် မြန်မာတဝှမ်းလုံးက \"ဘိုကိတ်ပဲ\"လို့ ခေါ်ကြပြီး မြန်မာနိုင်ငံအနှံ့အပြားမှာ ယခုထိ စိုက်ပျိုးနေကြဆဲဖြစ်သည် ဟု ဆိုကြပါသည်။<br><br>\r\n\r\n🌿ရာသီဥတု🌿<br><br>\r\n\r\nစိုစွတ်တဲ့မိုးရာသီမှာ စိုက်တာများပြီး ခြောက်သွေ့တဲ့ နွေရာသီမှာလည်း ရေသွင်းစိုက်လေ့ရှိကြပါသည်။ အလွန်အေးပြီး နှင်းကျတဲ့ရာသီဥတုကိုတော့ နှစ်သက်လေ့မရှိပါ။<br><br>\r\n\r\n🫘မြေအမျိုးအစား🫘<br><br>\r\n\r\nရေစီးဆင်းမှုကောင်းပြီး မြေအချဥ်ငံဓာတ် (၆.၅ - ၇) လောက် ရှိတဲ့ နုန်းမြေ၊ သဲနုန်းမြေတွေက အသင့်တော်ဆုံးမြေဖြစ်ပါတယ်။ ၎င်းမြေများသည် ရေမြုပ်ခြင်းကိုလည်း ရှောင်လွဲပေးနိုင်ပါသည်။<br><br>\r\n\r\n🌿စိုက်ပျိုးချိန်🌿<br><br>\r\n\r\nအများအားဖြင့် ဧပြီလ မှ အောက်တိုဘာလ အစောပိုင်းလောက်အထိ စိုက်ပျိုးကြပါသည်။<br><br>\r\n\r\n🫘မြေပြုပြင်ခြင်း🫘<br><br>\r\n\r\nမစိုက်ခင်မှာမြေကို ထယ်ထိုး၊ ထွန်မွှေပြီး ရိုးပြတ်တွေနဲ့ အမှိုက်မှန်သမျှကို ရှင်းလင်းပေးပါ။ သို့မှသာ ပေါင်းမြက်ပေါက်ရောက်မှုကို အနည်းဆုံးအနေအထားထိ လျော့ချနိုင်မှာလည်းဖြစ်ပါသည်။<br><br>\r\n\r\n🌿မြေဩဇာထည့်ခြင်း🌿<br><br>\r\n\r\nဘိုကိတ်ပဲသည် ကိုယ်တိုင်နိုက်ထရိုဂျင်ထုတ်ပေးသော သီးနှံမျိုးဖြစ်သည်။ တစ်ဧကအတွက် နွားချေး (၇)စီး၊ ပုလဲ(၇) ပြည်၊ ပိုတက် (၁၂)ပြည်၊ တီစူပါ(၂၂) ပြည်ကို မြေခံအဖြစ်ထည့်ပေးရပါမည်။<br><br>\r\n\r\n🫘စိုက်ပျိုးခြင်း🫘<br><br>\r\n\r\n▪️ မစိုက်ခင်မှာ မျိုးစေ့များကို မျိုးစေ့လူးနယ်ဆေးတစ်မျိုးမျိုးနှင့် လူးနယ်ထားပေးပါ။<br><br>\r\n\r\n▪️ တစ်ဧကလျှင် မျိုးစေ့နှုန်းထား (၆-၈) ပြည်နှုန်း အသုံးပြုပေးရပါမည်။<br><br>\r\n\r\n▪️ စိုက်ပျိုးရာတွင် တိုက်ရိုက်အစေ့ချစိုက်လေ့ရှိပြီး ကျင်းအနက် တစ်လက်မလောက် တစ်ကျင်းကို (၂) စေ့နှုန်းနှင့် စိုက်ပါ။ တစ်ကျင်းနဲ့တစ်ကျင်း အကွာအဝေးကို (၆) လက်မခြားပေးပြီး တန်းကြားကို (၁၂) လက်မခန့်ထားပေးရပါမည်။<br><br>\r\n\r\n🌿ရေသွင်းပေးခြင်း🌿<br><br>\r\n\r\nမိုးရာသီမှာစိုက်လျှင် ရေသွင်းရန်မလိုသော်လည်း နွေရာသီမှာစိုက်လျှင် ရေသွင်းပေးရန်လိုအပ်ပါသည်။ အထူးသဖြင့် အပင်ပေါက်ချိန်နှင့် အစေ့ဆံတည်ချိန်တွေမှာ ရေလိုအပ်ပါသည်။ Sprinkler နည်းနဲ့ ရေပေးမည်ဆိုလျှင် တစ်နေ့ကို (၂-၄) နာရီလောက်ရေပေးပေးပါ။<br><br>\r\n\r\n🫘ပေါင်းမြက်ရှင်းခြင်းနှင့် ကျရာက်တတ်သောပိုးမွှားရောဂါများ🫘<br><br>\r\n\r\n▪️ ပဲသက်တမ်းတစ်လျှောက်လုံးမှာ (၂-၃) ကြိမ် ကြားပေါင်းလိုက်ပေးရန် လိုအပ်ပါသည်။<br><br>\r\n\r\n▪️ အဓိကကျရောက်တတ်သည့်ပိုးမှာ လှေးပိုးနှင့် သီးလုံးဖောက်ပိုးဖြစ်ပြီး ပျ၊ ယင်ဖြူ နှင့် အဝါရောင် မိုစေ့ဗိုင်းရပ်စ်ရောဂါလည်း ကျရောက်တတ်ပါသည်။ ထိုသို့ဖျက်ပိုး နှင့် ရောဂါကျရောက်မှုကို ကာကွယ်နိုင်ရန် ပဲပင်(၁၅)ရက်သားကျော်လျှင် ဝိစာရ၏ “နိုးဝမ်း၊ ကေလာ၊ အီမာလန်ဒါ၊ ပရိုဆင့်” ဆေးများကို ဆေးညွှန်းပါအတိုင်း ရွေးချယ်အသုံးပြုပေးရပါမည်။<br><br>\r\n\r\n🌿ခူးဆွတ်ရိတ်သိမ်းခြင်း🌿<br><br>\r\n\r\nပျမ်းမျှအားဖြင့် စိုက်ပြီး ရက်ပေါင်း(၉၀-၁၂၀)ခန့် အကြာတွင် ခူးဆွတ်ကြပါသည်။ (သို့မဟုတ်) သီးထောင့်၏ ၉၅ % ဝါညိုရောင်ပြောင်းလာသည့်အချိန်တွင် ခူးဆွတ်ကြပါသည်။ <br><br>\r\n\r\nSources : စိုက်ပျိုးရေးဦးစီးဌာန', '', '19-02-2024'),
(34, 'စပါးခင်း ပေါင်းရှင်းပေးမည့် “ဝိစာရ”၏ စပါးရွေးချယ်ပေါင်းသတ်ဆေးများ', 'IMG-65d2f0ce3ac876.95733148.jpg', '🌾🌱🌾🌱🌾🌱🌾🌱🌾🌱🌾<br><br>\r\n\r\n✅မြန်မာနိုင်ငံတွင် ရေမြေဒေသအလိုက် ရေရရှိမှုအပေါ်မူတည်၍ စပါးသီးနှံကို တစ်နှစ်ပတ်လည်လုံး စိုက်ပျိုးကြပါသည်။ ထိုသို့စိုက်ပျိုးရာတွင် စပါးအထွက်ကောင်းရရှိစေရေးအတွက် အခြေခံအကျဆုံးမှာ စပါးခင်းများအတွင်း ပေါင်းမြက်ရှင်းလင်းနိုင်ရေးပင်ဖြစ်ပါသည်။ သို့အတွက် စပါးစိုက်ပျိုးနည်းစနစ်၊ စပါးသီးနှံတွင်ပေါက်ရောက်သောပေါင်းအုပ်စုနှင့် စပါးပင်သက်တမ်းများအလိုက် ရွေးချယ်အသုံးပြု ရမည့် ဝိစာရ၏ စပါးရွေးချယ်ပေါင်းသတ်ဆေးများကို တစ်စုတည်းတင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n၁ ။ အောရိုက် ၇၀ ဒဗလျူပီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Fenoxaprop-P-ethyl 13% + Quinclorac 50% + PSE 7% ပါဝင်ပါသည်။<br><br>\r\n\r\n▪️ ထိသေနှင့် ပင်လုံးပြန့် အာနိသင်ရှိပြီး မြက်သီး၊ မြက်ချို၊ ဝမ်းဘဲစာ၊ ဒေါင်းမြီးပျံ၊ လက်သဲခွ၊ မြက်ကြိန်၊ မြက်မုန်ညင်းစိမ်း၊ မှိုနတို၊ ပေါင်းလေးညှင်း၊ ကြိတ်မှန်၊ ပုဇွန်စာ၊ ကတောက်ဆတ်၊ ရေကညွတ်၊ လယ်ပဒူ အပါအဝင် မြက်အုပ်စု၊ ရွက်ပြန့်ပေါင်းအုပ်စု နှင့် မုန်ညင်းအုပ်စုများကို နှိမ်နင်းနိုင်သည်။<br><br>\r\n\r\n▪️ စပါးပင်သက်တမ်း (၁၅ - ၃၅)ရက်အတွင်း အသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\n၂ ။ ခရက်ဒစ် ၆၀ အိုဒီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Cyhalofop Butyl - 5% + Penoxsulam - 1% ပါဝင်ပါသည်။<br><br>\r\n\r\n▪️ တိုက်ရိုက်အစေ့ချ စပါးခင်းများအတွက် ဖော်စပ်ပုံအသစ်ဖြင့် အထူးထုတ်လုပ်ထားပါသည်။<br><br>\r\n\r\n▪️ မြက်သီး၊ ငသယောင်(တက်ကွက်) နှင့် မြက်အမျိုးမျိုး၊ ကျွဲကြောင်မင်စေး၊ လယ်လေးညှင်း၊ လယ်ပဒူ၊ ကတောက်ဆတ်၊ မှိုနတိုနှင့် ရွက်ပြန့်ပေါင်းအမျိုးမျိုး၊ မြက်မုန်ညင်းအမျိုးမျိုးကို နှိမ်နင်းရှင်းလင်း နိုင်သည်။<br><br>\r\n\r\n▪️ စပါးတိုက်ရိုက်အစေ့ချပြီး (၈-၁၂)ရက်အတွင်း ပေါင်းပင်အရွက်(၁-၃)ရွက်ထွက်ချိန်တွင် အသုံးပြုရပါမည်။<br><br>\r\n\r\n၃ ။ ဆိုင်ဟေလို ၁၀ အီးစီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Cyhalofop Butyl 10% ပါဝင်ပါသည်။<br><br>\r\n\r\n▪️ ပင်လုံးပြန့်အာနိသင်ရှိပြီး ဒေါင်းမြီးပျံ၊ မြက်သီး၊ ဝမ်းဘဲစာ၊ ငသယောင်(တက်ကွက်)၊ ဆင်ငိုမြက်၊ စပါးရိုင်း၊ မြက်ကြိမ်၊ လက်သဲခွမြက် နှင့် တစ်နှစ်ခံမြက်အမျိုးမျိုးကို နှိမ်နင်းနိုင်ပါသည်။ <br><br>\r\n\r\n▪️ စပါးပျိုးခင်း၊ အစေ့ချစပါးခင်းနှင့် ရွှေ့ပြောင်းစိုက်စပါးခင်းများအားလုံးတွင် အသုံးပြုနိုင်ပြီး ပြောင်းရွှေ့ စိုက်ခင်းများတွင် စိုက်ပြီး(၁၀-၁၅)ရက်သားအထိ အသုံးပြုနိုင်သည်။ ဒေါင်းမြီးပျံကိုနှိမ်နင်းရန် ဒေါင်းမြီးပျံ အရွက် (၂-၆)ရွက်ရှိချိန်တွင် ပက်ဖျန်းပေးရပါမည်။<br><br>\r\n\r\n၄ ။ ဒီမင်း ၇၂ အီးစီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း 2,4-D dimethylamine 72%W/V Aqueous solution၊ 2,4-D equivalent 60% W/V ပါဝင်ပါသည်။<br><br>\r\n\r\n▪️ ပင်လုံးပြန့်အာနိသင်ရှိပြီး စပါး၊ ဂျုံ၊ ပြောင်း၊ ဆီအုန်း၊ ရော်ဘာစိုက်ခင်းများတွင်ပေါက်သော မုန်ညင်းမျိုးရင်းဝင် မုန်ညင်းဥနက်နှင့် မြက်မုန်ညင်းစိမ်း၊ မြက်မုန်ညင်းဝါ၊ မြက်ကွမ်းသီးလေး၊ ဝက်လာ နှင့် ရွက်ပြန့်ပေါင်းမျိုးများဖြစ်သော ဝက်ကျွတ်၊ ကတောက်ဆတ်၊ လယ်ပဒူ၊ ပုဇွန်စာ၊ ပေါင်းလေးညှင်း၊ ဟင်းနုနွယ်ဆူးပေါက်၊ ကြိတ်မှန်၊ မှိုနတို၊ ဗေဒါ၊ ရေကန်ဇွန်း စသည့်ပေါင်းအမျိုးမျိုးကို နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n▪️ တိုက်ရိုက်အစေ့ချစပါးခင်းတွင် စပါးအပင်ပေါက်ပြီး(၂၀-၃၅)ရက်သား နှင့် ပျိုးထောင်စိုက်ခင်းတွင် ပြောင်းရွှေ့စိုက်ပြီး (၁၅-၂၀)ရက်သားအတွင်း ပက်ဖျန်းပေးရပါမည်။ <br><br>\r\n\r\n၅ ။ ဟာဘီ ၇.၅ အီးဒဗလျူ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Fenoxaprop-P-ethyl 75 g/l ပါဝင်ပါသည်။<br><br>\r\n\r\n▪️ တိုက်ရိုက်အစေ့ချစပါးခင်းနှင့် ရွှေ့ပြောင်းစိုက်စပါးခင်း (၂)မျိုးလုံးတွင်အသုံးပြုနိုင်ပြီး စပါးမျိုးစေ့ချပြီး (သို့) ရွှေ့ပြောင်းစိုက်ပျိုးပြီး (၁၅-၂၅)ရက်သား ပေါင်းပင်အရွက်(၃-၄)ရွက် ထွက်ချိန်တွင် အသုံးပြုနိုင်သည်။ <br><br>\r\n\r\n▪️ မြက်သီး၊ ဝမ်းဘဲစာ၊ ဒေါင်းမြီးပျံ၊ လက်သဲခွ၊ တက်ကွက်၊ စပါးရိုင်း၊ မြက်ကြိမ်၊ ဝါးရုံမြက်၊ ရေမချိုး (ဖော့မြက်) အစရှိသည့် ပေါင်းမြက်များကို နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၆ ။ နိုက် ၂၀၀ ဒဗလျူပီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Chlorimuron ethyl 100g/kg ၊ Metsulfuron methyl 100g/kg ပါဝင်ပါသည်။<br><br>\r\n\r\n▪️ ရွက်ပြန့်ပေါင်းအုပ်စုဝင် ပေါင်းများဖြစ်သော လယ်ပဒူ၊ လယ်လေးညှင်း၊ ရေကညွတ်၊ ကတောက်ဆတ်၊ ပုဇွန်စာ၊ ကနဖော့ နှင့် မြက်မုန်ညင်းမျိုးရင်းဝင် ပေါင်းများဖြစ်သော မြက်မုန်ညင်းအစိမ်း၊ မြက်မုန်ညင်း အဝါ၊ မြက်ကွမ်းသီးလေး၊ ဝက်လာ အစရှိသည့် ပေါင်းများကိုထိရောက်စွာနှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n▪️ တိုက်ရိုက်အစေ့ချစပါးခင်းနှင့် ရွှေ့ပြောင်းစိုက်စပါးခင်းနှစ်မျိုးစလုံးတွင် အသုံးပြုနိုင်ပြီး စပါးပင် သက်တမ်း(၁၀-၂၅)ရက်သားအတွင်း ပက်ဖျန်းပေးရပါမည်။<br><br>\r\n\r\n၇ ။ ပေါင်းကင်း ၁၀ ဒဗလျူပီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Bispyribac sodium 100g/kg ပါဝင်ပါသည်။<br><br>\r\n\r\n▪️ ပင်လုံးပြန့်အာနိသင်ရှိပြီး မျိုးစေ့ချပြီး (သို့မဟုတ်) စပါးစိုက်ပြီး (၁၀-၂၁)ရက်၊ ပေါင်းပင်အရွက် (၂-၃)ရွက်ထွက်ချိန်တွင် ပက်ဖျန်းပေးရပါသည်။<br><br>\r\n\r\n▪️ မြက်သီး၊ ဝမ်းဘဲစာ၊ မြက်မုန်ညင်းအဝါ၊ မြက်မုန်ညင်းအစိမ်း၊ မြက်ကွမ်းသီးလေး၊ တလိုင်းခေါင်း၊ ရေလေးညှင်း၊ ကတောက်ဆတ်၊ လယ်ပဒူပေါင်းများကို ထိရောက်စွာနှိမ်နင်းနိုင်သည်။ အထူးသဖြင့် ပေါင်းသတ်ဆေးဒဏ်ခံနိုင်ရည်ရှိသော ငသယောင်(တက်ကွက်)ပေါင်းကို ထိရောက်စွာနှိမ်နင်းရန် ထုတ်လုပ်ထားပါသည်။<br><br>\r\n\r\n၈ ။ ပေါင်းရှင်း ၃၀၀ အီးစီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Pretilachlor 300g/L , Safener : Fenclorin 100g/L ပါဝင်ပါသည်။ <br><br>\r\n\r\n▪️ စပါးစိုက်ခင်းအတွင်း ပေါင်းမပေါက်မီပက်ဖျန်းအသုံးပြုရသော (Pre – emergence selective herbicide) စပါးရွေးချယ် ပေါင်းသတ်ဆေးဖြစ်သည်။ <br><br>\r\n\r\n▪️ တိုက်ရိုက်အစေ့ချစပါးခင်းနှင့် ပြောင်းရွှေ့စိုက် စပါးခင်း နှစ်မျိုးလုံးတွင်အသုံးပြုနိုင်သည်။ စပါးအစေ့ချပြီး (သို့မဟုတ်) ပြောင်းရွှေ့စိုက်ပျိုးပြီး (၁-၄) ရက်အတွင်း (ပေါင်းမပေါက်မီ) တမန်းပြင်ရွှံ့ပျစ်ပျစ်အနေအထားတွင် တမန်းပြင်ကိုပက်ဖျန်းပါ။ တိုက်ရိုက်အစေ့ချပါက စပါးမျိုးစေ့ကို စာပါးစပ်ပြူသည်အထိ အညှောင့်ဖောက်ပြီးမှ မျိုးစေ့ချပါ။ <br><br>\r\n\r\n၉ ။ ကွင်ဖျူရန် ၄၀ ဒဗလျူပီ<br><br> \r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Bensulfuron Methyl 6 % + Quinclorac 34 % ပါဝင်ပါသည်။ <br><br>\r\n\r\n▪️ စပါးမျိုးကြဲပြီး (သို့မဟုတ်) ရွှေ့ပြောင်းစိုက်ပြီး (၁၅-၃၀)ရက် ပေါင်းပင်အရွက် (၃-၄)ရွက် ထွက်ချိန်တွင် ဆေးပက်ဖျန်းပါ။ <br><br>\r\n\r\n▪️ မှိုနတိုအပါအဝင် ရွက်ပြန့်ပေါင်းများ၊ မုန်ညင်းမြက်အမျိုးမျိုး နှင့် မြက်သီးအပါအဝင် မြက်အမျိုးမျိုးကို နှိမ်နင်းနိုင်ပါသည်။ <br><br>\r\n\r\n၁၀ ။ ရွှေတိုးပေါင်းရှင်း (စပါးပေါင်းသတ်ဆေး) <br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Pyrazosulfuron-ethyl 00.04% w/w ပါဝင်ပါသည်။<br><br> \r\n\r\n▪️ စပါးတိုက်ရိုက်မျိုးစေ့ချပြီး (၇-၁၅)ရက်အတွင်း ပျိုးထောင်စိုက်စပါးခင်းတွင် ပြောင်းရွှေ့စိုက်ပြီး (၇-၁၅) ရက်အတွင်း အသုံးပြုနိုင်ပါသည်။ <br><br>\r\n\r\n▪️ စပါးခင်းအတွင်း တိုက်ရိုက်ကြဲပက်အသုံးပြုနိုင်ပြီး မြက်မုန်ညင်းအဝါ၊ မြက်မုန်ညင်းအစိမ်း၊ မြက်ကွမ်းသီးလေးစသည့် မြက်မုန်ညင်းအုပ်စုများ နှင့် လယ်ပဒူ၊ ပုဇွန်စာ၊ ကတောက်ဆတ်၊ ပေါင်းလေးညှင်း၊ မှိုနတို စသည့် ရွက်ပြန့်ပေါင်းအုပ်စုများကို နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၁ ။ အောက်စီ-စတား ၂၃.၅ အီးစီ <br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Oxyfluorfen 23.5 % ပါဝင်ပါသည်။ <br><br>\r\n\r\n▪️ တောင်ယာစပါးခင်းရွေးချယ်ပေါင်းသတ်ဆေးဖြစ်၍ ယာစပါးမျိုးစေ့ချပြီး (၁-၂)ရက်အတွင်း ပက်ဖျန်းပေးရပါမည်။ <br><br>\r\n\r\n▪️ ဆင်ငိုမြက်၊ မြက်ပန်း၊ လက်သဲခွမြက်၊ ကျွဲကြောင်မင်စေး၊ ကရင်မပန်းဖူး၊ ဘောက်ခွေး၊ ကြက်မောက်ရိုင်း၊ မြက်မုန်ညင်းစိမ်း၊ မြက်မုန်ညင်းဝါ နှင့် မုန်ညင်းပေါင်းအမျိုးမျိုးကို နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၂ ။ ပေါင်းမင်း ၂၅ အီးစီ <br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Oxadiazon 25% ပါဝင်ပါသည်။ <br><br>\r\n\r\n▪️ ပင်လုံးပြန့်အာနိသင်ရှိ တောင်ယာစပါးရွေးချယ်ပေါင်းသတ်ဆေးဖြစ်သည်။ စပါးတိုက်ရိုက်စိုက် နှင့် တောင်ယာစပါးမျိုးစေ့ချပြီး (၁-၅)ရက်အတွင်း အသုံးပြုနိုင်သည်။ <br><br>\r\n\r\n▪️ မြက်အုပ်စု၊ မုန်ညင်းအုပ်စု နှင့် ရွက်ပြန့်ပေါင်းအုပ်စုများကို နှိမ်နင်းနိုင်သည်။ <br><br>\r\n\r\n', '', '19-02-2024'),
(35, 'ပဲပင် နှင့် ပင်စည်ထိုးယင်”', 'IMG-65d367ca9cef74.71073134.jpg', '🌱🪰🌱🪰🌱🪰🌱🪰🌱🪰🌱<br><br>\r\n\r\n▶️ဆောင်းရာသီ ပဲမျိုးစုံသီးနှံများစိုက်ပျိုးချိန်တွင် နေ့နှင့်ညအပူချိန်ဖြစ်ပေါ်ပြောင်းလဲမှုသည် မြန်ဆန်သည်။ နေ့ပူ၍ညချမ်းသည်။ နံနက်စောစောပိုင်းအချိန်၌ နှင်းကျပြီး နေ့လည်တွင်နေပူရှိန်သည် နွေကာလကဲ့သို့ ပူပြင်းသည်။ ဤသို့သောရာသီဥတုဖြစ်ပေါ်ပြောင်းလဲမှုသည် သီးနှံပင်များတွင် ဖျက်ပိုးနှင့် ရောဂါကို ပို၍ ဂရုပြုရသည်။<br><br>\r\n\r\n▶️၎င်းဖျက်ပိုးများအနက် \"ပဲပင်စည်ထိုးယင်\" သည် စိုက်ပျိုးမှုများသော မတ်ပဲ၊ ပဲတီစိမ်း နှင့် ပဲပုပ်တို့တွင် ပိုမိုကျရောက်တတ်သည်။ ပဲပင်စည်ထိုးယင်သည် ပဲပင်ငယ်စဉ်ကာလ အစေ့မှအပင်ပေါက်ပြီးအရွက် စတင်ထွက်ချိန်မှ အပင်တစ်လသားအတွင်းကျရောက်နိုင်သည်။<br><br>\r\n\r\n▶️အပင်ဖျက်ယင်များတွင် ယင်ဖြူဖျက်ပိုး၊ ပင်စည်ထိုးယင်၊ သီးထိုးယင်တို့သည် ဥအုနိုင်သည့်အတံဖြင့် အရွက် ပင်စည် အသီးတို့ထဲသို့ အုသည်။ အရွက်ပေါ်တွင်ယင်မကအုလျှင် ဥမှပေါက်လာသောယင်ကောင် ဖြစ်မည့် ပိုးလောက်ကောင်သည် အရွက်၏အတွင်းသားကိုထိုးဖောက်၍ လှိုဏ်ခေါင်းသဖွယ်ထွင်းဖောက် စားတော့သည်။ ထိုအခါအရွက်၏အရောင်သည် ဝါလာပြီးခြောက်သွားသည်။ ပဲစိုက်ခင်းများ၌ ပိုးမကျသောစိုက်ခင်းတွင် တစ်ခင်းလုံးစိမ်းစိုနေသော်လည်း ပင်စည်ထိုးယင်ကျရောက်လျှင် ဟိုတစ်ကွက် ဒီတစ်ကွက် အဝါကွက်များဖြစ်နေသည်ကို မြင်ကြရသည်။<br><br>\r\n\r\n▶️ပဲပင်ငယ်စဉ်ဖျက်ပိုးကျပါက အပင်မှာနုနယ်သေးငယ်ချိန် ဒဏ်မခံနိုင်၍သေကြရသည်။ ပင်စည်ထိုးယင်သည် ဦးစွာအပင်ကိုအရွက်၌ စတင်တိုက်ခိုက် သည်။ ပိုးကောင်သည် အရွက်မှရွက်ညှာသို့ရောက်သွား သည်။ ရွက်ညှာမှတစ်ဆင့် မြေကြီးနှင့်ကပ်နေသောပင်စည်ကိုရောက်ရှိသွားပြန်သည်။ ပင်စည်သို့ ရောက်သည်နှင့်ပင်စည်အက်ကွဲလာသည်။ အက်ကွဲကြောင်းထဲ၌ ပိုးလောက်ကောင်၊ ပိုးရုပ်ဖုံးများ ရှိနေကြသည်။ ပိုးလောက်ကောင်ဘဝမှ ပိုးရုပ်ဖုံးဘဝပြောင်းလဲပြီး ထပ်မံ၍ယင်ကောင်ဘဝ ပြောင်းလဲကာ (နှစ်မီလီမီတာခန့်ရှိ) အရွယ်သေးငယ်သော အရောင်မည်းမည်းခန္ဓာကိုယ်နှင့် အတောင်ပံ ပါရှိသည့် ယင်သည် အမဖြစ်လျှင် ဥများကိုရာနှင့်ချီ၍ ဥအုပြန်သည်။ ဥဘဝ နှစ်ရက်မှ သုံးရက်ကြာသည်။ ပိုးလောက်ကောင်ဘဝ တစ်ပတ်ကြာသည်။ ရုပ်ဖုံးဘဝ တစ်ပတ်ကြာသည်။ အကောင်ကြီးဘဝ နှစ်ပတ် ကြာသည်။ အချိန်တစ်လခန့်နှင့် တစ်ကောင်မှရာနှင့်ချီ၍ ပေါက်ဖွားများပြားသည်။ နှစ်စဉ် ပင်စည်ထိုး ယင်ကျခံပါက အသစ်စိုက်ပျိုးသောပဲခင်းတွင်ထပ်မံကျရောက်နိုင်သည်။ ပဲပင်ကြီးလာလျှင် ပင်စည် တုတ်ခိုင်မာကြောလာသဖြင့် ရိုးတံများတွင်ကျသည်။<br><br>\r\n\r\n▶️အကောင်းဆုံးကာကွယ်မှုမှာ .....<br><br>\r\n\r\n ☑️ပိုးကျသောအပင်ကိုစိုက်ခင်းမှ နုတ်ဖယ်ရှင်းပစ်ပါ။ <br><br>\r\n\r\n ☑️မြေပြုပြင်စဉ်တွင် ပိုးသတ်ဆေးသုံးပါ။ <br><br>\r\n\r\n ☑️အစေ့မှအရွက်နုထွက်ချိန်ပင်လုံးပြန့်ပိုးသတ်ဆေးတစ်မျိုးမျိုးပက်ဖျန်းပါ။ <br><br>\r\n\r\n ☑️ပဲမစိုက်ခင် ရှေ့တွင်စိုက်ပျိုးထားသော သီးနှံပင်၏ပင်ကြွင်းပင်ကျန်များကို ရှင်းဖယ်ထုတ်ပစ်ပါ။ <br><br>\r\n\r\n ☑️မြေကြီးကို ထယ်ထိုး၊ ထွန်မွှေကောင်းကောင်းပြုပြင်ပေးပါ။ <br><br>\r\n\r\n ☑️ပဲပင်ကောင်းစွာရှင်သန်ကြီးထွားရေးအတွက် ထည့်သွင်းရမည့်ဓာတ်မြေဩဇာများကို အချိုးကိုက်ထည့်သွင်းပါ။ <br><br>\r\n\r\n ☑️ပဲစိုက်ခင်းကို မကြာမကြာသွားရောက်စစ်ဆေးကြည့်ရှုပြီး ပိုးတွေ့လျှင်လက်ဦးအောင်ကာကွယ်နှိမ်နင်းပါ။ <br><br>\r\n\r\n▶️ပဲစိုက်ပျိုးမှုသည် တစ်ကွင်းတစ်စပ်စိုက်ခင်းကြီးမှာ တစ်ဦးနှင့်တစ်ဦး တစ်ခင်းနှင့်တစ်ခင်း ပြင်ကျယ်ခွင်ကျယ်ဆက်စပ်တည်ရှိနေကြသဖြင့် စုပေါင်း၍ကာကွယ်နှိမ်နင်းကြရပါမည်။ ကူးစက်ပျံ့နှံ့မှုမရှိခင် ပဲပင်တစ်လသားကာလအတွင်း၌ ပဲပင်စည်ထိုးယင်ကို ဂရုပြုကာကွယ်နှိမ်နင်းသွားကြရပါမည်။<br><br>\r\n\r\nSources : စိုက်ပျိုးရေးရာ အကြံပြုချက်များ', '', '19-02-2024'),
(36, '“သီးနှံစိုက်ပျိုးသူများ ယင်ဖြူသတိထား”', 'IMG-65d368a4ea69c6.37551838.jpg', '🌱🐛🌱🐛🌱🐛🌱🐛🌱🐛🌱<br><br>\r\n\r\n✅ဆောင်းရာသီပဲမျိုးစုံ စိုက်ပျိုးထုတ်လုပ်မှုသည် အင်နှင့်အားနှင့်ရှိသည်။ မြန်မာနိုင်ငံ၏ ဆီထွက်သီးနှံ နှင့် ပဲမျိုးစုံစိုက်ပျိုးမှုသည် မိုးရွာမှုအခြေပြုစိုက်ပျိုးကြရသဖြင့် မိုးရွာမှရေရရှိပြီးစိုက်ပျိုးရသောအညာဒေသ တွင် မိုးစိုက်ပဲနှင့် မိုးရာသီမှရရှိသောမြေကြီးအစိုဓာတ်ကိုမှီ၍ ဆောင်းရာသီစိုက်ကြသောဆောင်းပဲတို့ ရှိကြသည်။ မိုးများသောမြန်မာနိုင်ငံအောက်ပိုင်းဒေသများသည် မိုးကုန်မှပဲစိုက်ကြရသည်။ မိုးစပါး ရိတ်သိမ်းပြီး မြေမခြောက်ခင် ပဲမျိုးစေ့မြေချစိုက်နိုင်မှ အပင်ပေါက်ကောင်းသည်။ ရာသီမှီသည်။ အများဆုံးစိုက်ကြသည့် ဆောင်းပဲမှာ ဈေးကွက်ရှိသော ပဲတီစိမ်း နှင့် မတ်ပဲဖြစ်သည်။<br><br>\r\n\r\n✅ပဲစိုက်ခင်းများတွင် အပင်ဖြစ်ချိန်ကျသောဖျက်ပိုးနှင့် အသီးတောင့် အစေ့အဆံဖြစ်ချိန်ကျရောက်သော ဖျက်ပိုးတို့များစွာရှိသည်။ ဤသို့သောပိုးများစွာထဲမှ အပင်ဖြစ်ချိန်တွင် “ယင်ဖြူ နှင့် ပဲပင်စည်ထိုးယင်” ကို အထူးသတိထားရမည်။ ယင်ဖြူသည် ပူပြင်းခြောက်သွေ့သောအချိန်တွင် ပို၍တွေ့ရသောဖျက်ပိုး ဖြစ်သည်။ ဆောင်းရာသီဟုဆိုသော်လည်း နေ့ခင်းနေ့လည်နေပူရှိန်သည်ပူပြင်းပါသည်။ ယင်ဖြူသည် ဟင်းသီးဟင်းရွက်စိုက်ခင်းများတွင် အဓိကကျရောက်သော ဖျက်ပိုးအမျိုးအစားမဟုတ်သော်လည်း ဟင်းသီးဟင်းရွက်စိုက်ခင်းမှန်သမျှတွင် ကျယ်ကျယ်ပြန့်ပြန့် ကျရောက်တတ်သည်။ ဆောင်းရာသီတွင် ဒေသအနှံ့ နေရာအနှံ့ ဟင်းသီးဟင်းရွက်စိုက်ပျိုးကြသည်ကများပြားပါသည်။<br><br>\r\n\r\n✅ယင်မသည် အကြေးဖြူများရှိနေသည်။ အပင်ကိုလှုပ်ခါကြည့်ပါက အဖြူရောင်ယင်ဖြူများပျံထွက်လာ တတ်သည်။ အစာကိုစုပ်စားသည်။ ယင်ဖြူသည် အစာကိုစုပ်စားဖျက်ဆီးပြီး ခန္ဓာကိုယ်ထဲရှိ သယ်ဆောင် နိုင်သော ဗိုင်းရပ်စ်ရောဂါကို အပင်သို့ရောက်ရှိစေပြီး ရောဂါထပ်မံကျစေသည်။ ဥဘဝ ခုနှစ်ရက်၊ အကောင်ဘဝ (၂၈)ရက်နှင့် အကောင်ကြီးဖြစ်ရသဖြင့် (၃၅)ရက်ခန့်ဖြင့် ဘဝတစ်ခုပြန်လည်စတင် ဖြစ်ပွားသည်။ <br><br>\r\n\r\n✅ယင်ဖြူ ကို ခရမ်း၊ ရုံးပတီပင်များ၊ ချည်မျှင်ရှည်ဝါစိုက်ခင်းများနှင့် ပဲတီစိမ်း၊ ပဲစဉ်းငုံစိုက်ခင်းများတွင် အများဆုံး တွေ့ရသည်။ ယင်ဖြူပွားများမှုသည် မိုးနှောင်းရာသီ၊ ဆောင်းရာသီများ၌ များပြားသည်။ ပဲတီစိမ်းတွင် ပန်းပွင့်ပြီးနောက်ပိုင်း၌ တွေ့ရှိရမှုပိုများသည်။<br><br>\r\n\r\n✅ယင်ဖြူကို စိုက်ခင်းထဲ၌ အပင်လှုပ်ခါကြည့်မှု အရွက်၏အောက်ဘက်မျက်နှာပြင်ကို လှန်ပြီးကြည့်မှုဖြင့် တွေ့နိုင်သည်။ ငြိမ်သက်နေထိုင်တတ်သော ဖျက်ပိုးအမျိုးအစားဖြစ်သည်။ ဥကိုလည်းအရွက်၏ အောက်ဘက်တွင်လုပ်သည်။ ထို့ကြောင့် ဥနှင့် ပိုးကောင်ကိုမြင်တွေ့မှုနည်းပါးသည်။ အရွက်လှန်ကြည့်မှ မြင်ရသည်။ အမပိုးကောင်သည် သက်တမ်းတစ်လျှောက် တစ်လခန့်အသက်ရှင်ချိန်တွင် ဥပေါင်း ၁၀၀ကျော် အုနိုင်သည်။ ဥအုနိုင်သောအကောင်ကြီးသည် တစ်ပတ်ခန့်ကြာကြာ အသက်ရှင်နေနိုင်သည်။ <br><br>\r\n\r\n✅ကာကွယ်မှုအနေဖြင့် မီးခိုးမှိုင်းတိုက်ပေးခြင်းဖြင့် ယင်ဖြူများပျံပြေးကြသည်။ တမာပိုးသတ်ဆေးဖြင့် ဦးစွာနှိမ်နင်းပက်ဖျန်းပါ။ ဖျက်ပိုးအရေအတွက်များပြားပါက ဝိစာရ၏ “ကေလာ၊ နိုးဝမ်း” ဆေးများဖြင့် ပက်ဖျန်းနှိမ်နင်းပေးရပါမည်။<br><br>\r\n\r\n✅“ယင်ဖြူ”ကို ရာသီဥတုဖြစ်ပေါ်ပြောင်းလဲမှုမြန်ဆန်သော ဥတုရာသီဖောက်ပြန်သည့် အချိန်ကာလ မျိုးတွင် ပိုမိုဂရုပြုရသည်။ “ယင်ဖြူ” သည် နေ့ပူ၍ ညဘက်အေးချမ်းသော ဆောင်းရာသီကာလမျိုးနှင့် နေ့နှင့်ညအပူချိန် ပြောင်းလဲမှုကွာခြားသောဒေသမျိုးများတွင် ပိုမို၍ဂရုပြုသင့်သော ဖျက်ပိုးအမျိုးအစား ဖြစ်ပါသည်။ <br><br>\r\n\r\nSources : စိုက်ပျိုးရေးရာအကြံပြုချက်များ', '', '19-02-2024');
INSERT INTO `knowledge` (`kid`, `knowledgeTitle`, `knowledgePhoto`, `knowledgeDescript`, `knowledgeColor`, `CurrentDate`) VALUES
(37, 'ဖျက်ပိုးအမျိုးမျိုးကို အမြစ်ပြတ်ချေမှုန်းဖို့ “ဝိစာရ”ဆေးတွေ သုံးကြစို့', 'IMG-65d36a5bc100f3.50134509.jpg', '🦗🌾🐜🌾🐛🌿🦟🌾🕷🌾🐌<br><br>\r\n\r\n⏩သီးနှံဖျက်ပိုးအမျိုးမျိုးရှိကြသည်။ ၎င်းဖျက်ပိုးတို့သည် သီးနှံပင်ကိုစားသောက်ဖျက်စီးသည့်ပုံစံ နှင့် သဘာဝ မတူကြပါ။ အချို့က သစ်ရည်ကိုစုပ်ယူစားသောက်ကြသည်။ အချို့က သီးနှံပင်၏ အရွက် အကိုင်းအခက် အဖူးအပွင့် စသည့်အစိတ်အပိုင်းများကို ကိုက်ဖြတ်စားကြသည်။ အချို့အရွက်ကို လိပ်၍လည်းကောင်း အရွက်ကိုထွင်းဖောက်၍လည်းကောင်း၊ အပင်အစိတ်အပိုင်းများအတွင်းသို့ ဝင်ရောက်၍လည်းကောင်း၊ မြေကြီးအတွင်းခိုအောင်းနေထိုင်၍ လည်းကောင်း သီးနှံပင်ကို အမျိုးမျိုး စားသောက်ဖျက်ဆီးကြသည်။ ထိုသို့ မတူညီသည့် နေထိုင်စားသောက် ဖျက်ဆီးမှုများကို မူတည်၍ ၎င်းဖျက်ပိုးများကို ကာကွယ်နှိမ်နင်းရာတွင် အသုံးပြုရသည့် ပိုးသတ်ဆေးများလည်း အမျိုးအစား ကွဲပြားကြပါသည်။ သို့ဖြစ်ပါ၍ မိမိတို့၏သီးနှံစိုက်ခင်းများတွင် ကျရောက်သည့်ဖျက်ပိုးများအလိုက် ရွေးချယ်အသုံးပြုရမည့် \"ဝိစာရ၏ အစွမ်းထက်ပိုးသတ်ဆေးများ” ကို စုစည်းတင်ပြလိုက်ပါသည်။ <br><br>\r\n\r\n၁ ။ ဘီတာ စီ ၁၀၀ အီးစီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Beta-Cypermethrin 100 g/L 10% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ အာနိသင်ပြင်းထန် သော အထိရောက်ဆုံးပိုးသတ်ဆေးဖြစ်သည်။ ပိုးလောက်ကောင်များကို ဆေးထိပြီးပြုတ်ကျသေစေနိုင်သည်။<br><br>\r\n\r\n ▪️ နှိမ်နင်းနိုင်သောဖျက်ပိုးများမှာ ဂေါ်ဖီလိပ်ပြာဖြူ၊ စိန်ကွက်ဖလံ၊ ခရမ်းချဉ် ဖရဲ သခွား အပါအဝင် သီးနှံ အမျိုးမျိုးတွင်ကျရောက်တတ်သော ရွက်ထွင်းပိုးများ၊ ဝါသီးလုံးဖောက်ပိုးအမျိုးမျိုး၊ ဖောငမြှောင်တောင် အပါအဝင် ကိုက်ဖြတ်ဝါးစားပိုးအမျိုးမျိုး တို့ဖြစ်သည်။ ၎င်းအပြင် “ဘီတာ စီ” ကို မွှားပင့်ကူသတ်ဆေး အဖြစ်လည်းအသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\n၂ ။ ဆိုက်ပါမက်(စ်) ၁၀ အီးစီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Cypermethrin 10% ပါဝင်ပါသည်။ ပြင်းထန်သော ထိသေ၊ စားသေ အာနိသင် ပါရှိပါသည်။<br><br>\r\n\r\n ▪️ လိပ်ပြာဖလံအုပ်စု၊ ကျိုင်းအုပ်စုများနှင့် ငမြှောင်တောင်အပါအဝင် ကိုက်ဖြတ်ဝါးစားပိုးမျိုးစုံအား ဆေးထိလျှင်ချက်ချင်းပြုတ်ကျသေစေနိုင်သည်။ “ဆိုက်ပါမက်(စ်)” ဆေးကို ပိုးလောက်ကောင် စတွေ့လျှင်စတွေ့ချင်း ပက်ဖျန်းရန်သင့်တော်ပါသည်။<br><br>\r\n\r\n၃ ။ အီမာလန်ဒါ ၁၅ ဒဗလျူပီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Emamectin benzoate 5% + Lambda-cyhalothrin 10% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ နှင့် ထိုးဖောက်စိမ့်ဝင်အာနိသင် ပါရှိပါသည်။ ထို့ပြင် Lambda-cyhalothrinသည် ဖျက်ပိုးများကို ချက်ချင်းပြုတ်ကျသေစေနိုင်သော အာနိသင်ရှိသည်။<br><br>\r\n\r\n ▪️ ငမြှောင်တောင်၊ သီးလုံးဖောက်ပိုး၊ ရွက်ဖောက်ကျိုင်း၊ စိန်ကွက်ဖလံ၊ ရွက်ထွင်းပိုး၊ ပျ၊ ဖြုတ်၊ ယင်ဖြူ၊ လှေးပိုး နှင့် မွှားပင့်ကူနီတို့ကို ဆေးနှုန်းထားအနည်းငယ်မျှဖြင့် ကာကွယ်နှိမ်နင်းနိုင်သည်။ <br><br>\r\n\r\n၄ ။ ကေလာ ၂၅ ဒဗလျူဒီဂျီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Thiamethoxam 25% W/W ပါဝင်ပါသည်။ ထိသေ၊ စားသေ နှင့် ပင်လုံးပြန့်အာနိသင် ရှိသည်။<br><br>\r\n\r\n ▪️ စပါးတွင်ကျသော ဖြုတ်အမျိုးမျိုး နှင့် ကြက်သွန်မြိတ်ပိုး၊ သီးနှံအမျိုးမျိုးတွင်ကျသော ယင်ဖြူ နှင့် စုပ်စားပိုးအမျိုးမျိုး၊ သရစ်လှေးပိုး၊ ပိုးစေးနှဲ၊ ကျောက်ပိုး၊ ရွက်ဖောက်ကျိုင်း၊ ရွက်ထွင်းပိုး နှင့် သစ်သီးထိုးယင်များကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်သည်။ ဆေးနှုန်းထားအနည်းငယ်မျှအသုံးပြုရပါသည်။<br><br>\r\n\r\n၅ ။ နိုက်ဝမ်း ၂၀ အက်စ်စီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Indoxacarb 17% + Lambda cyhalothrin 3% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ နှင့် Bioactivation (ပိုးကောင်၏ခန္ဓာကိုယ်အတွင်းရှိ အင်ဇိုင်းများက ဆေးအာနိသင်ကိုတိုးမြှင့်လာစေခြင်း) ဖြစ်ပေါ်စေသော ထူးခြားအာနိသင်ပါရှိသည်။<br><br>\r\n\r\n ▪️ ငမြှောင်တောင်အပါအဝင် ကိုက်ဖြတ်ဝါးစားပိုးအမျိုးမျိုး၏ ပိုးဥ နှင့် ပိုးလောက်ကောင်များ နှင့် မုန်ညင်းမုန်လာ၊ ဂေါ်ဖီစိန်ကွက်ဖလံလောက်ကောင်များကို ဆေးနှုန်းထားအနည်းငယ်မျှဖြင့်ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်သည်။<br><br>\r\n\r\n၆ ။ လန်ဒါ ၅ အီးစီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Lambda-cyhalothrin 5% ပါဝင်ပါသည်။ ပြင်းထန်သော ထိသေ၊ စားသေ အာနိသင်ရှိသည်။ အင်းဆက်ဖျက်ပိုး၏အရေခွံကို လျင်မြန်စွာထိုးဖောက်စိမ့်ဝင်ပြီး ဖလံမကြီး၊ ဥ နှင့် လောက်ကောင်အဆင့်အားလုံးကို သတ်ဖြတ်နှိမ်နင်းနိုင်သည်။ <br><br>\r\n\r\n ▪️ လိပ်ပြာအုပ်စု၊ ယင်အုပ်စု၊ စုပ်စားပိုးအုပ်စု၊ သရစ်လှေးပိုးအုပ်စု၊ ဂျပိုးအုပ်စု၊ ကျိုင်းအုပ်စု နှင့် မွှားပင့်ကူနီအုပ်စုများအားလုံးကို ကာကွယ်နှိမ်နင်းနိုင်သည်။<br><br>\r\n\r\n၇ ။ လိုင်းအောက် ၄၈၀ အက်စ်စီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Flubendiamide 240 g/L , Thiacloprid 240 g/L ပါဝင်ပါသည်။ စားသေ နှင့် ပင်လုံးပြန့်အာနိသင်ရှိသည်။ သီးနှံပင်ပေါ်တွင် ဆေးအာနိသင်တာရှည်ခံနိုင်သည်။<br><br>\r\n\r\n ▪️ ပဲအမျိုးမျိုးတွင်ကျရောက်သော ဖူးထွေးပွင့်ထွေးပိုး၊ သီးတောင့်ထိုးပိုး၊ စပါးဆစ်ပိုး၊ စပါးရွက်လိပ်ပိုး၊ သီးနှံအမျိုးမျိုးတွင်ကျရောက်သော ဖောငမြှောင်တောင်၊ စိန်ကွက်ဖလံ၊ သီးလုံးဖောက်ပိုး၊ ပျ၊ ဖြုတ်၊ သရစ်လှေးပိုး နှင့် အခြားဖျက်ပိုးမျိုးစုံကို “လိုင်းအောက်” ဆေး တစ်မျိုးတည်းဖြင့် ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။ ထို့ပြင် “လိုင်းအောက်”ဆေးကို သီးနှံပင်များပန်းပွင့်ချိန်တွင်လည်း ပက်ဖျန်းအသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\n၈ ။ မိုက်အိုကေ ၁၀၀ အီးစီ<br><br>\r\n\r\n▪️ အစွမ်းရှိပစ္စည်း Hexythiazox 80 g/L , Chlorfenapyr 20 g/L ပါဝင်ပါသည်။ ထိသေ၊ စားသေ နှင့် ထိုးဖောက်စိမ့်ဝင် အာနိသင်ရှိပြီး ပိုးလောက်ကောင် နှင့် ပိုးဥများကိုပါ သတ်နိုင်သောအစွမ်းအာနိသင် ရှိသည်။<br><br>\r\n\r\n ▪️ မွှား နှင့် မွှားပင့်ကူအမျိုးမျိုး အပါအဝင် ဖျက်ပိုးမျိုးစုံကို နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၉ ။ မင်းရဲ ၂၅ အီးစီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Proefnofos 20% + Beta-cypermethrin 5% ပါဝင်ပါသည်။ ပြင်းထန်သော ထိသေ နှင့် စားသေ အာနိသင်ရှိပြီး သီးနှံပင်ပျားပေါ်တွင် ဆေးအာနိသင်တာရှည်ခံနိုင်ပါသည်။<br><br>\r\n\r\n ▪️ စိန်ကွက်ဖလံ၊ ဖောငမြှောင်တောင်၊ ဝါသီးလုံးဖောက်ပိုး၊ ပျ၊ ဖြုတ်၊ ယင်ဖြူ၊ မွှားပင့်ကူနီ နှင့် အခြားဖျက်ပိုး အမျိုးမျိုးကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၀ ။ နိုးဝမ်း ၇၀၀ ဒဗလျူပီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Dinotefuran 20% + Pymetrozine 50% ပါဝင်ပါသည်။ ထိသေ စားသေ နှင့် ပင်လုံးပြန့်အာနိသင် ရှိပါသည်။ ဆေးအာနိသင်မှာ (၃-၄)ပတ်အထိ တာရှည်ခံသည်။<br><br>\r\n\r\n ▪️ Pymetrozine သည် နောက်ဆုံးပေါ် ဖြုတ်ညို၊ ဖြုတ်စိမ်း အထူးသတ်ဆေးဖြစ်ပြီး “နိုးဝမ်း”ဖြင့် ဖရဲ၊ သခွား၊ အာလူး၊ ခရမ်းချဉ်များတွင် ကျရောက်သော ယင်ဖြူ နှင့် ပဲမျိုးစုံတွင် ကျရောက်တတ်သော ပျပိုး၊ လှေးပိုး နှင့် စုပ်စားပိုးအမျိုးမျိုးကိုလည်း ထိရောက်စွာ နှိမ်နင်းပေးနိုင်ပါသည်။<br><br>\r\n\r\n၁၁ ။ ပရိုဆင့် ၅၀ အက်စ်စီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Fipronil 5% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ အာနိသင်ရှိပြီး ပင်လုံးပြန့်အာနိသင် အနည်းငယ်ရှိသည်။<br><br> \r\n\r\n ▪️ မြေအောင်းပိုးများဖြစ်သော မြစ်စားပိုး၊ ဝါယာဝမ်း နှင့် ခြတို့ကို ကာကွယ်နှိမ်နင်းရန် မျိုးစေ့ဖြင့်လူးနယ် စိုက်ပျိုးခြင်း၊ စိုက်ခင်းမြေပြင်ကို ပက်ဖျန်းခြင်းတို့ဖြင့်အသုံးပြုရပါမည်။ အပင်ပေါ်ဖျက်ပိုးများဖြစ်သော စပါးတွင်ကျရောက်တတ်သည့် ဆစ်ပိုး၊ ဖြုတ်ညိုနှင့် ဖြုတ်အမျိုးမျိုး၊ ရွက်လိပ်အိမ်ပိုး နှင့် ပိုးလောင်မီး၊ မုန်ညင်း၊မုန်လာနှင့်ဂေါ်ဖီ စိန်ကွက်ဖလံ၊ ပဲမျိုးစုံ ရွက်ဖောက်ကျိုင်းနှင့်ပင်စည်ထိုးယင်၊ ပြောင်းသီးနှံတွင် ကျရောက်သော ဖောငမြှောင်တောင် နှင့် မြစ်စားပိုးများကိုကာကွယ်နှိမ်နင်းရန် အပင်ပေါ်သို့ပက်ဖျန်း ပေးရပါမည်။ အထူးသဖြင့်“ပရိုဆင့်”သည် စပါးနှင့် သီးနှံမျိုးစုံတွင်ကျရောက်ဖျက်စီးတတ်သော “သရစ်လှေးပိုး အမျိုးမျိုး” ကို ထိရောက်စွာ နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၂ ။ ရော့ကက် ၁.၈ အီးစီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Abamectin 1.8% ပါဝင်ပါသည်။ ထိသေ စားသေ နှင့် စိမ့်ဝင်ထိုးဖောက်အာနိသင် ရှိသည်။ အခြားပိုသတ်ဆေးအုပ်စုများနှင့် ရောစပ်သုံးစွဲခြင်းဖြင့် ဆတိုးစွမ်းအင်ဖြစ်လာစေသော အာနိသင်ရှိသည်။<br><br>\r\n\r\n ▪️ သီးနှံမျိုးစုံတွင် ဆိုးရွားစွာကျရောက်သော မွှားပင့်ကူနီ၊ စိန်ကွက်ဖလံ၊ လှေးပိုး၊ ယင်ဖြူ၊ ပိုးစေးနှဲ၊ အကြေးပိုး၊ ရွက်ထွေးပိုး၊ ငမြှောင်တောင်၊ ပိုးစိမ်းကောင်၊ ရွက်လိပ်၊ ရွက်ကပ် နှင့် ရှောက်လိမ္မော် ရွက်ထွင်းပိုးများကို ထိရောက်စွာနှိမ်နင်းနိုင်သည်။<br><br>\r\n\r\n၁၃ ။ ဆိုင်လာ ၂၅ ဒဗလျူပီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Acetamiprid 20% + Lambda-cyhalothrin 5% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ နှင့် ပင်လုံးပြန့်အာနိသင်ရှိသည်။ <br><br>\r\n\r\n ▪️ ငမြှောင်တောင်၊ သီးလုံးဖောက်ပိုးများအပါအဝင် ကိုက်ဖြတ်ဝါးစားပိုးအမျိုးမျိုး၊ သရစ်လှေးပိုး၊ ပျ၊ ယင်ဖြူ နှင့် စုပ်စားပိုးအမျိုးမျိုး၊ ပိုးစေးနှဲ၊ စိန်ကွက်ဖလံ၊ ရွက်ထွင်းပိုး၊ သစ်သီးထိုးယင် နှင့် ဖျက်ပိုးအမျိုးမျိုးကို ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၄ ။ အက်စ်ဖိတ် ၇၅ အက်စ်ပီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Acephate 75% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ နှင့် ပင်လုံးပြန့်အာနိသင်ပြင်းထန်သော ရေဖျော်ပိုးသတ်ဆေးအမှုန့်ဖြစ်သည်။ သီးနှံအမျိုးမျိုးကို ပန်းပွင့်ချိန်ကာလတွင် ပက်ဖျန်းရန်အထူးသင့်လျော်ပါသည်။<br><br>\r\n\r\n ▪️ သီးနှံမျိုးစုံတွင်ကျရောက်သော ငမြှောင်တောင်၊ ရွက်စားပိုး၊ သီးလုံးဖောက်ပိုး၊ ပွင့်ထွေးရွက်ထွေးပိုး၊ သီးထိုးယင် နှင့် စုပ်စားပိုးမျိုးစုံကို နှိမ်နင်းနိုင်သည်။<br><br>\r\n\r\n၁၅ ။ စပေါ့ ၈၀၀ ဒဗလျူဂျီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Thiodicarb 80% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ အာနိသင်ပါရှိပါသည်။ ဖျက်ပိုးအမျိုးမျိုး၏ ဥအဆင့် နှင့် ပိုးလောက်ကောင်အဆင့် အားလုံးကို ထိရောက်စွာနှိမ်နင်းနိုင်သည်။ <br><br>\r\n\r\n ▪️ သီးနှံစိုက်ခင်းများတွင်ဆိုးရွားစွာ ကျရောက်ဖျက်ဆီးသော (Fall armyworm , Beet armyworm) အပါအဝင် ငမြှောင်တောင်အမျိုးမျိုး၊ သီးနှံမျိုးစုံတွင်ကျရောက် ဖျက်ဆီးသော ပင်ဖြတ်ပိုး(Cutworm) များကို နှိမ်နင်းနိုင်သည်။<br><br>\r\n\r\n၁၆ ။ သူရိယ ၈၀ အက်စ်ပီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Acephate 50% + Monosultap 30% ပါဝင်ပါသည်။ ထိသေ၊ စားသေ နှင့် ပင်လုံးပြန့် အာနိသင်ရှိသည့်အပြင် Monosultap တွင် အဆိပ်ငွေ့အာနိသင်ရှိပြီး ပိုးဥများကိုလည်းသေစေသည်။ ဆေးလောင်ကျွမ်းမှုမရှိပဲ သီးနှံမျိုးစုံတွင်အသုံးပြုနိုင်သည်။<br><br>\r\n\r\n▪️ သီးနှံပင်အစိတ်အပိုင်းများအတွင်း ဝင်ရောက်ဖျက်ဆီးသော ကိုက်ဖြတ်ဝါးစားပိုးများနှင့် စုပ်စားပိုးများကို နှိမ်နင်းနိုင်သည်။ အထူးသဖြင့် ပဲမျိုးစုံတွင်ကျရောက်သော ငမြှောင်တောင်၊ ဖူးထွေးပွင့်ထွေးပိုး၊ သီးတောင့်ထိုးပိုး၊ ဝါသီးလုံးဖောက်ပိုးအမျိုးမျိုး၊ ပျ၊ ဖြုတ်စိမ်း၊ ယင်ဖြူ နှင့် စပါးတွင်ကျရောက်သော ဆစ်ပိုး၊ ရွက်လိပ်ပိုး နှင့် ဖြုတ်ညို၊ ဖြုတ်စိမ်း တို့ကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၇ ။ နစ်ကို ၇၀ ဒဗလျူပီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Niclosamide 70% ပါဝင်သော ခရုသတ်ဆေးဖြစ်ပါသည်။ စားသေ နှင့် အဆိပ်ငွေ့အာနိသင်ရှိပြီး စပါးအပါအဝင် သီးနှံအမျိုးမျိုးတွင် ဆိုးရွားစွာဖျက်ဆီးတတ်သော ရွှေခရုများကိုထိရောက်စွာ နှိမ်နင်းနိုင်သည်။<br><br>\r\n\r\n၁၈ ။ ဒီပါ ၄၆ ဂျီ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Cartap 4% + Thiamethoxam 0.4% + Abamectin 0.2% ပါဝင်ပါသည်။ ဆေး(၃)မျိုး ရောစပ်ထားသည့် ပင်လုံးပြန့်အာနိသင်ရှိ ပိုးသတ်ဆေးနှင့် နီမတုတ်သတ်ဆေးခဲဖြစ်သည်။ စိုက်ခင်း မြေပေါ်သို့ လွယ်ကူစွာကြဲပက်အသုံးပြုနိုင်ပါသည်။ <br><br>\r\n\r\n ▪️ မြေတွင်းအောင်းပိုးများ၊ စုပ်စားပိုးများ၊ အပင်အစိတ်အပိုင်းများအတွင်းသို့ဝင်ရောက်ဖျက်စီးသောပိုးများ၊ နီမတုတ်ကြောင့်ဖြစ်သောရောဂါများကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်သည်။ တစ်နည်းအားဖြင့် ပင်ဖြတ်ပိုး၊ ဖိုးလမင်းကျိုင်းလောက်ကောင်၊ ကျောက်ပိုး(ဝါယာပိုး)၊ ခြ၊ ပုရစ်၊ ပျ၊ ဖြုတ်စိမ်း၊ ဖြုတ်ညို၊ ယင်ဖြူ၊ သရစ်လှေးပိုး၊ ပိုးစေးနှဲ၊ စပါးဆစ်ပိုး၊ ပင်စည်ထိုးယင်၊ ရွက်ထွင်းပိုးအမျိုးမျိုး၊ နီမတုတ်ကြောင့် ဖြစ်သော စပါးမြစ်ဖုရောဂါ၊ ရွက်ဖျားဖြူရောဂါ၊ ယူဖရာရောဂါ အစရှိသည်တို့ကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၉ ။ ဖစ်ပရို ၃ ဂျီအာ<br><br>\r\n\r\n ▪️ အစွမ်းရှိပစ္စည်း Fipronil 0.3% ပါဝင်ပါသည်။ ထိသေ စားသေ နှင့် ပင်လုံးပြန့်အာနိသင်ရှိသည်။ စိုက်ခင်းအတွင်း လွယ်ကူစွာကြဲပက်အသုံးပြုနိုင်သော မြေတွင်းအောင်းပိုးသတ်ဆေးခဲဖြစ်သည်။<br><br> \r\n\r\n ▪️ သီးနှံအမျိုးမျိုးတွင်ကျရောက်တတ်သော မြေတွင်းအောင်းပိုးများဖြစ်သည့် မြေခွေးပုရစ်၊ ပင်ဖြတ်ပိုး၊ ဖိုးလမင်းကျိုင်းလောက်ကောင်၊ မြစ်စားပိုး၊ ဝါယာပိုး၊ ခြ နှင့် စပါးဆစ်ပိုး၊ စပါးကြက်သွန်မြိတ်ပိုး၊ သရစ်လှေးပိုးအပါအဝင် စုပ်စားပိုးအမျိုးမျိုး၊ ရွက်လိပ်ရွက်ကပ်ပိုး နှင့် စပါးရွက်ဖျားဖြူ(ယူဖရာ) နီမတုတ်ပိုးများကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n', '', '19-02-2024'),
(38, 'သီးနှံပင်တွေမှာ ရောဂါတွေကျနေပါလား !!! ဝိစာရရဲ့ ဘယ်မှိုသတ်ဆေးကို ရွေးချယ်သုံးစွဲကြမှာလဲ ?', 'IMG-65d36ad403c614.88605577.jpeg', '🌿🌶🌾🥔🌿🥦🌿🧅🌾🍅🌿<br><br>\r\n\r\n✅“အနာနှင့်ဆေး တည့်အောင်ပေးက ပျောက်ရေးမခက်ပါ” ဆိုသကဲ့သို့ပင် သီးနှံပင်များတွင်ကျရောက်သော အပင်ရောဂါအမျိုးမျိုးတို့အတွက် စိုက်ပျိုးနည်းစနစ်ကောင်းများဖြင့် မည်သို့ပင် ကာကွယ်ကုသစေကာမူ မှန်ကန်သော ဓာတုဆေးများဖြင့် ကြိုတင်ကာကွယ်ခြင်း နှင့် အချိန်မှီ ကုသနှိမ်နင်းရန်မှာ အလွန်အရေးကြီးပါသည်။ ထို့ကြောင့် သီးနှံပင်များတွင်ကျရောက်သောရောဂါများ အလိုက် ရွေးချယ်သုံးစွဲရမည့် ဝိစာရ၏ မှိုနှင့် ဘက်တီးရီးယားရောဂါ ကာကွယ်ကုသဆေးများကို စုစည်းတင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n၁ ။ ဘင်ဇိုကာ ၅၅၀ အက်စ်စီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Chlorothalonil 45.0% + Hexaconazole 3.5% + Cymoxanil 6.5% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️သီးနှံပင်များတွင်ကျရောက်တတ်သော စပါးရွက်ညိုပြောက်ရောဂါ၊ အာလူး စောပင်နာကျ၊ နှောင်းပင်နာကျရောဂါ၊ ခရမ်းချဉ် စောပင်နာကျ၊ နှောင်းပင်နာကျရောဂါ၊ သခွားနှင့် ဟင်းသီးဟင်းရွက် ပင်များတွင် ကျရောက်တတ်သော ဒေါင်းနီးမှိုရောဂါ၊ မီးခိုးရောင်မှိုရောဂါ၊ ဖားဥမှို နှင့် အခြားမှိုရောဂါ အမျိုးမျိုးကို ထိရောက်လျင်မြန်စွာ ကုသပေးနိုင်ပါသည်။<br><br>\r\n\r\n၂ ။ ကာဗာ ၂၅အက်စ်စီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Azoxystrobin 25% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️ကာကွယ်ကုသနိုင်သောရောဂါများမှာ ဂန္ဓမာသံချေးဖြူရောဂါ၊ အာလူးနှောင်းပင်နာကျ၊ ခရမ်းချဉ်နှောင်းပင်နာကျ၊ ကြက်သွန်ဗျောက် နှင့် တောက်တဲ့မြီးရောဂါ၊  စပါးဂုတ်ကျိုးရောဂါနှင့် အခြားမှိုရောဂါအမျိုးမျိုးတို့ဖြစ်သည်။ “ကာဗာ”မှိုသတ်ဆေးကို သီးနှံများစိုက်ပျိုးရာတွင် မျိုးစေ့လူးနယ်ဆေးအဖြစ်လည်းအသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\n၃ ။ ကျူပရိုမက်စ် ၈၅ဒဗလျူပီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Copper oxychloride 85% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️ကာကွယ်ကုသနိုင်သောရောဂါများမှာ သီးနှံမျိုးစုံခါးရိရောဂါ၊ ပင်ရင်းပုပ်၊ နှမ်းရိုးမဲ၊ အာလူးဥပုပ်၊ အာလူးစောပင်နာကျ၊ ကွမ်းရိုးမဲဆစ်ပြုတ်၊ လိမ္မော်အနာချိုင့်၊ ကြက်သွန်အပျော့ပုပ်၊ ဂေါ်ဖီအပျော့ပုပ် နှင့် စပါး ဘက်တီးရီးယားရွက်ခြောက်ရောဂါ၊ ဘက်တီးရီးယားရွက်စင်းရောဂါ၊ စပါးမှိုသီးရောဂါ၊ စပါးဂုတ်ကျိုးရောဂါ၊ စပါးရွက်ဖုံးခြောက်ရောဂါတို့ဖြစ်သည်။<br><br>\r\n\r\n၄ ။ ဆိုင်မိုဇက် ၇၂ ဒဗလျူပီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Cymoxanil 8% + Mancozeb 64% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️ကာကွယ်ကုသနိုင်သောရောဂါများမှာ အာလူး ခရမ်းချဉ်နှောင်းပင်နာကျရောဂါ နှင့် ဖရဲ၊ ကြက်သွန်၊ စပျစ် ဒေါင်းနီးရွက်ခြောက်ရောဂါ၊ မှည့်ပြောက်စွန်းရောဂါများ ဖြစ်သည်။<br><br>\r\n\r\n၅ ။ ဒိုင်ကိုဇက် ၈၀ ဒဗလျူပီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Mancozeb 80% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️“ဒိုင်ကိုဇက်”သည် သီးနှံပင်များတွင် မှိုရောဂါအမျိုးမျိုးမကျရောက်နိုင်စေရန် အကောင်းဆုံးကြိုတင် ကာကွယ်ဆေးဖြစ်သည်။ မြေအောင်းရောဂါမှိုများကို ကြိုတင်ကာကွယ်နိုင်ရန် မစိုက်မီ မျိုးစေ့နှင့် လူးနယ်စိုက်ပျိုးနိုင်ပါသည်။<br><br>\r\n\r\n၆ ။ ဒိုင်ဇီ ၃၂.၅ အက်စ်စီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Difenoconazole 12.5% + Azoxystrobin 20% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️အစွမ်းထက်ဆေးနှစ်မျိုးပေါင်းစပ်ထားပြီး ခရမ်းချဥ်စောပင်နာကျရောဂါ၊ငရုတ်အသီးမှည့်ပျောက်စွန်း နှင့် ကိုင်းဖျားခြောက်ရောဂါ၊ ပဲအမျိုးမျိုးတွင်ကျရောက်တတ်သော ဆာကိုစပိုးရားရွက်ပြောက်ရောဂါ၊ ကြက်သွန်တောက်တဲ့မြီးရောဂါ၊ ဂန္ဓမာသံချေးဖြူ(ကျောက်ရောဂါ)၊ အာလူးလောင်မဲရောဂါ နှင့် အခြားမှိုဆေးများဖြင့်နှိမ်နင်းရန်ခက်ခဲသည့် မှိုရောဂါအမျိုးမျိုးကို အမြစ်ပြတ်သုတ်သင်ရှင်းလင်းပေးနိုင်ပါသည်။<br><br>\r\n\r\n၇ ။ ဟက်ဇာဂွန် ၅ အက်စ်စီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Hexaconazole 5% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️ပဲမျိုးစုံတွင်ကျရောက်သော ဖားဥမှိုရောဂါ၊ ဖရဲ သခွားမွှေး ဖားဥမှိုရောဂါ၊ ဂန္ဓမာသံချေးဖြူရောဂါ၊ နှင်းဆီအနက်ပြောက်ရောဂါ၊ ပဲမျိုးစုံသံချေးရောဂါ၊ မြေပဲရွက်ပြောက်ရောဂါ၊ နှမ်းရိုးမဲရောဂါ၊ ကြက်သွန်တောက်တဲ့မြီး၊ ငရုတ်မှည့်ပြောက်စွန်း နှင့် ကိုင်းဖျားခြောက်ရောဂါ၊ စပျစ်ငှက်မျက်စိရောဂါ၊ ငှက်ပျောစီဂါတိုကာ (Sigatoka) နှင့် Cercospora musae ရွက်ခြောက်ရောဂါများကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၈ ။ ကာစင် ၂ အက်စ်အယ်လ်<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Kasugamycin 2% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️စပါးဘက်တီးရီးယားရွက်ခြောက်ရောဂါ၊ စပါးဂုတ်ကျိုးရောဂါ၊ အာလူး၊ ခရမ်းချဉ် နှင့် ဖရဲ၊ သခွား ဘက်တီးရီးယားပင်ညှိုးရောဂါ၊ ဘက်တီးရီးယားရွက်ပြောက်ရောဂါ၊ ပဲမျိုးစုံတွင်ကျရောက်သော ဘက်တီးရီးယားရွက်ပြောက် နှင့် မှဲ့ပြောက်စွန်းရောဂါ၊ ကြက်သွန်အပျော့ပုပ် နှင့် ကွမ်းဆီစွန်း ရိုးမဲ ဆစ်ပြုတ်ရောဂါများအတွက် ထိရောက်စွာကာကွယ်နှိမ်နင်းနိုင်ပါသည်။ ရောဂါကျရောက်မှုဆိုးရွားပါက “ကျူပရိုမက်စ်” နှင့် ရောစပ်အသုံးပြုပေးရပါမည်။<br><br>\r\n\r\n၉ ။ မက်တယ်လဇီး ၂၅ ဒဗလျူပီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Metalaxyl 25% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️သီးနှံမျိုးစုံတွင်ကျရောက်သော လောင်မဲရောဂါ၊ ဖားဥမှိုရောဂါ၊ ခါးရိရောဂါ၊ အကိုင်းခြောက်၊ ပင်စည်ပုပ်၊ အမြစ်ပုပ်၊ အသီးပုပ်ရောဂါများ၊ မြေတွင်းအောင်းမှိုများ၊ မျိုးစေ့တွင်တွယ်ကပ်နေသောရောဂါမှိုများကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းပေးသည်။ မြေတွင်းအောင်းမှိုရောဂါများကို ကာကွယ်နှိမ်နင်းရန် မျိုးစေ့နှင့် လူးနယ်စိုက်ပျိုးပေးရပါမည်။<br><br>\r\n\r\n၁၀ ။ နိုက်စ် ၅၂၅ အက်စ်အီး<br><br>\r\n\r\n☑️အစွမ်းရှိပစ္စည်း Propiconazole 12.5 % + Tricyclazole 40 % ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️စပါးတွင်ကျရောက်သော စပါးဂုတ်ကျိုးရောဂါအမျိုးမျိုး၊ ရွက်ပြောက်ရောဂါ၊ ရွက်ဖုံးပုပ်ရောဂါ၊ ရွက်ဖုံးခြောက်ရောဂါ နှင့် စပါးမှိုသီးရောဂါများကို အထိရောက်ဆုံး ကာကွယ်ကုသပေးနိုင်ပါသည်။<br><br>\r\n\r\n၁၁ ။ ပိုင်ရီဆိုက် ၄၀ အက်စ်စီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Tricyclazole 40 % ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️စပါးပင် အရွက်၊ ပင်စည်၊ အကိုင်းအခက် နှင့် စပါးနှံများတွင် ကျရောက်သော ဂုတ်ကျိုးရောဂါ အဆင့်တိုင်းကို ကာကွယ်ကုသနိုင်ပါသည်။ <br><br>\r\n\r\n၁၂ ။ ဆာဗိတ် ၈၀ ဒဗလျူဒီဂျီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Sulphur 80% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️မြေပဲရွက်ပြောက်ရောဂါ၊ သံချေးရောဂါ၊ ဂျုံနနွင်းရောဂါ၊ ပဲမျိုးစုံဖားဥမှိုရောဂါ၊ စပျစ်ဖားဥမှိုရောဂါ၊ နှင်းဆီ အနက်ပြောက် နှင့် သံချေးရောဂါများကို ကာကွယ်ကုသနိုင်သည်။ “ဆာဗိတ်” သည် မှိုရောဂါအမျိုးမျိုးကို ကာကွယ်ကုသနိုင်သည့်အပြင် မွှားပင့်ကူသတ်ဆေးအဖြစ်လည်း အသုံးပြုနိုင်ပါသည်။ ထို့အပြင် ကန့်ဓာတ်ပါဝင်သဖြင့် အပင်အစာချက်လုပ်မှုအားကောင်း၍ အပင်ကြီးထွားကြံ့ခိုင်ပြီး ပိုးမွှားရောဂါဒဏ် ခံနိုင်ရည်ရှိစေသဖြင့် သီးနှံအရည်အသွေး နှင့် အထွက်နှုန်းကို မြင့်မားစေနိုင်ပါသည်။<br><br>\r\n\r\n၁၃ ။ စူပါမော့ ၅၀၀ ဒဗလျူပီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Dimethomorph 500g/kg ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️ဖရဲ၊ သခွားမွှေး၊ စပျစ်၊ ကြက်သွန် ဒေါင်းနီးရွက်ခြောက်၊ ခရမ်းချဉ် အာလူး လောင်မဲရောဂါ၊ ဆေးရွက်ကြီး ပင်ခြေမဲ၊ ကွမ်းဒေါင်းမြီးကွက်၊ ရွက်ပုပ်ရောဂါများကို ထိရောက်စွာကာကွယ်နှိမ်နင်းနိုင်ပါသည်။<br><br>\r\n\r\n၁၄ ။ ဆိုင်မောက် ၂၅၀ ဒဗလျူပီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Cymoxanil 25 % ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️သီးနှံပင်များတွင်ကျရောက်သောမှိုရောဂါအမျိုးမျိုး အထူးသဖြင့် စပျစ်၊ ဖရဲ၊ သခွားတွင်ကျရောက်သော ဒေါင်းနီးရွက်ခြောက်ရောဂါ၊ အာလူး ခရမ်းချဉ် လောင်မဲရောဂါများနှင့် ကွမ်းရွက်ဒင်္ဂါးကွက်ရောဂါများအတွက် ထုတ်လုပ်ထားပါသည်။ “ဆိုင်မောက်”ကို အခြားမှိုသတ်ဆေးများနှင့် ရောစပ်ပက်ဖျန်းပေးခြင်းဖြင့် ဆေးအာနိသင်ကြာရှည်ခံပြီး ပိုမိုထိရောက်စေပါသည်။<br><br>\r\n\r\n၁၅ ။ တိုက်တန် ၇၅ အက်စ်စီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Propamocarb hydrochloride 37.5% + Chlorothalonil 37.5% ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️“တိုက်တန်”သည် စပျစ်ဒေါင်းနီးရောဂါ၊ ဖရဲ၊ သခွားမွှေးဒေါင်းနီး နှင့် အစေးထွက်ရောဂါ၊ ကြက်သွန် ဒေါင်းနီး ရောဂါ၊ ငရုတ်ပင်ခြေပုပ်ရောဂါများကို ကာကွယ်ကုသနိုင်ပြီး အာလူး၊ ခရမ်းချဉ်လောင်မဲရောဂါ ၊ ကွမ်းရိုးမဲဆစ်ပြုတ်ရောဂါတို့အတွက် အကောင်းဆုံး ကာကွယ်ကုသဆေးဖြစ်သည်။ ထို့ပြင်သီးနှံအမျိုးမျိုး နှင့်ဟင်းသီးဟင်းရွက် ပန်းမာန်များတွင်ကျရောက်တတ်သော ပစ်သီယမ်အမြစ်ပုပ် ခါးရိ နှင့်ပင်ငယ်သေ ရောဂါများအတွက်လည်း အပင်ခြေမြေကြီးကို ပက်ဖျန်းပေးခြင်းဖြင့်အထိရောက်ဆုံး ကာကွယ်ပေးနိုင်ပါ သည်။ ၎င်းအပြင် မက်တယ်လဇီးဆေး ကိုခံနိုင်ရည်ရှိနေသော အာလူးနှောင်းပင်နာကျရောဂါကို “တိုက်တန်” ကထိရောက်စွာ ကာကွယ်ကုသနိုင်ပါသည်။<br><br>\r\n\r\n၁၆ ။ ဘာလီဆိုဒ် ၅ အက်စ်အယ်လ်<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Validamycin 5 % ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️သီးနှံမျိုးစုံခါးရိရောဂါ၊ ပင်ရင်းပုပ်၊ နှမ်းရိုးမဲ၊ အာလူးဥပုပ်၊ ကွမ်းရိုးမဲဆစ်ပြုတ်၊ လိမ္မော်အနာချိုင့်၊ ကြက်သွန်အပျော့ပုပ်၊ ဂေါ်ဖီအပျော့ပုပ်ရောဂါများ၊ စပါး ဘက်တီးရီးယားရွက်ခြောက်ရောဂါ၊ ဘက်တီးရီးယားရွက်စင်းရောဂါ၊ စပါးမှိုသီးရောဂါ၊ စပါးဂုတ်ကျိုးရောဂါ၊ စပါးရွက်ဖုံးခြောက်ရောဂါများကို ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ပါသည်။ ထို့အပြင် “ဘာလီဆိုဒ်”သည် သီးနှံမျိုးစုံခါးရိရောဂါအတွက် အထူးကာကွယ်နှိမ်နင်းဆေးဖြစ်သည်။ “ဘာလီဆိုဒ်” ကို မျိုးစေ့ဖြင့်လူးနယ်ခြင်း၊ မြေပြင်ပေါ်ပက်ဖျန်း ခြင်း နှင့် သီးနှံပင်ပေါ်ပက်ဖျန်းခြင်းတို့ဖြင့် အသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\n၁၇ ။ ဇိုလာ ၂၅ အီးစီ<br><br>\r\n\r\n ☑️အစွမ်းရှိပစ္စည်း Difenoconazole 25 % ပါဝင်ပါသည်။<br><br>\r\n\r\n ☑️သီးနှံမျိုးစုံတွင်ကျရောက်သော မှိုရောဂါအမျိုးမျိုးကို ကာကွယ်နှိမ်နင်းနိုင်သော ဘက်စုံအစွမ်းထက် မှိုသတ်ဆေးဖြစ်သည်။ အထူးသဖြင့် အာလူး ခရမ်းချဉ် စောပင်နာကျရောဂါ၊ ပဲမျိုးစုံသံချေးရောဂါ၊ ဆာကိုစပိုးရားရွက်ပြောက်ရောဂါ နှင့် စပါးရွက်ညိုပြောက်ရောဂါများအတွက် ထုတ်လုပ်ထားပါသည်။ “ဇိုလာ”ကို မျိုးစေ့နှင့် လူးနယ် စိုက်ပျိုးခြင်း၊ အပင်ပေါ်ပက်ဖျန်းခြင်းတို့ဖြင့် ရောဂါဖြစ်စေသောမှိုမျှင်များ ကြီးထွားမှုကိုရပ်တန့်စေနိုင်သည်။<br><br>\r\n\r\n', '', '19-02-2024'),
(39, '“မြေပဲရွက်ပြောက်ရောဂါ” ဂရုပြု ကာကွယ်ပါ', 'IMG-65d36b6bd87c62.95365844.jpg', '🌿🥜🌿🥜🌿🥜🌿🥜🌿🥜🌿<br><br>\r\n\r\n☑️“မြေပဲရွက်ပြောက်ရောဂါ” သည် မြေပဲစိုက်ပျိုးသူများ နှစ်စဉ်ကြုံတွေ့ရသည့်ရောဂါဖြစ်သည်။ ထို့ကြောင့် မြေပဲရွက်ပြောက်ရောဂါအကြောင်းနှင့် ကာကွယ်နှိမ်နင်းရန် နည်းလမ်းများကို ရေးသားဖော်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n🥜ကျရောက်သည့် အခြေအနေ နှင့် ကူးစက်ပျံ့နှံ့ပုံ🥜<br><br>\r\n\r\n အများအားဖြင့် မြေပဲစိုက်ပျိုးပြီး (၃) ပတ်မှ (၅) ပတ်အတွင်း “မြေပဲရွက်ပြောက်” ရောဂါ ကျရောက် နိုင်ပြီး လေထုစိုထိုင်းဆမြင့်မားချိန် နှင့် အပူချိန် (၂၅-၃၀) ဒီဂရီစင်တီဂရိတ်ခန့်တွင် ရောဂါဆိုးရွား တတ်ပါသည်။ မြေပဲပြီးမြေပဲ ဆက်တိုက်စိုက်သည့်အခင်းများတွင် ကျရောက်မှုများတတ်ပါသည်။ ရောဂါဖြစ်စေသည့် မှိုသည် ပင်ကြွင်းပင်ကျန်များ နှင့် အလေ့ကျပေါက်သည့် မြေပဲပင်များတွင် ခိုအောင်းနေတတ်ပါသည်။ မိုးရေစက်နှင့် နှင်းစက်များကြောင့် အောက်အရွက်တွေကနေ ရောဂါစတင်ဖြစ်ပေါ်လာပြီး အပေါ်အရွက်များသို့ တစ်ဆင့်ပြီးတစ်ဆင့် ကူးစက်သွားတတ်ပါသည်။ ဤရောဂါသည် မြေပဲပင်တစ်ပင်မှတစ်ပင် တစ်ခင်းမှတစ်ခင်းသို့ လေနှင့်အလွယ်တကူ ကူးစက် ပျံ့နှံ့နိုင်ပါသည်။<br><br>\r\n\r\n🥜ရောဂါလက္ခဏာများ🥜<br><br>\r\n\r\n “မြေပဲရွက်ပြောက်ရောဂါ” ကျလျှင် အရွက်၏အပေါ်မျက်နှာပြင်မှာ အဝါရောင်အနားသတ်ပါပြီး ပုံသဏ္ဍာန်မမှန်သည့် အညိုရောင်ကွက်ပြောက် (ရွက်ညိုပြောက်)များ နှင့် အရွက်ရဲ့ အောက်မျက်နှာပြင်မှာ လုံးဝိုင်းတဲ့ အနက်ပြောက်(ရွက်နက်ပြောက်)များကို တွေ့ရမှာ ဖြစ်သည်။ ရွက်ညိုပြောက်များက အရင်ကျတတ်ပြီး ရွက်နက်ပြောက်များက နောက်မှကျတတ်ပါသည်။ ရောဂါတိုးပွားလာပါက ရောဂါကွက်ပြောက်များ ပေါင်းစပ်သွားပြီး အရွက်ခြောက်ပြီး နောက်ဆုံးတွင် ကြွေကျသွားပါသည်။ အရွက်မှတစ်ဆင့် ရိုးတံ နှင့် ပင်စည်များအပေါ်အထိ ကူးစက်နိုင်ပါသည်။ ရောဂါဆိုးရွားစွာကျရောက်ပါက အောင်မြင်သည့် မြေပဲတောင့်များမရရှိနိုင်တော့ဘဲ (၇၀%) အထိ အထွက်ဆုံးရှုံးစေနိုင်ပါသည်။<br><br>\r\n\r\n🥜ကာကွယ်နှိမ်နင်းရန်နည်းလမ်းများ🥜<br><br>\r\n\r\n ☑️ သီးနှံမစိုက်ပျိုးမီ မြေကြီးကို ထယ်ရေးနက်နက်ထိုးလှန်ထားပြီး မြေကြီးတွင်းရှိ ပင်ကြွင်းပင်ကျန်များမှ ရွက်ပြောက်ရောဂါဖြစ်စေသော မှိုစပိုးလ်များကို နေရောင်ပြင်းပြင်းဖြင့်တိုက်ရိုက်ထိတွေ့စေရပါမည်။<br><br>\r\n\r\n ☑️ ရောဂါဒဏ်ခံနိုင်ရည်ရှိသည့်မျိုးများကို ရွေးချယ်စိုက်ပျိုးပါ။<br><br>\r\n\r\n ☑️ အပင်စိပ်စိပ်စိုက်ခြင်းကို ရှောင်ကြဉ်ပါ။<br><br>\r\n\r\n ☑️ နှစ်စဉ်ရောဂါကျရောက်တတ်ပါက ပြောင်း၊ နှံစားပြောင်း၊ ပဲလွမ်းသီးနှံများနှင့် သီးလှည့်စိုက်ပျိုးပါ။<br><br>\r\n\r\n ☑️ စိုက်ခင်းအတွင်းရှိ ပေါင်းမြက်များနှင့် ရာသီမဟုတ်ဘဲ အလေ့ကျပေါက်သော မြေပဲပင်များကို ရှင်းလင်းဖျက်ဆီးပါ။<br><br>\r\n\r\n ☑️ ရောဂါကျနေတဲ့ အပင်များကို စတွေ့လျှင်တွေ့ချင်း ချက်ချင်းနုတ်ယူဖျက်ဆီးပါ။<br><br>\r\n\r\n ☑️ ရောဂါကျထားသောအခင်းမှ ပင်ကြွင်းပင်ကျန်များကို မီးရှို့ဖျက်ဆီးပါ။<br><br>\r\n\r\n ☑️ဓာတုနည်းအားဖြင့် နှိမ်နင်းရန်မှာ အခင်းတွင် ရွက်ညိုပြောက်များ စတင်တွေ့ချိန်၊ တစ်နည်းအားဖြင့် ရွက်နက်ပြောက်တွေမကျရောက်ခင်အချိန်မှာ မှိုသတ်ဆေးကို အချိန်မီပက်ဖျန်းနိုင်ရန် အထူးလိုအပ်ပါသည်။ အသုံးပြုရန်မှာ ဝိစာရ၏ “ကာဗာ၊ ဇိုလာ၊ ဒိုင်ဇီ၊ ဟက်ဇာဂွန်” ဆေးများမှ တစ်မျိုးမျိုးကို ဆေးညွှန်းပါအတိုင်းသုံးစွဲပေးရန်ဖြစ်ပါသည်။<br><br>\r\n\r\nSources : ဆီထွက်သီးနှံများတွင်ကျရောက်သောရောဂါများ (သီးနှံကာကွယ်ရေးဌာန)', '', '19-02-2024'),
(40, '“သီးနှံပင်များ ရှင်သန်ကြီးထွားရေးအတွက် အာဟာရဓာတ်များ၏ လုပ်ဆောင်ချက်များ”', 'IMG-65d36c05042087.48647894.jpg', '🌱🌱🌱🌱🌱🌱🌱🌱🌱🌱<br><br>\r\n\r\n✅သီးနှံပင်များစိုက်ပျိုးကြရာတွင် မိမိတို့၏ သီးနှံပင်များအတွက် လိုအပ်သောအာဟာရဓာတ်များ နှင့် ထိုအာဟာရဓာတ်များ၏ လုပ်ဆောင်ချက်များကို သိထားသင့်ပြီး လိုအပ်သလိုဖြည့်ဆည်းပေးနိုင်ရန် အရေးကြီးပါသည်။ သို့မှသာ သီးနှံပင်များစိုက်ပျိုးထုတ်လုပ်မှုတွင် အောင်မြင်နိုင်ပါမည်။ ထို့ကြောင့် အာဟာရဓာတ်များ၏လုပ်ဆောင်ချက်များကိုသိရှိပြီး သီးနှံပင်များအတွက် ရွေးချယ်ဖြည့်တင်းပေးနိုင်ပါရန် ဗဟုသုတအဖြစ် တင်ဆက်ပေးလိုက်ပါသည်။<br><br>\r\n\r\n၁။ နိုက်ထရိုဂျင်ဓာတ် ( N )<br><br>\r\n\r\n▪️ အပင်များ၏ရှင်သန်မှုဆိုင်ရာ အဖွဲ့အစည်းများအတွက် အရေးကြီးသောဓာတ်ဖြစ်ပါသည်။ ▪️ ပရိုတင်းတည်ဆောက်ရာတွင် အရေးကြီးသောအခန်းကဏ္ဍတွင် လုပ်ဆောင်ပါသည်။\r\n▪️ အစိမ်းရောင်ခြယ်ပစ္စည်းဖြစ်ပေါ်မှုကို တိုးပွားစေပါသည်။\r\n▪️ အပင်များ၏ အရွက်၊ အခက်အလက်၊ ပင်စည်များ ကြီးထွားမှုကို အားပေးပါသည်။\r\n▪️ အပင်များ၏ အထွက်နှုန်း နှင့် အရည်အသွေးကို တိုးပွားစေပါသည်။<br><br>\r\n\r\n ၂။ ဖော့စ်ပရပ်စ်ဓာတ် ( P ) <br><br>\r\n\r\n▪️ အပင်များအတွက်အရေးကြီးသော ဆဲလ်များတည်ဆောက်မှုကို အထောက် အကူပြုပါသည်။ \r\n▪️ ဆဲလ်ကွဲပွားခြင်း နှင့် ဆဲလ်အသစ်ဖြစ်ပေါ်မှုကို အားပေးပါသည်။ \r\n▪️ အလင်းမီ အစာချက်လုပ်မှုအတွက် လိုအပ်ပါသည်။ \r\n▪️ သကြား နှင့် ကစီဓာတ် ဖြစ်ပေါ်မှုအတွက် ကူညီပါသည်။ \r\n▪️ အပင်များအတွက် လိုအပ်သော စွမ်းအင်များကို ပြောင်းလဲလုပ်ဆောင်ပေးပါသည်။ \r\n▪️ အမြစ်များကို စောစီးစွာထွက်စေခြင်း၊ ပန်းပွင့်စေခြင်း၊ အစေ့အဆံဖြစ်ပေါ်ပြည့်ဝစေခြင်း အစရှိသည်တို့အတွက် ဆောင်ရွက်ပေးပါသည်။ <br><br>\r\n\r\n ၃။ ပိုတက်ဆီယမ်ဓာတ် ( K ) <br><br>\r\n\r\n▪️ အလင်းမီအစာချက်လုပ်ခြင်း နှင့် အစိမ်းရောင်ခြယ်ပစ္စည်း၏ လုပ်ငန်းဆောင်ရွက်ခြင်းတို့တွင် ကူညီပေးပါသည်။ \r\n▪️ မြောက်များစွာသော အင်ဇိုင်းများ၏ လုပ်ငန်းစဉ်များတွင် ကူညီပေးပါသည်။ \r\n▪️ ပရိုတင်းဖြစ်ပေါ်မှုတွင် ပါဝင်ပါသည်။ \r\n▪️ ဆဲလ်များ၏ အတွင်းပိုင်းဖိအားအတွက် ကူညီဖြေရှင်းပေးသည်။ \r\n▪️ ရာသီဥတု နှင့် ရောဂါဒဏ်များကို ခံနိုင်ရည်ရှိစေပါသည်။ \r\n▪️ ရေလိုအပ်မှုကို ထိန်းချုပ်တိုးတက်စေပြီး ရေငတ်ဒဏ် နှင့် အငံဓာတ်လွန်ကဲမှုကို ခံနိုင်စွမ်း တိုးစေပါသည်။ \r\n▪️ အမြစ်ကြီးထွားမှုအတွက် တိုးတက်စေပြီး အပင်ယိုင်လဲမှုများကို ကာကွယ်ပေးပါသည်။ \r\n▪️ သီးနှံများ၏ အရည်အသွေးကို တိုးမြှင့်ဆောင်ရွက်ပေးပါသည်။ <br><br>\r\n\r\n ၄။ ကယ်ဆီယမ်ဓာတ် ( Ca ) <br><br>\r\n\r\n▪️ အပင်များ၏ ဆဲလ်နံရံများကို တောင့်တင်းခိုင်မာစေပါသည်။ \r\n▪️ ဆဲလ်ကွဲပွားခြင်း နှင့် ဆဲလ်ရှည်ထွက်ခြင်းကို ကူညီပေးပါသည်။ \r\n▪️ အသီးတင်မှုကို ဖြစ်ပေါ်စေပြီး အသီးထိပ်ပုပ်ခြင်းကို ကာကွယ်ပေးပါသည်။ \r\n▪️ မြေဆီလွှာ အချဉ်ဓာတ်လွန်ကဲမှုကို လျော့နည်းစေပါသည်။<br><br> \r\n\r\n ၅။ ဆာလ်ဖာဓာတ် ( S )<br><br> \r\n\r\n▪️ အပင်များအတွက် အရေးကြီးသော ပရိုတင်းဖြစ်စေရန် အမိုင်နိုအက်စစ်ထုတ်လုပ်မှုကို လုပ်ဆောင်ပေးပါသည်။ \r\n▪️ အစိမ်းရောင်ခြယ်ပစ္စည်း ဖြစ်ပေါ်မှုအတွက် ကူညီပေးပါသည်။ \r\n▪️ ပဲမျိုးနွယ်ဝင် အပင်များတွင် နိုက်ထရိုဂျင်ကို ဖမ်းယူပေးသော ပဲမြစ်ဖုဖြစ်ပေါ်မှုအတွက် ဆောင်ရွက်ပေးပါသည်။ \r\n▪️ ကြက်သွန်နီ၊ ကြက်သွန်ဖြူ ၊ မုံညင်း၊ မုံလာ အစရှိသော သီးနှံများ၏ အနံ့ကို ကောင်းမွန်စေပါသည်။ \r\n▪️ အချို့အင်ဇိုင်းများ၏ စွမ်းရည်ကို တိုးတက်စေရန် ကူညီပေးပါသည်။ <br><br>\r\n\r\n ၆။ မဂ္ဂနီဆီယမ်ဓာတ် ( Mg ) <br><br>\r\n\r\n▪️ အပင်များအတွက် အစိမ်းရောင်ခြယ်ပစ္စည်း၏ မော်လီကျူးများတွင် ပါဝင်ဖွဲ့စည်းသော ဓာတ်ပစ္စည်းများကို ဖြစ်ပေါ်အားပေးပါသည်။ \r\n▪️ သကြားဓာတ် နှင့် ကစီဓာတ် ဖြစ်ပေါ်မှုကို ကူညီပေးပါသည်။ \r\n▪️ ဖော့စ်ပရပ်စ်ဓာတ်ကို ချိတ်ဆက်သယ်ဆောင်ရာတွင် အရေးကြီးသော အခန်းကဏ္ဍတစ်ခုအဖြစ် ပါဝင်ပါသည်။ \r\n▪️ အပင်များအတွက် များစွာသော အင်ဇိုင်းများ၏ လုပ်ငန်းတာဝန်များကို ကူညီပေးပါသည်။ <br><br>\r\n\r\n၇။ ဘိုရွန်ဓာတ် ( B ) <br><br>\r\n \r\n▪️ ဆဲလ်ကွဲပွားခြင်းအတွက် ဆောင်ရွက်ပေးပါသည်။ \r\n▪️ ကယ်ဆီယမ်ဓာတ်ကို ချိတ်ဆက်သယ်ယူရာတွင် ကူညီပေးပါသည်။ \r\n▪️ ပရိုတင်းဖြစ်ပေါ်မှုကို အားပေးပါသည်။ \r\n▪️ ကာဘိုဟိုက်ဒြိတ်ဖြိုခွဲမှုအတွက် ကူညီပေးပါသည်။ \r\n▪️ ဝတ်မှုန်ကူးမှုကို တိုးတက်ကောင်းမွန်စေပါသည်။ \r\n▪️ အပွင့် နှင့် အသီး ဖြစ်ပေါ်မှုတို့အတွက် ကူညီဆောင်ရွက်ပေးပါသည်။ \r\n▪️ အပင်များအတွက် လိုအပ်သော ဟော်မုန်းဖြစ်ပေါ်မှုကို ဆောင်ရွက်ပေးပါသည်။ <br><br>\r\n\r\n ၈။ ကော့ပါးဓာတ် ( Cu ) <br><br>\r\n\r\n▪️ အစိမ်းရောင်ခြယ်ပစ္စည်း ထုတ်လုပ်မှုအတွက် လိုအပ်ပါသည်။ \r\n▪️ အလင်းမီအစာချက်လုပ်မှုအတွက် ကူညီပေးပါသည်။ \r\n▪️ အင်ဇိုင်းများ၏ ပရိုတင်းထုတ်လုပ်ခြင်းတွင် ကူညီပေးပါသည်။ \r\n▪️ အင်ဇိုင်းများ၏ ဖွဲ့စည်းမှုတွင် ပါဝင်ပါသည်။ \r\n▪️ ဓာတ်တိုးဓာတ်လျော့လုပ်ငန်းစဉ်တွင် ပါဝင်ပါသည်။ \r\n▪️ အပင်များတွင် ရေရွေ့လျားမှုကို ထိန်းချုုပ်ကူညီပေးပါသည်။ \r\n▪️ အစေ့ထုတ်လုပ်ခြင်းအတွက် လိုအပ်ပါသည်။ \r\n▪️ အမြစ်များ ဇီဝဓာတ်ပြုမှုအတွက် ကူညီပေးပါသည်။ <br><br>\r\n\r\n ၉။ သံဓာတ် ( Fe ) <br><br>\r\n\r\n▪️ အရွက်များအတွင်း အောက်စီဂျင်ကို သယ်ယူရာတွင် ဓာတ်ကူပစ္စည်းအဖြစ် ကူညီပေးပါသည်။ <br><br>\r\n\r\n ၁၀။ မဂ္ဂနိစ်ဓာတ် ( Mn )<br><br>\r\n\r\n▪️ အပင်များ၏ အစိမ်းရောင်ခြယ်ပစ္စည်းထုတ်လုပ်ခြင်း နှင့် အလင်းမီအစာချက်လုပ်ခြင်းအတွက် အရေးကြီးပါသည်။ \r\n▪️ ဓာတ်တိုးဓာတ်လျော့ လုပ်ငန်းစဉ်များအတွက် ထိန်းညှိပေးပါသည်။ \r\n▪️ များစွာသော အင်ဇိုင်းများ၏ စွမ်းအင်အတွက် ပါဝင်ပါသည်။ \r\n▪️ အပင်ကြီးထွားမှုဖြစ်စဉ်တိုင်းတွင် ကော့ပါးဓာတ်၊ သံဓာတ်၊ သွပ်ဓာတ် တို့နှင့်အတူ ပေါင်းစပ်ကူညီပါသည်။<br><br> \r\n\r\n၁၁။ မိုလီဒီနမ်ဓာတ် ( Mo ) <br><br>\r\n\r\n▪️ လေထုထဲမှ နိုက်ထရိုဂျင်ဓာတ်ကို ဖမ်းယူပေးသော ပဲမြစ်ဖုဇီဝဘက်တီးရီးယားအတွက် လိုအပ်ပါသည်။ \r\n▪️ အင်ဇိုင်းများ ဓာတ်ပြုမှုအတွက် ကူညီပေးပါသည်။<br><br>\r\n\r\n၁၂။ သွပ်ဓာတ် ( Zn ) <br><br>\r\n\r\n▪️ အစိမ်းရောင်ခြယ်ပစ္စည်း ဖြစ်ပေါ်မှုအတွက် လိုအပ်ပါသည်။ \r\n▪️ အင်ဇိုင်းများ နှင့် ကြီးထွားဟော်မုန်းများအတွက် ပါဝင်ပါသည်။ \r\n▪️ အပင်များ ရေစုပ်ယူမှု နှင့် ရေအသုံးပြုမှုကို ထိန်းညှိကူညီပေးပါသည်။<br><br>\r\n\r\n ၁၃။ ကလိုရင်းဓာတ် ( Cl ) <br><br>\r\n\r\n▪️ အပင်အတွင်း ရေရွေ့လျားခြင်း နှင့် ရေအသုံးချမှုကို ကူညီဆောင်ရွက်ပေးပါသည်။ \r\n▪️ Stomata ခေါ် လေရှူပေါက်များ၏ အဖွင့်အပိတ်လုပ်ငန်းစဉ်အတွက် ကူညီပေးပါသည်။ ▪️ အပင်ကြီးထွားမှု နှင့် အပွင့်ဖြစ်ပေါ်မှုကို အားပေးပါသည်။ <br><br>\r\n\r\n ၁၄။ ဆီလီကာဓာတ် ( Si ) <br><br>\r\n\r\n▪️ အပင်အတွက် ပင်စည်ရှည်ထွက်မှုကို တိုးလာစေရန် အထောက်အကူပြုပါသည်။ \r\n▪️ ရေငတ်ဒဏ်၊ ရေဝပ်ဒဏ်ကို ခံနိုင်ရည်ရှိစေသည်။ \r\n▪️ အာဟာရစုပ်ယူမှုကောင်းမွန်စေရန် ကူညီသည်။ \r\n▪️ အချို့ Metal များ၏ လောင်ကျွမ်းခြင်းကို ကာကွယ်ပေးသည်။ \r\n▪️ စပါးပင်အတွက် မရှိမဖြစ်သော အာဟာရဓာတ်ဖြစ်သည်။ \r\n▪️ စပါးပင်ကြီးထွားရေးအတွက် လိုအပ်သော အရွက် ပင်စည် နှင့် အမြစ်ပိုင်းဆိုင်ရာ အားလုံးတွင် ဆောင်ရွက်ပေးပါသည်။ \r\n▪️ စပါးရွက် Cuticle ဖယောင်းလွှာကို ထူစေသောကြောင့် မှိုရောဂါ ၊ ဘက်တီးရီးယားရောဂါ နှင့် အင်းဆက်ပိုးများ၏ ဖျက်ဆီးမှုမှ ကာကွယ်ပေးပါသည်။ <br><br>\r\n\r\nRef : Plants & Nutrients', '', '19-02-2024'),
(41, 'ခရမ်းချဉ်ပင်တွင် ဂရုပြုကာကွယ်ရမည့် “စောပင်နာကျ” ရောဂါ', 'IMG-65d36c8258c7f6.95152197.jpg', '🌿🍅🌿🍅🌿🍅🌿🍅🌿🍅🌿<br><br>\r\n\r\nမြန်မာအမည် - အော်တာနေရီးယား ရွက်ပြောက်ရောဂါ (စောပင်နာကျရောဂါ)<br><br>\r\n\r\nအင်္ဂလိပ်အမည် - Alternaria Leaf Spot, Early Blight<br><br>\r\n\r\nရောဂါဖြစ်စေသောမှို - Alternaria solani<br><br>\r\n\r\nခရမ်းချဉ်စောပင်နာကျ ရောဂါအကြောင်း .....<br><br>\r\n\r\nခရမ်းချဉ်၏အထွက်နှုန်းကို အဓိကကျဆင်းစေသောရောဂါဖြစ်သည့် ခရမ်းချဉ်စောပင်နာကျရောဂါသည် မှိုကြောင့်ဖြစ်သော ရောဂါဖြစ်သည်။ ရောဂါဖြစ်စေသောမှို၏ သိပ္ပံအမည်မှာ Alternaria solani ဖြစ်ပြီး ခရမ်းချဉ်၏ မည်သည့်ကြီးထွားမှုအဆင့်မဆို ဖျက်ဆီးနိုင်ပါသည်။ ခရမ်းချဉ်ခင်း၏ မြေအစိုဓာတ်၊ ရေရရှိမှုများအပေါ်မူတည်ကာ ရောဂါကျရောက်မှုသည် တိုက်ရိုက်ပတ်သတ်နေသည်။ <br><br>\r\n\r\nရောဂါလက္ခဏာ ..... <br><br>\r\n\r\nရောဂါလက္ခဏာအား အောက်ခြေအရွက်ရင့်များပေါ်တွင် စတင်တွေ့ရသည်။ ညိုမဲရောင် အဝိုင်းရစ် အကွက်ဘေးတွင် အဝါရောင်အနားသားများဖြစ်သော အနာကွက်များဖြစ်ပေါ်သည်။ ရောဂါပြင်းထန် ပါက တစ်ရွက်လုံးဝါပြီးခြောက်သွားသည်။ အပေါ်ရွက်များသို့ကူးစက်သည်။ ရိုးတံနှင့် ပင်စည်ပေါ်တွင် ရောဂါကျရောက်ပါက အညိုရောင်အဝိုင်းရစ်အနာကွက်ကို ရှည်မျောမျောပုံသဏ္ဍန် တွေ့ရှိရသည်။<br><br>\r\n\r\nဒီရောဂါဟာ ခရမ်းချဉ်ပျိုးပင်တွေကို ခါးရိရောဂါဖြစ်စေနိုင်သလို မြေပြင်အနီးရှိ ပင်စည်ပတ်လည်တွင် အညိုရောင်ဒဏ်ရာများကို အပင်ငယ်တွေမှာ ဖြစ်ပေါ်စေပါတယ်။ ဤမှိုရောဂါဟာ ကွင်းပြင်စိုက်ခင်းမှာ တွေ့ရလေ့ရှိပီး စိုက်ခင်းအတွင်း စိုထိုင်းဆများမယ်ဆိုရင် ရောဂါကိုကြီးထွားစေနိုင်ပါတယ်။ ခရမ်းချဉ်ပင်ရဲ့ အပင်ငယ်စဉ်မှာ ကျရောက်တဲ့မှိုရောဂါတစ်မျိုးဖြစ်ပြီး အချိန်မီကာကွယ်သင့်တဲ့ ရောဂါတစ်မျိုးလည်းဖြစ်ပါတယ်။<br><br> \r\n\r\nကာကွယ်ကုသရန် နည်းလမ်းများ ..... <br><br>\r\n\r\n ၁ ။ ပျိုးပင်များကို စိုက်ခင်းသို့ရွှေ့မစိုက်မီ ရောဂါကင်း မကင်း သေချာစွာစစ်ဆေးပါ။ <br><br>\r\n\r\n ၂ ။ ရောဂါကင်းသော (သို့မဟုတ်) ရောဂါဒဏ်ခံနိုင်ရည်ရှိသော မျိုးကိုသုံးပါ။<br><br>\r\n\r\n ၃ ။ စိုက်ခင်းအားမြေစိုထိုင်းဆမြင့်မားမှုကိုရှောင်ကျဉ်၍ ရေဝပ်ခြင်းမှကာကွယ်ပါ။ <br><br>\r\n\r\n ၄ ။ ရောဂါကျသောပင်ကြွင်း ပင်ကျန်များကို မီးရှို့ဖျက်ဆီးပစ်ပါ။<br><br> \r\n\r\n ၅ ။ စိုက်ခင်းအတွင်းအပြင်ရှိ ပေါင်းမြက်များအား ရှင်းလင်းပါ။ <br><br>\r\n\r\n ၆ ။ ခရမ်းမျိုးရင်းဝင်မဟုတ်သောသီးနှံများနှင့် နှစ်နှစ်တစ်ကြိမ် သီးလှည့်စိုက်ပျိုးပေးပါ။ <br><br>\r\n\r\n ၇ ။ မှိုသတ်ဆေးအသုံးပြုရန် “ဒိုင်ဇီ၊ ဇိုလာ၊ ဘင်ဇိုကာ”ဆေးများမှ တစ်မျိုးမျိုးကို ရွေးချယ်၍ ဆေးညွှန်းပါအတိုင်း အသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\nSources : ပိုးမွှားရောဂါကာကွယ်နှိမ်နင်းနည်းများ', '', '19-02-2024'),
(42, '“ပဲတီစိမ်းအထွက်တိုးရန် နိုက်ထရိုဂျင်ဓာတ်၏ အရေးပါမှု”', 'IMG-65d36ce81e04f8.32948003.jpg', '🌿🌱🌿🌱🌿🌱🌿🌱🌿🌱🌿<br><br>\r\n\r\n✔️မြန်မာနိုင်ငံရဲ့ စိုက်ပျိုးမှုအများဆုံးသီးနှံတွေထဲက တစ်ခုအပါဝင်ဖြစ်တဲ့ ပဲတီစိမ်းသီးနှံအတွက် နိုက်ထရိုဂျင်ဓါတ်ရဲ့ အရေးပါမှုကိုသိရှိနိုင်ပါရန် တင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n✔️မြန်မာနိုင်ငံတွင် ပဲမျိုးစုံသီးနှံကို ဧက ၁၀ သန်း နီးပါး စိုက်ပျိုးပါသည်။ ၎င်းတို့အနက် ပဲတီစိမ်း စိုက်ဧကသည် အများဆုံးဖြစ်သည်။ ပဲတီစိမ်းသည် ပြည်ပပို့ကုန်တွင်လည်း အားကိုးရပြီး ပြည်တွင်း စားသုံးမှုအတွက်လည်း အားထားရသောသီးနှံဖြစ်သည်။ ပဲတီစိမ်းသည် တစ်နိုင်ငံလုံးပျမ်းမျှ အထွက် နှုန်းမှာ (၈)တင်း မှ (၁၀)တင်းသာ ရှိသည်။ ပဲတီစိမ်းသည် စနစ်တကျ စိုက်ပျိုးပြုစု ထိန်းသိမ်းနိုင်ပါက အထွက်ကောင်းရရှိနိုင်သော သီးနှံဖြစ်သည်။ <br><br>\r\n\r\n✔️ပဲတီစိမ်းအထွက်တိုးရန် အထွက်နှုန်းမိတ်ဖက်အချက်များကို စွမ်းရည်ပြည့်ဝအောင် ဆောင်ရွက် ပေးခြင်းသည်လည်း အရေးပါမှုတစ်ခုဖြစ်သည်။ ပဲတီစိမ်းတစ်ဧကတွင် ရိတ်သိမ်းအပင်ပေါင်း ၁၃၀,၀၀၀ ပင် ရှိအောင်စိုက်ပျိုးရမည်ဖြစ်သည်။ သီးကိုင်းတစ်ကိုင်းတွင် အတောင့်ပေါင်းခြောက်တောင့်မှ ရှစ်တောင့်ရရှိအောင်ထိန်းသိမ်းရမည် ဖြစ်သည်။ တစ်တောင့်တွင် အစေ့ပေါင်း ၁၀ စေ့မှ ၁၂ စေ့ရရှိအောင် ဂရုစိုက်ဆောင်ရွက်ရပါမည်။ ပဲတီစိမ်းမျိုးစေ့တစ်တင်းလျှင် အစေ့ပေါင်းခြောက်သိန်းကျော်ခန့်ရှိရာ ပဲတီစိမ်း တစ်ဧကလျှင် တင်း ၂၀ ထွက်ရှိရန် အတွက် ပဲစေ့ပေါင်း သိန်း ၁၂၀ ကျော်ခန့် ရရှိရန် လိုအပ်ပါသည်။<br><br>\r\n\r\n✔️ပဲတီစိမ်းသီးနှံတွင် ယခုကဲ့သို့ လိုအပ်သည့် ပဲစေ့အရေအတွက်ရရှိရန်မှာ အထွက်နှုန်း မိတ်ဖက် အချက်များအပေါ် နိုက်ထရိုဂျင်ဓာတ်၏ လိုအပ်ချက်က လွှမ်းမိုးနေပါသည်။ ပဲတီစိမ်းကို စိုက်ပျိုးပြီး ၇ ရက်မှ ၁၀ ရက်ကြာပါက အပင်ပေါက်စုံပါသည်။ အပင်၏ဇီဝကမ္မအရ အပင်ကြီးထွားမှုကာလ၊ ပန်းပွင့်ပြီး သန္ဓေအောင်သည့်ကာလ၊ ပဲတောင့် ပဲစေ့ ကြီးထွားဖွံ့ဖြိုးမှုကာလ၊ ရင့်မှည့်ရိတ်သိမ်းသည့်ကာလ ဟူ၍ ခွဲခြားထားသည်။ ပဲပင်၏ကြီးထွားဖွံ့ဖြိုးမှုကာလအဆင့်ဆင့်အလိုက် အာဟာရဓာတ်များနှင့် အစိုဓာတ်လိုအပ်ပါသည်။<br><br>\r\n\r\n✔️လိုအပ်သောအာဟာရဓာတ်များ ပြည့်စုံစွာထည့်ပေးနိုင်မှသာ ပဲပင်သည် သန်မာကြီးထွားဖွံ့ဖြိုးပြီး အောင်မြင်သော ပဲတောင့်၊ ပဲစေ့များကို များများထုတ်လုပ်ပေးနိုင်မည် ဖြစ်ပါသည်။ ပဲတီစိမ်းသည် စိုက်ပျိုးပြီး ခြောက်ပတ်မှ ရှစ်ပတ်ကြာလျှင် ပန်းစပွင့်ပါသည်။ ပန်းမပွင့်မီရက်အလိုက် ညနေဘက်တွင် အငုံထဲ၌ ဝတ်မှုန်အိတ်၊ ဝတ်မှုန်များရင့်၍အက်ကွဲပြီး ဝတ်မှုန်များထွက်၍ အပွင့်ထဲ၌ပင် မျိုးကူးစပ် သန္ဓေအောင်ပါသည်။ လုံး၀ပင်တည်းဝတ်မှုန်ကူးသောအပင်မျိုး ဖြစ်ပါသည်။ ပွင့်အာခြင်း မရှိဘဲ ဝတ်မှုန်ကူးသည့် ပန်းပွင့်မှာ ရာခိုင်နှုန်း၄၀ ကျော် ရှိပါသည်။ ပဲတီစိမ်းသည် ပန်းစတင်ပွင့်သည်မှ ပဲတောင့်ရင့်သည်ထိ ရက် ၂၀ မှ ရက် ၃၀ ထိကြာပါသည်။<br><br>\r\n\r\n✔️ဤကာလတွင် နိုက်ထရိုဂျင်ဓာတ်မလုံလောက်ပါက ပန်းပွင့်ရက်တိုသွားပြီး ပဲထွက်လည်းကျစေပါသည်။ ပဲမျိုးများသည် ပန်းပွင့်ရက်ကြာလေလေ အထွက်ကောင်းလေလေဖြစ်ပါသည်။ ပဲတီစိမ်း ပန်းပွင့်ပွင့်ပြီး သန္ဓေအောင်ပါသည်။ သန္ဓေအောင်ပြီးလျှင် ၎င်းသန္ဓေလေးမှ အတောင့်နုကလေး စတင်ဖြစ်ပေါ်ပါသည်။ အတောင့်နုကလေးသည် တဖြည်းဖြည်းရှည်ထွက်လာပြီး အတောင့်ထဲတွင် ပဲစေ့ဖြစ်လာမည့် ချိုရည်ကြည်များ ဖြစ်ပေါ်ပါသည်။ ပဲတောင့်ကြီးထွားလာသည်နှင့်အမျှ ပဲစေ့များသည်လည်း နို့ရည်ကြည်၊ နို့ရည်ပြစ်၊ နို့ရည်ခဲ၊ နောက်ဆုံး ပဲစေ့အဖြစ် အောင်မြင်လာပါသည်။ ဤသို့ ပဲတောင့် တစ်စတစ်စ ကြီးထွားဖွံ့ဖြိုးလာရန်နှင့် ပဲစေ့လေးများ တဖြည်းဖြည်း ကြီးထွားဖွံ့ဖြိုးလာရန်အတွက် အပင်တစ်ပင်လုံးမှချက်လုပ်သော အစာ၏ ၆၀ မှ ၇၀ ရာခိုင်နှုန်းကို အသုံးချသည်။<br><br>\r\n\r\n✔️ထိုအချိန်တွင် အစာအလိုအပ်ဆုံးအချိန်ဖြစ်သည်။ အစာချက်လုပ်ရန် တာဝန်ရှိသော အရွက်များသည် စိမ်းစို ကျန်းမာနေရန်လိုသည်။ မြေတွင်းအစိုဓာတ်နှင့် အာဟာရဓာတ် (နိုက်ထရိုဂျင်) လုံလောက်စွာရှိရန် လိုသည်။ အရွက်များဝါ၍ အစိုဓာတ်နှင့် အာဟာရဓာတ်ချို့တဲ့ပါက ပဲတောင့်လည်း သေးမည်၊ လုံးပိန် လုံးညှပ် အစေ့များလည်း ဖြစ်ပေါ်စေသည်။ စပါး၊ ပြောင်း၊ သီးနှံတို့သည် တစ်စေ့တစ်ဂရမ် ရရှိစေရန် နိုက်ထရိုဂျင်ဓာတ် ၁၅ ဂရမ် လိုအပ်သည်။ ပဲတီစိမ်းအစေ့တစ်ဂရမ် ရရှိစေရန်အတွက် နိုက်ထရိုဂျင်ဓာတ် ၃၉ ဂရမ် လိုအပ်သည်။ သီးနှံများတွင် အစေ့အတွက် နိုက်ထရိုဂျင်ဓာတ်လိုအပ်ချက်သည် ပဲတီစိမ်းတွင် အများဆုံးဖြစ်သည်။<br><br>\r\n\r\n✔️စပါးသီးနှံတွင် အစေ့တွင်းသို့ ပရိုတိန်းဓာတ် ၈ ရာခိုင်နှုန်းမှ ၁၀ ရာခိုင်နှုန်း ဖြည့်တင်းပြီးပါက ၎င်း၏တာဝန်ပြီးဆုံးသည်ဟု သတ်မှတ်သည်။ ပဲတီစိမ်းသည် ပန်းပွင့်ပြီး ပရိုတိန်းဓာတ် ၂၅ ရာခိုင်နှုန်းမှ ၃၅ ရာခိုင်နှုန်း ဖြည့်တင်းပြီးမှသာ ၎င်း၏တာဝန်ပြီးဆုံးသည်။ သို့အတွက် ပဲတီစိမ်းပန်းပွင့်ချိန်၊ သန္ဓအောင်ပြီးချိန်တွင် နိုက်ထရိုဂျင် အလိုအပ်ဆုံးအချိန်ဖြစ်သည်။ ပဲပင်၏အမြစ်များတွင် ပဲပင်အတွက် နိုက်ထရိုဂျင်အားဖြည့်ပေးမည့် ရိုင်ဇိုဘီယမ်းဘက်တီးရီးယားများသည် အဖုကလေးများသဖွယ် တွယ်ကပ်နေသည်။ ပဲပင်မှအစာကိုစုပ်ယူ၍ အသက်ရှင်သန်သည်။ ထို့နောက် လေထဲမှ နိုက်ထရိုဂျင် ဓာတ်ကို ဖမ်းယူ၍ ပဲပင်ကိုပို့ပေးသည်။ ရိုင်ဇိုဘီယမ်း ဘက်တီးရီးယားများသည် ပဲပင်သက်တမ်း တစ်လျှောက် လေထဲမှနိုက်ထရိုဂျင် နှစ်ကီလိုဂရမ်ဖမ်းယူ၍ ပဲပင်သို့ပို့ပေးသည်။<br><br>\r\n\r\n✔️ထိုသို့ ရိုင်ဇိုဘီယမ်း ဘက်တီးရီးယားများ၏ လေထဲမှနိုက်ထရိုဂျင်ကိုစုပ်ယူ၍ ပဲပင်သို့ပေးပို့ခြင်း လုပ်ငန်းကို ပန်းမပွင့်မီအချိန်ထိသာ လုပ်ဆောင်ပေးသည်။ ပန်းပွင့်ပြီးနောက်ပိုင်းတွင် ရိုင်ဇိုဘီယမ်း ဘက်တီးရီးယားများ သေကြေပျက်စီးသွားကြသည်။ ပဲပင်ပန်းပွင့်ပြီးချိန်တွင် အပင်၏ အစာပေးပို့မှုသည်လည်း အပင်အပေါ်ပိုင်းသို့သာ ပေးပို့မှုများပြီး အပင်အောက်ပိုင်းသို့ အစာပေးပို့မှု နည်းသွားပါသည်။ ထိုအကြောင်းကြောင့် ရိုင်ဇိုဘီယမ်း ဘက်တီးရီးယားများ ပဲပင်မှအစာကို မရရှိ ကြတော့သဖြင့် သေကြေပျက်စီးရခြင်းဖြစ်သည်။<br><br>\r\n\r\n✔️ပဲပင်ပန်းပွင့်ပြီးနောက်ပိုင်းတွင် ပဲပင်၏အောက်ပိုင်းရှိ သုံးပုံတစ်ပုံခန့်သောအရွက်များသည် ရင့်ရော်၍ ဝါပြီးကြွေကျသွားကြသည်။ အပင်တွင် အပင်အတွက်အစာချက်လုပ်ပေးမည့် အရွက် အရေအတွက် လည်း လျော့ပါးသွားရပြီဖြစ်သည်။ ပဲတီစိမ်းပင်တွင် နိုက်ထရိုဂျင်ဓာတ်အပြင် နောက်တစ်ခု အရေးပါ သည့်ဓာတ်မှာ ဘိုရွန်ဓာတ်ဖြစ်ပါသည်။ မြန်မာ့မြေများသည် အများအားဖြင့် ဘိုရွန်ဓာတ်ချို့တဲ့ တတ်ပါသည်။ မြေကြီး တစ်ကီလိုဂရမ်တွင် ဘိုရွန်ဓာတ် ငါးမီလီဂရမ်သာပါဝင်သည်ကို တွေ့ရှိရသည်။ ဘိုရွန်ဓာတ် လုံလောက်မှုရှိပါက အရွက်ကြွေမှုကာကွယ်သည်။ ဝတ်မှုန်ရှည်ထွက်မှုကောင်းသည်။ သီးတောင့်၊ အစေ့အောင်နှုန်းများစေသည်။ ဘိုရွန်ဓာတ်ချို့တဲ့ပါက ပရိုတိန်း တည်ဆောက်မှုနည်းပြီး အပွင့်အသီး ကြွေကျမှုများစေသည်။ ဝတ်မှုန်ရှင်သန်မှုကာလ တိုတောင်းစေသည်။ ပန်းပွင့်ပြီး သီးတောင့်တည်ချိန်တွင် ယူရီးယားမြေသြဇာ တစ်ဇွန်း၊ ဘိုရွန်(လက်ချား) ၄ဇွန်းခွဲ အမှုန့်ထောင်း၍ ရေ ဂါလံ (၂၀) နှင့် ရောဖျော်ပြီး ဖျန်းပေးနိုင်ပါကလုံလောက်ပါသည်။ ဘိုရွန်ဖျန်းပေးခြင်းဖြင့် ပဲတီစိမ်းတွင် ၂၅ ရာခိုင်နှုန်း အထွက်တိုးသည် ဟု သုတေသနက ထောက်ခံထားပါသည်။<br><br>\r\n\r\n✔️ပဲတီစိမ်း ပန်းပွင့် သန္ဓေအောင်ပြီး အတောင့်များ အဆင့်ဆင့်ကြီးထွားဖွံ့ဖြိုးဖြစ်ပေါ်ချိန်နှင့် အစေ့များ အဆင့်ဆင့်ကြီးထွားဖွံ့ဖြိုးမှုဖြစ်ပေါ်ချိန် နိုက်ထရိုဂျင်ဓာတ်အလိုအပ်ဆုံးအချိန်တွင် နိုက်ထရိုဂျင် ဖြည့်တင်းပေးနေသည့် ရိုင်ဇိုဘီယမ် ဘက်တီးရီးယားများကလည်း သေကြေပျက်စီးကြသည်။ ပဲတောင့်၊ ပဲစေ့များ၏ ကြီးထွားဖွံ့ဖြိုးမှုအတွက် အစာချက်လုပ်ပေးပို့ရမည့် အရွက်သုံးပုံတစ်ပုံမှာလည်း ရင့်ရော်ကြွေကျကုန်ကြသည်။ ထိုအချိန်တွင် ပဲတောင့်၊ ပဲစေ့များ ကြီးထွားဖွံ့ဖြိုးရန်အတွက် လိုအပ်နေသော အစာအာဟာရ (နိုက်ထရိုဂျင်ဓာတ်)ကို ဖြည့်စွက်မပေးနိုင်ပါက ပဲတောင့်၊ ပဲစေ့ လုံးပိန်လုံးညှပ်သာရမည်ဖြစ်သည်။ သို့ပါ၍ ပဲတီစိမ်းပန်းပွင့်ပွင့်ပြီးချိန်တွင် နိုက်ထရိုဂျင်ဓာတ် အချိုးများပါသော ရွက်ဖျန်းမြေသြဇာကိုမဖြစ်မနေ သုံးကြိမ်ခန့် ပက်ဖျန်းပေးရန်လိုအပ်ကြောင်း တိုက်တွန်းလိုက်ရပါသည်။<br><br>\r\n\r\nSources : စိုက်ပျိုးရေးဦးစီးဌာန', '', '19-02-2024'),
(43, '“ရာသီဥတုနှင့် စိုက်ပျိုးချိန်၏ မြေပဲအထွက်နှုန်းကို လွှမ်းမိုးနေမှုများ”', 'IMG-65d36db6686195.83324136.jpeg', '🌿🥜🌿🥜🌿🥜🌿🥜🌿🥜🌿<br><br>\r\n\r\n🔸မြေပဲသီးနှံဟာ ဆီထွက်သီးနှံများအနက် စိုက်ဧကများပြီး တစ်ဧကမှ ဆီပိဿာရာကျော်ထွက်နိုင်တဲ့ သီးနှံလည်းဖြစ်ပါတယ်။ မြေပဲသီးနှံဟာ ပြည်တွင်းစားသုံးမှုအပြင် ပြည်ပတင်ပို့မှုမှာလည်း နေရာရလာတဲ့အတွက် လွန်ခဲ့သောငါးနှစ်ကထက် ဧကနှစ်သိန်းနီးပါး တိုးချဲ့စိုက်ပျိုးလာတာ တွေ့ရပါတယ်။ မြေပဲစိုက်ဧကများ တိုးတက်လာသော်လည်း မြေပဲသီးနှံ အောင်ဧကနဲ့အထွက်နှုန်းဟာ ရည်မှန်းချက်မပြည့်မီတာ တွေ့ရပါတယ်။ အထူးသဖြင့် မြေပဲစိုက်ဧကများတဲ့ ဧရာဝတီ၊ စစ်ကိုင်း၊ မန္တလေး၊ မကွေး၊ ပဲခူးဒေသတွေမှာ ပိုတွေ့ရပါတယ်။\r\n<br><br>\r\n🔸မြေပဲသီးနှံအောင်ဧကနဲ့ အထွက်နှုန်းလျော့နည်းမှုကို ဆန်းစစ်ကြည့်ရင် တောင်သူလယ်သမားကြီးများ ထင်မထားတဲ့ ရာသီဥတုနဲ့ စိုက်ပျိုးချိန်က ကြိုးကိုင်မှုရှိနေတာကို တွေ့ရမှာဖြစ်ပါတယ်။ အထွက်ကောင်းတဲ့မျိုး၊ မှန်ကန်တဲ့နည်းစနစ်တွေ ဘယ်လိုပင်ကောင်းစေကာမူ ရာသီဥတုနဲ့ စိုက်ပျိုးချိန်ရဲ့ လွှမ်းမိုးနေမှုခံနေရရင် ကောင်းမွန်တဲ့မြေပဲအထွက်ကို မရရှိနိုင်ပါ။ မြန်မာနိုင်ငံတွင် မြေပဲကို စိုက်ပျိုးရာသီအလိုက် မိုးကြိုမြေပဲ (စကမြေပဲ)၊ မိုးမြေပဲ၊ မိုးနှောင်းသီးထပ်မြေပဲ၊ ကိုင်းကျွန်းမြေပဲ၊ ဆောင်းသီးထပ်မြေပဲလို့ ခေါ်ဝေါ်ကြပါတယ်။<br><br>\r\n\r\n🔸မြေပဲပင်ရဲ့ အပင်တည်ဆောက်မှုပုံသဏ္ဌာန်အရလည်း ပင်ထောင်မြေပဲ၊ ပင်ပြန့်မြေပဲလို့ခေါ်ဝေါ် လေ့ရှိကြတာကိုတွေ့ရပါတယ်။ ပင်ထောင်မြေပဲမျိုးများဟာပင်ပြန့်မြေပဲမျိုးများထက် ရာသီဥတု ပြောင်းလဲမှုဒဏ်ကို ပို၍ခံနိုင်ကြတာ တွေ့ရပါတယ်။ မြေပဲပင်ရဲ့ရှင်သန်ကြီးထွားဖြစ်ထွန်းအောင်မြင်မှုကို မြေပဲပင်သက်တမ်းတစ်လျှောက်ဖြစ်ပေါ်တဲ့အပူချိန်က လွှမ်းမိုးထားပါတယ်။ မြေပဲပင်ဖြစ်ထွန်း ကြီးထွားစဉ် တစ်လျှောက် အပူချိန်(၂၀) ဒီဂရီစင်တီဂရိတ်ကနေ (၃၀) ဒီဂရီစင်တီဂရိတ်ရရှိရန် လိုအပ်ပါတယ်။ အပူချိန် (၂၀) ဒီဂရီစင်တီဂရိတ်ထက်နိမ့်ကျပါက အပင်ကြီးထွားဖွံ့ဖြိုးမှုနှေးကွေး စေပါတယ်။ အပူချိန် (၃၅) ဒီဂရီစင်တီဂရိတ်ထက်ကျော်လွန်ပါက ပန်းပွင့်တာကို များစွာထိခိုက်စေပါတယ်။<br><br>\r\n\r\n🔸မြေပဲပင်ငယ်စဉ် အပူချိန်နိမ့်ကျခြင်းနဲ့ ကြုံတွေ့ပါက အပင်ကြီးထွားဖွံ့ဖြိုးမှုကို များစွာထိခိုက်စေတယ်လို့ ဆိုပါတယ်။ အပူချိန်ဟာ မြေပဲပင်ပန်းပွင့်တာကိုများစွာလွှမ်းမိုးထားပါတယ်။ ညအပူချိန်(၁၃) ဒီဂရီ စင်တီဂရိတ်ကနေ (၁၅) ဒီဂရီစင်တီဂရိတ်သာရှိမယ်ဆိုပါက ပန်းပွင့်အနည်းဆုံးပွင့်ပြီး ညအပူချိန် (၂၂) ဒီဂရီစင်တီဂရိတ်ကနေ (၂၅) ဒီဂရီစင်တီဂရိတ် ရောက်ရှိပါက တစ်ပင် အပွင့်ပေါင်း ၁၇၀ အထိ ပွင့်နိုင်ကြောင်း တွေ့ရပါတယ်။ ညအပူချိန် (၁၈) ဒီဂရီစင်တီဂရိတ်နဲ့ နေ့အပူချိန် (၂၂) ဒီဂရီစင်တီဂရိတ် ရှိပါက ပန်းအနည်းငယ်သာ ပွင့်နိုင်ပြီး စွယ်လုံးဝမဖြစ်ပေါ်နိုင်ပါ။ ညအပူချိန်(၂၀) ဒီဂရီစင်တီဂရိတ်နဲ့ နေ့အပူချိန် (၃၀) ဒီဂရီစင်တီဂရိတ်ရှိပါက မြေပဲအထွက် အကောင်းဆုံးကို ရရှိနိုင်ပါတယ်။ ပုံမှန်ကြီးထွား၊ အပွင့်အရေအတွက်များ၊ စွယ်ဖြစ်ထွန်းမှုကောင်း၊ အသီးတင်မှု၊ ရင့်မှည့်မှုစွမ်းအားပြည့် ရရှိစေပါတယ်။ <br><br>\r\n\r\n🔸အပူချိန် (၁၅)ဒီဂရီစင်တီဂရိတ်နဲ့ (၄၀) ဒီဂရီစင်တီဂရိတ်မှာ အပင်ကြီးထွားဖြစ်ထွန်းမှု ရပ်တန့်စေ ပါတယ်။ နေ့အပူချိန် (၄၀) ဒီဂရီစင်တီဂရိတ်နဲ့ ညအပူချိန် (၃၅) ဒီဂရီစင်တီဂရိတ်မှာမူ အပွင့်ပွင့်တာ လုံးဝမရှိတော့ပါ။ အပူချိန် (၁၅) ဒီဂရီစင်တီဂရိတ်ထက်ကျော်လွန်ပါက သာမန်ထက် ပင်စည်ရှည်ထွက် လာပါတယ်။ ပျမ်းမျှအပူချိန် (၂၁) ဒီဂရီစင်တီဂရိတ်မှာ ပန်းပွင့်ရက်အရှည်ကြာဆုံး ဖြစ်ပေါ်စေပြီး (၃၃) ဒီဂရီစင်တီဂရိတ်မှာ ပန်းပွင့်ရက်အစောဆုံးကိုဖြစ်ပေါ်စေသော်လည်း ပန်းဆက်ပွင့်နေစေကာမူ အသီးတင်မှု အလွန်နည်းသွားတာကိုတွေ့ရပါတယ်။ ဒါကြောင့်အပူချိန်ဟာ မြေပဲပင်ကြီးထွားမှုကို အားပေးခြင်း၊ အပွင့်အရေအတွက် အနည်း၊ အများ၊ ပန်းစတင်ပွင့်ရန်ရက် ကြာညောင်းမှု၊ စွယ်ဖြစ်ထွန်း နိုင်မှု၊ မျိုးအောင်မှုတို့ကို တိုက်ရိုက်အကျိုးသက်ရောက်မှုရှိနေသဖြင့် တောင်သူ လယ်သမားကြီးများ မြေပဲအထွက်တိုးအောင် ဆောင်ရွက်ရာမှာ အပူချိန်ရဲ့ အရေးပါမှုကို သတိပြုကြဖို့လိုအပ်ပါတယ်။ <br><br>\r\n\r\n🔸မြေပဲအထွက်နှုန်းတိုးစေဖို့လွှမ်းမိုးနေတဲ့ အချက်တစ်ချက်က အစိုဓာတ်နဲ့ စိုက်ပျိုးချိန်ဖြစ်ပါတယ်။ မြေပဲပင်အောင်မြင်ဖြစ်ထွန်း အထွက်နှုန်းကောင်းမွန်ရေးမှာမြေတွင်းအစိုဓာတ်ပေါ်မှာ များစွာ တည်မှီနေပါတယ်။ အစိုဓာတ်အလုံအလောက် ရရှိမှုဟာလည်းစိုက်ပျိုးချိန်မှန်ကန်မှုအပေါ် မူတည်နေပါ တယ်။ မြန်မာနိုင်ငံတွင်း စိုက်ပျိုးတဲ့မြေပဲ ဧရိယာအားလုံးဟာ မိုးရေနဲ့ မိုးရေကျန်မြေတွင်း အစိုဓာတ် ပေါ်မှာ အဓိကမှီခိုစိုက်ပျိုးကြပါတယ်။<br><br>\r\n\r\n🔸မိုးရာသီစိုက်မြေပဲခင်းများဟာ အများအားဖြင့် သဲဆန်တဲ့မြေမျိုးမှာ စိုက်ပျိုးကြပြီး မိုးနည်းရပ်ဝန်း ဒေသများ ဖြစ်သဖြင့် မိုးရေလုံလောက်စွာမရရှိဘဲ အထွက်နည်းလေ့ရှိတာကို တွေ့ရပါတယ်။ ဆောင်းရာသီစိုက်မြေပဲတွေဟာ နုန်းမြေ၊ နုန်းဆန်တဲ့မြေဖြစ်ပြီးအစိုဓာတ်အသင့်အတင့် ထိန်းနိုင်တဲ့ အတွက် အထွက်နှုန်းကောင်းတာတွေ့ရပါတယ်။ မြေပဲအထွက်နှုန်းတိုးရန်မိုးရေချိန်အနည်း၊ အများ အပြင် မိုးရွာသွန်းတဲ့ရက်ကြာမှုဟာလည်း အရေးပါပါတယ်။ တစ်ခါတစ်ရံ မိုးရေချိန်နည်းသော်လည်း နည်းနည်းနဲ့ ရက်များများရွာနေပါကလည်းမြေပဲအထွက်ကောင်းတာကို တွေ့ရပါတယ်။ မိုးမြေပဲကို မေလမှာ စိုက်ပျိုးလေ့ရှိရာ မိုးဦးစောစောဖြင့် မြေပြင်ပြီးမျိုးစေ့ချနိုင်တဲ့အထိ ရွာသွန်းပါက တောင်သူလယ်သမားများ အဆင်ပြေကြပါတယ်။ <br><br>\r\n\r\n🔸မြေပဲဟာ အစိုဓာတ်အနည်းငယ်ရရုံဖြင့် အစေ့အညှောက်ပေါက်နိုင်ပါတယ်။ ပေါက်လာတဲ့ အညှောက် ကလေးဟာ မြေတွင်းအစိုဓာတ် ဆက်လက်တည်ရှိမှုအပေါ်တည်၍ဆက်လက်ကြီးထွားခြင်း၊ သေဆုံးခြင်း ဖြစ်ပေါ်ပါတယ်။ အစိုဓာတ်သင့်တင့်ပါက (၅)ရက်သားမှာ အမြစ်ဟာ မြေတွင်းသို့ (၁၀) စင်တီမီတာမှ (၁၆) စင်တီမီတာအထိ ရှင်သန်ရှည်ထွက်လာပါတယ်။ (၁၂) ရက်သားမှာ (၃၁) စင်တီမီတာ အထိ ရှည်ထွက်လာပါတယ်။ ၎င်းအချိန်မှာ အရွက်လေးရွက်သာ ထွက်နိုင်ပါသေးတယ်။ အပေါ်ယံ မြေဆီလွှာတွင်း အစိုဓာတ်ဟာ ဆုတ်ယုတ်တဲ့အခြေအနေဆိုရင် ပင်ပြန့်မြေပဲမျိုးများရဲ့ အမြစ်ဟာ အနက်စင်တီမီတာ (၂၀၀) အထိ ဆင်းနိုင်ပြီး ပင်ထောင်မြေပဲများရဲ့ အမြစ်ဟာ အနက်စင်တီမီတာ (၁၇၀) အထိဆင်းနိုင်တာတွေ့ရပါတယ်။<br><br>\r\n\r\n🔸အပေါ်ယံမြေလွှာမှာ အစိုဓာတ်လုံလောက်နေပါက အမြစ်ဟာ အောက်ကိုလည်း နက်နက်မဆင်း၊ ဘေးကိုလည်း ပြန့်မထွက်ဘဲ ရှိနေပါတယ်။ မြေဆီလွှာအတွင်း အစိုဓာတ်လျော့နည်းပါက ပင်စည် ရှည်ထွက်နှုန်းနှေးခြင်း၊ ကိုင်းများတိုခြင်း၊ အရွက်များကြုံလှီခြင်း၊ အဆစ်များတိုခြင်း၊ ပန်းဖူးဖြစ်ပေါ်မှု တစ်ပတ်ခန့်နောက်ကျခြင်း၊ ပန်းပွင့်မှုအဟန့်အတားဖြစ်ခြင်း၊ အပွင့်အရေအတွက် လျော့နည်းစေခြင်း၊ မြေပဲစွယ်ဟာ မြေဆီလွှာအတွင်းထိုးမဆင်းဘဲ ကန်းသွားခြင်းများကြောင့် မြေပဲအထွက် သိသိသာသာကျဆင်းသွားပါတယ်။ အစိုဓာတ်ရှိရန် အဓိကအဆင့်များမှာ ပင်ပိုင်းကြီးထွားချိန်၊ ပန်းပွင့်ချိန်၊ အစေ့တည်ချိန်တို့ ဖြစ်ပါတယ်။ ရေချိုလွယ်လွယ်ရရှိနိုင်ပါကဒီအဆင့်တွေမှာ မှုတ်ရေတစ်ကြိမ်စီ သွင်းနိုင်ပါက အထွက်သေချာပါတယ်။ ထိုအဆင့်တွေမှာ အစိုဓာတ်နည်းတာဟာ တခြားအဆင့်အားလုံးမှာ အစိုဓာတ်ဆုတ်ယုတ်ခြင်းထက် အထွက်လေး၊ ငါးဆ ပို၍ထိခိုက်နိုင်ပါတယ်။ မြေပဲစွယ်ဟာ မြေပဲတောင့်ဖြစ်ဖို့ မြေတွင်းအစိုဓာတ်နဲ့ အမှောင်ထုလိုအပ်ပါတယ်။ ဒါကြောင့် မြေပဲစွယ်ဟာ မြေဆီလွှာအတွင်း ထိုးဝင်ပါတယ်။ မြေဆီလွှာအတွင်းအနက် ၁ မှ ၁. ၅ စင်တီမီတာရောက်ရင် စွယ်ထိပ်မှာ အတောင့်စတင်ဖြစ်ပေါ်ပြီးအဆင့်ဆင့်ကြီးထွားပါတယ်။<br><br>\r\n\r\n🔸အဲဒီအချိန်မှာ မြေတွင်းအစိုဓာတ်ယုတ်လျော့ပါက မြေရဲ့အပူချိန်တက်လာပြီး မြေပဲဆန်ပြည့်ဖြိုးမှုကို ထိခိုက်စေပါတယ်။ လုံးပိန်လုံးညှက်များစေပါတယ်။ မိုးများလွန်းပါကလည်း ရေဝပ်ပြီးရောဂါဖြစ်စေခြင်း၊ မြေကျပ်ပြီး စွယ်ထိုးဝင်ရန်ခက်ခဲခြင်း၊ မြေဆီလွှာတွင်းမြေပဲတောင့် အညှောက်ပေါက်ခြင်း၊ နုတ်သိမ်းရာ မှာ မြေကျပ်ပြီး နုတ်ရခက်ခြင်း၊ အတောင့်များ ပြတ်ကျန်ခြင်းတို့ ဖြစ်စေပါတယ်။ ဒါဆိုရင် မြေပဲအထွက် ကောင်းအောင်အပူချိန်ရော၊ စိုက်ပျိုးချိန် အစိုဓာတ်ပါ ကိုက်ညီအောင် ဘယ်အချိန် စိုက်ရမလဲ? မိုးရာသီမှာ မိုးမြေပဲကိုပင်ထောင်နဲ့ ပင်ပြန့်မျိုးများစိုက်နိုင်ပါတယ်။ မေလလယ်၊ ဇွန်လ၊ ဇူလိုင်လဆန်း အထိ စိုက်ပျိုးသင့်ပါတယ်။ မုတ်သုံမိုးနောက်ကျတဲ့ဒေသတွေမှာ ဇူလိုင်လကုန်အထိ စိုက်သင့်ပါတယ်။<br><br>\r\n\r\n🔸တောင်ပေါ်ဒေသ တောင်ယာတွေမှာ စကပဲအဖြစ် သြဂုတ်လနဲ့ စက်တင်ဘာလမှာ အပြီးစိုက်သင့် ပါတယ်။ ဇူလိုင်လဟာ မိုးအမြဲခေါင်တတ်လို့ မိုးဦးမြေပဲအဖြစ်စိုက်ပျိုးမဲ့အစား မိုးလယ် မြေပဲအဖြစ် သြဂုတ်လစိုက်ပျိုးတာဟာ အထွက်ပိုကောင်းစေပါတယ်။ ဆောင်းရာသီ ယာသီးနှံနဲ့ တောင်ယာမြေပဲကို စက်တင်ဘာလနဲ့ အောက်တိုဘာလမှာအပြီးစိုက်ပျိုးသင့်ပါတယ်။ မြစ်ရေ၊ချောင်းရေ လျှံတက်၍ ရေကျစိုက်ပျိုးတဲ့ ကိုင်းကျွန်းမြေပဲကို အောက်တိုဘာလနဲ့ နိုဝင်ဘာလမှာ အပြီးစိုက်ပျိုးသင့် ပါတယ်။ ပဲခူး၊ ဧရာဝတီ၊ ရန်ကုန်တိုင်းဒေသကြီး၊ မွန်၊ ကရင်၊ ရခိုင်ဒေသတွေမှာ စပါးသီးနှံအပြီး ဆောင်းသီးထပ်မြေပဲကိုအောက်တိုဘာလလယ်မှ နိုဝင်ဘာလ၊ ဒီဇင်ဘာလလယ်အပြီး စိုက်ပျိုးသင့် ပါတယ်။ မိုးကြိုရေသွင်းစိုက်ပျိုးတဲ့ စစ်ကိုင်း၊ မန္တလေး၊ မကွေး၊ ပဲခူးတိုင်းဒေသကြီးမြောက်ပိုင်း ဒေသတွေ မှာ ဖေဖော်ဝါရီနဲ့ မတ်လမှာ အပြီးစိုက်ပျိုးသင့်ပါတယ်။ အချို့ဒေသတွေမှာ သင်္ကြန်မိုးအမိအရဖမ်း၍ စိုက်ပျိုးကြတာကို တွေ့ရပါတယ်။<br><br>\r\n\r\n🔸ထို့ကြောင့် တောင်သူလယ်သမားကြီးများက မြေပဲအထွက်ကောင်းရအောင် မြေပဲအထွက်နှုန်းကို လွှမ်းမိုးနေတဲ့ ရာသီဥတု၊ အပူချိန်၊ စိုက်ပျိုးချိန် နှင့် အစိုဓာတ်ပါ ကိုက်ညီအောင် စိုက်ပျိုးကြဖို့ ဗဟုသုတအဖြစ် ရေးသားတင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\nSources : အောင်ဆန်း(စိုက်ပျိုးရေး)<br><br>\r\n\r\nမြန်မာတောင်သူကြီးများဂျာနယ်', '', '19-02-2024'),
(44, '“ခရမ်းချဉ် ၊ အာလူးတွင် ဖြစ်ပွားတတ်သောရောဂါများ နှင့် ကာကွယ်ကုသဆေးများ”', 'IMG-65d36dfe35e1e5.45738896.png', '🍅🥔🍅🥔🍅🥔🍅🥔🍅🥔🍅<br><br>\r\n\r\nဖြူစေရီယမ် ပင်ညှိုးရောဂါ<br>\r\n-----------------------<br><br>\r\n\r\n - ဖြူစေရီယမ်မှိုကြောင့်ဖြစ်သည်။<br><br>\r\n\r\n - အပင်ငယ်စဉ်တွင် အပင်ပုခြင်း၊ အရွက်များဝါ၍ အောက်သို့ကုပ်ခြင်း၊ ပင်စည်အတွင်း အစာရေကြောစည်းများညိုခြင်းများဖြစ်ကာ နောက်ဆုံးတွင် အပင်ညှိုး၍ သေသွားသည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- ကာဗာ၊ ဒိုင်ဇီ။ (အပင်ခြေမြေပြင်အထိပက်ဖျန်းပေးရန်)<br><br>\r\n\r\nခါးရိရောဂါ<br>\r\n---------<br><br>\r\n\r\n - မျိုးစေ့မှ ပေါက်ခါစ အပင်ငယ်၏ ပင်စည်တွင် ရေစိုနာကွက်များဖြစ်ပေါ်လာသည်။<br><br>\r\n\r\n - ၎င်းရေစိုနာကွက်များ အညိုရောင်သို့ပြောင်းသွားပြီး အပင်အစိတ်အပိုင်းများသို့ ပျံ့နှံ့၍ အပင်ပေါက်များသေသွားသည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- ဘာလီဆိုဒ်။<br><br>\r\n\r\nမိုစေ့ဗိုင်းရပ်စ်ရောဂါ<br>\r\n-----------------<br><br>\r\n\r\n - စုပ်စားပိုးများမှ ရောဂါသယ်ဆောင်လာသော ဗိုင်းရပ်စ်ရောဂါ ဖြစ်သည်။<br><br>\r\n\r\n - အရွက်များတွင် မညီမညာကွက်ကြားဖြစ်ခြင်း၊ အရွက်များတွန့်လိမ်နေခြင်း၊ အပင်များဝါ၍ပုနေခြင်းကိုတွေ့ရသည်။<br><br>\r\n\r\n - ရောဂါတွေ့ရှိပါမှ ကုသ၍မရပါ။ စုပ်စားပိုးများကို အချိန်မှီကြိုတင်ကာကွယ်နှိမ်နင်းပေးရပါမည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- စုပ်စားပိုးများကို ဦးစွာနှိမ်နင်းရန် ကေလာ၊ နိုးဝမ်း။<br><br>\r\n\r\nမြစ်ဖုနီမတုတ်ရောဂါ<br>\r\n------------------<br><br>\r\n\r\n - မြစ်ဖုနီမတုတ်ကြောင့်ဖြစ်သည်။<br><br>\r\n\r\n - ရောဂါကျရောက်ပါက အပင်ပုပြီး ညှိုးလာသည်။<br><br>\r\n\r\n - နှုတ်ကြည့်ပါက အမြစ်တွင် ပုတီးစေ့သဖွယ် အဖုများစွာကို တွေ့ရသည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- ဒီပါ။<br><br>\r\n\r\nဖားဥမှိုရောဂါ<br>\r\n------------<br><br>\r\n\r\n - အရွက်ရင့်များတွင်ကျရောက်ပြီး မျက်နှာပြင်တွင် ပေါင်ဒါမှုန့်ဖြူးထားသကဲ့ အဖြူရောင်မှိုမျှင်များ ကိုတွေ့ရပြီးနောက် ရောဂါပြင်းထန်လာပါက အရွက်များဝါ၍ကြွေကျသည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- ဟက်ဇာဂွန်၊ ဒိုင်ဇီ၊ ဇိုလာ။<br><br>\r\n\r\nဘက်တီးရီးယားပင်ညှိုးရောဂါ<br>\r\n---------------------------<br><br>\r\n\r\n - အရွက်နုမှစတင်ကာ မခြောက်ဘဲ စိမ်းပြီး တစ်ပင်လုံး ညှိုးသည်ကိုတွေ့ရသည်။<br><br>\r\n\r\n - ရောဂါရပင်စည်တွင် မြစ်မွှာများဖြစ်ပေါ်ပြီး ပင်စည်ကိုခွဲကြည့်ပါက အတွင်းသား အဝါရောင်မှ အညိုရောင်သို့ပြောင်းနေသည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- ကျူပရိုမက်စ်၊ ကာစင်။<br>\r\n\r\nစောပင်နာကျရောဂါ<br>\r\n------------------<br><br>\r\n\r\n - အရွက်၊ပင်စည်နှင့် အသီးများပေါ်တွင် ညိုမဲနေသော အပြောက်များကို တွေ့ရမည်။<br><br>\r\n\r\n - အေး၍စွတ်စိုထိုင်းမှိုင်းသော ရာသီဥတုအခြေအနေတွင် ရောဂါကျရောက်မှု ပြင်းထန်သည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- ဘင်ဇိုကာ၊ ဒိုင်ဇီ ။<br><br>\r\n\r\nနှောင်းပင်နာကျရောဂါ<br>\r\n--------------------<br><br>\r\n\r\n - အရွက်နှင့်ပင်စည်များပေါ်တွင်အညိုအမဲအနာကွက်များတွေ့ရပြီးတစ်ချိန်တည်း အရွက်၏ အောက်မျက်နှာပြင်တွင် မီးခိုရောင်မှိုစုများကို တွေ့ရမည်။<br><br>\r\n\r\n - တစ်ပင်လုံးအရွက်များ ညိုမဲတွန့် လိမ်၍ အပင်သေသည်။<br><br>\r\n\r\n - အသီးနှင့်ဥများတွင်လည်း ရောဂါကျရောက်သည်။<br><br>\r\n\r\n အသုံးပြုရမည့်ဆေး- ဘင်ဇိုကာ၊ တိုက်တန်၊ စူပါမော့၊ ဆိုင်မိုဇက်၊ ဆိုင်မောက်၊ မက်တယ်လဇီး။<br><br>\r\n\r\nSources : Plants & Diseases (သီးနှံကာကွယ်ရေး)', '', '19-02-2024');
INSERT INTO `knowledge` (`kid`, `knowledgeTitle`, `knowledgePhoto`, `knowledgeDescript`, `knowledgeColor`, `CurrentDate`) VALUES
(45, '“မြေပဲသီးနှံစိုက်ပျိုးထုတ်လုပ်မှု အောင်မြင်ရေးအတွက် အဓိကအချက်များ”', 'IMG-65d36e4a6f1990.37769741.jpeg', '🥜🥜🥜🥜🥜🥜🥜🥜🥜🥜<br><br>\r\n\r\n⏭မြေပဲသီးနှံသည် ရေမြေဒေသရာသီ ကွဲပြားခြားနားသော အခြေအနေအမျိုးမျိုးမှာ ဖြစ်ထွန်းနိုင်သော သီးနှံတစ်မျိုးဖြစ်သည်။ သို့သော် ရာသီအလိုက်သော် လည်းကောင်း၊ ဒေသအလိုက်သော်လည်းကောင်း တစ်ဧကအထွက်နှုန်းမှာတော့ ကွာခြားသည်။ မည်သည့်ဒေသရေမြေအခြေအနေမှာဖြစ်စေ စိုက်ပျိုးကုန်ကျ စရိတ်ထက် အထွက်နှင့်ဝင်ငွေက သာလွန်မှသာ စိုက်ပျိုးထုတ်လုပ်မှု အောင်မြင်သည်ဟုဆိုရမည်။<br><br>\r\n\r\n⏭ဆီထွက်သီးနှံတစ်မျိုးဖြစ်သော နှမ်းလျင်သီးနှံနှင့် နှိုင်းယှဉ်လျှင် စိုက်ပျိုးထုတ်လုပ်မှုကုန်ကျစရိတ် မြင့်မားသည်။ သို့သော် မျိုးစေ့မှ အထွက်ပြန်ရသည့် ပမာဏအချိုးမှာမူ နှမ်းလျင်သီးနှံထက် နည်းပါးပြန်သည်။ ထို့ကြောင့် ပိုမိုဂရုစိုက်ကာ စနစ်တကျလုပ်ကိုင်ဖို့လိုကြောင်း ပြောလိုရင်းဖြစ်ပါသည်။<br><br>\r\n\r\n၁။ မျိုးရွေးချယ်ခြင်း <br><br>\r\n\r\n ဒေသနှင့် ကိုက်ညီဖြစ်ထွန်းသည့်မျိုးကို ရွေးချယ်အသုံးပြုရန်ဖြစ်သည်။ အပင်ပေါက် ၈၀ ရာခိုင်နှုန်းနှင့် အထက်ရှိသည့်မျိုးကို စိုက်ပျိုးသင့်သည်။ အထွက်နှုန်းကောင်းမွန်သည့်မျိုးများကို သုတေသနပြု ထုတ်ဝေထားသည်။ ဆင်းပဒသော-၆၊ ဆင်းပဒေသာ-၇ နှင့် ဆင်းပဒေသာ-၁၁ မျိုးများကို ကျယ်ကျယ်ပြန့်ပြန့် စိုက်ပျိုးလျက်ရှိကြောင်းသိရသည်။ ယခုအခါ ဆင်းပဒေသာ-၁၂ နှင့် ဆင်းပဒေသာ-၁၃ စသည့် အခြားမျိုးသစ်များကိုလည်း စိုက်ပျိုးနိုင်ပြီဖြစ်သည်။ <br><br>\r\n\r\nဆင်းပဒေသာ - ၆<br><br>\r\n\r\n အပင်ပုံစံသည် ပင်ထောင်မျိုးဖြစ်သည်။ အပင်သက်တမ်းမှာ ၁၀၅ ရက် မှ ရက် ၁၁၀ ဖြစ်သည်။ တစ်ပင်ပါအောင်တောင့်မှာ ၁၅ မှ ၂၀ ဖြစ်သည်။ တစ်တောင့်ရှိအစေ့မှာ ၁ မှ ၂စေ့ ဖြစ်ကာ အစေ့ခွံအရောင်မှာ ပန်းရောင်ဖြစ်သည်။ ထူးခြားသည်မှာ ရေငတ်ခံနိုင်သည်။<br><br>\r\n\r\nဆင်းပဒေသာ - ၇ <br><br>\r\n\r\n အပင်ပုံစံသည် ပင်ထောင်မျိုးဖြစ်သည်။ အပင်သက်တမ်းမှာ ရက် ၉၀ မှ ၉၅ ရက်နှင့် တစ်ပင်ပါအောင်တောင့်မှာ ၁၅ မှ ၂၀ ဖြစ်သည်။ တစ်တောင့်ရှိအစေ့မှာ ၁ မှ ၂ နှင့် အစေ့ခွံအရောင်- ပန်းရောင်ဖြစ်ကာ အဆံထွက်ရာခိုင်နှုန်း ၇၄% ဖြစ်သည်။ <br><br>\r\n\r\nဆင်းပဒေသာ - ၁၁<br><br>\r\n\r\n အပင်ပုံစံမှာ ပင်ထောင်မျိုးပင်ဖြစ်သည်။ အပင်သက်တမ်း ရက် ၁၀၀ မှ ၁၀၅ ရက်နှင့် နှုတ်သိမ်းနိုင်သည်။ တစ်ပင်ပါ အောင်တောင့်မှာ ၂၀ မှ ၂၅ ရှိပြီး အဆံထွက်ရာခိုင်နှုန်း ၇၄% ဖြစ်သည်။<br><br>\r\n\r\nဆင်းပဒေသာ - ၁၂<br><br>\r\n\r\n အပင်ပုံစံမှာ ပင်ထောင်မျိုးပင်ဖြစ်သည်။ အပင်သက်တမ်း ၁၀၅ ရက် မှ ရက် ၁၁၀ နှင့် နှုတ်သိမ်းနိုင်သည်။ တစ်ပင်ပါ အောင်တောင့်မှာ ၁၅ မှ ၂၅ ရှိပြီး အဆံထွက်ရာခိုင်နှုန်း ၇၂% ဖြစ်သည်။ ရေငတ်ဒဏ်ခံနိုင်ပြီး မိုးရွာသွန်းမှု နည်းပါးသော အပူပိုင်းဒေသနှင့် သင့်တော်ကြောင်းသိရသည်။ <br><br>\r\n\r\nဆင်းပဒေသာ - ၁၃ <br><br>\r\n\r\n အပင်ပုံစံမှာ ပင်ထောင်မျိုးပင်ဖြစ်သည်။ အပင်သက်တမ်း ၁၀၅ ရက် မှ ရက် ၁၁၀ ရက်နှင့် နှုတ်သိမ်းနိုင်သည်။ တစ်ပင်ပါအောင်တောင့်မှာ ၂၀ မှ ၃၀ ရှိပြီး အဆံထွက်ရာခိုင်နှုန်း ၇၄% ဖြစ်သည်။ ဒေသမရွေးသင့်တော်သောမျိုးဖြစ်ကြောင်း သိရသည်။<br><br>\r\n\r\n၂။ စိုက်ပျိုးနည်းစနစ်မှန်ကန်ခြင်း <br><br>\r\n\r\n စိုက်ပျိုးနည်းစနစ်တွင် မြေဆီလွှာအခြေအနေ၊ စိုက်ပျိုးချိန်၊ မျိုးစေ့နှုန်း၊ အတန်းအပင်အကွာအဝေး၊ မျိုးစေ့အတိမ်အနက် နှင့် ရေပေးသွင်းခြင်းတို့သည် အရေးပါသောလုပ်ငန်းများဖြစ်သည်။ <br><br>\r\nမြေဆီလွှာအခြေအနေ..... <br><br>\r\n\r\n နုံးမြေနှင့် သဲနုံးမြေတို့သည် မြေပဲစိုက်ရန် အသင့်တော်ဆုံး မြေအမျိုးအစားများဖြစ်သည်။ ရေထုတ်ရန်လွယ်ကူပြီး ရေစိမ့်စီးဆင်းမှုကောင်းမွန်သော မြေဖြစ်သင့်သည်။ မြေချဉ်ငန်ကိန်း pH ၅.၀ ထက်ကျော်သောမြေတွင် ပိုမိုစိုက်ပျိုးဖြစ်ထွန်းကြောင်း သိရပါသည်။<br><br> \r\n\r\nစိုက်ပျိုးချိန် ..... <br><br>\r\n\r\n မိုးရာသီတွင် ပထမမိုးရွာပြီးနောက် ချက်ချင်းမြေပဲကို စိုက်နိုင်သည်။ ဆည်ရေသောက် ဒေသတွင် ဧပြီလ အစောပိုင်း တွင် စိုက်ပျိုးလေ့ရှိသည်။ ဆောင်းရာသီတွင် စက်တင်ဘာလလယ် မှ နိုဝင်ဘာလ ၁၅ ရက်နေ့ထိ ကာလအတွင်း စိုက်ပျိုးသင့်ပါသည်။ <br><br>\r\n\r\nမျိုးစေ့နှုန်း ..... <br><br>\r\n\r\n စံသတ်မှတ်ချက်နှင့်ပြည့်သည့် အရွယ်အစားကြီးမားသည့် မျိုးစေ့ကို သုံးရမည်။ စိုက်ဧရိယာအတွင်း ဝင်ဆန့်ရမည့် အပင်ဦးရေပမာဏ ပြည့်မီရေးအတွက် မျိုးစေ့အရွယ်အစား၊ သန့်စင်မှုနှင့် အပင်ပေါက်နှုန်း ကောင်းမွန်သောမျိုးဖြစ် ရမည်။ တစ်ဧက မျိုးစေ့လိုအပ်ချက်မှာ ၂ တင်း ခန့်ဖြစ်သည်။ မျိုးစေ့များကို မစိုက်မီ အပင်ပေါက်နှုန်းကိုစစ်ဆေးသင့်သည်။ အပင်ပေါက်နှုန်းအနည်းဆုံး ၈၀ ရာခိုင်နှုန်း အထက်တွင်ရှိသောမျိုးဖြစ်သင့်ပါသည်။ <br><br>\r\n\r\nအတန်းအပင်အကွာအဝေး ..... <br><br>\r\n\r\n မိုးရာသီတွင် တစ်ဧကတွင် အပင်ဦးရေ ၁၀၀,၀၀၀ ပင် မှ ၁၁၀,၀၀၀ ပင် ပြည့်မီရရှိအောင် စိုက်ပျိုးရန်ဖြစ်သည်။ အတန်းအပင်အကွာအဝေးအားဖြင့် တစ်တန်းနှင့်တစ်တန်း ၁၅ လက်မနှင့် တစ်ပင်နှင့်တစ်ပင် ၄ လက်မ အကွာ ထားရှိ စိုက်ပျိုးရန်လိုသည်။ ဆောင်းရာသီတွင် တစ်တန်းနှင့် တစ်တန်း ၁၂ လက်မနှင့် တစ်ပင်နှင့်တစ်ပင် ၄ လက်မ အကွာ ထားရှိစိုက်ပျိုးရန် ဖြစ်ပါသည်။<br><br>\r\n\r\nမျိုးစေ့အတိမ်အနက် ..... <br><br>\r\n\r\n မျိုးစေ့ချစိုက်ပျိုးရာတွင် အစိုဓာတ်မီရရှိသေချာစေရန် အတန်းအတွင်းတွင် မြေဆီလွှာအတိမ်အနက် ညီညီညာညာ ထားရှိ စိုက်ပျိုးသင့်သည်မှာ ၁.၅ မှ ၂ လက်မဖြစ်ပါသည်။ <br><br>\r\n\r\nရေသွင်းခြင်း ..... <br><br>\r\n\r\n အစိုဓာတ်လိုအပ်မှုရှိမရှိကို မြေပဲပင်အသက် ၅၅ ရက်မှ ၇၅ ရက်အတွင်းစစ်ဆေးပြီး လိုအပ်မှုရှိပါက ရေပေးသွင်းနိုင်ရေးဆောင်ရွက်သင့်ပါသည်။<br><br>\r\n\r\n၃။ မြေသြဇာကျွေးခြင်း <br><br>\r\n\r\nသဘာဝမြေသြဇာ .....<br><br>\r\nမြေမပြုပြင်မီ တစ်ဧကလျှင် နွားချေး၊ ကြက်ချေး သို့မဟုတ် သဘာဝမြေဆွေးများကို နွားလှည်း ၅ စီး မှ ၁၀ စီးခန့် ထည့်ပေးရမည်။ အမြစ်ဖုများဖြစ်ပေါ်မှု တိုးပွားစေရန် မျိုးစေ့ကို ပဲဖြစ်ဖုဇီဝမြေသြဇာနှင့် လူးနယ်စိုက်ပျိုးရန်ဖြစ်သည်။ အပင်ပေါက်ပြီး (၄၅) ရက်သားတွင် ကယ်လ်စီယမ် ၆ မှ ၉ ရာခိုင်နှုန်းပါဝင်သော ဂျစ်ပ်ဆန် မြေသြဇာကို တစ်ဧက လျှင်၂၀၀ မှ ၂၅၀ ပေါင် ထည့်ပေးသင့်ပါသည်။ <br><br>\r\n\r\nဓါတ်မြေသြဇာ ..... <br><br>\r\n\r\n တစ်ဧကလျှင် ယူရီးယား ၂၈ ပေါင်၊ တီစူပါ ၁၁၂ ပေါင် နှင့် ပိုတက်ရှ် ၂၈ ပေါင်ကို မြေခံအဖြစ် မြေပြုပြင်ချိန်တွင်ထည့်ပေးရန်လိုသည်။ ကွန်ပေါင်းဓာတ်မြေသြဇာကို အသုံးပြုပါက လိုအပ်ချက်နှင့်ကိုက်ညီသော ဓာတ်မြေသြဇာကို သုံးစွဲနိုင်သည်။ မြေအချဉ်အငန်ကိန်း pH ၅.၀ မှ ၅.၅ အတွင်းရှိသော မြေတွင် စိုက်ပျိုးပါက ရွက်ဖျန်းမြေသြဇာကို အနည်းဆုံး ၃ မှ ၅ ကြိမ် ပက်ဖျန်းပေးသင့်ပါသည်။ <br><br>\r\n\r\n၄။ ကာကွယ်နှိမ်နင်းခြင်း<br><br>\r\n\r\n အပင်တွင် ပိုးမွှားရောဂါ ကျရောက်နိုင်သည်။ ပေါင်းမြက်ကလည်း ဆိုးကျိုးပေးနိုင်သည်။<br><br>\r\n\r\nပေါင်းမြက် ..... <br><br>\r\n\r\n အပင်သက်တမ်း တစ်လခွဲအတွင်း ပေါင်းမြက်ကင်းစင်နေဖို့လိုသည်။ လက်ပေါင်းလိုက်ခြင်း၊ ကြားပေါင်းလိုက်ခြင်း စသည့် သင့်တော်ရာနည်းလမ်းဖြင့် နှိမ်နင်းရန်ဖြစ်ပါသည်။ <br><br>\r\n\r\nပိုးမွှား ..... <br><br>\r\n\r\n အပင်သက်တမ်း ကာလတလျောက်လုံးတွင် ရွက်လိပ်ရွက်ကပ်ပိုးများကို စောင့်ကြည့်ရန်လိုသည်။ မိုးခေါင်မှုဖြစ်ပေါ်ပါက သင့်တော်ရာ ပိုးသတ်ဆေးအမျိုးအစားဖြင့် ပိုးမွှားကာကွယ်နှိမ်နင်းရေးလုပ်ငန်းကို ဆောင်ရွက်ရန်ဖြစ်ပါသည်။ <br><br>\r\n\r\nရောဂါ ..... <br><br>\r\n\r\n စိုက်ပျိုးချိန်တွင် မြေအစိုဓါတ်များပါက အပင်ငယ်များကို ရောဂါကျရောက်မှုမှ ကာကွယ်နိုင်ရန် မျိုးစေ့ချချိန်တွင် သင့်တော်ရာ မျိုးစေ့လူးနယ်ဆေး (သို့မဟုတ်) မှိုသတ်ဆေးတစ်မျိုးမျိုးဖြင့် လူးနယ်စိုက်ပျိုးရန်လိုသည်။ <br><br>\r\n\r\n၅။ ရိတ်သိမ်းခြင်း <br><br>\r\n\r\nလေလွင့်ပျက်စီးဆုံးရှုံးမှု မဖြစ်စေရန် ရိတ်သိမ်းချိန်မှန်တွင် ရိတ်သိမ်းပြီးနောက်ပိုင်းတွင်လည်း နည်းလမ်းများမှန်ကန်စွာလုပ်ကိုင်ရန်လိုပါသည်။ <br><br>\r\n\r\nရိတ်သိမ်းချိန် .....<br><br> \r\n\r\n မြေပဲတောင့်များ၏ ၇၀ ရာခိုင်နှုန်းသည် ကောင်းစွာရင့်နေပါက နှုတ်သိမ်းရန်ဖြစ်သည်။ <br><br>\r\n\r\nရိတ်သိမ်းချိန်လွန် .....<br><br>\r\n\r\n ရိတ်သိမ်းပြီး မြေပဲတောင့့်များကို အစိုဓါတ် ၆ မှ ၉ ရာခိုင်နှုန်းသို့ ကျဆင်းသည်အထိ နေရိပ်တွင် အခြောက်လှန်းရန် ဖြစ်သည်။ ထို့နောက် လေလုံပုံးများတွင် စနစ်တကျ သိုလှောင်ထိန်းသိမ်းထားသင့်ပါသည်။ <br><br>\r\n\r\n⏭မြေပဲသီးနှံ စိုက်ပျိုးထုတ်လုပ်မှုအောင်မြင်ဖို့ ဆောင်ရွက်ရန် လိုအပ်သည့် အချက်များစွာအနက် အဓိကအချက် (၅) ချက်ကိုသာ ဖေါ်ပြခြင်းဖြစ်သည်။ မှန်ကန်စွာ လုပ်ကိုင်ဆောင်ရွက်သည်နှင့်အမျှ မျှော်မှန်းသည့်အထွက်ကိုရရှိနိုင်ပြီး စီးပွားရေးတွက်ခြေကိုက်သည့် အကျိုးအမြတ်ဝင်ငွေကို ရရှိကြစေလိုပါသည်။<br><br>\r\n\r\nSources : ဆရာဆင်းသီဟ (နည်းပညာအခြေခံ လယ်ယာဖွံ့ဖြိုးရန်)', '', '19-02-2024'),
(46, '\"မင်းကွတ်သီးစိုက်ပျိုးနည်း\"', 'IMG-65d36ec0b00ef3.31656632.jpg', '🌿🫐🌿🫐🌿🫐🌿🫐🌿🫐🌿<br><br>\r\n\r\nမြန်မာအမည် - မင်းကွတ်<br><br>\r\n\r\nအင်္ဂလိပ်အမည် - MANGOSTEEN<br><br>\r\n\r\nရုက္ခဗေဒအမည် - Garcinia mangotana<br><br>\r\n\r\nမျိုးရင်းအမည် - GUTTIFERAE<br><br>\r\n\r\nမင်းကွတ်သီးပင်ကို အိမ်ခြံဝင်းအတွင်း တစ်ပိုင်တစ်နိုင်စိုက်ပျိုးလိုလျှင်ဖြစ်စေ အသီးအရည်အသွးနှင့် သီးထွက်နှုန်းကောင်းစေရန် စိုက်ပျိုးနည်းစနစ် မှန်ကန်မှုရှိရန် လိုအပ်ပါသည်။<br><br>\r\n\r\n၁။ မူရင်းဒေသ<br><br>\r\n\r\n အရှေ့တောင်အာရှ ဒေသဖြစ်သည်။<br><br>\r\n\r\n၂။ စိုက်ပျိုးနိုင်သောရာသီဉတု<br><br>\r\n\r\n ပူအိုက်စိုစွတ်သောရာသီဉတုကို နှစ်သက်သည်။ အသင့်တော်ဆုံး ပျမ်းမျှအပူချိန် (၂၅ ဒီဂရီစင်တီဂရိတ် - ၃၀ ဒီဂရီစင်တီဂရိတ်)ကြား၊ စိုထိုင်းဆ ၈၀% ခန့်၊ မိုးရေချိန် ၇၅ လက်မအထက်တွင် ဖြစ်ထွန်းသည်။<br><br>\r\n\r\n၃။ မြေအမျိုးအစား<br><br>\r\n\r\n မြေသားထုနက်သည့် နုန်းမြေဆွေး အမျိုးအစားဖြစ်ပြီး ရေစီးစိမ့်မှုကောင်းပါက အသင့်တော်ဆုံး ဖြစ်သည်။ အမြစ်ဖွဲ့စည်းပုံ အားနည်းသဖြင့်အစိုဓာတ် ကောင်းရန်လိုသော်လည်း ရေမဝပ်စေသင့်ပါ။ စိုက်ပျိုးရန်အသင့်တော်ဆုံး pH မှာ (၅.၅-၇.ဝ) အကြားဖြစ်သည်။<br><br>\r\n\r\n၄။ စိုက်ပျိုးချိန်<br><br>\r\n\r\n မိုးဦးကျ ဇွန်လဆန်းတွင် စိုက်ပျိုးနိုင်ပါသည်။ ရေရရှိပါက နိုဝင်ဘာလမှ ဇန်နဝါရီလအထိ စိုက်ပျိုးနိုင်သည်။<br><br>\r\n\r\n၅။ မျိုးရွေးချယ်ခြင်း<br><br>\r\n\r\n မင်းကွတ်မှာမျိုးကွဲမရှိပါ။ ကမ္ဘာပေါ်တွင် တစ်မျိုးတည်းသာရှိပါသည်။ အခြားသစ်သီးဝလံများကဲ့သို့ မျိုးပွားနည်း (ဖူးသွင်း/ကိုင်းဆက်) ဖြင့် ဆောင်ရွက်ရန်ခက်ခဲပြီး ၎င်းနည်းဖြင့် ပွားသည့်အပင်မှာ Canopy မလှဘဲ တစ်ခြမ်းစောင်းနေသဖြင့် အပင်ပုံစံမကျပါ။ တောမင်းကွက်အရိုင်း၊ တောင်သလဲအောက်ခံပင် များနှင့် စမ်းသပ်အကိုင်းဆက်သော်လည်း သဟဇာတ သိပ်မဖြစ်ပါ။ ထိုကြောင့် အစေ့မှသာပျိုးပြီး ပျိုးခင်းတွင် နှစ်ချို့မွေးကာ အနည်းဆုံး (၂) နှစ်သား (၂ ပေခန့်) ရှိမှ စိုက်ပျိုးသင့်ပါသည်။<br><br>\r\n\r\n၆။ စိုက်ပျိုးနည်း<br><br>\r\n\r\n - ပင်ကြားတန်းကြား ၃၀ပေ x ၃၀ပေ (တစ်ဧကဝင်ဆန့်ပင်ရေ ၄၈ ပင်)<br><br>\r\n\r\n - ပင်ကြားတန်းကြား ၂၅ပေ x ၂၅ပေ (တစ်ဧကဝင်ဆန့်ပင်ရေ ၆၉ ပင်)<br><br>\r\n\r\n မင်းကွက်စိုက်ပျိုးရန်အတွက် ၃ပေ x ၃ပေ x ၃ပေ အရွယ် စိုက်ကျင်းတူးပြီး မြေခံမြေသြဇာ အဖြစ် ယူးရီးယား၊ တီစူပါ၊ ပိုတက်ရှ် ၁၅ : ၁၅ : ၁၅ အချိုး (၃) မျိုးစပ် နို့ဆီဗူး(၁) ဘူး၊ နွားချေးဆွေး (သို့) ကြက်ချေးဆွေး (၂) တင်း၊ မြေအောင်း ပိုးသတ်ဆေး (၁)ဇွန်း၊ မဖောက်ထုံး နို့ဆီဘူး (၁) ဘူးတို့အား အပေါ်ယံမြေနှင့် သမအောင်ရော၍ စိုက်ကျင်းအတွင်း ထည့်ကာ တစ်လခန့် နှပ်ထားရမည်။ ကျန်းမာသန်စွမ်းသော (၂-၃) နှစ်သား မင်းကွတ်ပျိုးပင်ကို မြေနှပ်ထားသော ကျင်းတွင် မြေလုံးမပျက် စိုက်ပျိုးရမည်။ ရေမဝပ်စေရန် ပင်ခြေပတ်လည် မြေဖို့ပေးပြီး ပလက်စတစ်အနက်စအုပ်ကာ တိုင်ထောင်ကြိုးချည်ရပါမည်။<br><br>\r\n\r\n၇။ ရေပေးသွင်းခြင်း<br><br>\r\n\r\n ခြောက်သွေ့ရာသီတွင် အနည်းဆုံး (၇) ရက်တစ်ကြိမ် ရေသွင်းရပါသည်။ ပင်ခြေတွင် ကောက်ရိုး၊ မြက် ခြောက် ဖုံးအုပ်ပေးခြင်းသည်အကျိုးရှိစေပါသည်။<br><br>\r\n\r\n၈။ အရိပ်ပေးခြင်း<br><br>\r\n\r\n အရိပ်ပေးခြင်းသည် မင်းကွတ်ပင်အတွက် အကျိုးသက်ရောက်မှုများစွာရှိပါသည်။ (၂-၃) နှစ်သားအထိ အရိပ်ပေးနိုင်ပါက အပင်ကြီးထွားမှုမြန်ဆန်ကြောင်းတွေ့ရသည်။<br><br>\r\n\r\n၉။ မြေသြဇာကျွေးခြင်း<br><br>\r\n\r\n သဘာဝမြေသြဇာ (Organic Manure) ကို အဓိကသုံးထားပြီး ဓာတ်မြေသြဇာလည်း အားဖြည့် သုံးသင့်ပါသည်။ N:P:K အချိုး (၁၅ : ၁၅ : ၁၅) ကို (၁-၂) နှစ်သားအပင်များအတွက် (၂၅၀) ဂရမ် (တစ်ပင်နှုန်း) နှင့် သက်တန်းကြီးလာသည်နှင့် အမျှ တစ်ဖြည်းဖြည်းတိုးကျွေးရပါသည်။ (၁၀)နှစ်သား အထက်ဖြစ်ပါက ၅-၇ ကီလို (၃-၄ ပိဿာ) အထိ၊ နွားချေး၊ ကြက်ချေး (၄-၅) တင်းထိ ကျွေးသင့်ပါသည်။ သီးကင်းဝင်ပြီးတစ်ကြိမ်နှင့် ရိတ်သိမ်းပြီးတစ်ကြိမ် ခွဲကျွေးသင့်သည်။<br><br>\r\n\r\n၁၀။ ပိုးမွှားနှင့်ရောဂါ<br><br>\r\n\r\n မင်းကွတ်သည် ပိုးမွှားရောဂါကျရောက်မှုနည်းပါးသော သီးနှံဖြစ်သည်။ ပိုးမွှားကျရောက်မှုမှာ လှေးပိုး နှင့် ပရွက်ဆိတ် တို့သာကျရောက်တတ်သည်။<br><br>\r\n\r\n ရောဂါအနေဖြင့် Brown rot (အညိုပုပ်ရောဂါ)၊ Stem Cancer (ပင်စည်ကင်ဆာရောဂါ) နှင့် အကိုင်းနုများတွင် အစက်အပြောက်များဖြစ်ပေါ်တတ်ပါသည်။<br><br>\r\n\r\n၁၁။ အပွင့်နှင့်အသီးဖွဲ့စည်းပုံ<br><br>\r\n\r\n လိင်စုံပင်ဖြစ်ပြီး ဖိုမပေါင်းစပ်မှုမရှိဘဲ (ဝတ်မှုန်မကူးဘဲ) မျိုးစေ့ရရှိပါသည်။ အစေ့များမှာ လိင်ပေါင်းစပ်မှု မရှိသည့် အသီး၏အတွင်းသား Nucellar tissue မှ ဖြစ်လာခြင်းဖြစ်သည်။<br><br>\r\n\r\n၁၂။ ပင်ပိုင်းဆိုင်ရာ ကြီးထွားမှုနှေးကွေးခြင်းနှင့် ပွင့်သီးရန် အချိန်ကြာရခြင်းအကြာင်းရင်း<br><br>\r\n\r\n မင်းကွတ်ပင်သည် အခြားသီးပင်များနှင့် နှိုင်းယှဉ်ပါက ကြီးထွားမှုနှေးခြင်း၊ စီးပွားဖြစ်အသီးရရန် နှစ်ကြာခြင်းများရှိပါသည်။ အကြောင်းရင်းမှာ မင်းကွတ်ပင် သဘာဝအရ ငယ်ရွယ်နုပျိုကာလ (Juvenile phase) သည် (၁၀-၁၂)နှစ် ရှည်လျားသောကြောင့်ဖြစ်သည်။<br><br>\r\n\r\n ၎င်းကို ကျော်လွှားနိုင်ရန် .....<br><br>\r\n\r\n (၁) ပျိုးခင်းတွင် (၃-၄) နှစ် မွေးခြင်း၊<br><br> \r\n\r\n (၂) စိုက်ပျိုးပြုစုမှု စနစ်ကောင်းအောင် ဆောင်ရွက်ခြင်းဖြင့် (၅-၆) နှစ်သားတွင် စီးပွားဖြစ် အသီးရနိုင်ပါသည်။<br><br>\r\n\r\n၁၃။ အသီးထွက်ရာသီ<br><br>\r\n\r\n မွန်ပြည်နယ်တွင် ဇန်နဝါရီ၊ ဖေဖော်ဝါရီလတွင် ပန်းပွင့်ပြီး ဧပြီ၊ မေလတွင် အသီးမှည့်ပါသည်။ ပန်းပွင့်သည်မှ မှည့်သည်အထိ (၃)လခန့် ကြာပါသည်။<br><br>\r\n\r\n၁၄။ အသီးဆွတ်ခူးခြင်း<br><br>\r\n\r\nအသီးခွံ ခရမ်းရောင်သည် အစိမ်းရောင်ပေါ်တွင် ၂၅% ရှိပါကဆွတ်ခူးနိုင်ပြီဖြစ်သည်။ ၎င်းအသီးသည် ၂၄နာရီအတွင်း မှည့်ပြီး (၁)ပတ်ခန့် အထားခံပါသည်။ အသီးခူးရာတွင် လက်ဖြင့်ခူးရန် လိုအပ်ပြီး မြေကြီးပေါ်မကျရန် သတိထားရပါသည်။ အသီးများကို ၁၃ ဒီဂရီ စင်တီဂရိတ် တွင် (၂-၃) ပတ်အထိ ထားနိုင်ပါသည်။ မင်းကွတ်သည် အသီးခူးပြီးမှ မှည့်သောအသီး (Crimactric Fruit) ဖြစ်သည်။ အသီးမှည့်စဉ် အီသလင်းဓာတ်ငွေ့ထုတ်လွှတ်ပါသည်။ ထိုကြောင့် အသီးမှည့်နှေးစေရန် နိမ့်သောအပူချိန်တွင်ထားပြီးထိန်းရပါသည်။<br><br>\r\n\r\n၁၅။ အထွက်နှုန်း<br><br>\r\n\r\n(၁၀-၂၀)နှစ်သား တစ်ပင်လျှင် အသီးထွက် ၁,၀၀၀ခန့် ရနိုင်ပါသည်။ အပင် Canopy ကြီးလာသည်နှင့် အမျှ အသီးအထွက်နှုန်းလည်း များလာမည်ဖြစ်သည်။<br><br>\r\n\r\nမင်းကွတ်သီးသည် အခြားသစ်သီးဝလံနှင့် နှိုင်းယှဉ်ပါက အရင်းကျေ အမြတ်ရခြင်း နောက်ကျသော် လည်း ရေရှည်အတွက်မူ စိုက်ပျိုးသင့်သောသီးနှံဖြစ်သည်။<br><br>\r\n\r\nSource : စိုက်ပျိုးရေး ဦးစီးဌာန', '', '19-02-2024'),
(47, 'ဂရုပြုကာကွယ်ရမည့် “စပါးရွက်ညိုပြောက်ရောဂါ”', 'IMG-65d36ef5f0af56.83061593.jpg', '🌾🌱🌾🌱🌾🌱🌾🌱🌾🌱🌾<br><br>\r\n\r\n↗️ စပါးရွက်ညိုပြောက်ရောဂါသည် စပါးစိုက်ဒေသတိုင်းမှာ ဖြစ်ပွားနိုင်သည့် ရောဂါဖြစ်စေသည့် သက်ရှိမှိုဖြစ်သည်။ အဆိုပါမှိုသည် စပါးရွက်ပေါ်တွင် ကျရောက်ပါက ရောဂါလက္ခဏာကို အရွက်နှင့် အစေ့များပေါ်တွင် အဓိကတွေ့ရသော်လည်း စေ့ရွက်အောက်ထွက်စ၊ ရွက်ဖုံး၊ အနှံခက်များပေါ်တွင် လည်း တွေ့ရှိနိုင်သည်။ အရွက်ပေါ်တွင် အစက်ငယ်မှ နှမ်းစေ့အရွယ်၊ တစ်ခါတစ်ရံ တစ်စင်တီမီတာ အရွယ်အထိရှိသော ဘဲဥပုံအညိုရောင်ပြောက်များ ညီညာစွာပြန့်ကျဲဖြစ်ပေါ်နေသည်။<br><br>\r\n\r\n↗️ အစက်အပြောက်များမှာ ကနဦးပိုင်းတွင် ခရမ်းရောင်၊ အညိုရောင်ရှိပြီး ကြီးလာသည်နှင့်အမျှ အညိုရောင်အနားရစ် အလယ်မီးခိုးရောင်ရှိသော ကွက်ပြောက်များဖြစ်လာသည်။ ထိုမှတစ်ဆင့် အရွက်များတဖြည်းဖြည်းခြောက်သေသွားသည်။ စပါးစေ့ခွံပေါ်တွင် အနက်ရောင် (သို့) အညိုရင့် အစက်အပြောက်များတွေ့နိုင်သည်။ နောက်တဖြည်းဖြည်း ဆန်စေ့အထိအမည်းပြောက်များတွေ့ နိုင်သည်။ အနှံခက်၏ အဆစ်များတွင်လည်း အညိုရောင်ရောဂါကွက်များဖြစ်ပြီး စပါးစေ့အဆံ တည်မှုနည်းစေသည်။ အဆံမအောင်ဘဲစပါးစေ့ရှုံ့လိမ်၍ အရောင်ပျက်စေသည်။ ရောဂါရစပါးစေ့များကိုပြန်လည်စိုက်ပျိုးခြင်းအားဖြင့် ပျိုးပင်နာကျရောဂါ ဖြစ်စေပါသည်။<br><br>\r\n\r\n↗️ အဆိုပါရောဂါဖြစ်စေသည့် မှိုသည်ရောဂါရအပင်အစိတ်အပိုင်းများတွင် နှစ်နှစ်မှသုံးနှစ်အထိ ခိုအောင်းရှင်သန်နိုင်သည်။ မြေဆီလွှာထဲတွင်လည်း ရှင်သန်နိုင်သည်။ ရောဂါရမျိုးစေ့များသည် ရောဂါကူးစက်ပျံ့နှံ့စေသောအကြောင်းတရားများဖြစ်သည်။ မြေဆီလွှာအတွင်းရှိ မှိုမှတစ်ဆင့်လည်း ရောဂါကူးစက်စေနိုင်တာ တွေ့ရသည်။ မှိုစပိုးများသည် လေဖြင့်လွင့်ပါ၍ တစ်နေရာမှတစ်နေရာသို့ ပျံ့နှံ့ကူးစက်နိုင်သည်။<br><br>\r\n\r\n↗️ အဆိုပါမှိုရောဂါကို တိုးတက်ဖြစ်ပေါ်စေသော အကြောင်းတရားများရှိပါသည်။ မြေတွင် နိုက်ထရိုဂျင်ဓာတ် လွန်ကဲခြင်းနှင့် အာဟာရ ချို့တဲ့ခြင်းများသည် အဆိုပါမှိုရောဂါကို ပိုမိုဖြစ်ပေါ်စေရန် တွန်းအားပေးနေသည်ကိုတွေ့ရသည်။ ထို့ပြင် ရေသွင်းရေထုတ်ညံ့ဖျင်းသဖြင့် မြေဆီလွှာအတွင်း ဓာတ်လျော့မှုလွန်ကဲစွာ ဖြစ်ပေါ်သောမြေများတွင် ရောဂါကို ပိုမိုဖြစ်ပေါ်စေရန် အခွင့်အလမ်းသာသည်။ စပါးပင်သည် မဂ္ဂနီးစ်၊ ဆီလီကာ၊ ဖော့စ်ဖရပ်၊ ပိုတက်စီယမ်၊ နိုက်ထရိုဂျင် စသောဓာတ်များ ချို့တဲ့ ပါကရောဂါပို ဖြစ်စေနိုင်သည်။ တမန်းအပုပ်လွန်သော လယ်မြေများတွင် ဟိုက်ဒရိုဂျင်ဆာလ်ဖိုဒ် ဓာတ်ငွေ့များထွက်သဖြင့် ဆီလီကာနှင့် ပိုတက်စီယမ်ဓာတ်တို့ကို အပင်က ပုံမှန်အတိုင်း မစုပ်ယူ နိုင်သောအခါ ရောဂါပိုမိုဖြစ်စေသည်။<br><br>\r\n\r\n↗️ ရွက်ညိုပြောက်ရောဂါလက္ခဏာသည် ပိုတက်စီယမ်ဓာတ်ချို့တဲ့သဖြင့် စပါးရွက်တွင် ဖြစ်ပေါ်သော လက္ခဏာနှင့်ဆင်တူသည်။ စွတ်စိုသောမြေထက် ခြောက်သွေ့သော မြေတွင်ရောဂါပိုဖြစ်စေပါသည်။ ရောဂါကူးစက်ရန်အကောင်းဆုံးအပူချိန်မှာ ၂၀ ဒီဂရီစင်တီဂရိတ် မှ ၂၅ ဒီဂရီစင်တီဂရိတ်ဖြစ်သည်။ တိမ်ထူပြီး မိုးအဆက်မပြတ်ရွာသွန်းနေပါက ရောဂါပြန့်ပွားမှု မြန်ဆန်စေပါသည်။ ရောဂါမှိုသည် အာဟာရချို့တဲ့သော မြေများတွင် ဖြစ်ပေါ်မှုများပြီးဒေသတော်တော်များများမှာလည်း ဖြစ်ပွားလေ့ ရှိသည်။ မြက်မျိုးစိတ်အပင်များ၊ စပါးရိုင်းပင်များတွင် လက်ခံပင်အဖြစ် တည်ရှိနေနိုင်သည်။<br><br>\r\n\r\n(က) ကြိုတင်ကာကွယ်ခြင်း<br>\r\n------------------------<br><br>\r\n\r\n၁။ ရောဂါကင်းသော မျိုးစေ့ကို ရွေးချယ်စိုက်ပါ။<br><br>\r\n\r\n၂။ ရောဂါရစပါးစိုက်ခင်းရဲ့ ရိုးပြတ်များ၊ ပင်ကြွင်းပင်ကျန်များ မီးရှို့ပါ။<br><br>\r\n\r\n၃။ ကန်သင်းပေါ်ရှိ ပေါင်းမြက်နှင့် စပါးရိုင်းပင်များကို သုတ်သင်မီးရှို့ပါ။<br><br>\r\n\r\n၄။ လယ်မြေကို အာဟာရပြည့်ပြီး မြေဆီလွှာကောင်းမွန်စေရန် နိုက်ထရိုဂျင် (မလွန်ကဲ)၊ ဖော့စ်ဖရပ်၊ ပိုတက်ရှ်ကို အချိုးညီညီထည့်ပါ။<br><br>\r\n\r\n၅ ။ ရေသွင်း၊ ရေထုတ်ကောင်းအောင် စီမံထားပါ။<br><br>\r\n\r\n၆ ။ ရောဂါကျရောက်ဖူးသော လယ်ကွက်ကိုဖြတ်၍ ရေသွင်းခြင်းကိုရှောင်ပါ။<br><br>\r\n\r\n၇ ။ တမန်းအပုပ်လွန်အောင် မစောင့်ဘဲ တမန်းအနေတော်အချိန်မှာစိုက်ပျိုးပါ။<br><br>\r\n\r\n၈ ။ ဓာတုဆေးဖြင့်ကြိုတင်ကာကွယ်လိုပါက သီးနှံပင်ငယ်စဉ်မှစ၍ “ဘင်ဇိုကာ” မှိုသတ်ဆေးဖြင့် ပက်ဖျန်းကာကွယ်နိုင်ပါသည်။<br><br>\r\n\r\n(ခ) နှိမ်နင်းခြင်း<br>\r\n-------------<br><br>\r\n\r\n၁။ မျိုးစေ့ကိုဆားရည်စိမ်ပြီးမှစိုက်ပျိုးပါ။<br><br>\r\n\r\n၂။ ရောဂါလက္ခဏာစတွေ့သည်နှင့် ဝိစာရ၏ \"ဇိုလာ၊ ဘင်ဇိုကာ\" မှိုသတ်ဆေးတစ်မျိုးမျိုးကို တစ်ပတ်ခြားတစ်ကြိမ်ခန့် ပက်ဖျန်းပေးရပါမည်။<br><br>\r\n\r\n၃။ ဆေးဖျန်းပြီးလျှင် တစ်ဧက ပိုတက်ရှ်မြေသြဇာ (၁၅ - ၂၀)ပေါင် ခန့်ကြဲပက်ပေးပါ။<br><br>\r\n\r\n🌾စစ်မှန် ပြည့်ဝ ဝိစာရ🌾', '', '19-02-2024'),
(48, 'စပါးခင်းထဲက ဂုတ်ကျိုးရောဂါ ', 'IMG-65d36fbb5cd8f4.35452419.jpg', '🌾🌾🌾🌾🌾🌾🌾🌾🌾🌾<br><br>\r\n\r\n⏩စပါးသီးနှံကို အထွက်လျော့စေနိုင်သည့် စပါးရောဂါများတွင် “စပါးဂုတ်ကျိုး” ရောဂါ အပါအဝင်ဖြစ်ရာ စပါးဂုတ်ကျိုးရောဂါအကြောင်း နှင့် ထိရောက်စွာ ကာကွယ်နှိမ်နင်းနိုင်ရန်နည်းလမ်းများကို ဗဟုသုတ အဖြစ်ရေးသားတင်ပြလိုက်ရပါသည်။<br><br>\r\n\r\n⏩စပါးဂုတ်ကျိုးရောဂါ လက္ခဏာမှာ စပါးရွက်ပေါ်တွင် လွန်းပုံသဏ္ဌာန်ရှိသော ရောဂါကွက်များ တွေ့ရသည်။ ရောဂါကွက်များကြီးခဲ့လျှင် အလယ်တွင် မီးခိုးရောင်အကွက်များဖြစ်ပေါ်တတ်သည်။ ခံနိုင်ရည်မရှိသော စပါးမျိုးများတွင် ရောဂါကွက်တစ်ခုနှင့်တစ်ခုဆက်သွားပြီး စပါးရွက်များ သေသွားတတ်သည်။ အနှံနှင့် ပင်စည်အဆစ်များတွင်လည်း ရောဂါကျရောက်တတ်ပြီး အနှံတွင် ရောဂါဝင်ရောက်ပါက ဂုတ်တွင် အညိုရောင်အကွက်များ ဖြစ်ပေါ်ပြီး ကျိုးကျတတ်သဖြင့် “ဂုတ်ကျိုးရောဂါ”ဟု ခေါ်ဆိုခြင်း ဖြစ်ပါသည်။ ပင်စည်အဆစ်တွင် ကျရောက်ပါက ကြွက်ဖျက်ဆီးသည့် လက္ခဏာနှင့် မှားယွင်းတတ်ပါသည်။<br><br>\r\n\r\n⏩နို့ရည်မတည်ခင် ရောဂါကျရောက်ပါက နို့ရည်ဆက်တည်နိုင်ခြင်းမရှိတော့ပါ။ အဆန်မတည်သော အနှံတို့မှာ စပါးရင့်မှည့်ချိန်မတိုင်မီကပင် ဖြူဖွေးထောင်မတ်လျက်ရှိကြသည်။ ၄င်းလက္ခဏာသည် စပါးဆစ်ပိုးဖျက်ဆီးသည့်လက္ခဏာ၊ စပါးရွက်ဖုံးခြောက်ရောဂါကြောင့်ဖြစ်သော လက္ခဏာများနှင့် မှားယွင်းတတ်ပါသည်။ စပါးဂုတ်ကျိုးရောဂါသည် အခြားဆစ်ပိုး၊ ကြွက်နှင့် စပါးရွက်ဖုံးခြောက်ရောဂါ လက္ခဏာများနှင့် မှားယွင်းတတ်သော်လည်း စပါးဂုတ်ကျိုးရောဂါ၏ အထင်ရှားဆုံးလက္ခဏာများ ဖြစ်သည့် အရွက်တွင် လွန်းပုံသဏ္ဌာန်ရွက်ပြောက်များ ဖြစ်ပေါ်ခြင်းနှင့် အနှံအောက်အဆစ် (စပါးနှံဂုတ်)တွင် အညိုရောင်အကွက်များဖြစ်ပေါ်ပြီး ကျိုးကျသည့်လက္ခဏာများကို ထောက်ရှု၍ တိကျစွာခွဲခြားနိုင်ကြပါသည်။<br><br>\r\n\r\n⏩အပူချိန်ပြောင်းလဲမှုနည်းသော အပူပိုင်းဒေသများတွင် လေထု၏စိုထိုင်းမှုနှင့် နှင်းစက်နှင်းပေါက် ဖြစ်ပေါ်မှုတို့သည် ရောဂါတိုးလာစေသောအဓိက အကြောင်းရင်းများဖြစ်သည်။ ထို့ပြင် မှိုစပိုးများသည် တစ်နေရာမှတစ်နေရာသို့ လေဖြင့်ပျံ့လွင့်၍ ရောဂါကူးစက်ပြန့်ပွားစေသည်။ သွင်းရေထုတ်ရေများမှ တစ်ဆင့်လည်းပျံ့နှံ့နိုင်သည်။ ၎င်းမှိုသည် စပါးစေ့၏ သန္ဓေလောင်း၊ အစေ့တွင်းစာ နှင့် စပါးခွံများတွင် လည်း ခိုအောင်းနိုင်သည်။<br><br>\r\n\r\n🔸စပါးဂုတ်ကျိုးရောဂါကို ကာကွယ်နှိမ်နင်းရန်နည်းလမ်းများမှာ နိုက်ထရိုဂျင်မြေဩဇာကို တစ်ကြိမ်တည်းများပြားစွာထည့်ပေးခြင်းသည် ရောဂါကိုအားပေးရာရောက်ပြီး အကြိမ်ကြိမ်ခွဲ၍ထည့်ပေးခြင်းဖြင့် ရောဂါကျရောက်မှုကို သက်သာစေနိုင်သည်။ ရောဂါရပင်ကြွင်းပင်ကျန်များကို မီးရှို့ဖျက်ဆီးပါ။ နွေစပါးစိုက်ခင်းတွင် ရေအမြဲရှိနေရန်ဆောင်ရွက်ပါ။ ရောဂါရလက်ခံပင်များ၊ ပေါင်းမြက်များကို ရှင်းလင်းပါ။ အပင်စိပ်စိပ်စိုက်ခြင်းကိုရှောင်ပါ။ ဂုတ်ကျိုးရောဂါ ဖြစ်ထွန်းမှုကိုအားပေးသော အပူချိန် ရှိသည့်လကိုရှောင်နိုင်ရန် စိုက်ပျိုးချိန်ကို ဂရုပြု၍ စိုက်ပျိုးပါ။<br><br>\r\n\r\n🔸စပါးဂုတ်ကျိုးရောဂါကို ဓာတုနည်းဖြင့်ကာကွယ်နှိမ်နင်းရန် ဝိစာရ၏ “ပိုင်ရီဆိုက် ၄၀ အက်စ်စီ” ဆေးကို အသုံးပြုပေးရပါမည်။ “ပိုင်ရီဆိုက်” တွင် Tricyclazole 40% ပါဝင်ပြီး စပါးဂုတ်ကျိုးရောဂါကို ကာကွယ် ကုသနိုင်သည့် ပင်လုံးပြန့်မှိုသတ်ဆေးဖြစ်သည်။<br><br>\r\n\r\n🔸“ပိုင်ရီဆိုက်”ကို စပါးသီးနှံသက်တမ်း အဆင့်တိုင်းတွင် အသုံးပြုနိုင်ပြီး အရွက်၊ ပင်စည်၊ အကိုင်းအခက် နှင့် စပါးနှံများတွင် ကျရောက်သော ဂုတ်ကျိုးရောဂါအဆင့်တိုင်းကို ကာကွယ်ကုသနိုင်သည်။ “ပိုင်ရီဆိုက်” ကို မျိုးစေ့ဖြင့်လူးနယ်စိုက်ပျိုးခြင်း၊ ပျိုးပင်ငယ်၏ အမြစ်ကိုဆေးရည်စိမ်စိုက်ပျိုးခြင်းနှင့် အပင်ပေါ်ဖျန်းခြင်းနည်းလမ်းများဖြင့် အသုံးပြုနိုင်ပါသည်။ <br><br>\r\n\r\n🔸အသုံးပြုရန်ဆေးနှုန်းထားမှာ ဆေးဖျန်းပုံးတစ်ပုံးလျှင် “ပိုင်ရီဆိုက်” (၄၀-၆၀)စီစီနှုန်းဖြင့် တစ်ဧကလျှင် (၂၀၀-၃၀၀)စီစီနှုန်း ပက်ဖျန်းအသုံးပြုရန်ဖြစ်ပါသည်။<br><br>\r\n\r\n🔸ဦးကြီးတို့၏စပါးခင်းများတွင် စပါးရောဂါများကင်းစင်၍ အရည်အသွေးနှင့် အထွက်နှုန်းများ မြင့်မားနိုင်ကြပါစေ။<br><br>\r\n\r\n🌾စစ်မှန်ပြည့်ဝ ဝိစာရ 🌾', '', '19-02-2024'),
(49, 'ပဲတီစိမ်း“ရွက်ပြောက်ရောဂါ” ကင်းဝေးဖို့ ..... “ဘင်ဇိုကာ” ကို သုံးကြစို့ .....', 'IMG-65d23f372ffcd8.53523086.jpg', '\r\n🌱🍂🌱🍂🌱🍂🌱🍂🌱🍂🌱<br><br>\r\n\r\n🔼ယခုနှစ်ဆောင်းကာလတွင် ဦးကြီးတို့၏စိုက်ပျိုးပြီး ပဲတီစိမ်းခင်းများအတွင်း ရာသီဥတုအခြေအနေ စိုစွတ်၍ ပတ်ဝန်းကျင်ခြောက်သွေ့ခြင်းကြောင့် ပဲရွက်ပြောက်ရောဂါ (Cercospora Leaf Spot)များ ကျရောက်နေသည်ကို တွေ့ရှိရပါသည်။ ထို့ကြောင့် ၎င်းရောဂါ၏ ရောဂါလက္ခဏာ၊ ရောဂါကူးစက် ပြန့်နှံ့ပုံတို့ကိုသိရှိပြီး ကြိုတင်ကာကွယ်နိုင်ရန် နှင့် အထိရောက်ဆုံးကာကွယ်နှိမ်နင်းနိုင်မည့် ဝိစာရ၏ “ဘင်ဇိုကာ” မှိုရောဂါကာကွယ် နှိမ်နင်းဆေးနှင့် မိတ်ဆက်ပေးလိုက်ပါသည်။<br><br>\r\n\r\n🔼ပဲရွက်ပြောက်ရောဂါ (Cercospora Leaf Spot)🔼<br><br>\r\n\r\nရောဂါလက္ခဏာ<br>\r\n--------------<br><br>\r\n\r\nရောဂါကျအရွက်ရင့်ပေါ်တွင် အရွယ်အစားအမျိုးမျိုးရှိသည့် အညိုရောင်၊ သံချေးရောင်ကွက်ပြောက်များ ဖြစ်ပေါ်ပြီး ရောဂါကွက်များသည်အလယ်တွင်မီးခိုးရောင်ရှိပြီး နီညိုရောင် အနားရစ်ပါရှိသည်။ ရောဂါပြင်းထန်ပါကအစိမ်းရောင်တစ်ရှူးသားများခြောက်သွားပြီး အရွက်များအစိမ်းရောင်မရှိတော့ပါ။ အထူးသဖြင့်ပဲတီစိမ်းတွင် ပိုမိုဆိုးရွားစွာကျရောက်တတ်သည်။ ပန်းပွင့်ချိန်နှင့် အသီးကင်းဝင်ချိန်တွင် ရွက်ပြောက်ရောဂါပြင်းထန်စွာကျရောက်ပါက အပွင့်နှင့် သီးကင်းကြွေခြင်းများ ဖြစ်ပေါ်တတ်ပါသည်။<br><br>\r\n\r\nရောဂါကူးစက်ပြန့်နှံ့ပုံ<br>\r\n-------------------<br><br>\r\n\r\nရောဂါဖြစ်စေသောမှိုသည် အပင်အကြွင်းအကျန်များပေါ်တွင် အသက်ရှင်နေထိုင်နိုင်ပြီး ရောဂါပျံ့ပွားဖို့ အဓိက ကတော့ မိုးရေ၊ နှင်းရေ (Rain & Snow Splashes) ကြောင့်ဖြစ်ပါသည်။ ပဲမျိုးအများစုဟာ ဒီရောဂါကိုခံနိုင်ရည်မရှိသည့် အတွက်ကြောင့် ရောဂါကူးစက်ပျံ့ပွားဖို့ အရမ်းလွယ်ကူပါသည်။ ပဲရွက်ပြောက်ရောဂါကျရောက်ရန် အကောင်းဆုံးပတ်ဝန်းကျင်အခြေအနေမှာ စိုထိုင်းဆ(၉၀-၁၀၀) ရာခိုင်နှုန်း နှင့် အပူချိန် (၂၀-၂၆) ဒီဂရီ စင်တီဂရိတ် ပူနွေးစွတ်စိုတဲ့ အခြေအနေဖြစ်သည်။ ရောဂါ ကျရောက်ရန် အားပေးသောအပူချိန်မှာ (၂၅ - ၃၀) ဒီဂရီစင်တီဂရိတ်ဖြစ်ပါသည်။ အပူချိန်(၁၀)ဒီဂရီ စင်တီဂရိတ်အောက်ကျရောက်သွားပါက ရောဂါဖြစ်စေသက်ရှိဟာ ဆက်လက်ပြီးမျိုးပွားနိုင်ခြင်း မရှိတော့ပါ။ ပဲရွက်ပြောက်ရောဂါကို ကောင်းမွန်စွာကာကွယ်နိုင်ခြင်းမရှိပါက အထွက်နှုန်းကို (၆၀)ရာခိုင်နှုန်းအထိ ဆုံးရှုံးနိုင်ပါသည်။<br><br>\r\n\r\n🔼သို့ဖြစ်ပါ၍ ပဲရွက်ပြောက်ရောဂါကို ထိရောက်စွာ ကာကွယ်ကုသမှုပေးနိုင်ရန် ဝိစာရ၏ မှိုရောဂါ ကာကွယ်ကုသဆေး အသစ် “ဘင်ဇိုကာ ၅၅၀ အက်စ်စီ” ကိုပက်ဖျန်းပေးရပါမည်။<br><br>\r\n\r\n🔼“ဘင်ဇိုကာ”တွင် အစွမ်းရှိပစ္စည်း Chlorothalonil 45.0% + Hexaconazole 3.5% + Cymoxanil 6.5% ပါဝင်၍ ထိသေနှင့်ပင်လုံးပြန့်အာနိသင်ရှိပြီး အပင်အတွင်းသို့ ထိုးဖောက်စိမ့်ဝင်နိုင်မှုအားကောင်းသည့် အပြင် အပင်အတွင်းရွေ့လျားပြန့်နှံ့နိုင်မှုလည်းအလွန်ကောင်းသည့် မှိုသတ်ဆေးဖြစ်သည်။<br><br>\r\n\r\n🔼“ဘင်ဇိုကာ”တွင် စွမ်းအားမြင့်မှိုဆေး(၃)မျိုး ပေါင်းစပ်ပါဝင်သဖြင့် သီးနှံပင်များတွင်ကျရောက်တတ်သော မှိုရောဂါများကို ကာကွယ်ခြင်း နှင့် ကုသရန်အတွက်ပါ အလွန်ထိရောက်ပါသည်။ “ဘင်ဇိုကာ”ကို သီးနှံပင် ငယ်စဉ်မှစ၍ သီးနှံပင်သက်တမ်းတလျောက် အသုံးပြုနိုင်ပါသည်။ ရောဂါကာကွယ်ဆေး အဖြစ်အသုံးပြုရန် ရောဂါမဖြစ်ခင်ဆေးပုံမှန်ဖျန်းပေးပါ။ ကုသဆေးအဖြစ် သုံးစွဲလိုလျှင် ရောဂါလက္ခဏာ စတွေ့တွေ့ချင်း အစောပိုင်းအဆင့်များတွင်အသုံးပြုပက်ဖျန်းပေးပါ။<br><br>\r\n\r\n🔼“ဘင်ဇိုကာ”ဖြင့် ပဲတီစိမ်း၊ မတ်ပဲ နှင့် ပဲအမျိုးမျိုးတွင်ကျရောက်တတ်သော Cercospora ရွက်ပြောက် ရောဂါ အပြင် ဖားဥမှိုရောဂါ၊ ပဲသံချေးရောဂါ၊ မှည့်ပြောက်စွန်းရောဂါ များအတွက်လည်း ကာကွယ်ကုသ ဆေးအဖြစ် အသုံးပြုနိုင်ပါသည်။<br><br>\r\n\r\n🔼အသုံးပြုရမည့်ဆေးနှုန်းထားမှာ ရေ(၂၀)လီတာဝင် ဆေးဖျန်းပုံးတစ်ပုံးလျှင် ဆေးရည် (၆၀ - ၇၀)စီစီ နှုန်းဖြင့် တစ်ဧကအတွက် ဆေး(၃၀၀ - ၃၅၀)စီစီ အသုံးပြုပေးရပါမည်။<br><br>\r\n\r\n🔼“ဘင်ဇိုကာ” မှိုဆေးကို ရွေးချယ်သုံးစွဲ၍ သီးနှံပင်များတွင် မှိုရောဂါများကင်းစင်ပြီး အထွက်နှုန်းနှင့် အရည်အသွေးကောင်း သီးနှံခင်းများကိုပိုင်ဆိုင်နိုင်ကြပါစေ။<br><br>\r\n', '', '18-02-2024');

